window.PACK={"book":{"id":"furuq-lughawiyya","title":"الفروق اللغوية","type":"lughabook","ilm":"lugha","author":"أبو هلال العسكري (ت ٣٩٥هـ)","source":"المكتبة الشاملة / هنداوي عبر مشروع OpenITI","edition":"مؤسسة النشر الإسلامي التابعة لجماعة المدرسين بـ «قم»","optional":true,"packVersion":"ba0316f6709c"},"items":[{"id":"furuq-lughawiyya:1","bookId":"furuq-lughawiyya","type":"section","seq":1,"chapter":"مقدمة","title":"مقدمة","page":"ص0","text":"معجم الفروق اللغوية\nالحاوي لكتاب أبي هلال العسكري وجزءا من كتاب السيد نور الدين الجزائري\nتحقيق مؤسسة النشر الإسلامي التابعة لجماعة المدرسين بقم المقدسة\nمعجم الفروق اللغوية\nتنظيم: الشيخ بيت الله بيات ومؤسسة النشر الإسلامي\nالموضوع: اللغة\nعدد الصفحات: 630\nعدد الاجزاء: جزء واحد\nالطبعة: الأولى\nالمطبوع: 2000 نسخة\nالتاريخ: شوال المكرم 1412\nمؤسسة النشر الإسلامي التابعة لجماعة المدرسين بقم المشرفة\nبسم الله الرحمن الرحيم\nالحمد لله رب العالمين والصلاة على محمد المصطفى وعلى آله الطيبين الطاهرين واللعنة على اعدائهم أجمعين.\nوبعد: فان من جملة علوم العربية المهمة التي اهتم بها اللغويون قديما وحديثا علم الفروق اللغوية المعني بتمييز المفردات المتقاربة المعاني والتي تبدوا مترادفة إذا نظر إليها من غير تدقيق الامر الذي دفع قدماء علماء اللغة إلى تصنيف كتب مستقلة في هذا المضمار، منها كتاب \" الفروق اللغوية \" لابي هلال الحسن بن عبد الله العسكري من أعلام القرن الرابع الهجري ولهذا الكتاب مكانته الخاصة في فهم النصوص العربية - قرآنا ورواية وشعرا وغيرها - باعتباره من الكتب المتقدمة.\nولما كان هذا الكتاب بشكل يصعب على المراجع له الوصول إلى مقصوده بسهولة قام فضيلة الشيخ بيت الله بيات - حفظه الله تعالى - بتبويبه وترتيبه بالترتيب الهجائي مراعيا فيه الأمور التالية:"},{"id":"furuq-lughawiyya:2","bookId":"furuq-lughawiyya","type":"section","seq":2,"chapter":"مقدمة","title":"1- المحافظة على المتن ثابتا من دون تغيير الا المقدمة فقد رأينا حذفها","page":"ج1 ص2","text":"المحافظة على المتن ثابتا من دون تغيير الا المقدمة فقد رأينا حذفها."},{"id":"furuq-lughawiyya:3","bookId":"furuq-lughawiyya","type":"section","seq":3,"chapter":"مقدمة","title":"2- حذف موارد التكرار والاستغناء منها بالارجاع إلى أرقامها السابقة أو اللاحقة","page":"ج1 ص2","text":"حذف موارد التكرار والاستغناء منها بالارجاع إلى أرقامها السابقة أو اللاحقة."},{"id":"furuq-lughawiyya:4","bookId":"furuq-lughawiyya","type":"section","seq":4,"chapter":"مقدمة","title":"3- عدم ملاحظة الحرورف الاصلية في ترتيب الكلمات","page":"ج1 ص2","text":"عدم ملاحظة الحرورف الاصلية في ترتيب الكلمات."},{"id":"furuq-lughawiyya:5","bookId":"furuq-lughawiyya","type":"section","seq":5,"chapter":"مقدمة","title":"4- تخريج الآيات المذكورة في متن الكتاب","page":"ج1 ص2","text":"تخريج الآيات المذكورة في متن الكتاب."},{"id":"furuq-lughawiyya:6","bookId":"furuq-lughawiyya","type":"section","seq":6,"chapter":"مقدمة","title":"5- الاعتماد على النسخة المطبوعة من منشورات مكتبة بصيرتي والاستفادة من بعض هوامشها","page":"ج1 ص2","text":"الاعتماد على النسخة المطبوعة من منشورات مكتبة بصيرتي والاستفادة من بعض هوامشها.\nوامور اخرى لا يخفى حسنها على المتأمل.\nواقترحت مؤسستنا - بعد تلقي عمل سماحة الشيخ البيات بالقبول والرضا - إضافة قسم من كتاب \" فروق اللغات \" للسيد نور الدين بن السيد نعمة الله الجزائري المتوفى سنة 1158 ه، فقامت بإدراج الموارد التي اختلف فيها السيد الجزائري مع أبي هلال والموارد التي اختص بها السيد ولم يذكرها أبو هلال\nوميزت تلك الاضافات بتذييلها بكلمة (اللغات) بين قوسين فلاحظ، مستفيدين من بعض ما جاء في النسخة المحققة وهي من منشورات \" دفتر نشر \" وسمينا هذا النتاج القيم الجامع بين هذين الكتابين ب \" معجم الفروق اللغوية \" وقامت لجنة التحقيق بترقيمه ترقيما جديدا شاملا لكل ما ورد في هذا الكتاب وتنظيم فهرس موسع له وإخراجه بهذه الصورة الأنيقة.\nولا يخفى أن أبا هلال العسكري قد أرجع بعض الفروق بعبارة \" ما ذكر \" أو أشار إلى بعضها بلفظ \" ستذكر \" ونحن وضعنا هما كما هي حفاظا للمتن.\nوأخيرا لا يسعنا إلا أن نتقدم بجزيل الشكر لسماحة الشيخ البيات والاخوة في لجنة التحقيق السيد علي الطباطبائي والشيخ رياض الراوي وأبو حيدر الجواهري وغيرهم سائلين الله للجميع مزيدا من التوفيق إنه نعم المولى ونعم النصير.\nمؤسسة النشر الاسلامي التابعة لجماعة المدرسين بقم المشرفة"},{"id":"furuq-lughawiyya:7","bookId":"furuq-lughawiyya","type":"section","seq":7,"chapter":"* (أ) *","title":"2 - الفرق بين آخر الشئ ونهايته: أن آخر الشئ خلاف أوله وهما اسمان، والنهاية مصدر مثل الحماية والكفاية إلا أنه سمي به منقطع الشئ فقيل هو نهايت","page":"ج1 ص4","text":"الدار الآخرة كما قيل مسجد الجامع والمراد مسجد اليوم الجامع ودار الساعة الآخرة، وأما حق اليقين فهو كقولك محض اليقين ومن اليقين وليس قول من يقول هذه إضافة الشئ إلى نعته بشئ لان الاضافة توجب دخول الأول في الثاني حتى يكون في ضمنه، والنعت تحلية وإنما يحلى بالشئ الذي هو بالحقيقة ويضاف إلى ما هو غيره في الحقيقة، تقول هذا زيد الطويل فالطويل هو زيد بعينه، ولو قلت زيد الطويل وجب أن يكون زيد غير الطويل ويكون في تلك الطويل، ولا يجوز إضافة الشئ إلا إلى غيره أو بعضه فغيره نحو عبد زيد وبعضه نحو ثوب حرير وخاتم ذهب أي من حرير ومن ذهب، وقال المازني: عام الاول إنما هو عام زمن الأول."},{"id":"furuq-lughawiyya:8","bookId":"furuq-lughawiyya","type":"section","seq":8,"chapter":"* (أ) *","title":"8 - الفرق بين الآل والذرية (1) : آل الرجل: ذو (2) قرابته، وذريته: نسله.","page":"ج1 ص5","text":"فكل ذرية آل، وليس كل آل بذرية.\nوأيضا: الآل يخص بالاشراف، وذوي الاقدار، بحسب الدين، أو الدنيا.\nفلا يقال: آل حجام، وآل حائك، بخلاف الذرية.\n(اللغات)"},{"id":"furuq-lughawiyya:9","bookId":"furuq-lughawiyya","type":"section","seq":9,"chapter":"* (أ) *","title":"9 - الفرق بين الآنية والظرف (1) (*) : الآنية: تطلق على كل ما يستعمل في الاكل والشرب، وغيرهما كالقدر والمغرفة والصحن، والغضارة.","page":"ج1 ص6","text":"والظرف أعم منه ومن غيره إذ هو ما يشغل الشئ ويحيط به، فالصندوق والمخزن، وكذا الحوض والدار: ظروف، ولا تطلق عليها الآنية، فبينهما عموم وخصوص، فإن كل آنية ظرف، وليس كل ظرف آنية، وأهل اللغة لم يفرقوا بينهما.\n(اللغات) ."},{"id":"furuq-lughawiyya:10","bookId":"furuq-lughawiyya","type":"section","seq":10,"chapter":"* (أ) *","title":"14 - الفرق بين الاباء والامتناع (1) : الاباء: شدة الامتناع، فكل اباء امتناع: وليس إباء (2) ، قاله الراغب.","page":"ج1 ص7","text":"قلت: ويدل عليه قوله تعالى: \" ويأبى الله إلا أن يتم نوره \" (3) .\nوقوله تعالى: \" إلا إبليس أبى واستكبر \" (4) .\nفإن المراد: شدة الامتناع في المقامين.\n(اللغات) ."},{"id":"furuq-lughawiyya:11","bookId":"furuq-lughawiyya","type":"section","seq":11,"chapter":"* (أ) *","title":"16 - الفرق بين الاباء والمضادة: أن الاباء يدل على النعمة، ألا ترى أن المتحرك ساهيا لا يخرجه ذلك من أن يكون أتى بضد السكون ولا يصح","page":"ج1 ص7","text":"أن يقال قد أبى السكون، والمضادة لا تدل على النعمة."},{"id":"furuq-lughawiyya:12","bookId":"furuq-lughawiyya","type":"section","seq":12,"chapter":"* (أ) *","title":"17 - الفرق بين الاباحة والاذن: أن الاباحة قد تكون بالعقل والسمع، والاذن","page":"ج1 ص8","text":"لا يكون إلا بالسمع وحده، وأما الاطلاق فهو إزالة المنع عمن يجوز عليه ذلك، ولهذا لا يجوز أن يقال ان الله تعالى مطلق وإن الاشياء مطلقة له."},{"id":"furuq-lughawiyya:13","bookId":"furuq-lughawiyya","type":"section","seq":13,"chapter":"* (أ) *","title":"18 - الفرق بين الاختراع والابتداع: أن الابتداع إيجاد ما لم يسبق إلى مثله يقال أبدع فلان إذا أتى بالشئ الغريب وأبدعه الله فهو مبدع وبديع ومنه","page":"ج1 ص8","text":"(1) وفعيل من أفعل معروف في العربية يقال بصير من أبصر وحليم من أحلم، والبدعة في الدين مأخوذة من هذا وهو قول ما لم يعرف قبله ومنه قوله تعالى \" ما كنت بدعا من الرسل \" (2) وقال رؤبة: وليس وجه الحق أن يبدعا"},{"id":"furuq-lughawiyya:14","bookId":"furuq-lughawiyya","type":"section","seq":14,"chapter":"* (أ) *","title":"19 - الفرق بين الابتداع والاختراع (3) : قال الجوهري (4) .","page":"ج1 ص8","text":"أبدعت الشئ: اخترعته.\nوقال الزمخشري في الاساس (5) : اخترع الله الاشياء: ابتدعها من غير سبب.\nانتهى.\nوخص بعضهم الابتداع بالايجاد لا لعلة، والاختراع بالايجاد لا من شئ ويؤيده ما رواه الصدوق (*) - طاب ثراه - في كتاب التوحيد من باب أنه عزوجل ليس بجسم ولا صورة.\nمسندا (6) عن محمد بن زيد قال:\nجئت إلى الرضا عليه السلام أسأله عن التوحيد فأملى علي: \" الحمد لله فاطر الاشياء ومنشئها إنشاء، ومبتدعها (1) ابتداء بقدرته وحكمته، لا من شئ فيبطل الاختراع، ولا لعلة فلا يصح الابتداع \"..الحديث.\nفخص عليه السلام الاختراع بالايجاد لا من شئ، والابتداع بالايجاد لا لعلة.\n(اللغات) ."},{"id":"furuq-lughawiyya:15","bookId":"furuq-lughawiyya","type":"section","seq":15,"chapter":"* (أ) *","title":"21 - الفرق بين الابتلاء والاختبار: أن الابتلاء لا يكون إلا بتحميل المكاره والمشاق.","page":"ج1 ص9","text":"والاختبار يكون بذلك وبفعل المحبوب، ألا ترى انه يقال اختبره بالانعام عليه ولا يقال ابتلاه بذلك ولا هو مبتلى بالنعمة كما قد يقال اختبره بالانعام عليه ولا يقال ابتلاه بذلك ولا هو مبتلى بالنعمة كما قد يقال إنه مختبر بها، ويجوز أن يقال إن الابتلاء يقتضي استخراج ما عند المبتلي من الطاعة والمعصية، والاختبار يقتضي وقوع الخبر بحاله في ذلك\nوالخبر: العلم الذي يقع بكنه الشئ وحقيقته فالفرق بينهما بين."},{"id":"furuq-lughawiyya:16","bookId":"furuq-lughawiyya","type":"section","seq":16,"chapter":"* (أ) *","title":"25 - الفرق بين الأبدي والأزلي (1) : قد فرق بينهما بأن الابدي: هو المصاحب لجميع الازمنة، محققة كانت أو مقدرة في جانب المستقبل إلى غير النهاية","page":"ج1 ص10","text":"والازلي: هو المصاحب لجميع الثابتات المستمرة الوجود في الزمان.\n(اللغات) ."},{"id":"furuq-lughawiyya:17","bookId":"furuq-lughawiyya","type":"section","seq":17,"chapter":"* (أ) *","title":"29 - الفرق بين الابلاء والابتلاء (3) : هما بمعنى الامتحان: والاختبار.","page":"ج1 ص11","text":"قال القتبي (1) :..يقال من الخير: أبليته أبليه، إبلاء ومن الشربلوته أبلوه بلاء.\nوقال ابن الاثير: المعروف أن الابتلاء يكون في الخير والشر معا من غير فرق بين فعليهما، ومنه قوله تعالى: \" ونبلوكم بالشر والخير فتنة \" (2) .\n(اللغات) ."},{"id":"furuq-lughawiyya:18","bookId":"furuq-lughawiyya","type":"section","seq":18,"chapter":"* (أ) *","title":"الفرق بين الابن والولد","page":"ج1 ص11","text":"أن الابن يفيد الاختصاص ومداومة الصحبة\nولهذا يقال ابن الفلاد لمن يداوم سلوكها وابن السرى لمن يكثر منه، وتقول تبنيت ابنا إذا جعلته خاصا بك، ويجوز أن يقال إن قولنا هو ابن فلان يقتضي أنه منسوب إليه ولهذا يقال الناس بنو آدم لانهم منسوبون إليه وكذلك بنو إسرائيل، والابن في كل شئ صغير فيقول الشيخ للشاب يا بني ويسمي الملك رعيته الابناء وكذلك أنبياء من بني إسرائيل كانوا يسمون اممهم أبناءهم ولهذا كني الرجل بأبي فلان وإن لم يكن له ولد على التعظيم، والحكماء والعلماء يسمون المتعلمين أبناءهم ويقال لطالبي العلم أبناء العلم وقد يكنى بالابن كما يكنى بالاب كقولهم ابن عرس وابن نمرة وابن آوى وبنت طبق وبنات نعش وبنات وردان، وقيل أصل الابن التأليف والاتصال من قولك بنيته وهو مبني وأصله بني وقيل بنو ولهذا جمع على أبناء فكان بين الاب والابن تأليف، والولد يقتضي الولادة ولا يقتضيها الابن والابن يقتضي أبا والولد يقتضي والدا، ولا يسمى الانسان والدا إلا إذا صار له ولد وليس هو مثل الاب لانهم يقولون في التكنية أبو فلان وإن لم يلد فلانا ولا يقولون في هذا والد فلان إلا أنهم قالوا في الشاة والد في حملها قبل أن تلد وقد ولدت إذا ولدت إذا أخذ ولدها والابن للذكر والولد للذكر والانثى."},{"id":"furuq-lughawiyya:19","bookId":"furuq-lughawiyya","type":"section","seq":19,"chapter":"* (أ) *","title":"34 - الفرق بين الابن والولد (1) : الأول للذكر، والثاني يقع على الذكر","page":"ج1 ص12","text":"والانثى، والنسل والذرية يقع على الجميع.\n(اللغات) ."},{"id":"furuq-lughawiyya:20","bookId":"furuq-lughawiyya","type":"section","seq":20,"chapter":"* (أ) *","title":"37 - الفرق بين الاتقان والإحكام: أن إتقان الشئ إصلاحه وأصله من التقن وهو الترنوق (1) الذي يكون في المسيل أو البئر وهو الطين المختلط بالحمأة","page":"ج1 ص13","text":"وحكى بعضهم أتقنت الباب إذا أصلحته قال أبو هلال رحمه الله تعالى: ولا يقال أحكمته إلا إذا ابتدأته محكما."},{"id":"furuq-lughawiyya:21","bookId":"furuq-lughawiyya","type":"section","seq":21,"chapter":"* (أ) *","title":"38 - الفرق بين الاتمام والاكمال (4) : قد فرق بينهما بأن الاتمام: لازالة نقصان الاصل.","page":"ج1 ص13","text":"والاكمال: لازالة نقصان العوارض بعد تمام الاصل.\nقيل: ولذا كان قوله تعالى: \" تلك عشرة كاملة \" (5) أحسن من (تامة) .\nفإن التام من العدد قد علم، وإنما نفي احتمال نقص في صفاتها.\nوقيل: تم: يشعر بحصول نقص (6) قبله.\nوكمل: لا يشعر بذلك.\nوقال العسكري: الكمال: اسم (1) لاجتماع أبعاض الموصوف به.\nوالتمام: (2) اسم للجزء الذي يتم به الموصوف.\nولهذا يقال: القافية تمام البيت، ولا يقال: كماله.\nويقولون: البيت بكماله، أو باجتماعه.\n(اللغات) ."},{"id":"furuq-lughawiyya:22","bookId":"furuq-lughawiyya","type":"section","seq":22,"chapter":"* (أ) *","title":"43 - الفرق بين الاثم والذنب: أن الاثم في أصل اللغة التقصير أثم يأثم إذا قصر ومنه قول الأعشى: جمالية تغتلي بالرداف * إذا كذب الآثمات الهجيرا","page":"ج1 ص15","text":"المقصرات ومن ثم سمي الخمر إثما لانها تقصر بشاربها لذهابها بعقله."},{"id":"furuq-lughawiyya:23","bookId":"furuq-lughawiyya","type":"section","seq":23,"chapter":"* (أ) *","title":"45 - الفرق بين الاثم والعدوان (1) : الاثم: الجرم كائنا ما كان.","page":"ج1 ص15","text":"والعدوان: الظلم.\nقاله الطبرسي رضي الله عنه، وعلى هذا فقوله تعالى \" يسارعون في الاثم والعدوان \" (2) .\nمن عطف الخاص على العام.\n(اللغات) ."},{"id":"furuq-lughawiyya:24","bookId":"furuq-lughawiyya","type":"section","seq":24,"chapter":"* (أ) *","title":"الفرق بين الأجر والثواب","page":"ج1 ص16","text":"أن الاجر يكون قبل الفعل المأجور عليه والشاهد أنك تقول ما أعمل حتى آخذ أجري ولا تقول لا أعمل حتى آخذ ثوابي لان الثواب لا يكون إلا بعد العمل على ما ذكرنا (1) هذا على أن الاجر لا يستحق له إلا بعد العمل كالثواب إلا أن الاستعمال يجري بما ذكرناه وأيضا فان الثواب قد شهر في الجزاء على الحسنات، والاجر يقال في هذا المعنى ويقال على معنى الاجرة التي هي من طريق المثامنة بأدني الاثمان وفيها معنى المعاوضة بالانتفاع."},{"id":"furuq-lughawiyya:25","bookId":"furuq-lughawiyya","type":"section","seq":25,"chapter":"* (أ) *","title":"56- الفرق بين الاجر والثواب","page":"ج1 ص16","text":"الفرق بين الاجر والثواب (2) : الثواب: وإن كان في اللغة الجزاء\nالذي يرجع إلى العامل بعلمه، ويكون في الخير والشر، إلا أنه قد اختص\nفي العرف بالنعيم على الاعمال الصالحة من العقائد الحقة، والاعمال البدنية والمالية، والصبر في مواطنه بحيث لا يتبادر منه عند الاطلاق إلا هذا المعنى.\nوالاجر: إنما يكون في الاعمال البدنية من الطاعات، ويدل عليه قول أمير المؤمنين (1) عليه السلام لبعض أصحابه في علة اعتلها: \" جعل الله ما كان من شكواك حطا بسيئاتك \" فإن المرض لا أجر فيه، لكنه يحط السيئات، ويحتها حت الاوراق، وإنما الاجر في القول باللسان، والعمل بالايدي والاقدام.\nوإن الله يدخل - بصدق النية والسريرة الصالحة من يشاء من عباده الجنة.\n(اللغات) ."},{"id":"furuq-lughawiyya:26","bookId":"furuq-lughawiyya","type":"section","seq":26,"chapter":"* (أ) *","title":"57 - الفرق بين الأجل والعمر (2) : [الأجل: هو آخر مدة العمر المضروبة في علمه تعالى، فهو لا يتبدل. والعمر: هو ما يتبدل ويحتمل الزيادة والنقصان","page":"ج1 ص18","text":"(اللغات)"},{"id":"furuq-lughawiyya:27","bookId":"furuq-lughawiyya","type":"section","seq":27,"chapter":"* (أ) *","title":"59 - الفرق بين الاجمال والاحسان: أن الاجمال هو الاحسان الظاهر من قولك","page":"ج1 ص20","text":"رجل جميل كأنما يجري فيه السمن وأصل الجميل الودك (1) واجتمل الرجل إذا طبخ العظام ليخرج ودكها ويقال أحسن اليه فيعدى بإلى وأجمل في أمره لانه فعل الجميل في أمره ويقال أنعم عليه لانه دخله معنى علو نعمة عليه فهي غامرة له، ولذلك يقال هو غريق في النعمة ولا يقال غريق في الاحسان والاجمال ويقال أجمل الحساب فيعدي ذلك بنفسه لانه مضمن بمفعول ينبئ عنه من غير وسيلة، وقد يكون الاحسان مثل الاجمال في استحقاق الحمد به وكما يجوز أن يحسن الانسان إلى نفسه يجوز أن يجمل في فعله لنفسه."},{"id":"furuq-lughawiyya:28","bookId":"furuq-lughawiyya","type":"section","seq":28,"chapter":"* (أ) *","title":"60 - الفرق بين قولنا أجمع والجمع: أن أجمع اسم معرفة يؤكد به الاسم المعرفة نحو قولك المال لك أجمع وهذا مالك أجمع ولا ينصرف لانه أفعل معرفة وا","page":"ج1 ص20","text":"فيقال مررت بجواريك جمع وجاءني جواريك جمع، وأجمع جمع جمع تقول جاءني القوم بأجمعهم كما تقول جاءني القوم بأفلسهم وأكلبهم وأعبدهم، وليس هذا الحرف من حروف التوكيد والشاهد دخول العامل عليه وإضافته، وأجمع الذي هو للتوكيد لا يضاف ولا يدخل عليه عامل ومن أجاز فتح الجيم في قولك جاءني القوم بأجمعهم فقد أخطأ."},{"id":"furuq-lughawiyya:29","bookId":"furuq-lughawiyya","type":"section","seq":29,"chapter":"* (أ) *","title":"61 - الفرق بين الاحباط والتكفير: أن الاحباط هو إبطال عمل البر من الحسنات بالسيئات وقد حبط هو ومنه قوله تعالى \" وحبط ما صنعوا","page":"ج1 ص21","text":"فيها \" (1) وهو من قولك حبط بطنه إذا فسد بالمأكل الردئ، والتكفير إبطال السيئات بالحسنات وقال تعالى \" كفر عنهم سيئاتهم \" (2) ."},{"id":"furuq-lughawiyya:30","bookId":"furuq-lughawiyya","type":"section","seq":30,"chapter":"* (أ) *","title":"66 - الفرق بين الاحداث والحدوث: أن الاحداث والمحدث يقتضيان محدثا","page":"ج1 ص21","text":"من جهة اللفظ، وليس كذلك الحدوث والحادث، وليس الحدوث والاحداث شيئا غير المحدث والحادث وإنما يقال ذلك على التقدير، وشبه بعضهم ذلك بالسراب وقال \" هو اسم لا مسمى له على الحقيقة \" وليس الامر كذلك لان السراب سبخة تطلع عليه الشمس فتبرق فيحسب ماء فالسراب على الحقيقة شئ إلا أنه متصور بصورة غيره وليس الحدوث والاحداث كذلك."},{"id":"furuq-lughawiyya:31","bookId":"furuq-lughawiyya","type":"section","seq":31,"chapter":"* (أ) *","title":"الفرق بين الأحد والواحد","page":"ج1 ص22","text":"أن الاحد يفيد أنه فارق غيره ممن شاركه في فن من الفنون ومعنى من المعاني، كقولك فارق فلان أوحد دهره في الجود والعلم تريد أنه فوق أهله في ذلك."},{"id":"furuq-lughawiyya:32","bookId":"furuq-lughawiyya","type":"section","seq":32,"chapter":"* (أ) *","title":"68- الفرق بين الأحد والواحد","page":"ج1 ص22","text":"الفرق بين الأحد والواحد: (67) و (2279) ."},{"id":"furuq-lughawiyya:33","bookId":"furuq-lughawiyya","type":"section","seq":33,"chapter":"* (أ) *","title":"69 - الفرق بين الاحساس والادراك: على ما قال أبو أحمد أنه يجوز أن يدرك الانسان الشئ وإن لم يحس به، كالشئ يدركه ببصره ويغفل عنه فلا يعرفه فيقا","page":"ج1 ص22","text":"وقال بعضهم: - إدامة الكلام في الفرق بين الحس والعلم في عدد (739) فراجع."},{"id":"furuq-lughawiyya:34","bookId":"furuq-lughawiyya","type":"section","seq":34,"chapter":"* (أ) *","title":"71 - الفرق بين الاحسان والافضال: أن الاحسان النفع الحسن، والافضال","page":"ج1 ص22","text":"النفع الزائد على أقل المقدار وقد خص الاحسان (3) بالفضل ولم يجب مثل ذلك في الزيادة لانه جرى مجرى الصفة الغالبة كما اختص النجم بالسماك ولا يجب مثل ذلك في كل مرتفع."},{"id":"furuq-lughawiyya:35","bookId":"furuq-lughawiyya","type":"section","seq":35,"chapter":"* (أ) *","title":"76 - الفرق بين الاحصار والحصر: قالوا الاحصار في اللغة منع بغير حبس، والحصر المنع بالحبس قال الكسائي: ما كان من المرض قيل فيه احصر، وقال أبو","page":"ج1 ص23","text":"إناء يشرب منه وأسقاه إذا جعل له سقيا، وقبره إذا تولى دفنه وأقبره جعل له قبرا.\nفمعنى قوله تعالى \" فإن احصرتم \" (1) عرض لكم شئ يكون سببا لفوات الحج."},{"id":"furuq-lughawiyya:36","bookId":"furuq-lughawiyya","type":"section","seq":36,"chapter":"* (أ) *","title":"77 - الفرق بين الاحق والاصلح (2) : قيل: الفرق بينهما أن الاحق قد يكون","page":"ج1 ص24","text":"من غير صفات الفعل، كقولك: زيد أحق بالمال.\nوالاصلح: لا يقع هذا الموقع لانه من صفات الفعل [7 / أ] وتقول: الله أحق بأن يطاع، ولا تقول: أصلح.\nقلت: ويؤيده قوله تعالى: \" والله ورسوله أحق أن يرضوه \" (1) .\n(اللغات) ."},{"id":"furuq-lughawiyya:37","bookId":"furuq-lughawiyya","type":"section","seq":37,"chapter":"* (أ) *","title":"83 - الفرق بين الاخبات والخضوع: أن المخبت هو المطمئن بالايمان وقيل هو المجتهد بالعبادة وقيل الملازم للطاعة والسكون وهو من أسماء الممدوح مثل","page":"ج1 ص24","text":"يوجبه الاشتقاق هو الخضوع المستمر على استواء."},{"id":"furuq-lughawiyya:38","bookId":"furuq-lughawiyya","type":"section","seq":38,"chapter":"* (أ) *","title":"92 - الفرق بين الاختصار والاقتصار (1) : قيل: الاختصار: ما كان قليل اللفظ، كثير المعنى.","page":"ج1 ص25","text":"والاقتصار: ما كان قليل اللفظ والمعنى.\nقلت: ويرشد إليه اشتقاقه (2) من القصور، وهو النقصان.\n(اللغات) ."},{"id":"furuq-lughawiyya:39","bookId":"furuq-lughawiyya","type":"section","seq":39,"chapter":"* (أ) *","title":"96 - الفرق بين الاختلاس والاستلاب (1) .","page":"ج1 ص26","text":"قيل (2) المختلس: هو الذي يأخذ المال من غير الحرز.\nوالمستلب: هو الذي يأخذه جهرا، ويهرب مع كونه غير محارب.\n(اللغات) ."},{"id":"furuq-lughawiyya:40","bookId":"furuq-lughawiyya","type":"section","seq":40,"chapter":"* (أ) *","title":"110 - الفرق بين أخمدت النار وأطفأتها: أن الاخماد يستعمل في الكثير","page":"ج1 ص29","text":"والاطفاء في الكثير والقليل يقال أخمدت النار وأطفأت النار ويقال\nأطفأت السراج ويقال أخمدت السراج، وطفئت النار يستعمل في الخمود مع ذكر النار فيقال خمدت نيران الظلم ويستعار الطفي في غير ذكر النار فيقال طفئ غضبه ولا يقال خمد غضبه وفي الحديث: \" الصدقة تطفئ غضب الرب \" (1) وقيل الخمود يكون بالغلبة والقهر والاطفاء بالمداراة والرفق، ولهذا يستعمل الاطفاء في الغضب لانه يكون بالمداراة والرفق، والاخماد يكون بالغلبة، ولهذا يقال خمدت نيران الظلم والفتنة.\nوأما الخمود والهمود فالفرق بينهما أن خمود النار أن يسكن لهبها ويبقى جمرها، وهمودها ذهابها البتة.\nوأما الوقود بضم الواو فاشتعال النار والوقود بالفتح ما يوقد به."},{"id":"furuq-lughawiyya:41","bookId":"furuq-lughawiyya","type":"section","seq":41,"chapter":"* (أ) *","title":"الفرق بين الاداء والابلاغ","page":"ج1 ص29","text":"أن الاداء إيصال الشئ على ما يجب فيه، ومنه أداء الدين، فلان حسن الاداء لما يسمع وحسن الاداء للقراءة، والابلاغ إيصال ما فيه بيان للافهام ومنه البلاغة وهي إيصال المعنى إلى النفس في أحسن صورة."},{"id":"furuq-lughawiyya:42","bookId":"furuq-lughawiyya","type":"section","seq":42,"chapter":"* (أ) *","title":"112- الفرق بين الاداء والابلاغ","page":"ج1 ص29","text":"الفرق بين الاداء والابلاغ (2) : قد يفرق بينهما بأن الابلاغ: إيصال ما فيه بيان وإفهام ومنه البلاغة، وهو إيصال الشئ إلى النفس بأحسن صورة من اللفظ.\nوالاداء: إيصال الشئ على الوجه الذي يجب (3) فيه.\nومنه: فلان أدى الدين أداء.\n(*) وقال بعض المحققين: الابلاغ: يستعمل في المعاني كما في قوله سبحانه: \" ليعلم أن قد أبلغوا رسالات ربهم \" (1) .\nوالاداء في الاعيان كما في قوله سبحانه: \" إن الله يأمركم أن تؤدوا الامانات إلى أهلها \" (2) (*) (3) .\n(اللغات) ."},{"id":"furuq-lughawiyya:43","bookId":"furuq-lughawiyya","type":"section","seq":43,"chapter":"* (أ) *","title":"114 - الفرق بين الأد والعجب: أن الأد العجب المنكر.","page":"ج1 ص30","text":"وأصله من قولك أد البعير كما تقول ند أي شرد فالاد العجب الذي خرج عما في العادة من أمثاله، والعجب استعظام الشئ لخفاء سببه والمعجب ما يستعظم لخفاء سببه."},{"id":"furuq-lughawiyya:44","bookId":"furuq-lughawiyya","type":"section","seq":44,"chapter":"* (أ) *","title":"117 - الفرق بين الإدراك والعلم: أن الإدراك موقوف على أشياء مخصوصة، وليس العلم كذلك، والادراك يتناول الشئ على أخص أوصافه وعلى الجملة، والعلم","page":"ج1 ص30","text":"ألا ترى أن الانسان لا ينسى ما يراه في الحال كما ينسى ما رآه قبل."},{"id":"furuq-lughawiyya:45","bookId":"furuq-lughawiyya","type":"section","seq":45,"chapter":"* (أ) *","title":"122 - الفرق بين الإذن والإجازة (1) : قد فرق بينهما بأن الاذن: هو الرخصة في الفعل قيل إيقاعه، ويدل عليه قوله تعالى: \" فإذا استأذنوك لبعض شأنه","page":"ج1 ص32","text":"وقوله تعالى: \" ليستاذنكم الذين ملكت أيمانكم والذين لم يبلغوا الحلم \" (3) .\nوالاجازة: الرخصة في الفعل بعد إيقاعه، وهو بمعنى الرضا بما وقع، ولذلك يسمون الفقهاء (4) رضا المالك بما فعله الغير: فضولا، وكذا يسمون رضا الوارث بما فعله الموصي من الوصية بما زاد على الثلث: إجازة.\n(اللغات) ."},{"id":"furuq-lughawiyya:46","bookId":"furuq-lughawiyya","type":"section","seq":46,"chapter":"* (أ) *","title":"125 - الفرق بين الإرادة والإصابة: أن الارادة سميت إصابة على المجاز في قولهم أصاب الصواب وأخطأ الجواب أي أراد، قال الله تعالى \" رخاء حيث أصاب","page":"ج1 ص32","text":"وذلك أن أكثر الاصابة تكون مع الارادة."},{"id":"furuq-lughawiyya:47","bookId":"furuq-lughawiyya","type":"section","seq":47,"chapter":"* (أ) *","title":"الفرق بين الإرادة والشهوة","page":"ج1 ص33","text":"أن الانسان قد يشتهي ما هو كاره له كالصائم يشتهي شرب الماء ويكرهه، وقد يريد الانسان مالا يشتهيه كشرب الدواء المر والحمية والحجامة وما بسبيل ذلك، وشهوة القبيح غير قبيحة وإرادة القبيح قبيحة فالفرق بينهما بين."},{"id":"furuq-lughawiyya:48","bookId":"furuq-lughawiyya","type":"section","seq":48,"chapter":"* (أ) *","title":"133- الفرق بين الإرادة والشهوة","page":"ج1 ص33","text":"الفرق بين الإرادة والشهوة (1) : قال الطبرسي (2) رضي الله عنه:\nالشهوة: مطالبة النفس بفعل ما فيه اللذة وليست كالارادة، لانها قد تدعو إلى الفعل من الحكمة.\nوالشهوة ضرورية [6 / ب] فينا من فعل الله تعالى.\nوالارادة: من فعلنا.\n(اللغات) ."},{"id":"furuq-lughawiyya:49","bookId":"furuq-lughawiyya","type":"section","seq":49,"chapter":"* (أ) *","title":"الفرق بين الإرادة والمشيئة","page":"ج1 ص34","text":"أن الارادة تكون لما يتراخى وقته ولما لا يتراخى، والمشيئة لما لم يتراخ وقته، والشاهد أنك تقول فعلت كذا شاء زيد أو أبى فيقابل بها إباه وذلك انما يكون عند محاولة الفعل وكذلك مشيئته إنما تكون بدلا من ذلك في حاله."},{"id":"furuq-lughawiyya:50","bookId":"furuq-lughawiyya","type":"section","seq":50,"chapter":"* (أ) *","title":"138- الفرق بين الإرادة والمشيئة","page":"ج1 ص34","text":"الفرق بين الإرادة والمشيئة (1) : قيل: الارادة هي العزم (2) على الفعل، أو الترك بعد تصور الغاية، المترتبة عليه من خير، أو نفع، أو لذة ونحو ذلك.\nوهي أخص من المشيئة، لان المشيئة ابتداء العزم على الفعل، فنسبتها إلى الارادة نسبة الضعف إلى القوة، والظن إلى الجزم، فإنك ربما شئت شيئا ولا تريده، لمانع عقلي أو شرعي.\nوأما الارادة فمتى حصلت صدر الفعل لا محالة.\nوقد يطلق كل منهما على الآخر توسعا.\nوإرادته عز وجل للشئ نفس\nإيجاده (1) له.\nويشهد لذلك الاخبار.\nمنها ما روي عن صفوان قال: قلت (2) لابي الحسن أخبرني عن الارادة من الله، ومن الخلق، فقال: الارادة من الخلق: الضمير وما يبدو لهم بعد ذلك من الفعل.\nوأما من الله تعالى فإرادته إحداثه لا غير ذلك، لانه لا يروي.\nولا يهم، ولا يتفكر.\nفهذه الصفات منفية عنه تعالى.\nوهي صفات الخلق.\nفإرادة الله الفعل لا غير، يقول له: كن فيكون، بلا لفظ ولا قول: ولا نطق بلسان،\nولا همة ولا تفكر.\nولا كيف لذلك، كما أنه لا كيف له.\nوقال بعض المحققين: الارادة في الحيوان شوق متأكد إلى حصول المراد.\nوقيل: إنها مغايرة للشوق (3) ، فإن الارادة هي الاجماع وتصميم العزم.\nوقد يشتهي الانسان ما لا يريده كالاطعمة اللذيذة بالنسبة إلى العاقل الذي يعلم ما في أكلها من الضرر.\nوقد يريد: ما لا يشتهيه كالأدوية الشنيعة (4) النافعة التي يريد الانسان تناولها لما فيها من النفع.\nوفرق بينهما بأن الارادة: ميل اختياري، والشوق: ميل جبلي طبيعي.\nولذا (5) يعاقب الانسان المكلف بإرادة المعاصي، ولا يعاقب باشتهائها.\nوقيل: إرادة الله سبحانه توجب للحق حالا يقع منه الفعل على وجه دون وجه.\n[3 / ب] وقيل: بل (1) هي علمه بنظام الكل على الوجه الاتم الاكمل، من حيث إنه كاف في وجود الممكنات، ومرجح لطرف وجودها على عدمها، فهي عين ذاته والمحبة فينا ميل النفس أو سكونها بالنسبة إلى ما يوافقها عند تصور كونه موافقا، وملائما لها، وهو مستلزم\nلارادته إياه.\nولما كانت المحبة بهذا المعنى محالا في حقه تعالى، فالمراد بها ذلك اللازم، وهو الارادة.\nوقال بعض الاعلام (2) : المشيئة والارادة قد يخالفان المحبة، كما قد نريد نحن شيئا لا يستلذ، كالحجامة، وشرب الدواء الكريه الطعم.\nوكذلك ربما انفكت مشيئة الله تعالى وإرادته عن محبته (3) ورضاه.\nانتهى.\nوعلى هذا فالارادة أعم من المحبة، لان كل محبوب مراد، دون العكس.\nوقال بعض المحدثين من المتأخرين، في جواب من سأل عن الفرق بين القضاء والقدر، والامضاء والمشيئة، والارادة والخلق: المستفاد من الاخبار أن هذه الاشياء متغايرة في المعنى، مترتبة في الوجود، إلا أن الظاهر أن الامضاء والخلق بمعنى واحد.\nفالمشيئة قبل الارادة، والارادة قبل القدر، والقدر (4) قبل القضاء، والقضاء قبل الامضاء، وهو الخلق، وهو إبراز المعدوم في الوجود، وتأليفه، وتركيبه، فالمشيئة بالنسبة إلينا\nهي (1) الميل الاول بعد حصول العلم بالشئ.\nوالارادة: هي الميل الثاني القريب بعد أن تنشطت النفس إلى فعله (2) ، وصممت على\nإيجاده.\nوالقدر: هو التقدير بالمقدار طولا وعرضا مثلا.\nوالقضاء: هو التقطيع والتأليف.\nوالامضاء: هو إبراز الصنعة في عالم (3) المصنوع، مثاله في المحسوس: هو أنك إذا أردت أن تخيط ثوبا، فلابد أن تكون عالما بالعلة (4) الغائية التي هي المرتبة الاولى، فيحصل لك ميل إلى لبس الثوب، وهذا هو المشيئة وهي المرتبة الثانية، فيدعوك ذلك الميل إلى لبسه إلى الميل إلى خياطته وتقطيعه، وهذا هو الارادة: وهي المرتبة الثالثة.\nفتقدره أولا قبل تقطيعه، لئلا يحصل فيه الزيادة والنقصان، وهذا هو القدر: وهي المرتبة الرابعة، فتقطعه بعد ذلك على حسب وضع الثوب في كيفيته، فيحصل الغرض المقصود منه، وهذا هو القضاء: وهي المرتبة الخامسة، ثم تؤلف تلك الاجزاء، وتضعها في مواضعها.\nوهذا هو الامضاء: وهو الخلق، وهو الصنع والتصوير.\nويدل على ذلك صريحا ما رواه الكلينى (5) قدس سره، قال: سئل العالم عليه السلام: كيف علم الله؟ قال: \" علم وشاء وأراد وقدر وقضى وأمضى فأمضى ما قضى، وقضى ما قدر وقدر ما أراد، فبعلمه كانت المشيئة وبمشيئته\nكانت الارادة، وبإرادته كان التقدير، وبتقديره كان القضاء، وبقضائه كان الامضاء.\nوالعلم متقدم على المشيئة، والمشيئة ثانية، والارادة ثالثة، والتقدير واقع على القضاء بالامضاء.\nفلله تبارك وتعالى البداء فيما علم متى شاء، وفيما أراد من تقدير الاشياء، فإذا وقع القضاء بالامضاء، فلا بداء.\nفالعلم بالمعلوم قبل كونه، والمشيئة في المشاء (1) قبل عينه، والارادة في المراد قبل قيامه.\nوالتقدير لهذه المعلومات قبل تفصيلها وتوصيلها عيانا ووقتا، والقضاء بالامضاء من المبرم من المفعولات، الحديث.\nوبه ينحل قول مولانا أمير المؤمنين لما فر من حائط أشرف على الانهدام: \" أفر من قضاء الله إلى قدره \".\nإلا أن نسبة هذه المعاني إليه سبحانه على وجه المجاز لا الحقيقة، إذ المقصود من هذا الكلام: التقريب إلى الافهام.\nإذا عرفت هذا فاعلم أن إرادته سبحانه على ضربين كمشيئته: أحدهما: حتم: وهي الارادة المتعلقة بالتكوين كالخلق، والرزق والاحياء، والاماتة، وتسخير الافلاك، وبالجملة فكل ما هو ليس من أفعال العباد الاختيارية فهذه لا تختلف عن إرادته، وإليه أشار سبحانه بقوله: \" ولو شاء ربك لآمن من في الارض كلهم جميعا \" (2) .\nالثاني (3) : إرادة عزم: وهي (4) المتعلقة بأفعال العباد وأعمالهم الاختيارية من الامور التكليفية، وهذه قد تختلف إذ ليس معنى إرادته فيها إلا أمره بها، ومحبته لها، وهذا لا يلزم منه الوقوع، وإلا لزم الجبر،\nوالالجاء، وبطل الثوب والعقاب.\nوفي القول به خروج عن جادة الصواب.\nانتهى كلامه، زيد إكرامه (1) .\nهذا، وقد استدل بعض الافاضل على أن المشيئة من الله تقتضي وجود الشئ، بما ورد من قوله صلى الله عليه وآله: \" ما شاء الله كان \" (2) وعلى أن الارادة منه سبحانه لا تقتضي وجود المراد لا محالة بقوله تعالى: \" يريد الله بكم اليسر ولا يريد بكم العسر \" (3) وبقوله سبحانه: \" وما الله يريد ظلما للعباد \" (4) .\nومعلوم أنه قد يحصل العسر والظلم فيما بين الناس (5) .\nأقول: ويمكن المناقشة في الاستدلال بالآيتين بأن المراد بإرادة اليسر وعدم إرادة العسر في الآية الاولى: الرخصة للمريض، والمسافر في الافطار في شهر رمضان، والآية مسوقة لذلك، لقوله تعالى: \" فمن شهد منكم الشهر فليصمه ومن كان مريضا أو على سفر فعدة من أيام أخر يريد الله بكم اليسر ولا يريد بكم العسر \" (6) والمراد: \" يريد الله بكم اليسر \" في جميع الامور، \" ولا يريد بكم العسر \" أي التضيق عليكم وتكليفكم ما لا تطيقونه، وعلى\nالتقديرين فإرادته سبحانه لم تتخلف (1) عن وجود المراد لا محالة في هذا الباب.\nوأما الآية الثانية فالمعنى أنه سبحانه: لا يريد ظلم عباده بأن يحملهم من العقاب مالا يستحقونه (2) أو ينقصهم من الثواب عما استحقوه.\nوهذا المراد أيضا لا يتخلف عن إرادته سبحانه.\n(اللغات)"},{"id":"furuq-lughawiyya:51","bookId":"furuq-lughawiyya","type":"section","seq":51,"chapter":"* (أ) *","title":"143 - الفرق بين الإرتياب والشك: أن الارتياب شك مع تهمة (4) والشاهد أنك تقول إني شاك اليوم في المطر، ولا يجوز أن تقول إني مرتاب بفلان إذا شكك","page":"ج1 ص40","text":"فأما: \" تتمة الكلام في كلمتين الريبة والتهمة \" (5) ."},{"id":"furuq-lughawiyya:52","bookId":"furuq-lughawiyya","type":"section","seq":52,"chapter":"* (أ) *","title":"144 - الفرق بين الإرسال والإنفاذ: أن قولك أرسلت زيدا إلى عمرو يقتضي أنك حملته رسالة إليه أو خبرا وما أشبه ذلك، والانفاذ لا يقتضي هذا","page":"ج1 ص41","text":"المعنى، ألا ترى انه ان طلب منك إنفاذ زيد إليه فأنفذته إليه قلت أنفذته ولا يحسن أن تقول أرسلته، وإنما يستعمل الارسال حيث يستعمل الرسول."},{"id":"furuq-lughawiyya:53","bookId":"furuq-lughawiyya","type":"section","seq":53,"chapter":"* (أ) *","title":"146 - الفرق بين الارشاد والهداية: أن الارشاد إلى الشئ هو التطريق إليه والتبيين له.","page":"ج1 ص41","text":"والهداية هي التمكن من الوصول إليه، وقد جاءت الهداية للمهتدي في قوله تعالى \" إهدنا الصراط المستقيم \" (1) فذكر انهم دعوا بالهداية وهم مهتدون لا محالة ولم يجئ مثل ذلك في الارشاد، ويقال أيضا هداه إلى المكروه كما قال الله تعالى \" فاهدوهم إلى صراط الجحيم \" (2) وقال تعالى \" إنك لعلى هدى مستقيم \" (3) والهدى الدلالة فإذا كان مستقيما فهو دلالة إلى الصواب والايمان هدى لانه دلالة إلى الجنة وقد يقال الطريق هدى ولا يقال أرشده إلا إلى المحبوب، والراشد هو القابل للارشاد والرشيد مبالغة من ذلك، ويجوز أن يقال الرشيد الذي صلح بما في نفسه مما يبعث عليه الخير، والراشد القابل لما دل عليه من طريق الرشد، والمرشد الهادي للخير والدال على طريق الرشد ومثل ذلك مثل من يقف بين طريقين لا يدري أيهما يؤدي إلى الغرض المطلوب فإذا دله عليه دال فقد أرشده وإذا قبل هو قول الدال فسلك قصد السبيل فهو راشد وإذا بعثته نفسه على سلوك الطريق القاصد فهو رشيد، والرشاد والسداد والصواب حق من يعمل عليه أن ينجو وحق من يعمل على خلافه أن يهلك."},{"id":"furuq-lughawiyya:54","bookId":"furuq-lughawiyya","type":"section","seq":54,"chapter":"* (أ) *","title":"152 - الفرق بين الاساءة والنقمة (1) : قد فرق بينهما بأن النقمة: قد تكون بحق جزاء على كفران النعمة.","page":"ج1 ص42","text":"والاساءة: لا تكون الا قبيحة.\nولذا لا يصح وصفه تعالى بالمسئ، وصح\nوصفه بالمنتقم.\nقال سبحانه: \" والله عزيز ذو انتقام \" (1) وقال: \" ومن عاد فينتقم الله منه \" (2) (اللغات) ."},{"id":"furuq-lughawiyya:55","bookId":"furuq-lughawiyya","type":"section","seq":55,"chapter":"* (أ) *","title":"156 - الفرق بين الإستجابة والإجابة (3) : قيل: الاستجابة فيه: قبول لما دعا إليه (4) ، ولذا وعد سبحانه الداعين بالاستجابة في قوله سبحانه: \" اد","page":"ج1 ص43","text":"\" للذين استجابوا لربهم الحسنى \" (6) .\nوأما قوله سبحانه: \" ويوم يقول نادوا شركائي الذين زعمتم\nفدعوهم فلم يستجيبوا لهم \" (1) مع أن الظاهر نفي مطلق الجواب.\nفلان الغرض بيان خيبتهم، وعدم حصول مأمولهم ومتوقعهم من قبول الشركاء دعاءهم وشفاعتهم عند الله.\nعلى أن كون الظاهر نفي مطلق الجواب غير ظاهر بدليل أنه سبحانه حكى عن الشركاء في موضع آخر بقوله تعالى: \" وقال شركاؤهم ما كنتم إيانا تعبدون \" (2) .\nفالمنفي: هو قبول الدعوة فقط، وليست (3) كذلك الاجابة، لانه يجوز (4) أن يجيب بالمخالفة كما يقول السائل: أتوافق في هذا المذهب (5) أم تخالف؟ فيقول المجيب: اخالف.\nوقيل: إن: أجاب و: استجاب بمعنى.\n(اللغات) ."},{"id":"furuq-lughawiyya:56","bookId":"furuq-lughawiyya","type":"section","seq":56,"chapter":"* (أ) *","title":"162 - الفرق بين قولنا استشرفه ببصره ومد إليه بصره: أن قولنا استشرفه ببصره معناه أنه مد إليه بصره من أعلاه.","page":"ج1 ص45","text":"* * *"},{"id":"furuq-lughawiyya:57","bookId":"furuq-lughawiyya","type":"section","seq":57,"chapter":"* (أ) *","title":"الفرق بين الاستطاعة والقدرة","page":"ج1 ص46","text":"أن الاستطاعة في قولك طاعت جوارحه\nللفعل أي انقادت له ولهذا لا يوصف الله بها ويقال أطاعة وهو مطيع وطاع له وهو طائع له إذا انقاد له، وجاءت الاستطاعة بمعنى الاجابة وهو قوله تعالى \" هل يستطيع ربك \" (1) أي هل يجيبك إلى ما تشأله وأما قوله تعالى \" لا يستطيعون سمعا \" (2) فمعناه أنه يثقل عليهم استماع القرآن ليس أنهم لا يقدرون على ذلك، وأنت تقول لا أستطيع أن أبصر فلانا تريد أن رؤيته تثقل عليك."},{"id":"furuq-lughawiyya:58","bookId":"furuq-lughawiyya","type":"section","seq":58,"chapter":"* (أ) *","title":"164- الفرق بين الاستطاعة والقدرة","page":"ج1 ص46","text":"الفرق بين الاستطاعة والقدرة (3) : قيل الفرق بينهما أن الاستطاعة: انطباع الجوارح للفعل.\nوالقدرة: هي ما أوجب كون القادر عليه قادرا.\nولذلك لا يوصف الله تعالى بأنه مستطيع، ويوصف بأنه قادر (اللغات) ."},{"id":"furuq-lughawiyya:59","bookId":"furuq-lughawiyya","type":"section","seq":59,"chapter":"* (أ) *","title":"165- الفرق بين الاستطاعة والقدرة","page":"ج1 ص46","text":"الفرق بين الاستطاعة والقدرة (4) : قيل: الاستطاعة أخص من القدرة، فكل مستطيع قادر وليس كل قادر بمستطيع، لان الاستطاعة: اسم لمعان يتمكن بها الفاعل مما يريده من أحداث الفعل وهي (5) أربعة أشياء: إرادته للفعل، وقدرته على الفعل بحيث لا يكون له مانع منه، وعلمه بالفعل، وتهيؤ ما يتوقف عليه الفعل.\nألا ترى أنه يقال: فلان قادر\nعلى كذا لكنه لا يريده، أو يمنعه منه مانع، أو لا علم له به أن يعوزه كذا.\nفظهر أن القدرة أعم من الاستطاعة، والاستطاعة أخص من القدرة.\n(اللغات) ."},{"id":"furuq-lughawiyya:60","bookId":"furuq-lughawiyya","type":"section","seq":60,"chapter":"* (أ) *","title":"172 - الفرق بين الاستكبار والتكبر (1) : الاول: طلب الكبر من غير استحقاق.","page":"ج1 ص48","text":"والثاني: قد يكون باستحقاق.\nولذلك جاز في صفة الله تعالى:\nالمتكبر.\nولا يجوز: المستكبر.\n(اللغات) ."},{"id":"furuq-lughawiyya:61","bookId":"furuq-lughawiyya","type":"section","seq":61,"chapter":"* (أ) *","title":"173 - الفرق بين الاستماع والسماع (2) : قال الفيومي: \" يقال \" استمع \" لما كان بقصد، لانه لا يكون إلا بالاصغاء - وهو الميل -.","page":"ج1 ص48","text":"و\" سمع \" يكون بقصد، وبدونه \" (3) .\nانتهى.\nقلت: ويؤيده قوله تعالى: \" وإذا قرئ القرآن فاستمعوا له \" (4) .\nإشارة إلى قصدهم إلى ذلك، وميلهم إلى السماع الخالي عن القصد.\n(اللغات) ."},{"id":"furuq-lughawiyya:62","bookId":"furuq-lughawiyya","type":"section","seq":62,"chapter":"* (أ) *","title":"174 - الفرق بين الاستماع والسمع: أن الاستماع هو استفادة المسموع بالاصغاء إليه ليفهم ولهذا لا يقال إن الله يستمع، وأما السماع فيكون اسما للمس","page":"ج1 ص49","text":"والتسمع طلب السمع مثل التعلم طلب العلم."},{"id":"furuq-lughawiyya:63","bookId":"furuq-lughawiyya","type":"section","seq":63,"chapter":"* (أ) *","title":"175 - الفرق بين الاستنكاف والاستكبار: أن في الاستنكاف معنى الانفة وقد","page":"ج1 ص49","text":"يكون الاستكبار طلب من غير أنفة وقال تعالى: \" ومن يستنكف عن عبادته ويستكبر \" (1) أي يستنكف عن الاقرار بالعبودية ويستكبر عن الاذعان بالطاعة."},{"id":"furuq-lughawiyya:64","bookId":"furuq-lughawiyya","type":"section","seq":64,"chapter":"* (أ) *","title":"178 - الفرق بين الاستواء والاستقامة: أن الاستواء هو تماثل أبعاض الشئ","page":"ج1 ص50","text":"واشتقاقه من السي وهو المثل كأن بعضه سي بعض أي مثله، ونقيضه التفاوت وهو أن يكون بعض الشئ طويلا وبعضه قصيرا وبعضه تاما وبعضه ناقصا.\nوالاستقامة الاستمرار على سنن واحد ونقيضها الاعوجاج وطريق مستقيم لا اعوجاج فيه."},{"id":"furuq-lughawiyya:65","bookId":"furuq-lughawiyya","type":"section","seq":65,"chapter":"* (أ) *","title":"185 - الفرق بين الاسم والتسمية والاسم واللقب: أن الاسم فيما قال ابن السراج: ما دل على معنى مفرد شخصا كان أو غير شخص.","page":"ج1 ص50","text":"وفيما قال أبو الحسن علي بن عيسى رحمه الله: كلمة تدل على معنى دلالة الاشارة واشتقاقه من السمو وذلك أنه كالعلم ينصب ليدل على صاحبه.\nوقال\nأبو العلاء المازني رحمه الله: الاسم قول دال على المسمى غير مقتض لزمان من حيث هو اسم.\nوالفعل ما اقتضى زمانا أو تقديره من حيث هو فعل.\nقال والاسم اسمان اسم محض وهو قول دال دلالة الاشارة واسم صفة وهو قول دال دلالة الافادة.\nوقال علي بن عيسى: التسمية تعليق الاسم بالمعنى على جهة الابتداء.\nوقال أبو العلاء: اللقب ما غلب على المسمى من اسم علم بعد اسمه الاول فقولنا زيد ليس بلقب لانه أصل فلا لقب إلا علم وقد يكون علم ليس بلقب.\nوقال النحويون: الاسم الاول هو الاسم المستحق بالصورة مثل رجل وظبي وحائط وحمار، وزيد هو اسم ثان.\nواللقب ما غلب على المسمى من اسم ثالث.\nواما النبز فإن المبرد قال: هو اللقب الثابت قال: والمنابزة الاشاعة باللقب يقال لبني فلان نبز يعرفون به إذا كان لهم لقب ذائع (1) شائع ومنه قوله تعالى \" ولا تنابزوا بالالقاب \" (2) وكان هذا من أمر الجاهلية فنهى الله تعالى عنه.\nوقيل النبز ذكر اللقب يقال نبز ونزب كما يقال جذب وجبذ، وقالوا في تفسير الآية هو أن يقول للمسلم يا يهودي أو يا نصراني فينسبه إلى ما تاب منه."},{"id":"furuq-lughawiyya:66","bookId":"furuq-lughawiyya","type":"section","seq":66,"chapter":"* (أ) *","title":"187 - الفرق بين الاسم الشرعي والاسم العرفي: أن الاسم الشرعي ما نقل عن أصله في اللغة فسمي به فعل أو حكم حدث في الشرع نحو الصلاة والزكاة والصو","page":"ج1 ص51","text":"وكانت هذه أسماء تجري قبل الشرع على أشياء ثم جرت في الشرع\nعلى أشياء اخر وكثر استعمالها حتى صارت حقيقة فيها وصار استعمالها على الاصل مجازا، ألا ترى أن استعمال الصلاة اليوم في الدعاء مجاز وكان هو الاصل، والاسم العرفي ما نقل عن بابه بعرف الاستعمال نحو قولنا دابة وذلك أنه قد صار في العرف اسما لبعض ما يدب وكان في الاصل\nاسما لجميعه، وكذلك الغائط كان اسما للمطمئن من الارض ثم صار في العرف اسما لقضاء الحاجة حتى ليس يعقل عند الاطلاق سواه، وعند الفقهاء أنه إذا ورد عن الله خطاب قد وقع في اللغة لشئ واستعمل في العرف لغيره ووضع في الشرع لآخر، فالواجب حمله على ما وضع في الشرع لان ما وضع له في اللغة قد انتقل عنه وهو الاصل فما استعمل فيه بالعرف أولى بذلك، وإذا كان الخطاب في العرف لشئ وفي اللغة بخلافه وجب حمله على العرف لانه أولى كما أن اللفظ الشرعي يحمله على ما عدل عنه، وإذا حصل الكلام مستعملا في الشريعة أولى على ما ذكر قبل، وجميع أسماء الشرع تحتاج إلى بيان نحو قوله تعالى \" وأقيموا الصلاة وآتوا الزكاة \" (1) إذ قد عرف بدليل أنه اريد بها غير ما وضعت له في اللغة وذلك على ضربين: أحدهما يراد به ما لم يوضع له البتة نحو الصلاة والزكاة، والثاني يراد به ما وضع له في اللغة لكنه قد جعل اسما في الشرع لما يقع منه على وجه مخصوص أو يبلغ حدا مخصوصا فصار كأنه مستعمل في غير ما وضع له وذلك نحو الصيام والوضوء وما شاكله."},{"id":"furuq-lughawiyya:67","bookId":"furuq-lughawiyya","type":"section","seq":67,"chapter":"* (أ) *","title":"191 - الفرق بين الاشتياط والغضب: أن الاشتياط خفة تلحق الانسان عند الغضب وهو في الغضب كالطرب في الفرح، وقد يستعمل الطرب في الخفة التي تعتري م","page":"ج1 ص53","text":"أن يقال الاشتياط سرعة الغضب.\nقال الأصمعي: يقال ناقة مشياط إذا كانت سريعة السمن، ويقال استشاط الرجل إذا التهب من الغضب كأن الغضب قد طار فيه."},{"id":"furuq-lughawiyya:68","bookId":"furuq-lughawiyya","type":"section","seq":68,"chapter":"* (أ) *","title":"الفرق بين الاصعاد والصعود","page":"ج1 ص53","text":"أن الاصعاد في مستوى الارض، والصعود في الارتفاع يقال أصعدنا من الكوفة إلى خراسان وصعدنا في الدرجة والسلم والجبل."},{"id":"furuq-lughawiyya:69","bookId":"furuq-lughawiyya","type":"section","seq":69,"chapter":"* (أ) *","title":"197- الفرق بين الاصعاد والصعود","page":"ج1 ص53","text":"الفرق بين الاصعاد والصعود (1) : قد فرق بينهما: بأن الاصعاد يكون\nفي مستو من الارض، والصعود: في ارتفاع.\nيقال: أصعدنا من مكة: إذا ابتدأ السفر (1) ومثله قول الشاعر (2) : هواي مع الركب اليمانين مصعد * جنيب وجثماني بمكة موثق قلت: ويدل عليه قوله تعالى: \" إذ تصعدون ولا تلوون على أحد \" (3) إشارة إلى ذهابهم (4) في وادي أحد، للإنهزام فرارا من العدو.\n(اللغات) ."},{"id":"furuq-lughawiyya:70","bookId":"furuq-lughawiyya","type":"section","seq":70,"chapter":"* (أ) *","title":"203 - الفرق بين الاضطراب والحركة: أن الاضطراب حركات متوالية في جهتين مختلفتين وهو افتعال من ضرب، يقال اضطرب الشئ كأن بعضه يضرب بعضا فيتمحص.","page":"ج1 ص54","text":"ولا يكون الاضطراب إلا مكروها فيما هو حقيقة\nفيه أو غير حقيقة، ألا ترى أنه يقال اضطربت السفينة واضطرب حال زيد واضطرب الثوب، وكل ذلك مكروه وليس الحركة كذلك."},{"id":"furuq-lughawiyya:71","bookId":"furuq-lughawiyya","type":"section","seq":71,"chapter":"* (أ) *","title":"216 - الفرق بين الاعتقاد والعلم: أن الاعتقاد هو اسم لجنس الفعل على أي","page":"ج1 ص56","text":"وجه وقع اعتقاده، والاصل فيه أنه مشبه بعقد الحبل والخيط فالعالم بالشئ على ما هو به كالعاقد المحكم لما عقده ومثل ذلك تسميتهم العلم بالشئ حفظا له ولا يوجب ذلك أن يكون كل عالم معتقدا لان اسم الاعتقاد اجري على العلم مجازا وحقيقة العالم هو من يصح منه فعل ما علمه متيقنا (1) إذا كان قادار عليه."},{"id":"furuq-lughawiyya:72","bookId":"furuq-lughawiyya","type":"section","seq":72,"chapter":"* (أ) *","title":"221 - الفرق بين الأعجمي والعجمي (1) : الاعجمي: الذي يمتنع لسانه من العربية، ولا يفصح، وإن كان نازلا بالبادية، والعجمي: منسوب إلى العجم، وإن","page":"ج1 ص57","text":"قاله صاحب أدب الكاتب، قلت: ويدل عليه قوله تعالى \" ولو نزلناه على بعض الاعجمين \" (2) .\nأي من لا يفصح القراءة.\n(اللغات) ."},{"id":"furuq-lughawiyya:73","bookId":"furuq-lughawiyya","type":"section","seq":73,"chapter":"* (أ) *","title":"223 - الفرق بين الإعدام والفقر: أن الاعدام أبلغ في الفقر: وقال أهل اللغة: المعدم الذي لا يجد شيئا، وأصله من العدم خلاف الوجود وقد أعدم","page":"ج1 ص57","text":"كأنه صار ذا عدم، وقيل في خلاف الوجود عدم للفرق بين المعنيين ولم يقل عدمه الله وإنما قيل أعدمه الله، وقيل في خلافه قد وجد ولم يقل وجده الله وإنما قيل أوجده الله، وقال بعضهم: الاعدام فقر (3) بعد غنى."},{"id":"furuq-lughawiyya:74","bookId":"furuq-lughawiyya","type":"section","seq":74,"chapter":"* (أ) *","title":"224 - الفرق بين الأعرابي والعربي (4) : الاعرابي: البدوي، وإن كان بالحضر","page":"ج1 ص58","text":"والعربي: منسوب إلى العرب، وإن لم يكن بدويا فبينهما عموم من وجه.\n(اللغات) ."},{"id":"furuq-lughawiyya:75","bookId":"furuq-lughawiyya","type":"section","seq":75,"chapter":"* (أ) *","title":"الفرق بين الأعلام والأخبار","page":"ج1 ص58","text":"(1) : قال الطبرسي: الفرق بينهما أن الاعلام قد يكون بخلق العلم الضروري في القلب، كما خلق الله - سبحانه - من كمال العقل والعلم بالمشاهدات، وقد يكون بنصب الأدلة على الشئ.\nوالاخبار: هو إظهار الخبر، علم به أو لم [8 / ب] يعلم، ولا يكون مخبرا بما يحدثه من العلم في القلب كما يكون معلما بذلك.\n(اللغات)"},{"id":"furuq-lughawiyya:76","bookId":"furuq-lughawiyya","type":"section","seq":76,"chapter":"* (أ) *","title":"231- الفرق بين الأعلام والإخبار","page":"ج1 ص58","text":"الفرق بين الأعلام والإخبار: أن الاعلام التعريض لان يعلم الشئ وقد يكون ذلك بوضع العلم في القلب لان الله تعالى قد علمنا ما اضطررنا\nإليه، ويكون الاعلام بنصب الدلالة والاخبار والاظهار للخبر علم به أو لم يعلم، ولا يكون الله مخبرا بما يحدثه من العلم في القلب."},{"id":"furuq-lughawiyya:77","bookId":"furuq-lughawiyya","type":"section","seq":77,"chapter":"* (أ) *","title":"232 - الفرق بين الاعلام والتعلم (1) : قيل: هما بمعنى.","page":"ج1 ص59","text":"كما تقول: علمت، وأعلمت، وفهمت وأفهمت.\nوقال بعضهم: بينهما فرق.\nفمعنى تعلم: تسبب إلى ما به يعلم من النظر في الادلة، وليس في (أعلم) هذا المعنى.\nفقد يقال ذلك لما يعلم بلا تأمل، كقولك: اعلم أن الفعل يدل على الفاعل، وتقول في الاول: تعلم النحو والفقه.\nانتهى.\nقلت: ويمكن أن يعتبر الفرق بوجه آخر، ولعله الانسب وهو أن التعلم يعتبر في مفهومه التكرار حتى يصير ذلك الشئ ملكة بخلاف الاعلام، إذ يعتبر في مفهومه ذلك، فإنه قريب من معنى الاخبار أو بما معناه، كما مر من قريب (2) (اللغات) ."},{"id":"furuq-lughawiyya:78","bookId":"furuq-lughawiyya","type":"section","seq":78,"chapter":"* (أ) *","title":"234 - الفرق بين الاعلى وفوق: أن أعلى الشئ منه يقال هو في أعلى النخلة يراد أنه في نهاية قامتها، وتقول السماء فوق الارض فلا يقتضي ذلك أن تكون","page":"ج1 ص60","text":"الشئ منه وتحته ليس منه ألا ترى انه يقال وضعته تحت الكوز ولا يقال وضعته أسفل الكوز بهذا المعنى ويقال أسفل البئر ولا يقال تحت البئر."},{"id":"furuq-lughawiyya:79","bookId":"furuq-lughawiyya","type":"section","seq":79,"chapter":"* (أ) *","title":"238 - الفرق بين الافشاء والاظهار: أن الافشاء كثرة الاظهار ومنه أفشى القوم","page":"ج1 ص60","text":"إذا كثر ما لهم مثل أمشوا والفشاء كثرة المال ومثله المشاء (1) وقريب منه النماء والضياء وقد أنمى القوم وأصبوا وأمشوا وأفشوا إذا كثر ما لهم، ولهذا يقال فشى الخير في القوم أو الشر إذا ظهر بكثرة وفشى فيها الحرب\nإذا ظهر وكثر، والاظهار يستعمل في كل شئ والافشاء لا يصح إلا فيما لا تصح فيه الكثرة ولا يصح في ذلك ألا ترى انك تقول هو ظاهر المروءة ولا تقول كثير المروءة."},{"id":"furuq-lughawiyya:80","bookId":"furuq-lughawiyya","type":"section","seq":80,"chapter":"* (أ) *","title":"244 - الفرق بين الافقار والعرى: أن الافقار مصدر فقر الرجل ظهر بعيره ليركبه","page":"ج1 ص61","text":"ثم يرده، مأخوذ من الفقار وهو عظم الظهر يقال أفقرته البعير أي أمكنته من فقاره."},{"id":"furuq-lughawiyya:81","bookId":"furuq-lughawiyya","type":"section","seq":81,"chapter":"* (أ) *","title":"252 - الفرق بين الاقتضاء والطلب: أن الاقتضاء على وجهين: أحدهما اقتضاء الدين وهو طلب أدائه والآخر مطالبة المعني لغيره كأنه ناطق بأنه لابد منه","page":"ج1 ص62","text":"المقدور والمقدور القادر وكاقتضاء وجود الحركة للمحل من غير أن يقتضي وجود المحل وجود الحركة لانه قد يكون فيه السكون واقتضاء الشئ لغيره قد يكون بجعل جاعل وبغير جعل جاعل وذلك نحو ضرب يقتضي ذكر الضارب بعده بوضع واضع اللغة له على هذه الجهة، وضرب لا يقتضي ذلك وكلاهما يدل عليه."},{"id":"furuq-lughawiyya:82","bookId":"furuq-lughawiyya","type":"section","seq":82,"chapter":"* (أ) *","title":"الفرق بين الاقرار والاعتراف","page":"ج1 ص63","text":"أن الاقرار فيما قاله أبو جعفر الدامغاني: حاصله إخبار عن شئ ماض.\nوهو في الشريعة جهة ملزمة للحكم والدليل على أنه جهة ملزمة قوله تعالى \" يا أيها الذين آمنوا إذا تداينتم بدين \" إلى قوله \" وليملل الذي عليه الحق \" (1) فأمر بالاصغاء إلى قول من عليه الحق في حال الاستيثاق والاشهاد ليثبت عليه ذلك فلولا أنه جهة ملزمة لم يكن لاثباته فائدة، وقال بعضهم: الاعتراف مثل الاقرار إلا أنه يقتضي تعريف صاحبه الغير أنه قد التزم ما اعترف به، وأصله من المعرفة، وأصل الاقرار من التقرير وهو تحصيل ما لم يصرح به القول، ولهذا اختار أصحاب الشروط أقربه ولم يختاروا اعترف به، قال الشيخ أبو هلال أيده الله تعالى: يجوز أن يقر بالشئ وهو لا يعرف أنه أقربه ويجوز أن يقر بالباطل الذي لا أصل له ولا يقال لذلك اعتراف إنما الاعتراف هو الاقرار الذي صحبته المعرفة بما أقر به مع الالتزام له، ولهذا يقال: الشكر اعتراف بالنعمة ولا يقال إقرار بها لانه لا يجوز أن يكون شكرا إلا إذا\nقارنت المعرفة موقع المشكور وبالمشكور له في أكثر الحال فكل اعتراف إقرار وليس كل إقرار اعتراف، ولهذا اختار أصحاب الشروط ذكر الاقرار لانه أعم، ونقيض الاعتراف الجحد ونقيض الاقرار الانكار."},{"id":"furuq-lughawiyya:83","bookId":"furuq-lughawiyya","type":"section","seq":83,"chapter":"* (أ) *","title":"256 - الفرق بين الاقرار والاعتراف (1) : الاقرار: هو التكلم بالحق، اللازم على النفس، مع توطين النفس على الانقياد والاذعان.","page":"ج1 ص64","text":"ويشهد له قوله تعالى: \" ثم أقررتم وأنتم تشهدون \" (2) .\nوالاعتراف: هو التكلم بذلك وإن لم يكن معه توطين، أو إن الاعتراف هو ما كان باللسان، والاقرار قد يكون به، وبغيره، بل بالقرائن، كما في حق الاخرس.\nوينطبق على الوجهين تسمية الشهادة بالتوحيد: إقرارا، لا اعترافا، كما لا يخفى.\nوأهل اللغة لم يفرقوا بينهما.\n(اللغات) ."},{"id":"furuq-lughawiyya:84","bookId":"furuq-lughawiyya","type":"section","seq":84,"chapter":"* (أ) *","title":"262 - الفرق بين الالجاء والاضطرار: أن الالجاء يكون فيما لا يجد الانسان منه","page":"ج1 ص65","text":"بدا من أفعال نفسه مثل أكل الميتة عند شدة الجوع ومثل العدو على الشوك عند مخافة السبع فيقال إنه ملجأ إلى ذلك، وقد يقال إنه مضطر إليه أيضا، فأما الفعل الذي يفعل في الانسان وهو يقصد الامتاع منه مثل حركة المرتعش فإنه يقال هو مضطر إليه ولا يقال ملجأ إليه، وإذا لم يقصد الامتناع منه لم يسم اضطرارا كتحريك الطفل يد الرجل القوي، ونحو هذا قول علي بن عيسى: إن الالجاء هو أن يحمل الانسان على أن يفعل، والضرورة أن يفعل فيه ما لا يمكنه الانصراف عنه من الضر والضر ما فيه ألم قال والاضطرار خلاف الاكتساب ألا ترى أنه يقال له باضطرار عرفت هذا أم باكتساب؟ ولا يقع الالجاء هذا الموقع، وقيل هذا الاصطلاح من المتكلمين قالوا فأما أهل اللغة فإن الالجاء والاضطرار عندهم سواء، وليس كذلك لان كل واحد منهما على صيغة ومن أصل وإذا اختلفت الصيغ والاصول اختلفت المعاني لا محالة، والاجبار يستعمل في الاكراه، والالجاء يستعمل في فعل العبد على وجه لا يمكنه أن ينفك منه، والمكره من فعل ما ليس له إليه داع وإنما يفعله خوف الضرر، والالجاء ما تشتد دواعي الانسان إليه على وجه لا يجوز أن يقع مع حصول تلك الدواعي."},{"id":"furuq-lughawiyya:85","bookId":"furuq-lughawiyya","type":"section","seq":85,"chapter":"* (أ) *","title":"263 - الفرق بين الاضطرار والالجاء (1) : قال بعض المحققين في الفرق بينهما إن الاضطرار: كون الشئ بحيث لا يقدر الانسان على الامتناع منه بسبب مو","page":"ج1 ص65","text":"كقوله\nسبحانه: \" ثم اضطره إلى عذاب النار \" (1) فإن أهل جهنم - وإن كانوا\nفي أنفسهم قادرين على الامتناع من دخولها - إلا أنهم مكرهون على ذلك.\nوالالجاء: قد يكون بالاختيار لبقاء القدرة على الامتناع، كما لو انحصر علاج المريض بالعضد مثلا، فإنه يقال: هو ملجأ إلى العضد، مع أن قدرته على الامتناع عنه غير مسلوبة.\nوالحاصل: أن الاضطرار أخص من الالجاء لاشتراط زوال الاختيار في الاول دون الثاني.\n(اللغات) ."},{"id":"furuq-lughawiyya:86","bookId":"furuq-lughawiyya","type":"section","seq":86,"chapter":"* (أ) *","title":"268 - الفرق بين إلا ولكن: أن الاستثناء هو تخصيص صيغة عامة فأما لكن فهي تحقيق إثبات بعد نفي أو نفي بعد إثبات تقول ما جاءني زيد لكن عمرو جاءني","page":"ج1 ص66","text":"وأتى عمرو لكن زيد لم يأت فهذا أصل لكن، وليس باستثناء في التحقيق، وقال ابن السراج: الاستثناء هو إخراج بعض من كل."},{"id":"furuq-lughawiyya:87","bookId":"furuq-lughawiyya","type":"section","seq":87,"chapter":"* (أ) *","title":"278 - الفرق بين الالهام والمعرفة الضرورية: أن الالهام ما يبدو في القلب من المعارف بطريق الخير ليفعل وبطريق الشر ليترك، والمعارف الضرورية على","page":"ج1 ص67","text":"والثالث عند الاخبار المتواترة والرابع أوائل العقل."},{"id":"furuq-lughawiyya:88","bookId":"furuq-lughawiyya","type":"section","seq":88,"chapter":"* (أ) *","title":"279 - الفرق بين الالهام والوحي (1) : قيل: الالهام يحصل من الحق تعالى من غير واسطة الملك.","page":"ج1 ص68","text":"والوحي: من خواص الرسالة، والالهام من خواص الولاية.\nوأيضا الوحي مشروط بالتبليغ، كما قال تعالى: \" يا أيها الرسول بلغ ما أنزل إليك من ربك \" (2) دون الالهام.\nومنهم من جعل الالهام نوعا من الوحي، وقال في الغريب: \" يقال لما يقع في النفس من عمل الخير: إلهام.\nولها يقع من الشر،\nوما لا خير فيه: وسواس.\nولما يقع من الخوف: إيحاش، ولما يقع من تقدير نيل الخير: أمل.\nولما يقع من التقدير الذي لا على الانسان ولا له: خاطر \".\nانتهى.\nوقال بعض المحققين: \" الوحي فيضان العلم من الله إلى النبي بواسطة الملك.\nوالالهام: الالقاء، في قلبه ابتداء.\nوالاول يختص بالانبياء عليهم السلام، وبينه قوله سبحانه \" قل إنما أنا بشر مثلكم يوحى إلي \" (3) .\nفإن الجملة الاخيرة إنما سيقت لبيان المايز، وأن المماثلة التي دلت عليها الجملة الاولى ليست في الصفات الجسمانية والنفسانية معا بل في الاولى خاصة \" انتهى.\nأقول: وقد يطلق الوحي على الالهام كما في قوله تعالى: \" وإذا أوحيت إلى الحواريين \" (4) .\nفإنهم لم يكونوا أنبياء.\nوقوله تعالى: \" وأوحينا إلى ام موسى \" (1) .\nوقوله: \" وأوحى ربك إلى النحل \" (2) .\nوهذا الاطلاق إما بحسب اللغة أو على سبيل التجوز (3) .\n(اللغات)"},{"id":"furuq-lughawiyya:89","bookId":"furuq-lughawiyya","type":"section","seq":89,"chapter":"* (أ) *","title":"281 - الفرق بين الامارة والعلامة: أن الامارة هي العلامة الظاهرة، ويدل على ذلك أصل الكلمة وهو الظهور، ومنه قيل أمر الشئ إذا كثر ومع الكثرة","page":"ج1 ص69","text":"ظهور الشأن، ومن ثم قيل الامارة لظهور الشأن، وسميت المشورة أمارا لان الرأي يظهر بها وائتمر القوم إذا تشاوروا قال الشاعر: * ففيم الامار فيكم والامار *"},{"id":"furuq-lughawiyya:90","bookId":"furuq-lughawiyya","type":"section","seq":90,"chapter":"* (أ) *","title":"285 - الفرق بين الامداد والمد (4) : قال المفضل: ما كان منه بطريق التقوية، والاعانة يقال فيه: أمده، يمده، إمدادا.","page":"ج1 ص70","text":"وما كان بطريق الزيادة يقال فيه: يمده، مدا، ومنه قوله تعالى: \" ويمدهم في طغيانهم يعمهون \" (1) وقوله سبحانه: \" ونمد له من العذاب مدا \" (2) .\nوالامداد في الخير، كما في قوله تعالى: \" وأمددناكم بأموال وبنين \" (3) .\nوقيل: المد: إعانة الرجل القوم بنفسه.\nوالامداد إعانته إياهم (4)\nبغيره.\nيقال: مد زيد القوم أي صار لهم مددا (5) .\nوأمدهم: أعانهم بمدد.\nوإلى هذا القول مال صاحب القاموس كما يظهر من تضاعيف كلامه (6) .\n(اللغات) ."},{"id":"furuq-lughawiyya:91","bookId":"furuq-lughawiyya","type":"section","seq":91,"chapter":"* (أ) *","title":"287 - الفرق بين الامر والخبر: أن الامر لا يتناول الآمر لانه لا يصح أن يأمر الانسان نفسه ولا أن يكون فوق نفسه في الرتبة فلا يدخل الآمر مع غير","page":"ج1 ص71","text":"وسلم تتعداه إلى غيره من حيث كان لا يجوز أن يختص بها، وفصلوا بينها وبين أفعاله بذلك فقالوا أفعاله لا تتعداه إلا بدليل، وقال بعضهم: بل حكمنا وحكمه في فعله سواء فإذا فعل شيئا فقد صار كأنه قال لنا إنه مباح، قال ويختص العام بفعله كما يختص بقوله.\nويفرق بينهما أيضا من وجه آخر وهو أن النسخ يصح في الامر ولا يصح في الخبر عند أبي علي\nوأبي هاشم رحمهما الله تعالى: وذهب أبو عبد الله البصري رحمه الله إلى أن النسخ يكون في الخبر كما يكون في الامر قال وذلك مثل أن يقول الصلاة تلزم المكلف في المستقبل ثم يقول بعد مدة إن ذلك لا يلزمه، وهذا أيضا عند القائلين بالقول الاول أمر وإن كان لفطه لفظ الخبر.\nوأما الخبر عند حال الشئ الواحد المعلوم أنه لا يجوز خروجه عن تلك الحال فان النسخ لا يصح في ذلك عند الجميع نحو الخبر عن صفات الله بأنه عالم وقادر."},{"id":"furuq-lughawiyya:92","bookId":"furuq-lughawiyya","type":"section","seq":92,"chapter":"* (أ) *","title":"290 - الفرق بين الاملاء والاستدراج (2) : الاملاء: هو الامهال والتأخير.","page":"ج1 ص72","text":"قال تعالى: \" وأملي لهم إن كيدي متين \" (1) .\nوالاستدراج: هو أنه كلما جدد العبد خطيئة جدد الله له نعمة، وأنساه (2) الاستغفار إلى أن يأخذه قليلا قليلا (3) ولا يباغته.\nوروي عن أبي عبد الله عليه السلام في تفسير، حيث سئل في قوله تعالى: \" سنستدرجهم من حيث لا يعلمون \" (4) .\nفقال: \" هو العبد يذنب الذنب فيجدد له النعمة معه، تلهية تلك النعمة عن الاستغفار من ذلك الذنب \".\nوعلى هذا هما (5) عموم وخصوص، إذ كل استدراج إملاء وليس كل إملاء استدراجا.\n(اللغات) ."},{"id":"furuq-lughawiyya:93","bookId":"furuq-lughawiyya","type":"section","seq":93,"chapter":"* (أ) *","title":"291 - الفرق بين الامل والطمع (6) : قيل: أكثر ما يستعمل الامل فيما يستبعد حصوله، فإن من عزم على سفر إلى بلد بعيد يقول: \" أملت الوصول إليه \" و","page":"ج1 ص72","text":"وقد يكون الامل بمعنى الطمع.\nوأما الرجاء: فهو بين الامل والطمع، فإن الراجي قد يخاف أن لا يحصل مأموله.\nولهذا يستعمل بمعنى الخوف (7) .\nومنه قوله تعالى: \" من كان يرجوا لقاء الله فإن أجل الله لآت \" (1) .\nأي يخافه.\nوقال بعضهم: الامل يكون في الممكن والمستحيل.\nوالرجاء يختص\nبالممكن.\nقلت: الصحيح أن هذا الفرق بين التمني والرجاء.\nوأما الامل فلا يكون في المستحيل.\n(اللغات) ."},{"id":"furuq-lughawiyya:94","bookId":"furuq-lughawiyya","type":"section","seq":94,"chapter":"* (أ) *","title":"298 - الفرق بين الاناة والحلم: أن الاناة هي البطء في الحركة وفي مقاربة الخطو في المشي ولهذا يقال للمرأة البدينة أناة قال الشاعر","page":"ج1 ص74","text":"رمته أناة من ربيعة عامر * نؤم الضحى في مأتم أي مأثم ويكون المراد بها في صفات الرجال المتمهل في تدبير الامور ومفارقة التعجل (1) فيها كأنه يقاربها مقاربة لطيفة من قولك أنى الشئ إذا قرب وتأنى أي تمهل ليأخذ الامر من قرب، وقال بعضهم الاناة السكون عند الحالة المزعجة."},{"id":"furuq-lughawiyya:95","bookId":"furuq-lughawiyya","type":"section","seq":95,"chapter":"* (أ) *","title":"301 - الفرق بين الانام والناس: أن الانام على ما قال بعض العلماء: يقتضي تعظيم شأن المسمى من الناس قال الله عزوجل \" الذين قال لهم الناس ان الن","page":"ج1 ص75","text":"أهل مكة قد جمعوا لكم، ولا تقول جاءني الانام تريد بعض الانام وجمع الانام آنام، قال عدي بن زيد: إن الانسي قلنا جمع نعلمه فيما من الانام والامم جمع امة وهي النعمة."},{"id":"furuq-lughawiyya:96","bookId":"furuq-lughawiyya","type":"section","seq":96,"chapter":"* (أ) *","title":"303 - الفرق بين الانتظار والامهال: أن الانتظار مقرون بما يقع فيه النظر","page":"ج1 ص75","text":"والامهال مبهم."},{"id":"furuq-lughawiyya:97","bookId":"furuq-lughawiyya","type":"section","seq":97,"chapter":"* (أ) *","title":"307 - الفرق بين الانتقال والزوال: أن الانتقال فيما ذكر علي بن عيسى: يكون في الجهات كلها، والزوال يكون في بعض الجهات دون بعض، ألا ترى أنه لا","page":"ج1 ص75","text":"تزول وذلك لما يظن من بطء حركتها إذا حصلت هناك، ولهذا قال شاعرهم: وزالت زوال الشمس عن مستقرها * فمن مخبري في أي أرض غروبها وليس كذلك الانتقال."},{"id":"furuq-lughawiyya:98","bookId":"furuq-lughawiyya","type":"section","seq":98,"chapter":"* (أ) *","title":"309 - الفرق بين الانجاء والتنجية (1) : كلاهما بمعنى التخليص من المهلكة.","page":"ج1 ص76","text":"(*) وفرق بعضهم بينهما فقال: الانجاء في الخلاص قبل الوقوع في المهلكة * (2) .\nوالتنجية يستعمل في الخلاص بعد الوقوع في المهلكة.\nقلت: ويؤيد الاول قوله تعالى: \" ثم صدقناهم الوعد فأنجيناهم ومن نشاء وأهلكنا المسرفين \" (3) .\nفإن المراد بالمنجين: الانبياء، وقد أنجاهم الله من العذاب قبل وقوعه على الامم.\nويؤيد الثاني قوله تعالى: \" وإذ نجيناكم من آل فرعون يسومونكم سوء العذاب \" (4) .\nفإن إنجاء بني إسرائيل من آل فرعون وذبح أبنائهم، وتحميلهم الاعمال الشاقة كان بعد مدة من الزمان.\nهذا وقد يستعمل كل منهما في موضع الآخر إما مجازا أو بحسب اللغة.\n(اللغات) ."},{"id":"furuq-lughawiyya:99","bookId":"furuq-lughawiyya","type":"section","seq":99,"chapter":"* (أ) *","title":"310 - الفرق بين الانذار والاعلام (1) : الانذار: إعلام معه تخويف، فكل منذر معلم، وليس بالعكس.","page":"ج1 ص77","text":"ويوصف القديم سبحانه بأنه منذر، لان الاعلام يجوز وصفه به، والتخويف أيضا كذلك لقوله تعالى: \" ذلك يخوف الله به عباده \" (2) فإذا جاز وصفه بالمعنيين، جاز وصفه بما يشتمل\nعليهما، قاله الطبرسي.\n(اللغات) ."},{"id":"furuq-lughawiyya:100","bookId":"furuq-lughawiyya","type":"section","seq":100,"chapter":"* (أ) *","title":"312 - الفرق بين الانذار والوصية: أن الانذار لا يكون إلا منك لغيرك وتكون الوصية منك لنفسك ولغيرك تقول أوصيت نفسي كما تقول أوصيت غيري ولا تقول","page":"ج1 ص77","text":"والوصية تكون بالحسن والقبيح لانه يجوز أن يوصي الرجل الرجل بفعل القبيح كما يوصي بفعل الحسن ولا يجوز أن\nينذره إلا فيما هو قبيح، وقيل النذارة نقيضة البشارة وليست الوصية نقيضة البشارة."},{"id":"furuq-lughawiyya:101","bookId":"furuq-lughawiyya","type":"section","seq":101,"chapter":"* (أ) *","title":"313 - الفرق بين الانزال والتنزيل (1) : قال بعض المفسرين: الانزال: دفعي، والتنزيل: للتدريج.","page":"ج1 ص78","text":"قلت: ويدلك عليه قوله تعالى: \" نزل عليك الكتاب بالحق مصدقا لما بين يديه وأنزل التوراة والانجيل \" (2) .\nحيث خص القرآن بالتنزيل،\nلنزوله منجما، والكتابين بالانزال لنزولهما دفقة.\nوأما قوله تعالى: \" الحمد لله الذي أنزل على عبده الكتاب \" (3) فالمراد هناك (4) مطلقا من غير اعتبار التنجيم، وكذا قوله تعالى: \" إنا أنزلناه في ليلة القدر \" (5) .\nفإن المراد إنزاله إلى سماء الدنيا (6) ، تم تنزيله منجما على النبي صلى الله عليه وآله في ثلاث وعشرين كما وردت به الروايات.\n(اللغات) ."},{"id":"furuq-lughawiyya:102","bookId":"furuq-lughawiyya","type":"section","seq":102,"chapter":"* (أ) *","title":"315 - الفرق بين الانسي والانسان: أن الانسي يقتضي مخالفة الوحشي ويدل على هذا أصل الكلمة وهو الانس والانس خلاف الوحشة، والناس يقولون إنسي ووحش","page":"ج1 ص79","text":"مخالفته البهيمة فيذكرون أحدهما في مضادة الآخر ويدل على ذلك أن اشتقاق الإنسان من النسيان وأصله إنسيان فلهذا يصغر فيقال انيسان، والنسيان لا يكون إلا بعد العلم فسمي الانسان إنسانا لانه ينسى ما علمه، وسميت البهيمة بهيمة لانها أبهمت على العلم والفهم ولا تعلم ولا تفهم فهي خلاف الانسان، والانسانية خلاف البهيمية في الحقيقة\nوذلك أن الانسان يصح أن يعلم إلا أنه ينسى ما علمه والبهيمة لا يصح أن تعلم."},{"id":"furuq-lughawiyya:103","bookId":"furuq-lughawiyya","type":"section","seq":103,"chapter":"* (أ) *","title":"319 - الفرق بين الانظار والتأخير (1) : قد فرق بينهما بأن الانظار: إمهال لينظر صاحبه في أمره، خلاف التقديم.","page":"ج1 ص80","text":"ويرشد إليه قوله تعالى حاكيا عن هود عليه السلام مخاطبا لقومه: \" فكيدوني جميعا ثم لا تنظرون \" (2) .\n(اللغات) ."},{"id":"furuq-lughawiyya:104","bookId":"furuq-lughawiyya","type":"section","seq":104,"chapter":"* (أ) *","title":"320 - الفرق بين الانعام والاحسان: أن الانعام لا يكون إلا من المنعم على غيره لانه متضمن بالشكر الذي يجب وجوب الدين، ويجوز إحسان الانسان إلى ن","page":"ج1 ص81","text":"أيضا من النعمة ما هو ضرر مثل التكليف نسميه نعمة لما يؤدي إليه من اللذة والسرور."},{"id":"furuq-lughawiyya:105","bookId":"furuq-lughawiyya","type":"section","seq":105,"chapter":"* (أ) *","title":"321 - الفرق بين الانعام والتمتع: أن الانعام يوجب الشكر، والتمتع كالذي يمتع الانسان بالطعام والشراب ليستنيم إليه فيتمكن من اغتصاب ماله","page":"ج1 ص81","text":"والاتيان على نفسه."},{"id":"furuq-lughawiyya:106","bookId":"furuq-lughawiyya","type":"section","seq":106,"chapter":"* (أ) *","title":"322 - الفرق بين الانعام والنعم: (1) قال الحريرى في \" درة الغواص \": قد فرقت بينهما العرب، فجعلت النعم اسما للابل خاصة، والماشية التي فيها الا","page":"ج1 ص81","text":"(اللغات) ."},{"id":"furuq-lughawiyya:107","bookId":"furuq-lughawiyya","type":"section","seq":107,"chapter":"* (أ) *","title":"325 - الفرق بين الانفاق والاعطاء: أن الانفاق هو إخراج المال من الملك","page":"ج1 ص82","text":"ولهذا لا يقال الله تعالى ينفق على العباد، وأما قوله تعالى \" ينفق كيف يشاء \" (1) فإنه مجاز لا يجوز استعماله في كل موضع وحقيقته أنه يرزق العباد على قدر المصالح، والاعطاء لا يقتضي إخراج المعطي من الملك، وذلك أنك تعطي زيدا المال ليشتري لك الشئ وتعطيه الثوب ليخيطه لك ولا يخرج عن ملكك بذلك فلا يقال لهذا إنفاق."},{"id":"furuq-lughawiyya:108","bookId":"furuq-lughawiyya","type":"section","seq":108,"chapter":"* (أ) *","title":"331 - الفرق بين قولك أنكر منه كذا وبين قولك نقم منه كذا: أن قولك أنكر منه كذا يفيد أنه لم يجوز فعله، وقولك أنكره عليه يفيد أنه بين أن ذلك لي","page":"ج1 ص83","text":"ومنه قوله تعالى \" وما نقموا منهم إلا أن يؤمنوا بالله \" (1) وذلك أنهم أنكروا منهم التوحيد وعذبوهم عليه في الاخدود المقدم ذكره في السورة وقال تعالى \" وما نقموا إلا أن أغناهم الله ورسوله من فضله \" (2) أي ما أنكروا من الرسول حين أرادوا إخراجه من المدينة وقتله إلا أنهم استغنوا وحسنت أحوالهم منذ قدم بلدهم والدليل على ذلك قوله تعالى \" وهموا بما لم ينالوا \" (3) أي هموا بقتله أو اخراجه ولم ينالوا ذلك، ولهذا المعنى سمي العقاب انتقاما والعقوبة نقمة."},{"id":"furuq-lughawiyya:109","bookId":"furuq-lughawiyya","type":"section","seq":109,"chapter":"* (أ) *","title":"335 - الفرق بين الاهل والآل: أن الاهل يكون من جهة النسب والاختصاص فمن جهة النسب قولك أهل الرجل لقرابته الادنين، ومن جهة الاختصاص قولك أهل ال","page":"ج1 ص84","text":"وقال بعضهم: الآل عيدان الخيمة وأعمدتها وآل الرجل مشبهون بذلك لانهم معتمده، والذي يرفع في الصحارى آل لانه يرتفع كما ترفع عيدان الخيمة، والشخص آل لانه كذلك."},{"id":"furuq-lughawiyya:110","bookId":"furuq-lughawiyya","type":"section","seq":110,"chapter":"* (أ) *","title":"338 - الفرق بين الاواب والرجوع (1) : قال الراغب: الاوب ضرب من الرجوع، وذلك لان الاواب لا يقال إلا في الحيوان الذي له إرادة","page":"ج1 ص84","text":"والرجوع يقال فيه، وفي غيره.\nوالاواب، كتواب: الراجع إلى الله تعالى بترك المعاصي، وفعل الطاعات، ومنه قيل: التوبة أوبة (2) .\nانتهى ملخصا.\n(اللغات) ."},{"id":"furuq-lughawiyya:111","bookId":"furuq-lughawiyya","type":"section","seq":111,"chapter":"* (أ) *","title":"343 - الفرق بين قولنا الاول وبين قولنا قبل وبين قولنا آخر وقولنا بعد: أن الاول هو من جملة ما هو أوله وكذلك الآخر من جملة ما هو آخره وليس كذل","page":"ج1 ص85","text":"وبعد لا يقتضيان زمانا ولو اقتضيا زمانا لم يصح أن يستعملا في الازمنة والاوقات بأن يقال بعضها قبل بعض أو بعده لان ذلك يوجب للزمان زمانا، وغير مستنكر وجود زمان لا في زمان ووقت لا في وقت، وقبل مضمنة بالاضافة في المعنى واللفظ وربما حذفت الاضافة اجتزاء بما في الكلام من الدلالة عليها، وأصل قبل المقابلة فكأن الحادث المتقدم قد قابل الوقت الاول والحادث المتأخر قد بعد عن الوقت الاول ما يستقبل والآخر يجئ على تفصيل الاثنين تقول أحدهما كذا والآخر كذا، والاول والآخر يقال بالاضافة يقال أوله كذا وآخره إلا في أسماء الله تعالى والاول الموجود قبل والآخر الموجود بعد."},{"id":"furuq-lughawiyya:112","bookId":"furuq-lughawiyya","type":"section","seq":112,"chapter":"* (أ) *","title":"344 - الفرق بين الايتاء والاعطاء (1) : قال الفاضل النيسابوري: في الاعطاء دليل التملك دون الايتاء.","page":"ج1 ص85","text":"انتهى.\nقلت: ويؤيده قوله تعالى: \" إنا أعطيناك الكوثر \" (1) فإنه كان له منع من شاء [9 / أ] منه كالمالك للملك.\nوأما القرآن فحيث (2) أن امته مشاركون له في فوائده، ولم يكن له منعهم منه، قال: \" ولقد آتيناك سبعا من المثاني والقرآن العظيم \" (3) .\n(اللغات) ."},{"id":"furuq-lughawiyya:113","bookId":"furuq-lughawiyya","type":"section","seq":113,"chapter":"* (أ) *","title":"345 - الفرق بين الاياب والرجوع: أن الاياب هو الرجوع إلى منتهى المقصد، والرجوع يكون لذلك ولغيره، ألا ترى انه يقال رجع إلى بعض الطريق ولا يقال","page":"ج1 ص86","text":"الليل في منزله وأنشد: البايتون قريبا من بيوتهم * ولو يشاؤون آبو الحي أو طرقوا وهذا يدل على أن الاياب الرجوع إلى منتهى القصد ولهذا قال تعالى (إن إلينا إيابهم) (4) كأن القيامة منتهى قصدهم لانها لا منزلة بعدها."},{"id":"furuq-lughawiyya:114","bookId":"furuq-lughawiyya","type":"section","seq":114,"chapter":"* (أ) *","title":"346 - الفرق بين الايثار والاختيار: أن الايثار على ما قيل هو الاختيار المقدم والشاهد قوله تعالى \" قالوا تالله لقد آثرك الله علينا \" (5) أي قد","page":"ج1 ص87","text":"على الكتان أي اخترت لبس هذا على لبس هذا وقال تعالى \" ولقد اخترناهم على علم على العالمين \" (1) أي اخترنا إرسالهم، وتقول في الفاعل مختار لكذا وفي المفعول مختار من كذا، وعندنا أن قوله تعالى \" آثرك الله علينا \" معناه أنه فضلك الله علينا، وأنت من أهل الاثرة عندي أي ممن افضله على غيره"},{"id":"furuq-lughawiyya:115","bookId":"furuq-lughawiyya","type":"section","seq":115,"chapter":"* (أ) *","title":"ب","page":"ج1 ص87","text":"تأثير الخير والنفع عنده، واخترتك أخذتك للخير الذي فيك في نفسك ولهذا يقال آثرتك بهذا الثوب وهذا الدينار ولا يقال اخترتك به وإنما يقال اخترتك لهذا الامر، فالفرق بين الايثار والاختيار بين من هذا الوجه."},{"id":"furuq-lughawiyya:116","bookId":"furuq-lughawiyya","type":"section","seq":116,"chapter":"* (أ) *","title":"350 - الفرق بين الايلام والعذاب (2) : قال الطبرسي: الفرق بينهما أن الايلام قد يكون بجزء من الالم في الوقت الواحد مقدار ما يتألم به.","page":"ج1 ص87","text":"والعذاب: الالم الذي له استمرار في أوقات، ومنه العذاب: الاستمرار في الخلق.\n(اللغات) ."},{"id":"furuq-lughawiyya:117","bookId":"furuq-lughawiyya","type":"section","seq":117,"chapter":"* (أ) *","title":"الفرق بين البأساء والضراء","page":"ج1 ص88","text":"أن البأساء ضراء معها خوف وأصلها البأس وهو الخوف يقال لا بأس عليك أي لا خوف عليك، وسميت الحرب بأسا لما فيها من الخوف والبأس الرجل إذا لحقه بأس وإذا لحقه بؤس أيضا وقال تعالى \" فلا تبتئس بما كانوا يفعلون \" (2) أي لا يلحقك بؤس، ويجوز أن يكون من البأس أي لا يلحقك خوف بما فعلوا، وجاء البأس بمعنى الاثم\nفي قولهم لا بأس بكذا أي لا إثم فيه ويقال أيضا لا بأس فيه أي هو جائز شائع."},{"id":"furuq-lughawiyya:118","bookId":"furuq-lughawiyya","type":"section","seq":118,"chapter":"* (أ) *","title":"355- الفرق بين البأساء والضراء","page":"ج1 ص88","text":"الفرق بين البأساء والضراء (3) : قيل: الاول إشارة إلى الضرر\nالحاصل، والثاني إلى الضرر المتوقع أو: الاول: الضرر الشديد، والثاني: الضعيف.\nوقيل: يحتمل أن يكون الاول: الجهل البسيط، والثاني المركت.\n(اللغات) ."},{"id":"furuq-lughawiyya:119","bookId":"furuq-lughawiyya","type":"section","seq":119,"chapter":"* (أ) *","title":"357 - الفرق بين الباطل والفاسد (*) (1) : الاول: ما لم يشرع بالكلية كبيع ما في بطون الامهات.","page":"ج1 ص89","text":"والثاني: ما يشرع أصله، ولكن امتنع لاشتماله على وصف كالربا (2) كذا قال الشهيد في تمهيد القواعد (3) .\n(اللغات) ."},{"id":"furuq-lughawiyya:120","bookId":"furuq-lughawiyya","type":"section","seq":120,"chapter":"* (أ) *","title":"358 - الفرق بين الباقي والقديم والمتقدم: أن الباقي هو الموجود لا عن حدوث في حال وصفه بذلك، والقديم ما لم يزل كائنا موجودا على ما ذكرنا وأنت","page":"ج1 ص89","text":"تقول سابقي هذا المتاع لنفسي ولا تقول ساقدمه واستبقيت الشئ\nولا تقول استقدمته، وقال قوم: القديم في اللغة مبالغة في الوصف بالتقدم في الوجود وكلما تقدم وجوده حتى سمي قديما فذلك حقيقة فيه، وقال من يرد ذلك لو كان القدم يستفاد لجاز أن تقول لما علمته سيبقى طويلا أنه سيقدم كما تقول أنه سيبقى، وفي بطلان ذلك دلالة على أنه في المحدث توسع والمتقدم خلاف المتأخر، والتقدم حصول الشئ قدام الشئ ومنه القدوم لتقدمها في العمل وقيل لمضيها في العمل لا تنثني فتوبع لها في الصفة كالتقدم في الامر، ومنه القدم لانك تتقدم بها في المكان في المشي، والسابقة في الخير والشر قدم وفي القرآن \" قدم صدق عند ربهم \" (1) وقوادم الريش العشر المتقدمات، ويقال قدم العهد وقدم البلى أي طال وكل ما يقدم فهو قديم وقدم، وفي الحديث \" حتى يضع الجبار فيها قدمه \" أي في النار يريد من سلف في علمه أنه عاص، ويجوز أن يكون من سلف بعصيانه، والقديم على الحقيقة هو الذي لا أول لحدوثه."},{"id":"furuq-lughawiyya:121","bookId":"furuq-lughawiyya","type":"section","seq":121,"chapter":"* (أ) *","title":"363 - الفرق بين البحث والطلب: أن البحث هو طلب الشئ مما يخالطه فأصله أن يبحث التراب عن شئ يطلبه فالطلب يكون لذلك ولغيره","page":"ج1 ص91","text":"وقيل فلان يبحث عن الامور تشبيها بمن يبحث التراب لاستخراج الشئ."},{"id":"furuq-lughawiyya:122","bookId":"furuq-lughawiyya","type":"section","seq":122,"chapter":"* (أ) *","title":"الفرق بين البدن والجسد","page":"ج1 ص91","text":"أن البدن هو ما علا من جسد الانسان ولهذا يقال للزرع القصير الذي يلبس الصدر إلى السرة بدن لانها تقع على البدن وجسم الانسان كله جسد، والشاهد أنه يقال لمن قطع بعض أطرافه إنه قطع شئ من جسده ولا يقال شئ من بدنه وإن قيل فعلى بعد، وقد يتداخل الاسمان إذا تقاربا في المعنى، ولما كان البدن هو\nأعلى الجسد وأغلظة قيل لمن غلظ من السمن قد بدن وهو بدين، والبدن الابل المسمنة للنحر ثم كثر ذلك حتى سمي ما يتخذ للنحر بدنة سمينة كانت أو مهزولة."},{"id":"furuq-lughawiyya:123","bookId":"furuq-lughawiyya","type":"section","seq":123,"chapter":"* (أ) *","title":"371 - الفرق بين البدن والجسد (1) : قال في البارع (2) : (لا يقال الجسد إلا للحيوان العاقل - وهو الانسان والملائكة والجن - ولا يقال لغيره جسد)","page":"ج1 ص92","text":"(اللغات) ."},{"id":"furuq-lughawiyya:124","bookId":"furuq-lughawiyya","type":"section","seq":124,"chapter":"* (أ) *","title":"372 - الفرق بين البدنة والهدي: أن البدن ما تبدن من الابل أي تسمن يقال بدنت الناقة إذا سمنتها وبدن الرجل سمن، ثم كثر ذلك حتى سميت الابل بدنا","page":"ج1 ص93","text":"نحرها بغير مكة وهو كقوله علي جزور ومن قال علي هدي لم يجز أن يذبحه إلا بمكة، وهذا قول جماعة من التابعين وبه قال أبو حنيفة ومحمد رحمهم الله، وقال غيرهم إذا قال علي بدنه أو هدي فبمكة وإذا قال جزور فحيث يرى وهو قول أبي يوسف."},{"id":"furuq-lughawiyya:125","bookId":"furuq-lughawiyya","type":"section","seq":125,"chapter":"* (أ) *","title":"374 - الفرق بين البديع والمبدع (1) : كلاهما بمعنى في اللغة.","page":"ج1 ص93","text":"وهو منشئ الاشياء على غير مثال سبق.\nغير أن الفرق بينهما: أن في البديع مبالغة ليست في المبدع، إذ هو يستحق [10 / ب] الوصف به في غير حال الفعل على الحقيقة، بمعنى أن من شأنه إنشاء الاشياء على غير مثال (اللغات) ."},{"id":"furuq-lughawiyya:126","bookId":"furuq-lughawiyya","type":"section","seq":126,"chapter":"* (أ) *","title":"377 - الفرق بين البذر والبزر (2) : قد يفرق بينهما بأن البذر - بالذال المعجمة -","page":"ج1 ص93","text":"في الحبوب، كالحنطة والشعير.\n- والبزر بالزاء (3) للرياحين والبقول.\n(اللغات) ."},{"id":"furuq-lughawiyya:127","bookId":"furuq-lughawiyya","type":"section","seq":127,"chapter":"* (أ) *","title":"الفرق بين البر والخير","page":"ج1 ص94","text":"أن البر مضمن بجعل عاجل قد قصد وجه النفع به فأما الخير فمطلق حتى لو وقع عن سهو لم يخرج عن استحقاق الصفة به، ونقيض الخير الشر ونقيض البر العقوق."},{"id":"furuq-lughawiyya:128","bookId":"furuq-lughawiyya","type":"section","seq":128,"chapter":"* (أ) *","title":"383- الفرق بين البر والخير","page":"ج1 ص94","text":"الفرق بين البر والخير (1) : قيل: الفرق بينهما أن البر هو الخير الواصل إلى الغير مع القصد إلى ذلك والخير يكون خيرا، وإن وقع عن سهو.\nوضد البر: العقوق، وضد الخير: الشر.\n(اللغات)"},{"id":"furuq-lughawiyya:129","bookId":"furuq-lughawiyya","type":"section","seq":129,"chapter":"* (أ) *","title":"385 - الفرق بين البر والصلة: أن البر سعة الفضل المقصود إليه، والبر ايضا","page":"ج1 ص95","text":"يكون بلين الكلام، وبر والده إذا لقيه بجميل القول والفعل قال الراجز: بني ان البر شئ هين * وجه طليق وكلام لين والصلة البر المتأصل، وأصل الصلة وصلة على فعله وهي للنوع والهيئة يقال بار وصول أي يصل بره فلا يقطعه، وتواصل القوم تعاملوا بوصول بر كل واحد منهم إلى صاحبه وواصله عامله بوصول البر وفي القرآن \" ولقد وصلنا لهم القول \" (1) أي كثرنا وصول بعضه ببعض بالحكم الدالة على الرشد."},{"id":"furuq-lughawiyya:130","bookId":"furuq-lughawiyya","type":"section","seq":130,"chapter":"* (أ) *","title":"387 - الفرق بين البركة والزيادة (2) : البركة: هي الزيادة والنماء من حيث لا يوجد بالحس ظاهرا، فإذا عهد من الشئ هذا المعنى خافيا عن الحس، قيل","page":"ج1 ص95","text":"ويوصف بها كل شئ لزمه وثبت فيه خير إلهي.\nوليس لضدها اسم معروف، فلذلك يقال فيه: قليل البركة، ولا يسند فعل البركة إلا إلى الله، فلا يقال: بارك زيد في الشئ، وإنما يقال: بارك الله فيه.\nوإلى هذه الزيادة أشير بما روي أنه (3) : لا ينقص مال من صدقة، لا إلى النقصان المحسوس.\nفإذن كل بركة زيادة، وليس كل زيادة بركة.\n(اللغات)"},{"id":"furuq-lughawiyya:131","bookId":"furuq-lughawiyya","type":"section","seq":131,"chapter":"* (أ) *","title":"389 - الفرق بين البرهان والدليل (1) : البرهان: الحجة القاطعة المفيده للعلم.","page":"ج1 ص96","text":"وأما ما يفيد الظن فهو الدليل.\nويقرب منه: الامارة.\nولذا أفحم سبحانه الكفار بطلب البرهان منهم فقال، وهو أصدق القائلين: \" قل هاتوا برهانكم إن كنتم صادقين \" (2) .\n(اللغات)"},{"id":"furuq-lughawiyya:132","bookId":"furuq-lughawiyya","type":"section","seq":132,"chapter":"* (أ) *","title":"391 - الفرق بين البزاق والريق (1) : قيل: البزاق: ماء الفم إذا خرج منه، وما دام فيه ريق.","page":"ج1 ص97","text":"(اللغات)"},{"id":"furuq-lughawiyya:133","bookId":"furuq-lughawiyya","type":"section","seq":133,"chapter":"* (أ) *","title":"393 - الفرق بين البزوغ والطلوع والشروق: أن البزوغ أول الطلوع ولهذا قال تعالى \" فلما رأى الشمس بازغة \" (2) أي لما رآها في أول أحوال طلوعها تف","page":"ج1 ص97","text":"الطلوع تقول طلعت ولا يقال شرق الرجل كما يقال طلع الرجل فالطلوع أعم."},{"id":"furuq-lughawiyya:134","bookId":"furuq-lughawiyya","type":"section","seq":134,"chapter":"* (أ) *","title":"395 - الفرق بين البسلة (1) والحلوان والرشوة: أن البسلة أجر الراقي وجاء النهي عنها وذلك إذا كانت الرقية بغير ذكر الله تعالى فأما إذا كانت بذك","page":"ج1 ص98","text":"والمرتشي \" وكانت العرب تسميها الاتاوة وقال أبو زيد: أتوت الرجل أتوا وهي الرشوة قال زهير:\nأفي كل أسواق العراق إتاوة * وفي كل ما باع امرؤ مكس درهم قال المكس الخيانة وهو هاهنا الضريبة التي تؤخذ في الاسواق ويقال مكسه مكسا إذا خانه ويقال المكس العشر وجاء في الحديث \" لا يدخل الجنة صاحب مكس \" وقال بعضهم: الاسلال الرشوة وفي الحديث \" لا إغلال ولا إسلال \" والاغلال الخيانة، وقال أبو عبيدة: الاسلال السرقة، وقال بعضهم الاتاوة الخراج."},{"id":"furuq-lughawiyya:135","bookId":"furuq-lughawiyya","type":"section","seq":135,"chapter":"* (أ) *","title":"396 - الفرق بين البشارة والخبر (1) : البشارة: الاخبار بما يسر به المخبر به إذا كان سابقا لكل خبر سواه.","page":"ج1 ص99","text":"وبنى العلماء عليه مسألة فقهية بأن الانسان إذا قال لعبيده أيكم بشرني بقدوم زيد فهو حر، فبشروه فرادى، عتق أولهم، لانه هو الذي سره بخبره سابقا، ولو قال: مكان بشرني: (أخبرني) عتقوا جميعا.\nواشتقاقه قيل من البشر، وهو السرور، فيختص بالخبر الذي يسر، [9 / ب] وأما قوله تعالى: \" فبشرهم بعذاب أليم \" (2) و \" إذا بشر أحدهم بالانثى ظل وجهه مسودا وهو كظيم \" (3) .\nفهو من باب التهكم والاستهزاء.\nوقيل: اشتقاقه (4) من البشرة وهو ظاهر الجلد لتأثيره في تغيير بشرة الوجه، فيكون فيما يسر ويغم، لان السرور كما يوجب تغيير البشرة، فكذلك (5) الحزن يوجبه.\nفوجب أن يكون لفظ التبشير حقيقة في\nالقسمين، لكنه عند الاطلاق يختص في العرف بما يسر، وإن اريد خلافه قيد.\nقال تعالى: \" فبشر عباد \" (1) .\nوفي الثاني: \" فبشرهم بعذاب أليم \" (2) (اللغات) ."},{"id":"furuq-lughawiyya:136","bookId":"furuq-lughawiyya","type":"section","seq":136,"chapter":"* (أ) *","title":"399 - الفرق بين البشر والبشاشة: أن البشر أول ما يظهر من السرور بلقي من يلقاك، ومنه البشارة وهي أول ما يصل إليك من الخبر السار فاذا وصل إليك","page":"ج1 ص100","text":"والهشاشة هي الخفة للمعروف وقد هششت يا هذا بكسر الشين وهو من قولك شئ هش إذا كان سهل المتناول فإذا كان الرجل سهل العطاء قيل هو هش بين الهشاشة.\nوالبشاشة إظهار السرور بمن تلقاه وسواء كان أولا أو أخيرا."},{"id":"furuq-lughawiyya:137","bookId":"furuq-lughawiyya","type":"section","seq":137,"chapter":"* (أ) *","title":"400 - الفرق بين البشر والناس: أن قولنا البشر يقتضي حسن الهيئة وذلك أنه مشتق من البشارة وهي حسن الهيئة يقال رجل بشير وامرأة بشيرة إذا","page":"ج1 ص100","text":"كان حسن الهيئة فسمي الناس بشرا لانهم أحسن الحيوان هيئة، ويجوز أن يقال إن قولنا بشر يقتضي الظهور وسموا بشرا لظهور شأنهم، ومنه قيل لظاهر الجلد بشرة، وقولنا الناس يقتضي النوس وهو الحركة، والناس\nجمع والبشر واحد وجمع وفي القرآن \" ما هذا إلا بشر مثلكم \" (1) وتقول محمد خير البشر يعنون الناس كلهم ويثنى البشر فيقال بشران وفي القرآن \" لبشرين مثلنا \" (2) ولم يسمع أنه يجمع."},{"id":"furuq-lughawiyya:138","bookId":"furuq-lughawiyya","type":"section","seq":138,"chapter":"* (أ) *","title":"405 - الفرق بين قولك بطر النعمة وقولك كفر النعمة: أن قولك بطرها يفيد أنه عظمها وبغى فيها.","page":"ج1 ص101","text":"وكفرها يفيد أنه عظمها فقط، وأصل البطر الشق\nومنه قيل للبيطار بيطار وقد بطرت الشئ أي شققته وأهل اللغة يقولون البطر سوء إستعمال النعمة وكذلك جاء في تفسير قوله تعالى \" بطرت معيشتها \" (1) \" ولا تكونوا كالذين خرجوا من ديارهم بطرا ورئاء الناس \" (2) ."},{"id":"furuq-lughawiyya:139","bookId":"furuq-lughawiyya","type":"section","seq":139,"chapter":"* (أ) *","title":"410 - الفرق بين البعض والجزء: أن البعض ينقسم والجزء لا ينقسم والجزء يقتضي جمعا والبعض يقتضي كلا، وقال بعضهم يدخل الكل على أعم العام ولا يدخل","page":"ج1 ص103","text":"بقرينة تقوم مقام الاستثناء كقولك: لزيد في كل شئ يد ويجئ البعض بمعنى الكل كقوله تعالى \" إن الانسان لفي خسر \" (1) وحد البعض ما يشمله وغيره إسم واحد ويكون في المتفق والمختلف كقولك الرجل بعض الناس وقولك السواد بعض الالوان ولا يقال الله تعالى بعض الاشياء، وإن كان شيئا واحدا يجب إفراده بالذكر لما يلزم من تعظيمه وفي القرآن \" والله ورسوله أحق أن يرضوه \" (2) ولم يقل يرضوهما، وقيل حد البعض التناقص عن الجملة، وقال البلخي رحمه الله: البعض أقل من النصف، وحد الجزء الواحد من ذا الجنس، ولهذا لا يسمى القديم جزءا كما يسمى واحدا."},{"id":"furuq-lughawiyya:140","bookId":"furuq-lughawiyya","type":"section","seq":140,"chapter":"* (أ) *","title":"413 - الفرق بين البغض والكراهة: أنه قد إتسع بالبغض ما لم يتسع بالكراهة فقيل أبغض زيدا أي أبغض إكرامه ونفعه، ولا يقال أكرهه بهذا المعنى كما إ","page":"ج1 ص104","text":"أريده في هذا المعنى، ومع هذا فإن الكراهة تستعمل فيما لا يستعمل فيه البغض فيقال أكره هذا الطعام ولا يقال أبغضه كما تقول احبه والمراد إني أكره أكله أن المراد بقولك اريد هذا الطعام أنك تريد أكله أو شراءه."},{"id":"furuq-lughawiyya:141","bookId":"furuq-lughawiyya","type":"section","seq":141,"chapter":"* (أ) *","title":"419 - الفرق بين بلى ونعم: أن بلى لا تكون إلا جوابا لما كان فيه حرف جحد كقوله تعالى \" ألست بربكم قالوا بلى \" (2) وقوله عزوجل \" ألم يأتكم","page":"ج1 ص105","text":"رسل منكم \" (1) ثم قال في الجواب \" قالوا بلى \" (2) ونعم لا تكون للاستفهام بلا جحد كقوله تعالى \" فهل وجدتم ما وعد ربكم حقا قالوا نعم \" (3) وكذلك جواب الخبر إذا قال قد فعلت ذلك قلت نعم لعمري قد فعلته، وقال الفراء وإنما امتنعوا أن يقولوا في جواب الجحود نعم لانه إذا قال الرجل مالك علي شئ فلو قال الآخر نعم كان صدقه كأنه قال نعم ليس لي عليك شئ وإذا قال بلى فانما هو رد لكلام صاحبه أي بلى لي عليك شئ فلذلك إختلف بلى ونعم."},{"id":"furuq-lughawiyya:142","bookId":"furuq-lughawiyya","type":"section","seq":142,"chapter":"* (أ) *","title":"424 - الفرق بين البهجة والحسن: أن البهجة حسن يفرح به القلب، وأصل","page":"ج1 ص106","text":"البهجة السرور ورجل بهج وبهيج مسرور وإبتهج إذا سر ثم سمي الحسن الذي يهج القلب بهجة، وقد يسمى الشئ بإسم سببه، والبهجة عند الخليل حسن لون الشئ ونضارته قال ويقال رجل بهج أي مبتهج بأمر يسره فأشار إلى ما قلناه."},{"id":"furuq-lughawiyya:143","bookId":"furuq-lughawiyya","type":"section","seq":143,"chapter":"* (أ) *","title":"427 - الفرق بين البيان والبرهان والسلطان (1) : هي نظائر، وتختلف حدودها.","page":"ج1 ص107","text":"فالبيان: إظهار المعنى للنفس كإظهار نقيضه.\nوالبرهان: إظهار صحة المعنى وإفساد نقيضه.\nوالسلطان: إظهار ما يتسلط به على نقيض المعنى بالابطال كذا قيل.\n(اللغات)"},{"id":"furuq-lughawiyya:144","bookId":"furuq-lughawiyya","type":"section","seq":144,"chapter":"* (أ) *","title":"428 - الفرق بين البيان والفائدة: قال علي بن عيسى: ما ذكر ليعرف به غيره فهو البيان كقولك غلام زيد وإنما ذكر ليعرف به الغلام فهو للبيان وقولك","page":"ج1 ص108","text":"البيان نحو قولك مررت برجل قام فهو هاهنا صفة مذكورة للزيادة في البيان."},{"id":"furuq-lughawiyya:145","bookId":"furuq-lughawiyya","type":"section","seq":145,"chapter":"* (أ) *","title":"429 - الفرق بين البيان والهدى: أن البيان في الحقيقة إظهار المعنى للنفس كائنا ما كان فهو في الحقيقة من قبيل القول.","page":"ج1 ص108","text":"والهدى بيان طريق الرشد ليسلك (1) دون طريق الغي هذا إذا أطلق فإذا قيد استعمل في غيره فقيل هدي إلى النار وغيرها."},{"id":"furuq-lughawiyya:146","bookId":"furuq-lughawiyya","type":"section","seq":146,"chapter":"* (أ) *","title":"ت","page":"ج1 ص108","text":"وهمهم أن معنى بات فلان أي نام، وليس كذلك، بل معنى بات: أظله المبيت وأجنه الليل، سواء نام أم لم ينم، يدل على ذلك قوله تعالى: \" والذين يبيتون لربهم سجدا وقياما \" (3) .\nويشهد له أيضا قول ابن رميض (4) : باتوا نياما وابن هند لم ينم * بات يساقيها غلام كالزلم (اللغات)"},{"id":"furuq-lughawiyya:147","bookId":"furuq-lughawiyya","type":"section","seq":147,"chapter":"* (أ) *","title":"433 - الفرق بين قولك تابعت زيدا وقولك وافقته: أن قولك تابعته يفيد أنه قد","page":"ج1 ص109","text":"تقدم منه شئ افتديت به فيه، ووافقته يفيد أنكما إتفقتما معا في شئ من الاشياء ومنه سمي التوفيق توفيقا، ويقول أبو علي رحمة الله عليه.\nومن تابعه يريد به أصحابه ومنه سمي التابعون التابعين، وقال أبو علي رحمة الله: ومن وافقه يريد من قال بقوله وإن لم يكن من أصحابه، وأيضا فإن النظير لا يقال إنه تابع لنظيره لان التابع دون المتبوع ويجوز أن يوافق النظير النظير."},{"id":"furuq-lughawiyya:148","bookId":"furuq-lughawiyya","type":"section","seq":148,"chapter":"* (أ) *","title":"434 - الفرق بين التالي والتابع: أن التالي فيما قال علي بن عيسى: ثان وإن لم يكن يتدبر بتدبر الاول.","page":"ج1 ص109","text":"والتابع إنما هو المتدبر بتدبر الاول، وقد يكون التابع قبل المتبوع في المكان كتقدم المدلول وتأخر الدليل وهو مع ذلك يأمر بالعدول تارة إلى الشمال وتارة إلى اليمين كذا قال."},{"id":"furuq-lughawiyya:149","bookId":"furuq-lughawiyya","type":"section","seq":149,"chapter":"* (أ) *","title":"436 - الفرق بين التأريب والابرام: أن التأريب شدة العقد يقال أرب العقد إذا جعل عقدا فوق عقد وهو خلاف النشط يقال نشطه إذا عقده بانشوطة","page":"ج1 ص109","text":"وهو عقد ضعيف وأربه إذا أحكم عقده وأنشطه إذا حل الانشوطة."},{"id":"furuq-lughawiyya:150","bookId":"furuq-lughawiyya","type":"section","seq":150,"chapter":"* (أ) *","title":"437 - الفرق بين التأسف والتلهف (1) : ذهب كثير من أهل اللغة إلى ترادفهما، وانهما بمعنى الحزن.","page":"ج1 ص110","text":"وفرق بعضهم بأن التلهف: (2) التحزن على ما فات، والتأسف: مطلق الحزن والاصح أن يقال: إن التأسف: على ما فات، والتلهف: على ما يأتي.\nويؤيده قول الشاعر: وبعد غد يا لهف نفسي من غد * إذا راح أصحابي ولست برائح! قال الجوهري: الاسف: أشد الحزن، والتلهف: الحزن.\n(اللغات) ."},{"id":"furuq-lughawiyya:151","bookId":"furuq-lughawiyya","type":"section","seq":151,"chapter":"* (أ) *","title":"438 - الفرق بين التأسف والندم: أن التأسف يكون على الفائت من فعلك","page":"ج1 ص110","text":"وفعل غيرك والندم جنس من أفعال القلوب لا يتعلق إلا بواقع من فعل النادم دون غيره فهو مباين لافعال القلوب وذلك أن الارادة والعلم والتمني والغبط قد يقع على فعل الغير كما يقع على فعل الموصوف به، والغضب يتعلق بفعل الغير فقط."},{"id":"furuq-lughawiyya:152","bookId":"furuq-lughawiyya","type":"section","seq":152,"chapter":"* (أ) *","title":"440 - الفرق بين الترتيب والتأليف والتركيب والتصنيف (3) : الترتيب: هو جمع الاشياء المختلفة، بحيث يطلق عليها اسم: الواحد، ويكون لبعضها نسبة إل","page":"ج1 ص111","text":"يرشدك إليه اشتقاقه من الالفة سواء كانت مرتبة الوضع أو لا، وهما أخص من التركيب مطلقا لانه: ضم الاشياء مؤتلفة كانت أم لا، مرتبة الوضع كانت أم لا.\nوقد يستعمل الترتيب أخص مطلقا من التأليف، وقد يجعلان مترادفين، كذا حققه الشهيد الثاني طاب ثراه.\nوأما التصنيف فالمشهور أنه: ما كان من كلام المصنف.\nقال شيخنا البهاء (1) - قدس سره - في الكشكول: قد يقال: إن جمع القرآن لا يسمى تصنيفا إذ الظاهر أن التصنيف ما كان من كلام\nالمصنف، والجواب إن جمع القرآن إذا لم يكن تصنيفا لما ذكرت من العلة، فجمع الحديث أيضا ليس تصنيفا مع أن إطلاق التصنيف على كتب الحديث شائع ذائع.\nانتهى.\n(اللغات) ."},{"id":"furuq-lughawiyya:153","bookId":"furuq-lughawiyya","type":"section","seq":153,"chapter":"* (أ) *","title":"442 - الفرق بين التأليف والتصنيف: أن التأليف أعم من التصنيف وذلك أن","page":"ج1 ص112","text":"التصنيف تأليف صنف من العلم ولا يقال للكتاب إذا تضمن نقض شئ من الكلام مصنف لانه جمع الشئ وضده والقول ونقيضه، والتأليف يجمع ذلك كله وذلك أن تأليف الكتاب هو جمع لفظ إلى لفظ ومعنى إلى معنى فيه حتى يكون كالجملة الكافية فيما يحتاج إليه سواء (1) كان متفقا أو مختلفا والتصنيف مأخوذ من الصنف ولا يدخل في الصنف غيره."},{"id":"furuq-lughawiyya:154","bookId":"furuq-lughawiyya","type":"section","seq":154,"chapter":"* (أ) *","title":"447 - الفرق بين الابدال والتبديل (2) : قيل: هما بمعنى، وقيل: (3) التبديل: تغيير حال إلى حال آخر [4 / ب] يقال: بدل صورته.","page":"ج1 ص112","text":"والابدال: رفع الشئ بأن يجعل (4) غيره مكانه.\nوقال بعضهم: التبديل هو التغيير، يقال: أبدلت الشئ بالشئ إذا بدلت (5) عينا بعين، قال الشاعر (6) :\n* عزل الأمير بالأمير المبدل * وبدلت، بالتشديد: إذا غيرت هيئته، والعين واحد، يقولون: بدلت جبتي قميصا: أي: جعلتها قميصا ذكره المغربي.\nوقد يكون التبديل بأن يوضع غيره موضعه.\nقال تعالى: \" يوم تبدل الارض \" (1) .\nوقال سبحانه: \" وبدلناهم بجنتيهم جنتين ذواتي أكل خمط وأثل وشئ من سدر قليل \" (2) ، ويحتمل الوجهين قوله سبحانه: \" ما يبدل القول لدى \" (3) .\n(اللغات) ."},{"id":"furuq-lughawiyya:155","bookId":"furuq-lughawiyya","type":"section","seq":155,"chapter":"* (أ) *","title":"449 - الفرق بين التبذير والاسراف (4) : قيل: التبذير: إنفاق المال فيما","page":"ج1 ص113","text":"لا ينبغي.\nوالاسراف: صرفه زيادة على ما ينبغي.\nوبعبارة اخرى: الاسراف: تجاوز الحد في صرف المال، والتبذير:\nاتلافه في غير موضعه، هو (1) أعظم من الاسراف، ولذا قال تعالى: \" إن المبذرين كانوا إخوان الشياطين \" (2) .\nقيل: وليس الاسراف متعلقا بالمال فقط، بل بكل شئ وضع في غير (3) موضعه اللائق به.\nألا ترى أن الله سبحانه وصف قوم لوط بالاسراف لوضعهم البذر في غير المحرث، فقال: \" إنكم لتاتون الرجال شهوة من دون النساء بل أنتم قوم\nمسرفون \" (4) .\nووصف فرعون بالاسراف بقوله: \" إنه كان عاليا من المسرفين \" (5) .\nأقول: ويستفاد (6) من بعض الاخبار أن الاسراف على ضربين: حرام، ومكروه.\nفالاول: مثل إتلاف مال ونحوه فيما فوق المتعارف.\nوالثاني: إتلاف شئ ذي نفع بلا غرض (7) ، ومنه إهراق ما بقي من شرب ماء الفرات ونحوها خارج الماء (8) .\nوقد روي ذلك عن أمير المؤمنين عليه السلام.\n(اللغات) ."},{"id":"furuq-lughawiyya:156","bookId":"furuq-lughawiyya","type":"section","seq":156,"chapter":"* (أ) *","title":"451 - الفرق بين التتابع والتواتر (1) : قال الحريرى في درة الغواص: تقول جاءتنا الخيل متتابعة إذا جاء بعضها في إثر بعض، بلا فصل.","page":"ج1 ص115","text":"وجاءت متواترة: إذا تلاحقت، وبينها فصل، ويؤيده قوله تعالى: \" ثم أرسلنا رسلنا تترا \" (2) .\nومعلوم أنه كان بين كل فترة وتراخي مدة.\nوعن بعض الصحابة أنه قال لعلي عليه السلام: إن علي أياما من شهر رمضان أيجوز إن أقضيها متفرقة؟.\nقال: اقضها إن شئت متتابعة، وإن شئت متواترة تترى، فقلت: إن بعضهم قال لا تجزئ عنك إلا متتابعة.\nفقال: بل (3) تجزئ تترى لانه عزوجل قال: \" فعدة من أيام أخر \" (4) .\nولو أراد متتابعة لبين التتابع كما قال عزوجل: \" فصيام شهرين متتابعين \" (5) .\nانتهى ملخصا.\n(اللغات) ."},{"id":"furuq-lughawiyya:157","bookId":"furuq-lughawiyya","type":"section","seq":157,"chapter":"* (أ) *","title":"452 - الفرق بين التثريب والتفنيد واللوم: أن التثريب شبيه بالتقريع والتوبيخ تقول وبخه وقرعه وثربه بما كان منه، واللوم قد يكون لما يفعله الانس","page":"ج1 ص116","text":"في الحال ولا يقال لذلك تقريع وتثريب وتوبيخ، واللوم يكون على الفعل الحسن ولا يكون التثريب إلا على قبيح، والتفنيد تعجيز الرأي يقال فنده إذا عجز رأيه وضعفه والاسم الفند، وأصل الكلمة الغلظ ومنه قيل\nللقطعة من الجبل فند، ويجوز أن يقال التثريب الاستقصاء في اللوم والتعنيف، وأصله من الثرب وهو شحم الجوف لان البلوغ إليه هو البلوغ إلى المواضع الاقصى من البدن."},{"id":"furuq-lughawiyya:158","bookId":"furuq-lughawiyya","type":"section","seq":158,"chapter":"* (أ) *","title":"455 - الفرق بين التحسس والتجسس (1) (*) : التحسس - بالحاء المهملة -: طلب الشئ بالحاسة.","page":"ج1 ص116","text":"والتجسس - بالجيم - مثله.\nوفي الحديث: \" لا تحسسوا، ولا تجسسوا \" (1) .\nقيل: معناهما واحد، وعطف أحدهما على الآخر لاختلاف اللفظين كقول الشاعر: * متى أدن منه ينأ عني ويبعد *\nوقيل: التجسس - بالجيم - البحث عن عورات النساء.\n- وبالحاء - الاستماع لحديث القوم، ويروى أن ابن عباس سئل عن الفرق بينهما فقال: لا يبعد أحدهما عن الآخر: التحسس في الخير، والتجسس في الشر.\nقلت: ويؤيده قوله تعالى حكاية عن يعقوب: \" يا بني اذهبوا فتحسسوا من يوسف \" (2) - بالحاء -.\nعلى القراءة المشهورة، فإنه كان متوقعا لان يأتيه الخبر بسلامة يوسف.\nوقوله سبحانه: \" ولا تجسسوا \" (3) - بالجيم - فإن المنهي عنه البحث عن معائب الناس وأسرارهم التي لا يرضون بإفشائها واطلاع الغير عليها.\n(اللغات) ."},{"id":"furuq-lughawiyya:159","bookId":"furuq-lughawiyya","type":"section","seq":159,"chapter":"* (أ) *","title":"457 - الفرق بين التحلية والصفة: أن التحلية في الاصل فعل المحلي وهو تركيب","page":"ج1 ص118","text":"الحلية على الشئ مثل السيف وغيره.\nوليس هي من قبيل القول.\nواستعمالها في غير القول مجاز وهو أنه قد جعل ما يعبر عنه بالصفة صفة كما أن الحقيقة من قبيل القول.\nثم جعل ما يعبر عنه بالحقيقة حقيقة وهو الذات\nإلا أنه كثر به الاستعمال حتى صار كالحقيقة."},{"id":"furuq-lughawiyya:160","bookId":"furuq-lughawiyya","type":"section","seq":160,"chapter":"* (أ) *","title":"458 - الفرق بين التحميل والتكليف: أن التحميل لا يكون إلا لما يستثقل ولهذا قال تعالى \" ولا تحمل علينا إصرا \" (1) والاصر الثقل.","page":"ج1 ص118","text":"والتكليف قد يكون لما لا ثقل له نحو الاستغفار تقول كلفه الله الاستغفار ولا تقول حمله ذلك."},{"id":"furuq-lughawiyya:161","bookId":"furuq-lughawiyya","type":"section","seq":161,"chapter":"* (أ) *","title":"461 - الفرق بين التخصيص والنسخ: أن التخصيص هو ما دل على أن المراد","page":"ج1 ص119","text":"بالكلمة بعض ما تناولته دون بعض، والنسخ ما دل على أن مثل الحكم الثابت بالخطاب زائل في المستقبل على وجه لولاه لكان ثابتا، ومن حق التخصيص أن لا يدخل إلا فيما يتناوله اللفظ، والنسخ يدخل في النص على عين والتخصيص ما لا يدخل فيه، والتخصيص يؤذن بأن المراد\nبالعموم عند الخطاب ما عداه، والنسخ يحقق أن كل ما يتناوله اللفظ مراد في حال الخطاب وإن كان غيره مرادا فيما بعد، والنسخ في الشريعة لا يقع بأشياء يقع بها التخصيص، والتخصيص لا يقع ببعض ما يقع به النسخ فقد بان لك مخالفة أحدهما للآخر في الحد والحكم جميعا، وتساويهما في بعض الوجوه لا يوجب كون النسخ تخصيصا."},{"id":"furuq-lughawiyya:162","bookId":"furuq-lughawiyya","type":"section","seq":162,"chapter":"* (أ) *","title":"467 - الفرق بين التخويل والتمويل: أن التخويل إعطاء الخول يقال خوله إذا جعل له خولا كما يقال موله إذا جعل له مالا وسوده إذا جعل له سوددا، وسن","page":"ج1 ص120","text":"إبله إذا إسترعاه إياها فكثر حتى جعل كل هبة وعطية تخويلا كأنه جعل له من ذلك ما يرعاه."},{"id":"furuq-lughawiyya:163","bookId":"furuq-lughawiyya","type":"section","seq":163,"chapter":"* (أ) *","title":"الفرق بين التدبر والتفكر","page":"ج1 ص120","text":"أن التدبر تصرف القلب بالنظر في العواقب والتفكر تصرف القلب بالنظر في الدلائل.\nوسنبين إشتقاق التدبر وأصله\nفيما بعد."},{"id":"furuq-lughawiyya:164","bookId":"furuq-lughawiyya","type":"section","seq":164,"chapter":"* (أ) *","title":"470- الفرق بين التدبر والتفكر","page":"ج1 ص120","text":"الفرق بين التدبر والتفكر (1) : قد فرق بينهما [11 / ب] بأن التدبر: تصرف القلب بالنظر في عواقب الامور.\nوالتفكر: تصرف القلب بالنظر في الدلائل.\n(اللغات) ."},{"id":"furuq-lughawiyya:165","bookId":"furuq-lughawiyya","type":"section","seq":165,"chapter":"* (أ) *","title":"474 - الفرق بين التذكير والتنبيه: أن قولك ذكر الشئ يقتضي أنه كان عالما به ثم نسيه فرده إلى ذكره ببعض الاسباب وذلك أن الذكر هو العلم","page":"ج1 ص121","text":"الحادث بعد النسيان على ما ذكرنا (1) ويجوز أن ينبه الرجل على الشئ لم يعرفه قط ألا ترى أن الله ينبه على معرفته بالزلازل والصواعق وفهم من لم يعرفه البتة فيكون ذلك تنبيها له كما يكون تنبيها لغيره، ولا يجوز أن يذكره ما لم يعلمه قط."},{"id":"furuq-lughawiyya:166","bookId":"furuq-lughawiyya","type":"section","seq":166,"chapter":"* (أ) *","title":"475 - الفرق بين التذلل والذل: أن التذلل فعل الموصوف به وهو إدخال النفس في الذل كالتحلم إدخال النفس في الحلم والذليل المفعول به الذل من قبل غ","page":"ج1 ص121","text":"يمدح الرجل بأنه متذلل ولا يمدح بأنه ذليل لان تذلله لغيره إعترافه له والاعتراف حسن ويقال العلماء متذللون لله تعالى ولا يقال أذلاء له سبحانه."},{"id":"furuq-lughawiyya:167","bookId":"furuq-lughawiyya","type":"section","seq":167,"chapter":"* (أ) *","title":"476 - الفرق بين التذلل والتواضع: أن التذلل إظهار العجز عن مقاومة من يتذلل له.","page":"ج1 ص121","text":"والتواضع إظهار قدرة من يتواضع له سواء كان ذا قدرة على المتواضع أو لا ألا ترى انه يقال العبد متواضع لخدمة أي يعاملهم معاملة من لهم عليه قدرة ولا يقال يتذلل لهم لان التذلل إظهار العجز عن مقاومة المتذلل له وإنه قاهر وليست هذه صفة الملك مع خدمه."},{"id":"furuq-lughawiyya:168","bookId":"furuq-lughawiyya","type":"section","seq":168,"chapter":"* (أ) *","title":"الفرق بين الترجي والانتظار","page":"ج1 ص122","text":"والتوقع: أن الترجي إنتظار الخير خاصة ولا يكون إلا مع الشك، وأما الانتظار والتوقع فهو طلب ما يقدر أن يقع."},{"id":"furuq-lughawiyya:169","bookId":"furuq-lughawiyya","type":"section","seq":169,"chapter":"* (أ) *","title":"480- الفرق بين الترجي والانتظار","page":"ج1 ص122","text":"الفرق بين الترجي والانتظار (1) : الفرق بينهما أن الترجي للخير خاصة.\nوالانتظار قد يكون في الخير، والشر.\nويدل عليه قوله تعالى: \" قل انتظروا إنا منتظرون \" (2) وقوله سبحانه: \" يرجون تجارة لن تبور \" (3) و \" يرجوا رحمة ربه \" (4) ونحوهما\nمما استعمل فيه الرجاء في الخير خاصة.\n(اللغات) ."},{"id":"furuq-lughawiyya:170","bookId":"furuq-lughawiyya","type":"section","seq":170,"chapter":"* (أ) *","title":"483 - الفرق بين الترك والكف: أن الترك عند المتكلمين فعل أحد الضدين اللذين يقدر عليهما المباشر وقال بعضهم كل شيئين تضادا وقدر عليهما","page":"ج1 ص123","text":"بقدرة واحدة مع كون وقت وجودهما وقتا واحدا وكانا يحلان محل القدرة وانصرف القادر بفعل أحدهما عن الآخر سمى الموجود منهما تركا وما لم يوجد متروكا، والترك عند العرب تخليف الشئ في المكان الذي هو فيه والانصراف عنه، ولهذا يسمون بيضة النعامة إذا خرج فرخها تريكة لان النعامة تنصرف عنها، والتريكة الروضة يغفلها الناس ولا يرعونها."},{"id":"furuq-lughawiyya:171","bookId":"furuq-lughawiyya","type":"section","seq":171,"chapter":"* (أ) *","title":"486 - الفرق بين التسبيح والتقديس (1) : هما يرجعان إلى معنى واحد، وهو تبعيد الله عن السوء.","page":"ج1 ص123","text":"وقال بعض الافاضل: بين التسبيح والتقديس فرق، وهو أن التسبيح هو التنزيه عن الشرك والعجز والنقص، والتقديس هو التنزيه عما ذكروه عن التعلق بالجسم، وقبول الانفعال، وشوائب الامكان، وإمكان (2) التعدد في ذاته وصفاته، وكون الشئ من كمالاته بالقوة.\nوالتقديس أعم، إذ كل مقدس مسبح من غير عكس، وذلك لان الابعاد من الذهاب في الارض أكثر من الابعاد في الماء، فالملائكة المقربون الذين هم أرواح مجردة بتجردهم وامتناع تعلقهم، وعدم احتجابهم عن نور ربهم، وقهرهم لما تحتهم بإضافة النور عليهم، وتأثيرهم في غيرهم، وكون كل كمالاتهم بالفعل مسبحون ومقدسون، وغيرهم من الملائكة السماوية والارضية ببساطة ذواتهم وخواص أفعالهم وكمالاتهم،\nمسبحون بل كل شئ مسبح وليس بمقدس.\nويقال: سبوح قدوس.\nولا يعكس.\n* وقال بعض المحققين: التسبيح هو تنزيه الله عما لا يليق بجاهه من صفات النقص.\nوالتقديس: تنزيه الشئ عن النقوص (1) .\nوالحاصل أن التقديس لا يختص به سبحانه بل يستعمل في حق الآدميين.\nيقال: فلان رجل مقدس: إذا اريد تبعيده عن مسقطات العدالة ووصفه بالخبر، ولا يقال: رجل مسبح، بل ربما يستعمل في غير ذوي العقول أيضا، فيقال: قدس الله روح فلان، ولا يقال: سبحه.\nومن\nذلك قوله تعالى: \" ادخلوا الارض المقدسة \" (2) يعني أرض المقدسة، يعني أرض الشام.\nوأما قول الملائكة: (سبوح، قدوس) مع أن المناسب تقديم القدوس ليكون ذكره بعده ترقيا من الادنى إلى الاعلى، فلعله للايذان من أول الامر بأن المراد وصفه سبحانه دون غيره.\nانتهى.\nوهو تحقيق أنيق * (3) .\n(اللغات) ."},{"id":"furuq-lughawiyya:172","bookId":"furuq-lughawiyya","type":"section","seq":172,"chapter":"* (أ) *","title":"487 - الفرق بين التسديد والتقويم: أن التسديد هو التوجيه للصواب فيقال سدد السهم إذا وجهه وجه الصواب، والتقويم إزالة الاعوجاج كتقويم الرمح وال","page":"ج1 ص125","text":"السبب المؤدي كاللطف الذي يؤدي إلى الطاعة، والسبب على وجهين مولد ومؤد فالمولد هو الذي لا يتسع المسبب إلا به لنقص القادر عن فعله دونه والمؤدي هو الداعي إلى الفعل دعاء الترغيب والترهيب والتسديد من أكبر الاسباب لانه يكون في المولد والمؤدي والتسديد للحق لا يكون إلا مع طلب الحق فأما مع الاعراض عنه والتشاغل بغيره فلا يصح والاصلاح تقويم الامر على ما تدعو إليه الحكمة."},{"id":"furuq-lughawiyya:173","bookId":"furuq-lughawiyya","type":"section","seq":173,"chapter":"* (أ) *","title":"490 - الفرق بين التشبيه والاستعارة: أن التشبيه صيغة لم يعبر عنها واللفظ","page":"ج1 ص125","text":"المستعار قد نقل من أصل إلى فرع فهو مغير عما كان عليه فالفرق بينهما بين."},{"id":"furuq-lughawiyya:174","bookId":"furuq-lughawiyya","type":"section","seq":174,"chapter":"* (أ) *","title":"493 - الفرق بين التصور والتوهم: أن تصور الشئ يكون مع العلم به، وتوهمه لا يكون مع العلم به لان التوهم من قبيل التجويز والتجويز ينافي العلم، و","page":"ج1 ص125","text":"كونه فإذا عرفت صدقه وقع العلم بمخبره وزال التوهم، وقال آخر: التوهم هو تجويز ما لا يمتنع من الجائز والواجب ولا يجوز أن يتوهم الانسان ما يمتنع كونه ألا ترى أنه لا يجوز أن يتوهم الشئ متحركا ساكنا في حال واحدة."},{"id":"furuq-lughawiyya:175","bookId":"furuq-lughawiyya","type":"section","seq":175,"chapter":"* (أ) *","title":"500 - الفرق بين التعريض والكناية (1) : الفرق بينهما أن التعريض ضد التصريح: وهو إبهام المقصود بما لم يوضع له لفظ حقيقة ولا مجازا، وهو أن نضمن","page":"ج1 ص126","text":"قيل: وأصله من العرض للشئ الذي هو جانبه وناحية منه.\nكأن\nالمتكلم أمال الكلام إلى جانب يدل على الغرض.\nويسمى: التلويخ أيضا، لانه يلوح منه ما يريده.\nوالكناية: الدلالة.\nعلى الشئ بغير لفظه الموضوع له، بل لوازمه، كطويل النجاد: لطويل القامة، وكثير الرماد: للمضياف.\n(اللغات)"},{"id":"furuq-lughawiyya:176","bookId":"furuq-lughawiyya","type":"section","seq":176,"chapter":"* (أ) *","title":"504 - الفرق بين التفاوت والاختلاف: أن التفاوت كله مذموم ولهذا نفاه الله تعالى عن فعله فقال \" ما ترى في خلق الرحمن من تفاوت \" (1) ومن الاختلا","page":"ج1 ص127","text":"على علم فاعله، والتفاوت هو الاختلاف الواقع على غير سنن وهو دال على جهل فاعله."},{"id":"furuq-lughawiyya:177","bookId":"furuq-lughawiyya","type":"section","seq":177,"chapter":"* (أ) *","title":"505 - الفرق بين قولنا تفرد وبين قولنا توحد: أنه يقال تفرد بالفضل والنبل.","page":"ج1 ص127","text":"وتوحد تخلى."},{"id":"furuq-lughawiyya:178","bookId":"furuq-lughawiyya","type":"section","seq":178,"chapter":"* (أ) *","title":"506 - الفرق بين التفريق والتفكيك: أن كل تفكيك تفريق وليس كل تفريق تفكيكا وإنما التفكيك ما يصعب من التفريق وهو تفريق الملتزقات من المؤلفات وا","page":"ج1 ص128","text":"بعضها من بعض كما يقل فرقتها، وقيل التفريق تفكيك ما جمع وألف تقريبا، وهذا يقوله من لا يثبت للالتزاق معنى غير التأليف."},{"id":"furuq-lughawiyya:179","bookId":"furuq-lughawiyya","type":"section","seq":179,"chapter":"* (أ) *","title":"509 - الفرق بين التفريق والتقسيم (1) : التقسيم جعل الشئ أقساما، وذلك يستدعي تقدم ما يتناول الاقسام نحو: الكلمة: اسم وفعل وحرف.","page":"ج1 ص128","text":"والتفريق: قطع الاتصال بين شيئين أو أكثر لما عرفت وذلك لا يستدعي تقدم ما يتناول.\nقاله الشمني (2) في حواشي المغني (3) .\n(اللغات) ."},{"id":"furuq-lughawiyya:180","bookId":"furuq-lughawiyya","type":"section","seq":180,"chapter":"* (أ) *","title":"الفرق بين التفسير والتأويل","page":"ج1 ص128","text":"أن التفسير هو الاخبار عن أفراد آحاد الجملة، والتأويل الاخبار بمعنى الكلام، وقيل التفسير أفراد ما انتظمه ظاهر التنزيل، والتأويل الاخبار بغرض المتكلم بكلام، وقيل التأويل إستخراج معنى الكلام لا على ظاهره بل على وجه يحتمل مجازا أو حقيقة\nومنه يقال تأويل المتشابه، وتفسير الكلام إفراد آحاد الجملة ووضع كل شئ منها موضعه ومنه أخذ تفسير الامتعة بالماء، والمفسر عند الفقهاء ما فهم معناه بنفسه والمجمل ما لا يفهم المراد به إلا بغيره، والمجمل في اللغة ما يتناول الجملة، وقيل المجمل ما يتناول جملة الاشياء أو ينبئ عن الشئ\nعلى وجه الجملة دون التفصيل، والاول هو العموم وما شاكله لان ذلك قد سمي مجملا من حيث يتناول جملة مسميات، ومن ذلك قيل أجملت الحساب، والثاني هو ما لا يمكن أن يعرف المراد به خلاف المفسر والمفسر ما تقدم له تفسير، وغرض الفقهاء غير هذا وإنما سموا ما يفهم المراد منه بنفسه مفسرا لما كان يتبين كما يتبين ماله تفسير، وأصل التأويل في العربية من ألت إلى الشئ أؤول إليه إذا صرت إليه، وقال تعالى \" وما يعلم تأويله إلا الله والراسخون في العلم \" (1) ولم يقل تفسيره لانه أراد ما يؤول من المتشابه إلى المحكم."},{"id":"furuq-lughawiyya:181","bookId":"furuq-lughawiyya","type":"section","seq":181,"chapter":"* (أ) *","title":"511 - الفرق بين التفسير والتأويل (2) : قد اختلف العلماء في تفسيرهما.","page":"ج1 ص129","text":"فقال أبو عبيدة، والمبرد: هما بمعنى.\nوقال الراغب: التفسير من التأويل، وأكثر استعماله في الالفاظ، ومفرداتها.\nوأكثر التأويل في المعاني والجمل، وأكثر ما يستعمل في الكتب\nالالهية، والتفسير يستعمل فيها وفي غيرها.\nوقال غيره: التفسير بيان لفظ لا يحتمل إلا وجها واحدا.\nوالتأويل: توجيه لفظ متوجه إلى معان مختلفة بما ظهر من الادلة.\nوقال الماتريدي (3) : التفسير: القطع على أن المراد من اللفظ هذا،\nوالشهادة على الله أنه عنى باللفظ هذا، فإن قام دليل مقطوع به فصحيح، وإلا فتفسير بالرأي.\nوهو المنهي عنه (1) .\nوالتأويل بترجيح أحد المحتملات بدون (2) القطع، والشهادة على الله سبحانه وتعالى.\nوقال الثعلبي (3) : التفسير بيان وضع اللفظة حقيقة أو مجازا كتفسير الصراط بالطريق، والصيب بالمطر.\nوالتأويل: تفسير باطن اللفظ مأخوذ من الاول وهو الرجوع لعاقبة الامر.\nفالتأويل: إخبار عن حقيقة المراد، والتفسير إخبار عن دليل المراد؟ لان اللفظ يكشف عن المراد، والكاشف دليل.\nمثاله قوله تعالى: \" إن ربك لبالمرصاد \" (4) .\nوتفسيره: إنه من الرصد، يقال رصدته أي رقبته، والمرصاد: مفعال منه.\nوتأويله: التحذير من التهاون بأمر الله سبحانه،\nوالغفلة عن الاهبة، والاستعداد للعرض عليه.\nوقواطع الادلة تقتضي بيان المراد منه على خلاف وضع اللفظ في اللغة.\nوقال الاصبهاني في (5) تفسيره: اعلم أن التفسير في عرف العلماء\nكشف معاني القرآن، وبيان المراد أعم من أن يكون بحسب اللفظ المشكل وغيره.\nوالتأويل: أكثره في الجمل، والتفسير إما أن يستعمل في غريب الالفاظ، نحو البحيرة (1) والسائبة (2) والوصيلة (3) ، أو في وجيز يتبين بشرح نحو \" واقيموا الصلاة واتوا الزكاة \" (4) .\nأو في كلام متضمن لقصة لا يمكن تصويره إلا بمعرفتها كقوله تعالى: \" إنما النسئ زيادة في الكفر \" (5) .\nوأما التأويل فإنه يستعمل تارة عاما، وتارة خاصا نحو الكفر المستعمل في الجحود المطلق، وتارة في جحود الباري خاصة، والايمان\nالمستعمل في التصديق المطلق تارة وفي تصديق الحق في (1) أخرى، وإما في لفظ مشترك بين معان مختلفة، نحو لفظ (وجد) المستعمل في الجدة والوجود.\nوقال غيره: التفسير يتعلق بالرواية، والتأويل يتعلق بالدراية.\nوقال قوم: ما وقع مبينا في الكتاب، ومعينا في صحيح السنة سمي\nتفسير، لان معناه قد ظهر ووضح، وليس لاحد أن يتعرض له باجتهاد (2) ولا غيره، بل بحمله على المعنى الذي ورد ولا يتعداه.\nوالتأويل: ما استنبطه العلماء العاملون بمعاني الخطاب، الماهرون في آيات العلوم.\nوقال الطبرسي (3) : التفسير كشف المراد عن اللفظ المشكل.\nوالتأويل: رد أحد المحتملين إلى ما يطابق الظاهر.\nوقال بعض المحققين: التفسير كشف الغطاء، ودفع الابهام بما لا يخالف الظاهر.\nومثله ما ورد في قوله سبحانه: \" وأقيموا الصلاة \" (4) من بيان أعدادها، وأوقاتها، وشرائطها، ونحو ذلك.\nومثل ما ورد في تفسير الاستطاعة في قوله سبحانه: \" من استطاع إليه سبيلا \" (5) .\nفي ذكر ماهية الاستطاعة، وشروطها، وما يتركب فيها، فإن شيئا من ذلك لا يخالف الظاهر.\nوالتأويل: صرف اللفظ عن ظاهره، لوجود ما يقتضي ذلك، مثل\nقوله سبحانه: \" وجوه يومئذ ناضرة إلى ربها ناظرة \" (1) .\nعلى أن المراد نظرها إلى رحمة ربها، أو انتظارها لنعمته وجنته.\nوحمل قوله سبحانه: \" وجاء ربك والملك صفا \" (2) على أن المراد\nوالمجئ أمر الرب أو جنوده وملائكته الفعالة لقيام الادلة القاطعة على امتناع الرؤية (3) ، والمجئ والذهاب وأمثالهما عليه سبحانه انتهى.\nأقول: لا يخفى أن غاية ما يتحصل من هذه الاقاويل يتخلص من هذه التفاصيل أن: التأويل له مزية زائدة على التفسير، ويرشد إليه قوله تعالى: \" وما يعلم تأويله إلا الله والراسخون في العلم \" (4) حيث حصر سبحانه علم التأويل في جنابه تعالى ومن رسخ في العلم قدمه واستضاء في طريق التحقيق علمه، ووقع على عجائب ما أودع فيه من الاسرار، وأطلع على تفاصيل ما اشتمل عليه من الاحكام والآثار.\nوقد دعا النبي صلى الله عليه وآله لابن عباس وقال (5) : \" اللهم فقهه في الدين، وعلمه التأويل \".\nفلو لم يكن للتأويل مزيد فضل لم يكن لتخصيص ابن عباس بذلك مع جلالة قدره، وعظيم شأنه (6) ، مزيد فائدة (7) .\n(اللغات)"},{"id":"furuq-lughawiyya:182","bookId":"furuq-lughawiyya","type":"section","seq":182,"chapter":"* (أ) *","title":"512 - الفرق بين التفصيل والتقسيم: أن في التفصيل معنى البيان عن كل قسم بما يزيد على ذكره فقط والتقسيم يحتمل الامرين، والتقسيم يفتح المعنى","page":"ج1 ص134","text":"والتفصيل يتم بيانه."},{"id":"furuq-lughawiyya:183","bookId":"furuq-lughawiyya","type":"section","seq":183,"chapter":"* (أ) *","title":"526 - الفرق بين التصديق والتقليد: (1) الفرق بينهما أن التصديق لا يكون فيما","page":"ج1 ص135","text":"يبرهن عند صاحبه.\nوالتقليد يكون فيما لم يبرهن.\nولهذا لا نكون مقلدين للنبي صلى الله عليه وآله، وإن كنا مصدقين له.\nقاله الطبرسي.\n(اللغات) ."},{"id":"furuq-lughawiyya:184","bookId":"furuq-lughawiyya","type":"section","seq":184,"chapter":"* (أ) *","title":"531 - الفرق بين التقوى والتقى (2) : قيل: التقوى خصلة من الطاعة يحترز بها من العقوبة.","page":"ج1 ص136","text":"والتقى: صفة مدح لا تطلق إلا [11 / أ] على من يستحق الثواب.\n(اللغات) ."},{"id":"furuq-lughawiyya:185","bookId":"furuq-lughawiyya","type":"section","seq":185,"chapter":"* (أ) *","title":"532 - الفرق بين التقوى (*) والطاعة (3) : المستفاد من الروايات هو أن الطاعة: الانقياد لمطلوب الشارع بما أمر به واجبا كان أم مستحبا.","page":"ج1 ص136","text":"والتقوى: كف النفس عما نهى الشارع عنه حراما كان أم مكروها.\nأقول: وهو المناسب لمعناهما عند اللغويين أيضا.\n(اللغات) ."},{"id":"furuq-lughawiyya:186","bookId":"furuq-lughawiyya","type":"section","seq":186,"chapter":"* (أ) *","title":"536 - الفرق بين التكرار والاعادة: أن التكرار يقع على إعادة الشئ مرة وعلى إعادته مرات، والاعادة للمرة الواحدة ألا ترى أن قول القائل أعاد فلان","page":"ج1 ص137","text":"كذا لا يفيد إلا إعادته مرة واحدة وإذا قال كرر كذا كان كلامه مبهما لم يدر أعاده مرتين أو مرات، وأيضا فإنه يقال أعاده مرات ولا يقال كرره مرات إلا أن يقول ذلك عامي لا يعرف الكلام، ولهذا قال الفقهاء الامر لا يقتضي التكرار والنهي يقتضي التكرار ولم يقولوا الاعادة، وإستدلوا على ذلك بأن النهي الكف عن المنهي ولا ضيق في الكف عنه ولا حرج فاقتضى الدوام والتكرار ولو إقتضى الامر التكرار للحق المأمور به الضيق والتشاغل به عن اموره فاقتضى فعله مرة ولو كان ظاهرا لامر يقتضي التكرار ما قال سراقة للنبي صلى الله عليه [وآله] وسلم ألعامنا هذا أم للابد فقال للنبي صلى الله عليه [وآله] وسلم للابد قال لو قلت نعم لوجبت، فأخبر أن الظاهر لا يوجبه وإنه يصير واجبا بقوله.\nوالمنهي عن الشئ إذا عاد إلى فعله لم يقل إنه قد إنتهى عنه وإذا أمر بالشئ ففعله مرة واحدة لم يقل إنه لم يفعله.\nفالفرق بين الامر والنهي في ذلك ظاهر، ومعلوم أن من يوكل غيره بطلاق إمرأته كان له أن يطلق مرة واحدة، وما كان من أوامر القرآن مقتضيا للتكرار فإن ذلك قد عرف من حاله بدليل لا يظاهره، ولا يتكرر (1) الامر مع الشرط أيضا ألا ترى إن من قال لغلامه إشتر اللحم إذا دخلت السوق لم يعقل ذلك التكرار."},{"id":"furuq-lughawiyya:187","bookId":"furuq-lughawiyya","type":"section","seq":187,"chapter":"* (أ) *","title":"538 - الفرق بين التكليف والابتلاء: أن التكليف إلزام ما يشق إرادة الانسانية عليه، وأصله في العربية اللزوم ومن ثم قيل كلف بفلانة يكلف بها كلفا","page":"ج1 ص138","text":"الملزم به على مشقة وهو الذي يلتزم ما لا يلزمه أيضا ومنه قوله تعالى \" وما أنا من المتكلفين \" (1) ومثله المكلف.\nوالابتلاء هو إستخراج ما عند المبتلي وتعرف حاله في الطاعة والمعصية بتحميله المشقة وليس هو من التكليف في شئ فإن سمي التكليف إبتلاء في بعض المواضع فقد يجري على الشئ إسم ما يقاربه في المعنى، وإستعمال الابتلاء في صفات الله تعالى مجاز معناه أنه يعامل العبد معاملة المبتلى المستخرج لما عنده ويقال للنعمة بلاء لانه يستخرج بها الشكر والبلى يستخرج قوة الشئ بإذهابه إلى حال البال فهذا كله أصل واحد."},{"id":"furuq-lughawiyya:188","bookId":"furuq-lughawiyya","type":"section","seq":188,"chapter":"* (أ) *","title":"الفرق بين التلاوة والقراءة","page":"ج1 ص139","text":"أن التلاوة لا تكون إلا لكلمتين فصاعدا، والقراءة تكون للكلمة الواحدة يقال قرأ فلان إسمه ولا يقال تلا اسمه وذلك أن أصل التلاوة إتباع الشئ الشئ يقال تلاه إذا تبعه فتكون التلاوة في الكلمات يتبع بعضها بعضا ولا تكون في الكلمة الواحدة إذ\nلا يصح فيه التلو."},{"id":"furuq-lughawiyya:189","bookId":"furuq-lughawiyya","type":"section","seq":189,"chapter":"* (أ) *","title":"542- الفرق بين التلاوة والقراءة","page":"ج1 ص139","text":"الفرق بين التلاوة والقراءة (1) : قال الراغب: التلاوة تختص باتباع كتب الله المنزلة تارة بالقراءة وتارة بالارتسام، لما فيها من أمر ونهي وترغيب وترهيب، أو ما يتوهم فيه ذلك، وهي أخص من القراءة، فكل تلاوة قراءة، وليس كل قراءة (2) تلاوة، فقوله تعالى: \" وإذا تتلى عليهم آياتنا \" (3) ، فهذا بالقراءة [11 / ب] وقوله تعالى: \" يتلونه حق تلاوته \" (4) .\nالمراد به الاتباع له بالعلم والعمل، وإنما استعمل التلاوة في قوله تعالى (5) : \" واتبعوا ما تتلوا الشياطين على ملك سليمان \" (6) .\nلما كان يزعم الشياطين أن ما يتلونه من كتب الله.\nانتهى.\nوقيل: إن معنى تتلو: تكذب.\nقال أبو مسلم: تلا عليه إذا كذب.\nفاليهود لما ادعوا أن سليمان إنما وجد تلك المملكة بسبب ذلك العلم كان (7) ذلك الادعاء كالافتراء على ملك سليمان.\nقال الطبرسي: الفرق بين القراءة والتلاوة أن أصل القراءة جمع الحروف (1) .\n(اللغات) ."},{"id":"furuq-lughawiyya:190","bookId":"furuq-lughawiyya","type":"section","seq":190,"chapter":"* (أ) *","title":"543 - الفرق بين التلقين والتعليم: أن التلقين يكون في الكلام فقط، والتعليم","page":"ج1 ص140","text":"يكون في الكلام وغيره تقول لقنه الشعر وغيره ولا يقال لقنه التجارة والنجارة والخياطة كما يقال علمه في جميع ذلك، واخرى فإن التعليم يكون في المرة الواحدة، والتلقين لا يكون إلا في المرات، واخرى فإن التلقين هو مشافهتك الغير بالتعليم وإلقاء القول إليه ليأخذه عنك ووضع الحروف مواضعها والتعليم لا يقتضي ذلك.\nولهذا لا يقال إن الله يلقن العبد كما يقال إن الله يعلمه."},{"id":"furuq-lughawiyya:191","bookId":"furuq-lughawiyya","type":"section","seq":191,"chapter":"* (أ) *","title":"548 - الفرق بين التمكين والاقدار: أن التمكين إعطاء ما يصح به الفعل كائنا ما كان من الآلات والعدد والقوى، والاقدار إعطاء القدرة وذلك أن الذي","page":"ج1 ص141","text":"منها إذا حضرت الآلة، والقدرة ضد العجز، والتمكن ضد التعذر."},{"id":"furuq-lughawiyya:192","bookId":"furuq-lughawiyya","type":"section","seq":192,"chapter":"* (أ) *","title":"551 - الفرق بين التمني والارادة: أن التمني معنى في النفس يقع عند فوت فعل كان للمتمني في وقوعه نفع أو في زواله ضرر مستقبلا كان ذلك الفعل أو م","page":"ج1 ص142","text":"قوله تعالى \" من نطفة إذا تمنى \" (1) ، وتمنى كذب وروي إن بعضهم قال للشعبي: أهذا مما رويته أو مما تمنيته أي كذبت في روايته، وأما التمني في قوله تعالى \" فتمنوا الموت إن كنتم صادقين \" (2) فلا يكون إلا قولا وهو أن يقول أحدهم ليته مات، ومتى قال الانسان ليت الآن كذا فهو عند أهل اللسان متمن غير اعتبارهم لضميره ويستحيل أن يتحداهم\nبأن يتمنوا ذلك بقلوبهم مع علم الجميع بأن التحدي بالضمير لا يعجز أحدا ولا يدل على صحة مقالته ولا فسادها لان المتحدي بذلك يمكنه أن يقول تمنيت بقلبي فلا يمكن خصمه إقامة الدليل على كذبه، ولو إنصرف ذلك إلى تمني القلب دون العبارة باللسان لقالوا قد تمنينا ذلك بقلوبنا فكانوا مساوين له فيه وسقط بذلك دلالته على كذبهم وعلى صحة ثبوته فلما لم يقولوا ذلك علم أن التحدي وقع بالتمني لفظا."},{"id":"furuq-lughawiyya:193","bookId":"furuq-lughawiyya","type":"section","seq":193,"chapter":"* (أ) *","title":"553 - الفرق بين التمني والمحبة (3) : قد فرق بينهما بأن التمني قد يقع على الماضي والمستقبل.","page":"ج1 ص142","text":"ألا ترى أنه يصح أن يتمنى أن كان له ولد، ويصح أن يتمنى أن يكون له ولد.\nوالمحبة لا تقع إلا على المستقبل، وبه يظهر الفرق بين المحبة والمودة، لان المودة قد تكون بمعنى التمني كقولك: أو دلو قدم زيد، بمعنى: أتمنى قدومه، ولا يجوز أحب لو قدم زيد.\n(اللغات) ."},{"id":"furuq-lughawiyya:194","bookId":"furuq-lughawiyya","type":"section","seq":194,"chapter":"* (أ) *","title":"555 - الفرق بين التمويه والسحر: أن التمويه هو تغطية الصواب وتصوير الخطأ بغير صورته، وأصله طلاء الحديد والصفر (1) بالذهب والفضة ليوهم أنه ذهب","page":"ج1 ص143","text":"والسحر إسم لما دق من الحيلة\nحتى لا تفطن الطريقة، وقال بعضهم التمويه إسم لكل حيلة لا تأثير لها قال ولا يقال تمويه إلا وقد عرف معناه والمقصد منه، ويقال سحر وإن لم يعرف المقصد منه ولهذا قيل: التمويه ما لا يثبت، وقيل التمويه أن ترى شيئا مجوزا بغيره كما يفعل مموه الحديد فيجوزه بالذهب.\nوسمى النبي صلى الله عليه [وآله] وسلم البيان سحرا وذلك، أن البليغ يبلغ ببلاغته ما لا يبلغ الساحر بلطافة حيلته."},{"id":"furuq-lughawiyya:195","bookId":"furuq-lughawiyya","type":"section","seq":195,"chapter":"* (أ) *","title":"556 - الفرق بين التناقض والتضاد: أن التناقض يكون في الاقوال والتضاد يكون في الافعال يقال الفعلان متضادان ولا يقال متناقضان فإذا جعل الفعل مع","page":"ج1 ص144","text":"المعنى دون الوجود، وكل متضادين متنافيان وليس كل متنافيين ضدين عند أبي علي كالموت والارادة وقال أبو بكر: هما ضدان لتمانعهما وتدافعهما قال ولهذا سمي القرنان المتقاومان ضدين.\nومما يجري مع هذا وإن لم يكن قولا التنافي والتضاد والفرق بينهما أن التنافي لا يكون إلا بين شيئين يجوز عليهما البقاء، والتضاد يكون بين ما يبقى وما لا يبقى."},{"id":"furuq-lughawiyya:196","bookId":"furuq-lughawiyya","type":"section","seq":196,"chapter":"* (أ) *","title":"569 - الفرق بين التوبة والاعتذار: أن التائب مقر بالذنب الذي يتوب منه","page":"ج1 ص145","text":"معترف بعدم عذره فيه والمعتذر يذكر أن له فيما أتاه من المكروه عذرا ولو كان الاعتذار التوبة لجاز أن يقال إعتذر إلى الله كما يقال تاب إليه وأصل العذر إزالة الشئ عن جهته إعتذر إلى فلان فعذره أي أزال ما كان في نفسه عليه في الحقيقة أو في الظاهر ويقال عذرته عذيرا، ولهذ يقال من عذيري من فلان وتأويله من يأتيني بعذر منه ومنه قوله تعالى \" عذرا أو نذرا \" (1) والنذر جمع نذير."},{"id":"furuq-lughawiyya:197","bookId":"furuq-lughawiyya","type":"section","seq":197,"chapter":"* (أ) *","title":"570 - الفرق بين التوبة والانابة (2) : قيل: التوبة هي الندم على فعل ما سبق.","page":"ج1 ص145","text":"والانابة: ترك المعاصي في المستقبل.\nقلت: ويشهد لذلك قول سيد الساجدين - عليه السلام - في الصحيفة\nالشريفة: \" اللهم إن يكن الندم توبة إليك فأنا أندم النادمين، وإن يكن الترك لمعصيتك إنابة فأنا أول المنيبين \" (1) (اللغات) ."},{"id":"furuq-lughawiyya:198","bookId":"furuq-lughawiyya","type":"section","seq":198,"chapter":"* (أ) *","title":"577 - الفرق بين التوقير والوقار: أن التوقير يستعمل في معنى التعظيم يقال وقرته إذا عظمته وقد أقيم الوقار موضع التوقير في قوله تعالى \" مالكم ل","page":"ج1 ص147","text":"ابن أبي سلمة رحمه الله: الله جل إسمه لا يوصف بالوقار ويوصف العباد بأنهم يوقرونه أي يعظمونه ولا يقال إنه وقور بمعنى عظيم كما يقال إنه يوقر بمعنى يعظم لان الصفة بالوقور ترجع إليه إذا وصف بها، قال أبو هلال: وهي غير لائقة به لان الوقار مما تتغير به الهيبة، قال أبو أحمد: والصفة بالتوقير ترجع إلى من توقره، قال أبو هلال أيده الله تعالى: عندنا أنه يوصف بالتوقير إن وصف به على معنى التعظيم لا لغير ذلك."},{"id":"furuq-lughawiyya:199","bookId":"furuq-lughawiyya","type":"section","seq":199,"chapter":"* (أ) *","title":"ث","page":"ج1 ص147","text":"م كثر حتى استعمل في غير ذلك."},{"id":"furuq-lughawiyya:200","bookId":"furuq-lughawiyya","type":"section","seq":200,"chapter":"* (أ) *","title":"584 - الفرق بين الثرد والثريد (2) : في الحديث أن النبي صلى الله عليه وآله قال: \" بورك لامتي في الثرد والثريد \".","page":"ج1 ص148","text":"قيل: الثرد ما صغر، والثريد.\nما كبر.\nوفي الحديث: \" أول من ثرد الثريد إبراهيم عليه السلام وأول من هشم الثريد هاشم \" (3) .\nوكأن الفرق بينهما أن الثرد في غير اليابس، والهشيم في اليابس.\nقال الجوهري: الهشم كسر اليابس، يقال هشم الثريد، وبه سمي هاشم.\n(اللغات) ."},{"id":"furuq-lughawiyya:201","bookId":"furuq-lughawiyya","type":"section","seq":201,"chapter":"* (أ) *","title":"587 - الفرق بين الثمين (1) والمثمن (2) : قال الحريري في درة الغواص: الثمين يقال لما كثر ثمنه، كما يقال: رجل لحيم، إذا كثر لحمه، وكبش شحيم، إ","page":"ج1 ص149","text":"والمثمن: هو الذي صار له ثمن - وإن قل - كما يقال: غصن مورق، إذا بدا فيه الورق - وإن قل - وشجر مثمر، إذا أخرج الثمرة.\n(اللغات) ."},{"id":"furuq-lughawiyya:202","bookId":"furuq-lughawiyya","type":"section","seq":202,"chapter":"* (أ) *","title":"590 - الفرق بين الثناء والنثاء على ما قال أبو أحمد بن عبد الله بن سعيد رحمه","page":"ج1 ص150","text":"الله: (1) أن الثناء يكون في الخير والشر يقال أثنى عليه بخير وأثنى عليه بشر والنثا مقصور لا يكون إلا في الشر ونحن سمعناه في الخير والشر، والصحيح عندنا أن النثاء هو بسط القول في مدح الرجل أو ذمه وهو مثل النث نث الحديث نثا إذا نشره ويقولون"},{"id":"furuq-lughawiyya:203","bookId":"furuq-lughawiyya","type":"section","seq":203,"chapter":"* (أ) *","title":"ج","page":"ج1 ص150","text":"اءني نثا خبر ساءني يريدون\nإنتشاره وإستفاضته، وقال أبو بكر: الثناء بالمد لا يكون إلا في الخير وربما أستعمل في الشر والنثا يكون في الخير والشر، وهذا خلاف ما حكاه أبو أحمد والثناء عندنا هو بسط القول مدحا أو ذما والنثا تكريره فالفرق بينهما بين."},{"id":"furuq-lughawiyya:204","bookId":"furuq-lughawiyya","type":"section","seq":204,"chapter":"* (أ) *","title":"596 - الفرق بين الجانب والناحية والجهة قال المتكلمون (1) : أن جانب الشئ غيره وجهته ليست غيره ألا ترى أن الله تعالى لو خلق الجزء الذي لا يتجز","page":"ج1 ص151","text":"وجهته بعضه أو ما هو في حكم البعض.\nيقال ناحية العراق أي العراق كلها وجهة العراق يراد بها بعض أطرافها.\nوعند أهل العربية أن الوجه مستقبل كل شئ، والجهة النحو يقال كذا على جهة كذا قاله الخليل:\nقال ويقال رجل احمر من جهة الحمرة وأسود من جهة السواد، والوجهة القبلة قال تعالى \" ولكل وجهة \" (1) أي في كل وجه استقبلته وأخذت فيه، وتجاه الشئ ما إستقبلته يقال توجهوا إليك ووجهوا إليك كل يقال غير ان قولك وجهوا إليك على معنى ولوا وجوههم والتوجه الفعل اللازم والناحية فاعلة بمعنى مفعولة وذلك أنها منحوة أي مقصودة كما تقول راحلة وإنما هي مرحولة وعيشة راضية أي مرضية."},{"id":"furuq-lughawiyya:205","bookId":"furuq-lughawiyya","type":"section","seq":205,"chapter":"* (أ) *","title":"599 - الفرق بين الجبار والقهار (2) : الجبار في صفة الله عزوجل صفة تعظيم، لانه يفيد الاقتدار، وهو - سبحانه - لم يزل جبارا، بمعنى: أن ذاته تدع","page":"ج1 ص152","text":"العوارف بها إلى تعظيمها.\nوالقهار: هو الغالب لمن ناوأه، أو كان في حكم المناوى، بمعصيته إياه.\nولا يوصف - سبحانه - فيما لم يزل بأنه قهار.\nوالجبار في صفة المخلوقين صفة ذم لانه يتعظم لما ليس له، فإن العظمة لله سبحانه.\nقال تعالى: \" وإذا بطشتم بطشتم جبارين \" (1) .\nوقال تعالى حكاية عن عيسى عليه السلام \" ولم يجعلني جبارا شقيا \" (2) .\n(اللغات) ."},{"id":"furuq-lughawiyya:206","bookId":"furuq-lughawiyya","type":"section","seq":206,"chapter":"* (أ) *","title":"600 - الفرق بين الجبت والطاغوت (3) : قيل: هما صنمان كانا لقريش.","page":"ج1 ص153","text":"وقيل: الجبت، الاصنام.\nوالطاغوت، تراجمة الاصنام الذين كانوا يتكلمون بالكذب عنها.\nوقيل: الجبت، الساحر، والطاغوت: * (4) الكاهن.\nوقيل: الجبت: إبليس، والطاغوت (5) : أولياؤه.\nوقيل: هما كل ما عبد من دون الله من حجر أو صورة أو شيطان.\nوهو الاولى لشموله كل ما ذكر.\n* (6) ويؤيده قوله - سبحانه \" فمن يكفر بالطاغوت ويؤمن بالله \" (7) .\n(اللغات) ."},{"id":"furuq-lughawiyya:207","bookId":"furuq-lughawiyya","type":"section","seq":207,"chapter":"* (أ) *","title":"604 - الفرق بين الجبهة والجبين (3) : الجهة: مسجد الرجل الذي يصيبه ندب السجود، والجبينان يكتنفانها: من كل جانب جبين.","page":"ج1 ص155","text":"قاله صاحب أدب الكتاب.\n(اللغات) ."},{"id":"furuq-lughawiyya:208","bookId":"furuq-lughawiyya","type":"section","seq":208,"chapter":"* (أ) *","title":"610 - الفرق بين الجدال والحجاج (1) : الفرق بينهما أن المطلوب بالحجاج هو (2) ظهور الحجة.","page":"ج1 ص157","text":"والمطلوب بالجدال: الرجوع عن المذهب، فإن أصله من الجدل، وهو شدة القتل، ومنه الاجدل لشدة قوته من بين الجوارح، ويؤيده قوله تعالى: \" قالوا يا نوح قد جادلتنا فاكثرت جدالنا \" (3) .\nوقوله تعالى: \" وجادلهم بالتي هي أحسن \" (4) .\nوذلك أن دأب الانبياء عليهم السلام (5) كان ردع القوم عن المذاهب الباطلة، وإدخالهم في دين الله ببذل القوة والاجتهاد في إيراد الادلة والحجج.\nهذا وقد يراد بالجدال مطلق المخاصمة، ومنه قوله تعالى: \" فما أنتم هؤلاء جادلتم عنهم في الحياة الدنيا فمن يجادل الله عنهم يوم القيامة \" (6) .\nوقوله تعالى: \" يجادلون في آيات الله بغير سلطان أتاهم \" (7) .\nوأما قوله تعالى: \" فلما ذهب عن إبراهيم الروع وجاءته البشرى يجادلنا في قوم لوط \" (8) ... الآية.\nفقيل إنه قال للملائكة: بأي شئ استحقوا عذاب الاستئصال وهل ذلك واقع لا محالة أم هو تخويف لهم (9) ليرجعوا إلى الطاعة؟ وبأي شئ يهلكون؟ وكيف ينجي الله المؤمنين؟ فسمي ذلك السؤال المستقصي جدالا.\nفالمراد: يجادل رسلنا وتلك المجادلة إنما كان\nمن رقة قلبه * رحمته وشدة رأفت عليه السلام * (1) .\nوفي قوله تعالى: \" إن ابراهيم لحليم أواه منيب \" (2) .\nإشارة إلى هذا (3) .\n(اللغات) ."},{"id":"furuq-lughawiyya:209","bookId":"furuq-lughawiyya","type":"section","seq":209,"chapter":"* (أ) *","title":"611 - الفرق بين الجدال والمراء (4) : قيل: هما بمعنى.","page":"ج1 ص158","text":"غير أن المراء مذموم، لانه مخاصمة في الحق بعد ظهوره وليس كذلك الجدال.\n(اللغات) ."},{"id":"furuq-lughawiyya:210","bookId":"furuq-lughawiyya","type":"section","seq":210,"chapter":"* (أ) *","title":"618 - الفرق بين الجرم والجسم: أن جرم الشئ هو خلقته التي خلق عليها يقال فلان صغير الجرم أي صغير من أصل الخلقة، أصل الجرم في العربية القطع كأن","page":"ج1 ص159","text":"غير المبالغة فقيل أمر جسيم وكل ما لا يطلق إلا في موضع مخصوص فهو مجاز."},{"id":"furuq-lughawiyya:211","bookId":"furuq-lughawiyya","type":"section","seq":211,"chapter":"* (أ) *","title":"624 - الفرق بين الجزء من الجملة والسهم من الجملة: أن الجزء منها ما انقسمت عليه فالاثنان جزء من العشرة لانهما ينقسمان عليها والثلاثة ليست بجز","page":"ج1 ص160","text":"السهم يقع على السدس ويقع على سهام الورثة وما يدخل في قسمة الميراث فأنصباء الورثة تسمى سهاما فتعطيه مثل أحسن سهام الورثة إذا كان أقل من السدس لانا لا نعطيه الزيادة على الاخس إلا بدلالة وإن كان أنقص من السدس نقصناه من السدس لانه يسمى سهما ولا تزيده على السدس لان السدس يعبر عنه بالسهم فلا نزيده عليه إلا بدلالة."},{"id":"furuq-lughawiyya:212","bookId":"furuq-lughawiyya","type":"section","seq":212,"chapter":"* (أ) *","title":"625 - الفرق بين الجزء والسهم (1) : الفرق بينهما أن السهم من الجملة ما ينقسم عليه، نحو الاثنين من العشرة.","page":"ج1 ص161","text":"وقد يقال: الجزء لما لا ينقسم عليه، نحو الثلاثة من العشرة، ولا تنقسم العشرة عليها وإن كانت الثلاثة جزء من العشرة.\nقاله الطبرسي.\nوربما يخص الجزء بالعشر، وفرع عليه الفقهاء أنه لو أوصى بجزء من ماله انصرف إلى العشر، وقد وردت بذلك رواية عن طريق الاصحاب رضوان الله عليهم - أجمعين (2) استئناسا بقوله تعالى: \" ثم اجعل على كل جبل منهم جزء \" (3) وكانت الجبال يومئذ عشرة.\n(اللغات)"},{"id":"furuq-lughawiyya:213","bookId":"furuq-lughawiyya","type":"section","seq":213,"chapter":"* (أ) *","title":"627 - الفرق بين الجسد والطلل: أن الجسد يفيد الكثافة ولا يفيد الطلل والشخص ذلك وهو من قولك دم جاسد أي جامد، والجسد أيضا الدم بعينه قال النابغ","page":"ج1 ص162","text":"فيجوز أن يقال إنه سمي جسدا لما فيه من الدم فلهذا خص به الحيوان فيقال جسد الانسان وجسد الحمار ولا يقال جسد الخشبة كما يقال جرم الخشبة وإن قيل ذلك فعلى التقريب والاستعارة ويقال ثوب مجسد إذا - كان يقوم من كثافة صبغه وقيل للزعفران جساد تشبيها.\nبحمرة الدم."},{"id":"furuq-lughawiyya:214","bookId":"furuq-lughawiyya","type":"section","seq":214,"chapter":"* (أ) *","title":"628 - الفرق بين الجسر والقنطرة (1) : القنطرة ما بينى على الماء، للعبور عليه، والجسر أعم منه، لانه يكون بناء وغير بناء.","page":"ج1 ص162","text":"(اللغات)"},{"id":"furuq-lughawiyya:215","bookId":"furuq-lughawiyya","type":"section","seq":215,"chapter":"* (أ) *","title":"634 - الفرق بين الجلالة والجلال (1) : قال الراغب: الجلالة - بالهاء - عظم القدر والجلال - بغير الهاء - التناهي في ذلك، وخص بوصف الله تعالى، ف","page":"ج1 ص163","text":"(اللغات)"},{"id":"furuq-lughawiyya:216","bookId":"furuq-lughawiyya","type":"section","seq":216,"chapter":"* (أ) *","title":"637 - الفرق بين الجلوس والقعود (3) : قد فرق بينهما بأن الجلوس: هو الانتقال من سفل إلى علو.","page":"ج1 ص163","text":"والقعود: هو الانتقال من علو إلى أسفل.\nفعلى الاول يقال لمن هو نائم: اجلس، وعلى الثاني لمن هو قائم: اقعد.\nقيل: وقد يستعمل جلس بمعنى قعد، كما يقال [13 / ب] جلس\nمتربعا، قد متربعا (1) ، وفي حديث القبر: (2) إذا وضع الميت في القبر يقعدانه، ويجوز أن يراد به الايقاظ تجوزا واتساعا.\n(اللغات) ."},{"id":"furuq-lughawiyya:217","bookId":"furuq-lughawiyya","type":"section","seq":217,"chapter":"* (أ) *","title":"647 - الفرق بين الجمال والحسن: أن الجمال هو ما يشتهر ويرتفع به الانسان من","page":"ج1 ص165","text":"الافعال والاخلاق ومن كثرة المال والجسم وليس هو من الحسن في شئ ألا ترى انه يقال لك في هذا الامر جمال ولا يقال لك فيه حسن، وفي القرآن \" ولكم فيها جمال حين تريحون وحين تسرحون \" (1) يعني الخيل والابل.\nوالحسن في الاصل الصورة ثم استعمل في الافعال\nوالاخلاق: والجمال في الاصل للافعال والاخلاق والاحوال الظاهرة ثم استعمل في الصور، وأصل الجمال في العربية العظم ومنه قيل الجملة لانها أعظم من التفاريق والجمل الحبل الغليظ والجمل سمي جملا لعظم خلقته، ومنه قيل للشحم جميل لعظم نفعه."},{"id":"furuq-lughawiyya:218","bookId":"furuq-lughawiyya","type":"section","seq":218,"chapter":"* (أ) *","title":"651 - الفرق بين الجمع والتأليف: أن بعضهم قال لفظ التأليف في العربية يدل على الالصاق ولفظ الجمع لا يدل على ذلك ألا ترى أنك تقول جمعت بين القو","page":"ج1 ص166","text":"قلوبهم \" (1) ويقال جمع بين الاهواء ولا يقال ألف بين الاهواء لانها أعراض، وعندنا أن التأليف والالفة في العربية تفيد الموافقة، والجمع لا يفيد ذلك ألا ترى أن قولك تألف الشئ وألفته يفيد موافقة بعضه لبعض وقولك إجتمع الشئ وجمعته لا يفيد ذلك ولهذا قال تعالى \" وألف بين قلوبهم \" لانها اتفقت على المودة والمصافاة، ومنه قيل\nالالفان والاليفان لموافقة أحدهما صاحبه على المودة والتواصل والانسة، والتأليف عند المتكلمين ما يجب حلوله في محلين فإنما قيل يجب ليدخل فيه المعدوم، والاجتماع عندهم ما صار به الجوهر أن يحب لا قرب قريب منه، وقد يسمون التأليف مماسة وإجتماعا، وقال بعضهم الخشونة واللين والصقال يرجع إلى التأليف، وقال آخرون يرجع إلى ذهاب الجسم في جهات."},{"id":"furuq-lughawiyya:219","bookId":"furuq-lughawiyya","type":"section","seq":219,"chapter":"* (أ) *","title":"660 - الفرق بين الجنس والوجه: أن الجنس يقع على الذوات، والوجه يتناول الصفات يقال الجواهر جنس من الاشياء ولا يقال وجه منها وإنما يقال","page":"ج1 ص167","text":"الشئ على وجوه أي على صفات."},{"id":"furuq-lughawiyya:220","bookId":"furuq-lughawiyya","type":"section","seq":220,"chapter":"* (أ) *","title":"664 - الفرق بين الجهر والاظهار: أن الجهر عموم الاظهار والمبالغة فيه ألا ترى أنك إذا كشفت الامر للرجل والرجلين قلت أظهرته لهما ولا تقول جهرت","page":"ج1 ص168","text":"جهرة \" (1) أي عيانا لا شك معه، وأصله رفع الصوت يقال جهر بالقراءة إذا رفع صوته بها وفي القرآن \" ولا تجهر بصلاتك ولا تخافت بها \" (2) أي بقراءتك في صلاتك، وصوت جهير رفيع الصوت ولهذا يتعدى بالباء فيقال جهرت به كما تقول رفع صوته به لانه في معناه وهو في غير ذلك إستعارة، وأصل الجهر إظهار المعنى للنفس وإذا أخرج الشئ من وعاء أو بيت لم يكن ذلك جهرا وكان إظهارا، وقد يحصل الجهر نقيض الهمس لان المعنى يظهر للنفس بظهور الصوت."},{"id":"furuq-lughawiyya:221","bookId":"furuq-lughawiyya","type":"section","seq":221,"chapter":"* (أ) *","title":"671 - الفرق بين الجوارح والاعضاء (1) : الجوارح: أعضاء الانسان التي يكتسب بها، كيديه ورجليه.","page":"ج1 ص169","text":"قال تعالى: \" ويعلم ما جرحتم \" (2) .\nأي كسبتم.\nوالجوارح: الصوائد من السباع والطير، سميت بذلك لانها كواسب\n[14 / أ] بأنفسها.\nقال تعالى: \" وما علمتم من الجوارح \" (3) .\nفكل جارحة عضو ولا ينعكس.\n(اللغات)"},{"id":"furuq-lughawiyya:222","bookId":"furuq-lughawiyya","type":"section","seq":222,"chapter":"* (أ) *","title":"الفرق بين الجود والكرم","page":"ج1 ص169","text":"أن الجود هو الذي ذكرناه (4) ، والكرم يتصرف على وجوه فيقال لله تعالى كريم ومعناه أنه عزيز وهو من صفات ذاته ومنه قوله تعالى \" ما غرك بربك الكريم \" (5) أي العزيز الذي لا يغلب،\nويكون بمعنى الجواد المفضال فيكون من صفات فعله، ويقال رزق كريم إذا لم يكن فيه إمتهان أي كرم صاحبه، والكريم الحسن في قوله تعالى \" من كل زوج كريم \" (1) ومثله \" وقل لهما قولا كريما \" (2) أي حسنا والكريم بمعنى المفضل في قوله تعالى \" إن أكرمكم عند الله أتقاكم \" (3) أي أفضلكم ومنه قوله تعالى \" ولقد كرمنا بني آدم \" (4) أي فضلناهم، والكريم أيضا السيد في قوله صلى الله عليه [وآله] وسلم \" إذا أتاكم كريم قوم فاكرموه \" أي سيد قوم، ويجوز أن يقال الكرم هو إعطاء الشئ عن طيب نفس قليلا كان أو كثيرا، والجود سعة العطاء ومنه سمي المطر الغزير الواسع جودا سواء كان عن طيب نفس أو لا، ويجوز أن يقال الكريم هو إعطاء من يريد إكرامه وإعزازه، والجواد قد يكون كذلك وقد لا يكون."},{"id":"furuq-lughawiyya:223","bookId":"furuq-lughawiyya","type":"section","seq":223,"chapter":"* (أ) *","title":"674 - الفرق بين الجود والكرم (5) : قيل في الفرق بينهما أن الجواد هو الذي يعطي مع السؤال.","page":"ج1 ص170","text":"والكريم: الذي يعطي من غير سؤال.\nوقيل بالعكس.\nوالحق: الاول، لما ورد في أدعية الصحيفة الشريفة: (6) \" وأنت الجواد الكريم \" ترقيا في الصفات العلية من الادنى إلى الاعلى.\nوقيل: الجود إفادة ما ينبغي لا لغرض (7) .\nوالكرم: إيثار الغير بالخير (1) .\n(اللغات)"},{"id":"furuq-lughawiyya:224","bookId":"furuq-lughawiyya","type":"section","seq":224,"chapter":"* (أ) *","title":"ح","page":"ج1 ص171","text":"كمه والسلطان في سيرته إذا فارق الاستقامة في ذلك، والظلم ضرر لا يستحق ولا يعقب عوضا سواء كان من سلطان أو حاكم أو غيرهما ألا ترى أن خيانة الدانق والدرهم تسمى ظلما ولا تسمى جورا فإن أخذ ذلك على وجه القهر أو الميل سمي جورا وهذا واضح، وأصل الظلم نقصان الحق، والجور العدول عن الحق من قولنا جار عن الطريق إذا عدل عنه وخلف بين النقيضين فقيل في نقيض الظلم الانصاف وهو إعطاء الحق على التمام، وفي نقيض الجور العدل وهو العدول بالفعل إلى الحق."},{"id":"furuq-lughawiyya:225","bookId":"furuq-lughawiyya","type":"section","seq":225,"chapter":"* (أ) *","title":"678 - الفرق بين الحاذر والحذر (1) : قيل: الحاذر: الفاعل للحذر.","page":"ج1 ص172","text":"والحذر: المطبوع على الحذر، فهو أبلغ.\nوقرئ بهما قوله تعالى: \" وإنا لجميع حاذرون \" (2) .\n(اللغات) ."},{"id":"furuq-lughawiyya:226","bookId":"furuq-lughawiyya","type":"section","seq":226,"chapter":"* (أ) *","title":"685 - الفرق بين قولك لا يحبه وقولك يبغضه: أن قولك لا يحبه أبلغ من حيث","page":"ج1 ص173","text":"يتوهم إذا قال يبغضه إنه يبغضه من وجه ويحبه من وجه كما إذا قلت يجهله جاز أن يجهله من وجه ويعلمه من وجه وإذا قلت لا يعلمه لم يحتمل الوجهين."},{"id":"furuq-lughawiyya:227","bookId":"furuq-lughawiyya","type":"section","seq":227,"chapter":"* (أ) *","title":"الفرق بين الحبور والسرور","page":"ج1 ص173","text":"أن الحبور هي النعمة الحسنة من قولك حبرت الثوب إذا حسنته وفسر قوله تعالى \" في روضة يحبرون \" (2) أي تنعمون وإنما يسمى السرور حبورا لانه يكون مع النعمة الحسنة، وقيل في المثل: ما من دار ملئت حبرة إلا ستملا عبرة قالوا الحبرة هاهنا السرور والعبرة\nالحزن، وقال العجاج: الحمد لله الذي أعطى الحبر * هو إلى الحق أن المولى شكر وقال الفراء: الحبور الكرامة، وعندنا أن هذا على جهة الاستعارة، والاصل فيه النعمة الحسنة ومنه قولهم للعالم حبر لانه حبر بأحسن الاخلاق، والمداد حبر لانه يحسن الكتب."},{"id":"furuq-lughawiyya:228","bookId":"furuq-lughawiyya","type":"section","seq":228,"chapter":"* (أ) *","title":"689 - الفرق بين الحبور والسرور (1) : قيل: السرور: انبساط القلب لنيل محبوب أو توقعه.","page":"ج1 ص174","text":"والحبور: السرور الذي يظهر في الوجه أثره، فهو أشد السرور، ولذا خاطب - سبحانه - أهل الجنة بقوله: \" ادخلوا الجنة أنتم وأزواجكم تحبرون \" (2) .\n(اللغات)"},{"id":"furuq-lughawiyya:229","bookId":"furuq-lughawiyya","type":"section","seq":229,"chapter":"* (أ) *","title":"691 - الفرق بين الحث والحض (3) : قال الخليل: الحث يكون في السير","page":"ج1 ص175","text":"والسوق، والحض يكون فبما عداهما نحو قوله تعالى: \" ولا يحض على طعام المسكين \" (1) .\n(اللغات) ."},{"id":"furuq-lughawiyya:230","bookId":"furuq-lughawiyya","type":"section","seq":230,"chapter":"* (أ) *","title":"694 - الفرق بين الحجاب والستر والغطاء: أنك تقول حجبني فلان عن كذا ولا تقول سترني عنه ولا غطاني، وتقول إحتجبت بشئ كما تقول تسترت","page":"ج1 ص175","text":"به فالحجاب هو المانع والممنوع به والستر هو المستور به، ويجوز أن يقال حجاب الشئ ما قصد ستره ألا ترى انك لا تقول لمن منع غيره من الدخول إلى الرئيس داره من غير قصد المنع له أنه حجبه، وإنما يقال حجبه إذا قصد منعه ولا تقول إحتجبت بالبيت إلا إذا قصدت منع غيرك عن مشاهدتك ألا ترى أنك إذا جلست في البيت ولم تقصد ذلك لم تقل إنك قد إحتجبت.\nوفرق آخر أن الستر لا يمنع من الدخول على المستور والحجاب يمنع."},{"id":"furuq-lughawiyya:231","bookId":"furuq-lughawiyya","type":"section","seq":231,"chapter":"* (أ) *","title":"698 - الفرق بين الحدث والخبث (1) : الحدث: هو الاثر الحاصل للمكلف، وشبهه عند عروض أحد أسباب الوضوء، والغسل المانع من الصلاة، المتوقف رفعه على","page":"ج1 ص176","text":"والخبث: هو النجس.\nوفرق بينهما بأن الحدث ما افتقر إلى النية، والخبث ما لا يفتقر إليها،\nوأن الاول ما لا يدرك بالحس، والثاني ما يدرك به.\n(اللغات) ."},{"id":"furuq-lughawiyya:232","bookId":"furuq-lughawiyya","type":"section","seq":232,"chapter":"* (أ) *","title":"699 - الفرق بين الحد والاسم: أن الحد يوجب المعرفة بالمحدود من غير الوجه المذكور في المسألة عنه فيجمع للسائل المعرفة من وجهين.","page":"ج1 ص176","text":"وفرق آخر وهو أنه قد يكون في الاسماء مشترك وغير مشترك مما يقع الالتباس فيه بين المتجادلين فإذا توافقا على الحد زال ذلك.\nوفرق آخر وهو أنه قد يكون مما يقع عليه الاسم ما هو مشكل فإذا جاء الحد زال ذلك.\nمثاله قول النحويين الاسم والفعل والحرف.\nوفي ذلك إشكال فإذا جاء الحد أبان.\nوفرق آخر وهو أن الاسم يستعمل على وجه الاستعارة والحقيقة فإذا جاء الحد بين ذلك وميزه."},{"id":"furuq-lughawiyya:233","bookId":"furuq-lughawiyya","type":"section","seq":233,"chapter":"* (أ) *","title":"700 - الفرق بين الحد والحقيقة: أن الحد ما أبان الشئ وفصله من أقرب","page":"ج1 ص177","text":"الاشياء بحيث منع من مخالطة غيره له وأصله في العربية المنع.\nوالحقيقة ما وضع من القول موضعه في أصله اللغة والشاهد أنها مقتضية المجاز وليس المجاز إلا قولا فلا يجوز أن يكون ما يناقضه إلا قولا.\nومثل ذلك الصدق لما كان قولا كان نقيضه وهو الكذب قولا ثم يسمى ما يعبر عنه بالحقيقة وهو الذات حقيقة مجازا فهي على الوجهين مفارقة للحد مفارقة بينة.\nوالفرق بينهما أيضا أن الحد لا يكون إلا لما له غير يجمعه واياه جنس قد فصل بالحد بينه وبينه.\nوالحقيقة تكون كذلك ولما ليس له غير كقولنا شئ والشئ لا حد له من حيث هو شئ وذلك أن الحد هو المانع للمحدود من الاختلاط بغيره والشئ لا غير له ولو كان له غير لما كان شيئا كما أن غير اللون ليس بلون فتقول ما حقيقة الشئ ولا تقول ما حد\nالشئ.\nوفرق آخر وهو أن العلم بالحد هو علم به وبما يميزه والعلم بالحقيقة علم بذاتها."},{"id":"furuq-lughawiyya:234","bookId":"furuq-lughawiyya","type":"section","seq":234,"chapter":"* (أ) *","title":"701 - الفرق بين الحد والرسم: أن الحد اتم ما يكون من البيان عن المحدود.","page":"ج1 ص177","text":"والرسم مثل السمة يخبر به حيث يعسر التحديد.\nولابد للحد من الاشعار بالاصل إذا أمكن ذلك فيه والرسم غير محتاج إلى ذلك.\nوأصل الرسم في اللغة العلامة ومنه رسوم الديار.\nوفرق المنطقيون بين الرسم والحد فقالوا الحد مأخوذ من طبيعة الشئ والرسم من أعراضه."},{"id":"furuq-lughawiyya:235","bookId":"furuq-lughawiyya","type":"section","seq":235,"chapter":"* (أ) *","title":"711 - الفرق بين الحذف والاختصار (1) : الحذف يتعلق بالالفاظ: وهو أن يأتي بلفظ تقضى غيره، ويتعلق به ولا يستقل (2) بنفسه، ويكون في","page":"ج1 ص178","text":"الموجود دلالة المحذوف، فيقتصر عليه طلب لاختصار، كقوله تعالى: \" واسأل القرية \" (3) أي: أهل القرية.\nفإن السؤال يتعلق بأهلها، والقرية تدل على المحذوف.\nوأما الاختصار: فيرجع إلى المعاني، وهو أن يؤتى بلفظ مفيد لمعان كثيرة لو غير بغيره، لاحتاج إلى أكثر من ذلك اللفظ، كقوله تعالى في\nقصة يوسف: \" أنا أنبئكم بتأويله فأرسلون \" (1) فأرسلوه، فأبى يوسف، فقال: أيها الصديق! وكقوله تعالى: \" اضرب بعصاك الحجر فانفجرت \" (2) .\nالمعنى: فضربها، فانفجرت.\nوعلى هذا فبين الحذف والاختصار عموم وخصوص، فكل حذف اختصار، وليس كل اختصار حذفا.\n(اللغات) ."},{"id":"furuq-lughawiyya:236","bookId":"furuq-lughawiyya","type":"section","seq":236,"chapter":"* (أ) *","title":"713 - الفرق بين الحراسة والحفظ: أن الحراسة حفظ مستمر، ولهذا سمي الحارس حارسا لانه يحرس في الليل كله أو لان ذلك صناعته فهو يديم فعله، وإشتقاق","page":"ج1 ص179","text":"النعمة أي صرف عنها الآفة صرفا مستمرا والحفظ لا يتضمن معنى الاستمرار وقد حفظ الشئ وهو حافظ والحفيظ مبالغة وقالوا الحفيظ في أسماء الله بمعنى العليم والشهيد فتأويله الذي لا يعزب عنه الشئ، وأصله أن الحافظ للشئ عالم به في أكثر الاحوال إذا كان من خفيت عليه أحواله لا يتأتى له حفظه، قال أبو هلال أيده الله تعالى: والحفيظ بمعنى عليم توسع ألا ترى أنه لا يقال إن الله حافظ لقولنا وقدامنا على\nمعنى قولنا فلان يحفظ القرآن ولو كان حقيقة لجري في باب العلم كله."},{"id":"furuq-lughawiyya:237","bookId":"furuq-lughawiyya","type":"section","seq":237,"chapter":"* (أ) *","title":"716 - الفرق بين الحرث والزرع (1) : الفرق بينهما أن الحرث: بذر الحب من الطعام في الارض.","page":"ج1 ص180","text":"والزرع: نبته نباتا إلى أن يبلغ.\nويؤيده قوله تعالى: \" أفرأيتم ما تحرثون أأنتم تزرعونه أم نحن\nالزارعون \" (2) .\nحيث أسند الحرث إلى العباد، والزرع إلى نفسه - سبحانه - وروي عنه - صلى الله عليه وآله - أنه قال: \" لا يقولن أحدكم زرعت، وليقل حرثت \".\nوهو يرشد إلى ما ذكرناه (3) .\nوأهل اللغة لم يفرقوا بينهما.\n(اللغات) ."},{"id":"furuq-lughawiyya:238","bookId":"furuq-lughawiyya","type":"section","seq":238,"chapter":"* (أ) *","title":"717 - الفرق بين الحرج والضيق: أن الحرج ضيق لا منفذ فيه مأخوذ من الحرجة وهي الشجر الملتف حتى لا يمكن الدخول فيه ولا الخروج منه","page":"ج1 ص181","text":"ولهذا جاء بمعنى الشك في قوله تعالى \" ثم لا يجدوا في أنفسهم حرجا مما قضيت \" (1) أي شكا لان الشاك في الامر لا ينفذ فيه ومثله \" فلا يكن في صدرك حرج منه \" (2) وليس كل ما خاطب به النبي صلى الله عليه [وآله] وسلم والمؤمنين أرادهم به ألا ترى إلى قوله \" يا أيها الذين آمنوا كتب عليكم القصاص في القتلى \" (3) والقصاص في العمد فكأنه أثبت لهم الايمان مع قتل العمد وقتل العمد يبطل الايمان وإنما أراد أن يعلمهم الحكم فيمن يستوجب ذلك ونحوه قوله تعالى \" يا أيها الذين آمنوا لا تأكلوا الربا أضعافا مضاعفة \" (4) وقد تكلمنا في هذا الحرف في كتاب تصحيح الوجوه والنظائر بأكثر من هذا ومما قلنا قال بعض المفسرين في قوله تعالى \" وما جعل عليكم في الدين من حرج \" (5) أنه أراد ضيقا لا مخرج منه وذلك أنه يتخلص من الذنب بالتوبة فالتوبة مخرج وترك ما يصعب فعله على الانسان بالرخص ويحتج به فيما أختلف فيه من الحوادث فقيل إن ما أدى إلى الضيق فهو منفي وما أوجب\nالتوسعة فهو أولى."},{"id":"furuq-lughawiyya:239","bookId":"furuq-lughawiyya","type":"section","seq":239,"chapter":"* (أ) *","title":"718 - الفرق بين الحرد والغضب: أن الحرد هو أن يغضب الانسان فيبعد عن من غضب عليه وهو من قولك كوكب حريد أي بعيد عن الكواكب وحي حريد أي بعيد الم","page":"ج1 ص182","text":"أن يبلغ في الغضب أبعد غاية."},{"id":"furuq-lughawiyya:240","bookId":"furuq-lughawiyya","type":"section","seq":240,"chapter":"* (أ) *","title":"720 - الفرق بين الحرص والطمع (2) : قيل: الحرص أشد الطمع، وعليه جرى قوله تعالى: \" أفتطمعون أن يؤمنوا لكم \" (3) .","page":"ج1 ص182","text":"لان الخطاب فيه للمؤمنين.\nوقوله - سبحانه -: \" إن تحرص على هداهم \" (4) .\nفإن الخطاب فيه مقصور على النبي صلى الله عليه وآله.\nولا شك أن رغبته صلى الله عليه وآله في إسلامهم وهدايتهم كان أشد (5)\nواكثر من رغبة المؤمنين المشاركين له في الخطاب الاول في ذلك.\n(اللغات)"},{"id":"furuq-lughawiyya:241","bookId":"furuq-lughawiyya","type":"section","seq":241,"chapter":"* (أ) *","title":"الفرق بين الحزن والبث","page":"ج1 ص183","text":"أن قولنا الحزن يفيد غلظ الهم، وقولنا البث يفيد أنه ينبث ولا ينكتم من قولك أبثثته ما عندي وبثثته إذا أعلمته\nإياه، وأصل الكلمة كثرة التفريق ومنه قوله تعالى \" كالفراش المبثوث \" (1) وقال تعالى \" إنما أشكو بثي وحزني إلى الله \" (2) فعطف البث على الحزن لما بينهما من الفرق في المعنى وهو ما ذكرناه.\n\" اشارة بهذا العدد."},{"id":"furuq-lughawiyya:242","bookId":"furuq-lughawiyya","type":"section","seq":242,"chapter":"* (أ) *","title":"731- الفرق بين الحزن والبث","page":"ج1 ص183","text":"الفرق بين الحزن والبث (3) : قيل: البث أشد الحزن، الذي لا يصبر عليه\nصاحبه، حتى يبثه أو يشكوه.\nوالحزن: أشد الهم.\nوقيل: البث: ما أبداه الانسان، والحزن: ما أخفاه، لان الحزن مستكن في القلب، والبث: ما بث وأظهر وكل شئ فرقته فقد بثثته.\nومنه قوله تعالى: \" وبث فيها من كل دابة \" (1) .\nفالبث غير الحزن.\nوقيل: هما بمعنى، وقوله تعالى: \" إنما أشكوا بثي وحزني إلى الله \" (2) من عطف الشئ على رديفه.\n(اللغات) ."},{"id":"furuq-lughawiyya:243","bookId":"furuq-lughawiyya","type":"section","seq":243,"chapter":"* (أ) *","title":"735 - الفرق بين الحسبان والزعم (3) : الفرق بينهما أن الحسبان لا يكون إلا باطلا.","page":"ج1 ص184","text":"قال تعالى: \" أفحسبتم أنما خلقناكم عبثا وأنكم إلينا\nلا ترجعون \" (4) .\nوالزعم قد يكون حقا، وقد يكون باطلا، قال الشاعر: [14 / ب]\nيقول هلكنا إن هلكت وإنما * على الله أرزاق العباد كما زعم! فإن هذا الزعم حق.\n(اللغات) ."},{"id":"furuq-lughawiyya:244","bookId":"furuq-lughawiyya","type":"section","seq":244,"chapter":"* (أ) *","title":"737 - الفرق بين الحسرة والاسف والغم: أن الحسرة غم يتجدد لفوت فائدة فليس كل غم حسرة.","page":"ج1 ص185","text":"والاسف حسرة معها غضب أو غيظ والآسف الغضبان المتلهف على الشئ ثم كثر ذلك حتى جاء في معنى الغضب وحده في قوله تعالى \" فلما آسفونا إنتقمنا منهم \" (1) أي أغضبونا، وإستعمال الغضب في صفات الله تعالى مجاز وحقيقته إيجاب العقاب للمغضوب عليه."},{"id":"furuq-lughawiyya:245","bookId":"furuq-lughawiyya","type":"section","seq":245,"chapter":"* (أ) *","title":"738 - الفرق بين قولنا حس يحس وبين قولنا درك يدرك: أن الصفة بحس مضمنة بالحاسة والصفة تدرك مطلقة، والحاسة إسم لما يقع به إدراك شئ مخصوص ولذلك","page":"ج1 ص185","text":"وجه يصح أن يتبين منه لنفسه، ولا يصح أن يقال إنه يشم ويذوق لان الشم ملابسة المشموم للانف، والذوق ملابسة المذوق للفم، ودليل ذلك قولك شممته فلم أجد له رائحة وذقته فلم أجد له طعما، ولا يقال إن الله يحس بمعنى أنه يرى ويسمع إذ قولنا يحس يقتضي حاسة."},{"id":"furuq-lughawiyya:246","bookId":"furuq-lughawiyya","type":"section","seq":246,"chapter":"* (أ) *","title":"739 - الفرق بين الحس والعلم: أن الحس هو أول العلم ومنه قوله تعالى \" فلما","page":"ج1 ص186","text":"أحس عيسى منهم الكفر \" (1) أي علمه في أول وهلة، ولهذا لا يجوز أن يقال ان الانسان يحس بوجود نفسه، قلنا وتسمية العلم حسا وإحساسا مجاز ويسمى بذلك لانه يقع مع الاحساس والاحساس من قبيل الادراك، والآلات التي يدرك بها حواس كالعين والاذن والانف والفم، والقلب ليس من الحواس لان العلم الذي يختص به ليس بإدراك وإذا لم يكن العلم إدراكا لم يكن محله حاسة، وسميت الحاسة حاسة على النسب لا على الفعل لانه لا يقال منه حسست وإنما يقال أحسستهم إذا أبدتهم قتلا مستأصلا، وحقيقته أنك تأتي على إحساسهم فلا تبقي لهم حسا."},{"id":"furuq-lughawiyya:247","bookId":"furuq-lughawiyya","type":"section","seq":247,"chapter":"* (أ) *","title":"742 - الفرق بين الحسنة والحسن: أن الحسنة هي الاعلى في الحسن لان الهاء داخلة للمبالغة فلذلك قلنا إن الحسنة تدخل فيها الفروض والنوافل ولا يدخل","page":"ج1 ص186","text":"مباح حسن ولكنه لا ثواب فيه ولا حمد فليس هو بحسنة."},{"id":"furuq-lughawiyya:248","bookId":"furuq-lughawiyya","type":"section","seq":248,"chapter":"* (أ) *","title":"751 - الفرق بين الحشر والجمع: أن الحشر هو الجمع مع السوق، والشاهد قوله تعالى \" وابعث في المدائن حاشرين \" (1) أي إبعث من يجمع السحرة ويسوقهم","page":"ج1 ص188","text":"وتقول القياس جمع بين مشتبهين يدل الاول على صحة الثاني ولا يقال في ذلك حشر وإنما يقال الحشر فيما يصح فيه السوق على ما ذكرنا وأقل الجمع عند شيوخنا ثلاثة، وكذلك هو عند الفقهاء، وقال بعضهم إثنان وإحتج بأنه مشتق من أجتماع شئ إلى شئ وهذا وإن كان صحيحا فإنه قد خص به شئ بعينه، كما أن قولنا دابة وإن كان يوجب إشتقاقه إن جرى على كل مادب فإنه قد خص به شئ بعينه فاما قوله عليه الصلاة والسلام \" الاثنان فما فوقهما جماعة \" فان ذلك ورد في الحكم لا في تعليم الاسم لان كلامه صلى الله عليه [وآله] وسلم يجب أن يحمل على ما يستفاد من جهته دون ما يصح أن يعلم من جهته، وأما قوله تعالى \" هذان خصمان إختصموا \" (1) وقوله تعالى \" وكنا لحكمهم شاهدين \" (2) يعني داود وسليمان عليهما السلام فإن ذلك مجاز كقوله تعالى \" إنا نحن نزلنا الذكر وإنا له لحافظون \" (3) ولو كان لفظ الجمع حقيقة في الاثنين لعقل منه الاثنان كما يعقل منه الثلاثون، وإذا كان قول الرجل رأيت الرجال لا يفهم منه إلا ثلاثة علمنا أن قول الخصم باطل."},{"id":"furuq-lughawiyya:249","bookId":"furuq-lughawiyya","type":"section","seq":249,"chapter":"* (أ) *","title":"752 - الفرق بين الحشر والنشر (4) : الحشر لغة: إخراج الجماعة عن مقرهم، وإزعاجهم، وسوقهم إلى الحرب، ونحوها.","page":"ج1 ص188","text":"ثم خص في عرف الشرع عند الاطلاق بإخراج الموتى عن قبورهم، وسوقهم إلى الموقف للحساب والجزاء.\nقال الراغب: لا يقال: الحشر إلا للجماعة (1) .\nقلت: هذا في أصل اللغة وإلا فقد يستعمل في الواحد والاثنين.\nومنه دعاء الصحيفة الشريفة (2) : \" وارحمني في حشري ونشري \".\nوالنشر إحياء الميت بعد موته.\nومنه قوله تعالى: \" ثم إذا شاء أنشره \" (3) أي أحياه.\n(اللغات) ."},{"id":"furuq-lughawiyya:250","bookId":"furuq-lughawiyya","type":"section","seq":250,"chapter":"* (أ) *","title":"755 - الفرق بين الحصر والصد (4) : هما بمعنى المنع، لكن اصطلح الفقهاء بتسميته: الممنوع عن الحج بالمرض محصورا، والممنوع بالعدو مصدودا.","page":"ج1 ص189","text":"(اللغات) ."},{"id":"furuq-lughawiyya:251","bookId":"furuq-lughawiyya","type":"section","seq":251,"chapter":"* (أ) *","title":"763 - الفرق بين الحفظ والرعاية: أن نقيض الحفظ الاضاعة ونقيض الرعاية الاهمال ولهذا يقال للماشية إذا لم يكن لها راع همل، والاهمال هو ما يؤدي إ","page":"ج1 ص191","text":"فأما قولهم للساهر أنه يرعى النجوم فهو تشبيه براعي المواشي لانه يراقبها كما يراقب الراعي مواشيه."},{"id":"furuq-lughawiyya:252","bookId":"furuq-lughawiyya","type":"section","seq":252,"chapter":"* (أ) *","title":"768 - الفرق بين الحقبة والزمان: أن الحقبة إسم للسنة إلا أنها تفيد غير ما تفيده السنة وذلك أن السنة تفيد أنها جمع شهور والحقبة تفيد أنها","page":"ج1 ص191","text":"ظرف لاعمال ولامور تجري فيها مأخوذة من الحقيبة وهي ضرب من الظروف تتخذ من الادم يجعل الراكب فيها متاعه وتشد خلف رحله أو\nسرجه.\nوأما البرهة فبعض الدهر ألا ترى أنه يقال برهة من الدهر كما يقال قطعة من الدهر وقال بعضهم هي فارسية معربة."},{"id":"furuq-lughawiyya:253","bookId":"furuq-lughawiyya","type":"section","seq":253,"chapter":"* (أ) *","title":"الفرق بين الحق والصدق","page":"ج1 ص192","text":"أن الحق أعم لانه وقوع الشئ في موقعه الذي هو أولى به، والصدق الاخبار عن الشئ على ما هو به، والحق يكون إخبارا وغير إخبار."},{"id":"furuq-lughawiyya:254","bookId":"furuq-lughawiyya","type":"section","seq":254,"chapter":"* (أ) *","title":"773- الفرق بين الحق والصدق","page":"ج1 ص192","text":"الفرق بين الحق والصدق (1) : الحق في اللغة: هو الثابت الذي لا يسوغ إنكاره من حق الشئ، يحق، إذا ثبت ووجب (2) .\nوفي اصطلاح أهل المعاني: الحكم المطابق للواقع، يطلق على الاقوال والعقائد، والاديان، والمذاهب باعتبار اشتمالها على ذلك، ويقابله الباطل.\nوأما الصدق، فقد شاع في الاقوال خاصة، ويقابله الكذب.\nوقد يفرق بينهما بأن المطابقة تعتبر في الحق من جانب الواقع وفي الصدق من جانب الحكم، فمعنى صدق الحكم مطابقته للواقع.\nومعنى حقيته: مطابقة الواقع إياه، وقد يطلق الحق على الموجد للشئ (1) ، وعلى\nالحكمة، ولما يوجد عليه، كما يقال: الله: حق (2) ، وكلمته: حق.\nوقد يراد به الاقبال على الله تعالى بلزوم الاعمال الصالحة المطابقة للعقائد المطابقة للواقع، وبالباطل: الالتفات عنه إلى غير ذلك مما لا يجدي نفعا في الآخرة.\n(اللغات) ."},{"id":"furuq-lughawiyya:255","bookId":"furuq-lughawiyya","type":"section","seq":255,"chapter":"* (أ) *","title":"776 - الفرق بين الحقيقة والحق: أن الحقيقة ما وضع من القول موضعه في أصل","page":"ج1 ص194","text":"اللغة حسنا كان أو قبيحا والحق ما وضع موضعه من الحكمة فلا يكون إلا حسنا وإنما شملهما إسم التحقيق لاشتراكهما في وضع الشئ منهما موضعه من اللغة والحكمة."},{"id":"furuq-lughawiyya:256","bookId":"furuq-lughawiyya","type":"section","seq":256,"chapter":"* (أ) *","title":"779 - الفرق بين الحكم والحاكم: أن الحكم يقتضي أنه أهل أن يتحاكم إليه، والحاكم الذي من شأنه أن يحكم.","page":"ج1 ص194","text":"فالصفة بالحكم أمدح وذلك أن صفة حاكم جار على الفعل فقد يحكم الحاكم بغير الصواب فأما من يستحق الصفة بحكم فلا يحكم إلا بالصواب لانه صفة تعظيم ومدح."},{"id":"furuq-lughawiyya:257","bookId":"furuq-lughawiyya","type":"section","seq":257,"chapter":"* (أ) *","title":"782 - الفرق بين الحلال والطيب (2) : قال بعض أصحابنا: الحلال والطيب","page":"ج1 ص195","text":"- وإن كانا (1) متقاربين، بل متساويين في اللغة، إلا أن المستفاد من الاخبار أن بينهما فرقا في عرف الائمة - عليهم السلام -.\nانتهى.\nوكان الفرق هو أن الطيب: ما هو طيب في ظاهر الشرع سواء كان طيبا في الواقع أم لا.\nوالحلال: ما هو حلال وطيب (2) في الواقع لم تعرضه النجاسة والخباثة قطعا، ولم تتناوله أيدي المتغلبة أصلا.\nوقد ورد أنه قوت الانبياء عليهم السلام، وأنه نادر جدا، وأما ما وقع\nمن طلبه في بعض الادعية فالمراد به ما هو بمعنى الطيب.\n* وهذا ولا يخفى أن الغالب استعمال الطيب بمعنى المستحسن المرغوب فيه، ويقابله الخبيث، وقد حكي في شأن نزول قوله تعالى: \" أنفقوا من طيبات ما كسبتم \" (3) .\nأنهم كانوا يأتون أخبث الثمر وأرداه فيخرجونه في زكواتهم وصدقاتهم، فنهوا عنه.\n* (4) (اللغات) ."},{"id":"furuq-lughawiyya:258","bookId":"furuq-lughawiyya","type":"section","seq":258,"chapter":"* (أ) *","title":"الفرق بين الحلال والمباح","page":"ج1 ص195","text":"أن الحلال هو المباح الذي علم إباحته بالشرع، والمباح لا يعتبر فيه ذلك تقول المشي في السوق مباح ولا تقول حلال، والحلال خلاف الحرام والمباح خلاف المحظور وهو الجنس الذي لم يرغب فيه، ويجوز أن يقال هو ما كان لفاعله أن يفعله ولا ينبئ عن مدح ولا ذم وقيل هو ما أعلم المكلف أو دل على حسنه وإنه لا ضرر عليه في فعله ولا تركه، ولذلك لا توصف أفعال الله تعالى بأنها مباحة\nولا توصف أفعال البهائم بذلك فمعنى قولنا أنه على الاباحة أن للمكلف أن ينتفع به ولا ضرر عليه في ذلك وإرادة المباح والامر به قبيح لانه لا فائدة فيه إذ فعله وتركه سواء في أنه لا يستحق عليه ثواب وليس كذلك الحلال."},{"id":"furuq-lughawiyya:259","bookId":"furuq-lughawiyya","type":"section","seq":259,"chapter":"* (أ) *","title":"784 - الفرق بين الحلال والمباح (1) : (2) * الحلال من حل العقد في التحريم.","page":"ج1 ص196","text":"والمباح: من التوسعة في الفعل.\nكذا قيل.\nوالمراد أن (3) * الحلال ما نص الشارع على حله، فكأنه انحل من عقد التحريم.\nوالمباح: ما لم ينص على تحريمه في حكم خاص أو عام.\nفالانسان في توسعه (4) من حكمه، بمعنى أنه يجوز له تناول ذلك واستعماله، كبعض الاطعمة والالبسة التي لم ينص الشارع على تحريمها عموما أو خصوصا.\n(اللغات) ."},{"id":"furuq-lughawiyya:260","bookId":"furuq-lughawiyya","type":"section","seq":260,"chapter":"* (أ) *","title":"786 - الفرق بين الحلم والامهال: أن كل حلم إمهال وليس كل إمهال حلما لان الله تعالى لو أمهل من أخذه لم يكن هذا الامهال حلما لان الحلم صفة مدح","page":"ج1 ص197","text":"أن يكون ضد الحلم السفه إذا كان الحلم واجبا لان ضده استفساد فلو فعله لم يكن ظلما إلا أنه لم يكن حكمة ألا ترى أنه قد يكون الشئ سفها وإن لم يكن ضده حلما وهذا نحو صرف الثواب عن المستحق إلى غيره لان ذلك يكون ظلما من حيث حرمة من استحقه ويكون سفها من حيث وضع في غير موضعه ولو أعطي مثل ثواب المطيعين من لم يطع لم يكن ذلك ظلما لاحد ولكن كان سفها لانه وضع الشئ في غير\nموضعه، وليس يجب أن تكون إثابة المستحقين حلما وإن كان خلاف ذلك سفها فثبت بذلك أن الحلم يقتضي بعض الحكمة وأن السفه يضاد ما كان من الحلم واجبا لا ما كان منه تفضلا وأن السفه نقيض الحكمة في كل وجه، وقولنا الله حليم من صفات الفعل، ويكون من صفات الذات بمعنى أهل لان يحلم إذا عصي، ويفرق بين الحلم والامهال من وجه آخر وهو أن الحلم لا يكون إلا عن المستحق للانتقام وليس كذلك الامهال ألا ترى أنك تمهل غريمك إلى مدة ولا يكون ذلك منك حلما، وقال بعضهم لا يجوز أن يمهل أحد غيره في وقت إلا ليأخذه في وقت آخر."},{"id":"furuq-lughawiyya:261","bookId":"furuq-lughawiyya","type":"section","seq":261,"chapter":"* (أ) *","title":"788 - الفرق بين الحلم والرؤيا (1) : كلاهما ما يراه الانسان في المنام، لكن غلبت الرؤيا على ما يراه من الخير، والشئ الحسن، والحلم: ما يراه من","page":"ج1 ص198","text":"الشيطان \" (1) (اللغات) ."},{"id":"furuq-lughawiyya:262","bookId":"furuq-lughawiyya","type":"section","seq":262,"chapter":"* (أ) *","title":"789 - الفرق بين الحلم والصبر: أن الحلم هو الامهال بتأخير العقاب المستحق، والحلم من الله تعالى عن العصاة في الدنيا فعل ينافي تعجيل العقوبة من","page":"ج1 ص198","text":"العقوبة وما يجري مجراها من التأديب بالضرب وهو ممن لا يقدر على ذلك ولهذا قال الشاعر: * لا صفح ذل ولكن (2) * صفح أحلام * ولا يقال لتارك الظلم حليم إنما يقال حلم عنه إذا أخر عقابه أو عفا عنه ولو عاقبه كان عادلا، وقال بعضهم ضد الحلم السفه، وهو جيد لان السفه خفة وعجلة وفي الحلم أناة وإمهال، وقال المفضل السفه في الاصل قلة المعرفة بوضع الامور مواضعها وهو ضعف الرأي، قال أبو هلال: وهذا يوجب أنه ضد الحلم لان الحلم من الحكمة والحكمة وجود الفعل على جهة الصواب، قال المفضل: ثم أجري السفه على كل جهل وخفة يقال سفه رأيه سفها، وقال الفراء: سفه غير متعد وإنما ينصبب رأيه على التفسير، وفيه لغة أخرى سفه يسفه سفاهة، وقيل السفيه في قوله تعالى \" فإن كان الذي عليه الحق سفيها \" (3) هو الصغير وهذا يرجع إلى أنه القليل المعرفة، والدليل على أن الحلم أجري مجرى الحكمة نقيضا للسفه قول المتلمس:\nلذي الحلم قبل اليوم ما تقرع العصا * وما علم الانسان إلا ليعلما أي لذي المعرفة والتمييز، وأصل السفه الخفة ثوب سفيه أي خفيف، وأصل الحلم في العربية اللين ورجل حليم أي لين في معاملته في الجزاء على السيئة بالاناة، وحلم في النوم لان حال النوم حال سكون وهدوء واحتلم الغلام وهو محتلم وحالم يرجع إلى قولهم حلم في النوم، وحلمة\nالثدي الناتئ في طرفه لما يخرج منها من اللبن الذي يحلم الصبي وحلم الاديم ثقل بالحلم وهو قردان عظيمة لينة الملمس وتحلم الرجل تكلف الحلم.\nوالصبر حبس النفس لمصادفة المكروه، وصبر الرجل حبس نفسه عن إظهار الجزع، والجزع إظهار ما يلحق المصاب من المضض (1) والغم وفي الحديث \" يصبر الصابر ويقتل القاتل \" (2) والصابر هاهنا هو الذي يصبر النفس عن القتل، ولا تجوز الصفة على الله تعالى بالصبر لان المضار لا تلحقه وتجوز الصفة عليه بالحلم لانه صفة مدح وتعظيم وإذا قال قائل اللهم حلمك عن العصاة أي إمهالك فذلك جائز على شرائط الحكمة من غير أن يكون فيه مفسدة وإمهال الله تعالى إياهم مظاهرة عليهم."},{"id":"furuq-lughawiyya:263","bookId":"furuq-lughawiyya","type":"section","seq":263,"chapter":"* (أ) *","title":"792 - الفرق بين الحلية والهيئة: أن الحلية هيئة زائدة على الهيئة التي لابد منها كحلية السكين والسيف إنما هي هيئة زائدة على هيئة السكين والسيف","page":"ج1 ص200","text":"سمي الحلي الملبوس حليا."},{"id":"furuq-lughawiyya:264","bookId":"furuq-lughawiyya","type":"section","seq":264,"chapter":"* (أ) *","title":"794 - الفرق بين الحماية والحفظ: أن الحماية تكون لما لا يمكن إحرازه وحصره مثل الارض والبلد تقول هو يحمي البلد والارض وإليه حماية البلد، والحف","page":"ج1 ص200","text":"لا يعرف الكلام."},{"id":"furuq-lughawiyya:265","bookId":"furuq-lughawiyya","type":"section","seq":265,"chapter":"* (أ) *","title":"796- الفرق بين الحمد والشكر","page":"ج1 ص200","text":"الفرق بين الحمد والشكر: (1211) ."},{"id":"furuq-lughawiyya:266","bookId":"furuq-lughawiyya","type":"section","seq":266,"chapter":"* (أ) *","title":"797 - الفرق بين الحمد والشكر والمدح (1) : الحمد: هو الثناء باللسان على الجميل، سواء تعلق بالفضائل كالعلم، أم (2) بالفواضل كالبر.","page":"ج1 ص200","text":"والشكر: فعل ينبئ عن تعظيم المنعم لاجل النعمة، سواء أكان نعتا باللسان، أو اعتقادا، أو محبة بالجنان، أو عملا وخدمة بالاركان.\nوقد جمعها الشاعر في قوله (3) :\nأفادتكم النعماء مني ثلاثة * يدي ولساني والضمير المحجب فالحمد أعم مطلقا، لانه يعم النعمة وغيرها، وأخص موردا إذ هو باللسان فقط، والشكر بالعكس، إذ متعلقه النعمة فقط، ومورده اللسان وغيره.\nفبينهما عموم وخصوص من وجه، فهما يتصادقان في الثناء باللسان على الاحسان، ويتفارقان في صدق (1) الحمد فقط على النعت بالعلم مثلا، وصدق الشكر فقط على المحبة بالجنان، لاجل الاحسان.\nوأما الفرق بين الحمد والمدح فمن وجوه: منها: أن المدح للحي ولغير\nالحي كاللؤلؤ واليواقيت الثمينة.\nوالحمد للحي فقط.\nومنها: أن المدح قد يكون قبل الاحسان وقد يكون بعده، والحمد إنما يكون بعد الاحسان.\nومنها: أن المدح قد يكون منهيا عنه.\nقال - صلى الله عليه وآله - \" احثوا التراب على وجوه المداحين \" (2) .\nوالحمد مأمور به مطلقا.\nقال صلى الله عليه وآله: \" من لم يحمد الناس لم يحمد الله \"؟ ومنها أن المدح عبارة عن القول الدال على أنه مختص بنوع من أنواع الفضائل باختياره، وبغير اختياره (3) .\nوالحمد قول دال على أنه مختص بفضيلة من الفضائل معينة وهي فضيلة الانعام إليك، وإلى غيرك، ولابد أن يكون على جهة التفضيل لا على التهكم والاستهزاء.\nومنها أن الحمد نقيضه الذم، ولهذا قيل: (1) \" الشعير يؤكل ويذم \".\nوالمدح نقيضه الهجاء.\nهذا والزمخشري لم يفرق بينهما.\nقال في الكشاف (2) : \" الحمد والمدح أخوان \".\nبمعنى واحد.\n(اللغات) ."},{"id":"furuq-lughawiyya:267","bookId":"furuq-lughawiyya","type":"section","seq":267,"chapter":"* (أ) *","title":"798 - الفرق بين الحمد والمدح: أن الحمد لا يكون إلا على إحسان والله حامد لنفسه على إحسانه إلى خلقه فالحمد مضمن بالفعل، والمدح يكون بالفعل","page":"ج1 ص202","text":"والصفة وذلك مثل أن يمدح الرجل باحسانه إلى نفسه وإلى غيره وان يمدحه بحسن وجهه وطول قامته ويمدحه بصفات التعظيم من نحو قادر وعالم وحكيم ولا يجوز أن يحمده على ذلك وإنما يحمده على إحسان يقع منه فقط."},{"id":"furuq-lughawiyya:268","bookId":"furuq-lughawiyya","type":"section","seq":268,"chapter":"* (أ) *","title":"800 - الفرق بين الحميل والضمين: أن الحمالة ضمان الدية خاصة تقول حملت حمالة وأنا حميل وقال بعض العرب: حملت دماء عولت فيها على مالي وآمالي فقد","page":"ج1 ص203","text":"والضمان يكون في ذلك وفي غيره."},{"id":"furuq-lughawiyya:269","bookId":"furuq-lughawiyya","type":"section","seq":269,"chapter":"* (أ) *","title":"801 - الفرق بين الحنان والمنان (1) : الحنان: الذي يقبل على من أعرض","page":"ج1 ص203","text":"عنه.\nوالمنان: الذي يبدأ بالنوال قبل السؤال.\nروي ذلك عن أمير المؤمنين عليه السلام (اللغات) ."},{"id":"furuq-lughawiyya:270","bookId":"furuq-lughawiyya","type":"section","seq":270,"chapter":"* (أ) *","title":"804 - الفرق بين الحول والقوة (2) : قيل: الحول: القدرة على التصرف","page":"ج1 ص204","text":"والقوة: مبدأ الافعال الشاقة، وروي عن مولانا أمير المؤمنين في تفسير.\nلا حول ولا قوة إلا بالله، أن المعنى لا حائل عن المعاصي، ولا قوة على الطاعات إلا بالله، أي باستعانته وتوفيقه (اللغات) ."},{"id":"furuq-lughawiyya:271","bookId":"furuq-lughawiyya","type":"section","seq":271,"chapter":"* (أ) *","title":"808 - الفرق بين الحياة والنماء: أن الحياة هي ما تصير به الجملة كالشئ الواحد في جواز تعلق الصفات بها فأما قوله تعالى \" فأحيينا به الارض بعد","page":"ج1 ص204","text":"موتها \" (1) فمعناه أنا جعلنا حالها كحال الحي في الانتفاع بها، والصفة لله بأنه حي مأخوذة من الحياة على التقدير لا على الحقيقة كما أن صفته بأنه موجود مأخوذة من الوجود على التقدير وقد دل الدليل على أن الحي بعد أن لم يكن حيا حي من أجل الحياة فالذي لم يزل حيا ينبغي أن يكون حيا لنفسه، والنماء يزيد الشئ حالا بعد حال من نفسه لا بإضافة إليه فالنبات ينمي ويزيد وليس بحي والله تعالى حي ولا ينام، ولا يقال لمن أصاب ميراثا أو أعطي عطية أنه قد نما ماله وإنما يقال نما ماله إذا زاد في نفسه، والنماء في الماشية حقيقة لانها تزيد بتوالدها قليلا قليلا، وفي الورق والذهب مجاز فهذا هو الفرق بين الزيادة والنماء، ويقال للاشجار والنبات نوام لانها تزيد في كل يوم إلى أن تنتهي إلى حد التمام."},{"id":"furuq-lughawiyya:272","bookId":"furuq-lughawiyya","type":"section","seq":272,"chapter":"* (أ) *","title":"813 - الفرق بين الحيلة والتدبير: أن الحيلة ما أحيل به عن وجهه فيجلب به نفع أو يدفع به ضر، فالحيلة بقدر النفع والضر من غير وجه وهي في قول الف","page":"ج1 ص205","text":"والمحظور أن تقول لمن ترك صلاته ارتد ثم أسلم يسقط عنك قضاؤها،\nوإنما سمي ذلك حيلة لانه شئ أحيل من جهة إلى جهة أخرى ويسمى تدبيرا أيضا.\nومن التدبير ما لا يكون حيلة وهو تدبير الرجل لاصلاح ماله وإصلاح أمر ولده وأصحابه، وقد ذكرنا (1) إشتقاق التدبير قبل."},{"id":"furuq-lughawiyya:273","bookId":"furuq-lughawiyya","type":"section","seq":273,"chapter":"* (أ) *","title":"الفرق بين الحيلة والمكر","page":"ج1 ص205","text":"أن من الحيلة ما ليس بمكر وهو أن يقدر نفع الغير لا من وجهه فيسمى ذلك حيلة مع كونه نفعا، والمكر لا يكون نفعا.\nوفرق آخر وهو أن المكر بقدر ضرر الغير من غير أن يعلم به وسواء كان من وجهه أو لا، والحيلة لا تكون إلا من غير وجهه، وسمى الله تعالى ما توعد به الكفار مكرا في قوله تعالى \" فلا يأمن مكر الله إلا القوم\nالخاسرون \" (1) وذلك أن الماكر ينزل المكروه بالممكور به من حيث لا يعلم فلما كان هذا سبيل ما توعدهم به من العذاب سماه مكرا، ويجوز أن يقال سماه مكرا لانه دبره وأرسله في وقته، والمكر في اللغة التدبير على العدو فلما كان أصلهما واحدا قام أحدهما مقام الآخر، وأصل المكر في اللغة الفتل ومنه قيل جارية ممكورة أي ملتفة البدن وإنما سميت الحيلة مكرا لانها قيلت على خلاف الرشد."},{"id":"furuq-lughawiyya:274","bookId":"furuq-lughawiyya","type":"section","seq":274,"chapter":"* (أ) *","title":"815 - الفرق بين الحيلة والمكر (2) : قال الطبرسي رضي الله عنه: الحيلة قد تكون لاظهار ما يعسر من الفعل من غير قصد إلى الاضرار بالعبد (3) .","page":"ج1 ص206","text":"والمكر: حيلة على العبد توقعه في مثل الوهق (4) .\nانتهى.\nولا يخفى أن مكر الله عباده كما قال تعالى: \" ومكروا ومكر الله والله خير الماكرين \" (5) عبارة عن إيصال الجزاء إلى الماكر، واستدراجه\nالعبد من حيث لا يعلم، ومعاملته معاملة الماكر للممكور (6) ."},{"id":"furuq-lughawiyya:275","bookId":"furuq-lughawiyya","type":"section","seq":275,"chapter":"* (أ) *","title":"816 - الفرق بين الحين والسنة: أن قولنا حين إسم جمع أوقاتا متناهية سواء كان سنة أو شهورا أو أياما أو ساعات ولهذا جاء في القرآن لمعان مختلفة","page":"ج1 ص207","text":"وبينه وبين الدهر فرق وهو أن الدهر يقتضي أنه أوقات متوالية م"},{"id":"furuq-lughawiyya:276","bookId":"furuq-lughawiyya","type":"section","seq":276,"chapter":"* (أ) *","title":"خ","page":"ج1 ص207","text":"تلفة على ما ذكرنا (1) ولهذا قال الله عزوجل حاكيا عن الدهريين \" وما يهلكنا إلا الدهر \" (2) أي يهلكنا الدهر بإختلاف أحواله، والدهر أيضا لا يكون إلا ساعات قليلة ويكون الحين كذلك."},{"id":"furuq-lughawiyya:277","bookId":"furuq-lughawiyya","type":"section","seq":277,"chapter":"* (أ) *","title":"822 - الفرق بين الخاطر والنظر: أن الخاطر مرور معنى بالقلب بمنزلة خطاب مخاطب يحدث بضروب الاحاديث، والخواطر تنقسم بحب المعاني إذ كل معنى فله خ","page":"ج1 ص209","text":"شئ من غير حقيقة، وعند البلخي رحمه الله أنه كلام يحدثه الله تعالى في سمع الانسان أو يحدثه الملك أو الشيطان فإذا كان من الشيطان سمي\nوسواسا، وإلى هذا ذهب أبو هاشم رحمه الله، والذي يدل علي أن الخاطر ليس بكلام ما يدل من أفعال الاخرس خطور الخواطر بقلبه وهو لا يعرف الكلام أصلا ولا يعرف معانيه، وعن إبراهيم: أنه لابد من خاطرين أحدهما يأمر بالاقدام والآخر بالكف ليصح الاختيار، وعن إبن الراوندي: أن خاطر المعصية من الله تعالى وأن ذلك كالعقل والشهوة لان الشهوة ميل الطبع المشتهي، والعقل التمييز بين الحسن والقبيح."},{"id":"furuq-lughawiyya:278","bookId":"furuq-lughawiyya","type":"section","seq":278,"chapter":"* (أ) *","title":"828 - الفرق بين الخبر وبن الحديث: أن الخبر هو القول الذي يصح وصفه بالصدق والكذب ويكون الاخبار به عن نفسك وعن غيرك واصله ان يكون الاخبار به ع","page":"ج1 ص210","text":"صيغته لانه يكون على صيغة ما ليس بخبر كقولك رحم الله زيدا والمعنى اللهم إرحم زيدا.\nوالحديث في الاصل هو ما تخبر به عن\nنفسك من غير أن تسنده إلى غيرك وسمي حديثا لانه لا تقدم له وإنما هو شئ حدث لك فحدثت به ثم كثر إستعمال اللفظين حتى سمي كل واحد منهما بإسم الآخر فقيل للحديث خبر وللخبر حديث، ويدل على صحة ما قلنا أنه يقال فلان يحدث عن نفسه بكذا وهو حديث النفس ولا يقال يخبر عن نفسه ولا هو خبر النفس، وإختار مشايخنا قولهم إن سأل سائل فقال أخبروني ولم يختاروا حدثوني لان السؤال إستخبار والمجيب مخبر، ويجوز أن يقال إن الحديث ما كان خبرين فصاعدا إذا كان كل واحد منهما متعلقا بالآخر فقولنا رأيت زيدا خبر، ورأيت زيدا منطلقا حديث، وكذلك قولك رأيت زيدا وعمرا حديث مع كونه خبرا."},{"id":"furuq-lughawiyya:279","bookId":"furuq-lughawiyya","type":"section","seq":279,"chapter":"* (أ) *","title":"830 - الفرق بين الخبر والعلم: أن الخبر هو العلم بكنه المعلومات على حقائقها ففيه معنى زائد على العلم، قال أبو أحمد بن أبي سلمة رحمه الله: لا","page":"ج1 ص211","text":"وما جاءنا من نحو أرضك خابر * ولا جاهل إلا يذمك يا عمرو"},{"id":"furuq-lughawiyya:280","bookId":"furuq-lughawiyya","type":"section","seq":280,"chapter":"* (أ) *","title":"832 - الفرق بين الختم والرسم: أن الختم ينبئ عن إتمام الشئ وقطع فعله وعمله تقول ختمت القرآن أي أتممت حفظه وقرأته وقطعت قراءته وختمت الكبر لان","page":"ج1 ص211","text":"منع وقوله تعالى \" ختم الله على قلوبهم \" (2) ليس بمنع ولكنه ذم بأنها كالممنوعة من قبول الحق على أن الرسم فارسي معرب لا أصل له في العربية فيجوز أن يكون بمعنى الختم لا فرق بينهما لانهما لغتان."},{"id":"furuq-lughawiyya:281","bookId":"furuq-lughawiyya","type":"section","seq":281,"chapter":"* (أ) *","title":"834 - الفرق بين الخجل والحياء: أن الخجل معنى يظهر في الوجه لغم يلحق القلب عند ذهاب حجة أو ظهور على ريبة وما أشبه ذلك فهو شئ تتغير به الهيبة،","page":"ج1 ص212","text":"وقد يستعمل الحياء موضع الخجل توسعا، وقال الانباري: أصل الخجل في اللغة الكسل والتواني وقلة الحركة في طلب الرزق ثم كثر إستعمال العرب له حتى أخرجوه على معنى الانقطاع في الكلام، وفي الحديث\n\" إذا جعتن وقعتن وإذا شبعتن خجلتن \" وقعتن أي ذللتن وخجلتن كسلتن، وقال أبو عبيدة: الخجل هاهنا الاشر وقيل هو سوء إحتمال العناء وقد جاء عن العرب الخجل بمعنى الدهش قال الكميت: فلم يدفعوا عندنا ما لهم * لوقع الحروب ولم يخجلوا أي لم يقوا دهشين مبهوتين."},{"id":"furuq-lughawiyya:282","bookId":"furuq-lughawiyya","type":"section","seq":282,"chapter":"* (أ) *","title":"836 - الفرق بين الخدع والكيد: أن الخدع هو إظهار ما ينطق خلافه أراد إجتلاب نفع أو دفع ضر، ولا يقتضي أن يكون بعد تدبر ونظر وفكر ألا ترى أنه يق","page":"ج1 ص213","text":"الكلام والتفرقة بين المعنيين، ويجوز أن يقال إن الفرق بين الخدع والكيد أن الكيد إسم لفعل المكروه بالغير قهرا تقول كايدني فلان أي ضرني قهرا، والخديعة إسم لفعل المكروه بالغير من غير قهر بل بأن يريد بأنه\nينفعه، ومنه الخديعة في المعاملة وسمى الله تعالى قصد أصحاب الفيل مكة كيدا في قوله تعالى \" ألم يجعل كيدهم في تضليل \" (1) وذلك أنه كان على وجه القهر."},{"id":"furuq-lughawiyya:283","bookId":"furuq-lughawiyya","type":"section","seq":283,"chapter":"* (أ) *","title":"838 - الفرق بين الخرص والكذب: أن الخرص هو الحزر وليس من الكذب في شئ والخرص ما يحزر من الشئ يقال كم خرص نخلك أي كم يجئ من ثمرته وإنما أستعمل","page":"ج1 ص214","text":"قيل كذب بالباطل لانه من أصل فاسد وهو الكذب فصار الذم أغلب عليه كما أن الكافر صفة ذم وإن قيل كفر بالطاغوت لانه من أصل فاسد وهو الكفر."},{"id":"furuq-lughawiyya:284","bookId":"furuq-lughawiyya","type":"section","seq":284,"chapter":"* (أ) *","title":"842 - الفرق بين الخسوب والكسوف (1) : الغالب نسبة الكسوف إلى الشمس والخسوف إلى القمر، وعليه جرى قول جرير (2) .","page":"ج1 ص214","text":"والشمس كاسفة ليست بطالعة * تبكي عليك نجوم الليل والقمر وقد يطلق الكسوف عليهما معا.\nوكذا الخسوف.\n(اللغات) ."},{"id":"furuq-lughawiyya:285","bookId":"furuq-lughawiyya","type":"section","seq":285,"chapter":"* (أ) *","title":"843 - الفرق بين الخشوع والتواضع (3) : قال الراغب في الفرق بينهما: إن التواضع يعتبر بالاخلاق والافعال الظاهرة والباطنة.","page":"ج1 ص215","text":"والخشوع: يقال باعتبار الجوارح، ولذلك قيل: إذا تواضع القلب خشعت الجوارح.\n(اللغات) ."},{"id":"furuq-lughawiyya:286","bookId":"furuq-lughawiyya","type":"section","seq":286,"chapter":"* (أ) *","title":"الفرق بين الخشوع والخضوع","page":"ج1 ص215","text":"أن الخشوع على ما قيل فعل يرى فاعليه أن من يخضع له فوقه وأنه أعظم منه، والخشوع في الكلام خاصة والشاهد\nقوله تعالى \" وخشعت الاصوات للرحمن \" (1) وقيل هما من أفعال القلوب وقال إبن دريد: يقال خضع الرجل للمرأة وأخضع إذا ألان كلامه لها قال والخاضع المطأطئ رأسه وعنقه وفي التنزيل \" فظلت أعناقهم لها خاضعين \" (2) وعند بعضهم أن الخشوع لا يكون إلا مع خوف الخاشع المخشوع له ولا يكون تكلفا ولهذا يضاف إلى القلب فيقال خشع قلبه وأصله البس ومنه يقال قف خاشع للذي تغلب عليه السهولة، والخضوع هو التطامن والتطأطوء ولا يقتضي أن يكون معه خوف، ولهذا لا يجوز إضافته إلى القلب فيقال خضع قلبه وقد يجوز أن يخضع الانسان تكلفا من غير أن يعتقد أن المخضوع له فوقه ولا يكون الخشوع كذلك، وقال بعضهم الخضوع قريب المعنى من الخشوع إلا أن الخضوع في البدن والاقرار بالاستجداء والخشوع في الصوت."},{"id":"furuq-lughawiyya:287","bookId":"furuq-lughawiyya","type":"section","seq":287,"chapter":"* (أ) *","title":"845- الفرق بين الخشوع والخضوع","page":"ج1 ص215","text":"الفرق بين الخشوع والخضوع (3) : قال الفيروز آبادي (4) : الخشوع: الخضوع أو قريب من الخضوع أو هو في البدن.\nوالخشوع في الصوت والبصر.\nوقال صاحب المحكم (1) : خشع يخشع خشوعا، [16 / أ] وتخشع رمى ببصره نحو الارض، وخفض صوته (2) .\nوقيل: الخشوع قريب من الخضوع إلا أن الخضوع في البدن والخشوع في الصوت والبصر، لقوله تعالى: \" خاشعة أبصارهم \" (3) وقوله:\n\" وخشعت الاصوات للرحمن \" (4) .\nانتهى.\nقلت: ويناسب التفسير (5) الاول عبارة الدعاء في طلب التوبة في الصحيفة الشريفة: \" فمثل بين يديك متضرعا، وغمض بصره إلى الارض متخشعا \" (6) .\nوقال البيضاوي: الخشوع: الاخبات، والخضوع: اللين والانقياد ولذلك يقال: الخشوع بالجوارح والخضوع بالقلب.\n(اللغات) ."},{"id":"furuq-lughawiyya:288","bookId":"furuq-lughawiyya","type":"section","seq":288,"chapter":"* (أ) *","title":"الفرق بين الخوف والخشية","page":"ج1 ص216","text":"أن الخوف يتعلق بالمكروه وبترك المكروه\nتقول خفت زيدا كما قال تعالى \" يخافون ربهم من فوقهم \" (1) وتقول خفت المرض كما قال سبحانه \" ويخافون سوء الحساب \" (2) والخشية تتعلق بمنزل المكروه ولا يسمى الخوف من نفس المكروه خشية ولهذا قال\n\" ويخشون ربهم ويخافون سوء الحساب \" (3) فإن قيل أليس قد قال \" إني خشيت أن تقول فرقت بين بني اسرائيل \" (4) قلنا إنه خشي القول المؤدي إلى الفرقة والمؤدي إلى الشئ بمنزلة من يفعله وقال بعض العلماء يقال خشيت زيدا ولا يقال خشيت ذهاب زيد فإن قيل ذلك فليس على الاصل ولكن على وضع الخشية مكان الخوف، وقد يوضع الشئ مكان الشئ إذا قرب منه."},{"id":"furuq-lughawiyya:289","bookId":"furuq-lughawiyya","type":"section","seq":289,"chapter":"* (أ) *","title":"850 - الفرق بين الخوف والخشية (5) : ذكر المحقق الطوسي في بعض مؤلفاته ما حاصله: أن الخوف والخشية وإن كانا في اللغة بمعنى واحد إلا أن بين خوف","page":"ج1 ص217","text":"وهو يحصل لاكثر الخلق وإن كانت مراتبه متفاوتة جدا، والمرتبة العليا منه لا تحصل إلا للقليل.\nوالخشية: حالة تحصل عند الشعور بعظمة الخالق وهيبته وخوف الحجب عنه، وهذه حالة لا تحصل إلا لمن اطلع على حال الكبرياء وذاق لذة القرب، ولذا قال تعالى: \" إنما يخشى الله من عباده العلماء \" (6) .\nفالخشية: خوف خاص، وقد يطلقون عليها الخوف.\nانتهى كلامه.\nقلت: ويؤيد هذا الفرق أيضا قوله تعالى يصف المؤمنين \" ويخشون\nربهم ويخافون سوء الحساب \" (1) حيث ذكر الخشية في جانبه سبحانه والخوف في جانب الحساب (2) .\nهذا وقد يراد بالخشية: الاكرام والاعظام، وعليه حمل قراءة من قرأ: \" إنما يخشى الله من عباده العلماء \" (3) برفع (الله) ونصب العلماء (4) .\n(اللغات) ."},{"id":"furuq-lughawiyya:290","bookId":"furuq-lughawiyya","type":"section","seq":290,"chapter":"* (أ) *","title":"855 - الفرق بين الخطأ والاخطاء (1) : قال أبو عبيدة: خطأ، وأخطأ: بمعنى واحد: لمن يذنب على غير عمد.","page":"ج1 ص219","text":"وقال غيره: (خطأ) في الدين، و (أخطأ) في كل شئ عامدا كان أو غير عامد.\nوقيل: خطأ: إذا تعمد ما نهي عنه، فهو خاطئ.\nوأخطأ: إذا أراد الصواب فصار إلى غيره.\nقلت: ويناسب المعنى الاخير عبارة الدعاء في الصحيفة الشريفة: \" أنا المسئ المعترف الخاطئ \" (2) .\nفإنه عليه السلام أراد الاقرار على نفسه بالمعاصي متعمدا بقرينة ما بعده، وهو قوله عليه السلام: \" أنا الذي عصاك متعمدا \" (3) .\nوقوله تعالى حكاية عن المؤمنين: \" ربنا اغفر لنا ذنوبنا وإسرافنا في أمرنا \" (4) .\n[6 / أ] فإن المراد: المعاصي الواقعة عن عمد، لان الصادر عن غير عمد لا (5) مؤاخذة عليه، فلا يناسبه استدعاء المغفرة مع أنه قد سبق سؤال عدم المؤاخذة عليه في قولهم: \" ربنا لا تؤاخذنا إن نسينا أو\nأخطأنا \" (1) (اللغات) ."},{"id":"furuq-lughawiyya:291","bookId":"furuq-lughawiyya","type":"section","seq":291,"chapter":"* (أ) *","title":"858 - الفرق بين الخطأ والذنب (2) : الفرق بينهما أن الذنب يطلق على ما يقصد بالذات، وكذا السيئة والخطيئة تغلب على ما يقصد بالعرض، لانها من الخ","page":"ج1 ص220","text":"(3) * وقيل: الخطيئة: السيئة الكبيرة، لان الخطأ بالصغيرة أنسب والسوء بالكبيرة ألصق *.\nوقيل الخطيئة ما كان بين الانسان وبين الله تعالى، والسيئة ما كان\nبينه وبين العباد (اللغات) ."},{"id":"furuq-lughawiyya:292","bookId":"furuq-lughawiyya","type":"section","seq":292,"chapter":"* (أ) *","title":"864 - الفرق بين الخلافة والامامة (2) : قال الطبرسي: الخليفة والامام واحد، إلا أن بينهما فرقا، فالخليفة من استخلف في الامر مكان من كان (3) قب","page":"ج1 ص221","text":"والامام: مأخوذ من التقدم، فهو المتقدم فيما يقتضي (4) وجوب الاقتداء بغيره، وفرض طاعته فيما تقدم فيه.\n(اللغات) ."},{"id":"furuq-lughawiyya:293","bookId":"furuq-lughawiyya","type":"section","seq":293,"chapter":"* (أ) *","title":"865 - الفرق بين الخلاق والنصيب: أن الخلاق النصيب الوافر من الخير خاصة بالتقدير لصاحبه أن يكون نصيبا له لان إشتقاقه من الخلق وهو التقدير","page":"ج1 ص222","text":"ويجوز أن يكون من الخلق لانه مما يوجبه الخلق الحسن."},{"id":"furuq-lughawiyya:294","bookId":"furuq-lughawiyya","type":"section","seq":294,"chapter":"* (أ) *","title":"869 - الفرق بين الخلف والخلف: أنه يقال لمن جاء بعد الاول خلف شرا كان أو خيرا والدليل على الشر قول لبيد: * وبقيت في خلف كجلد الأجرب * وعلى ال","page":"ج1 ص223","text":"والخلف بالتحريك ما أخلف عليك بدلا مما أخذ منك."},{"id":"furuq-lughawiyya:295","bookId":"furuq-lughawiyya","type":"section","seq":295,"chapter":"* (أ) *","title":"870 - الفرق بين الخلف والكذب (1) : قال في أدب الكاتب: الكذب فيما مضى، وهو أن تقول فعلت كذا، ولم تفعله! والخلف لما (2) يستقبل: وهو","page":"ج1 ص223","text":"أن تقول: سأفعل كذا - ولا نفعله - انتهى.\nقلت: ويرشد إليه قوله تعالى: \" والله يشهد إن المنافقين لكاذبون \" (3) .\nأي فيما أخبروا به من إيمانهم فيما مضى.\nوقوله تعالى: \" فلا تحسبن الله مخلف وعده رسله \" (4) .\nأي فيما وعدهم بالنصر وإهلاك أعدائهم في المستقبل.\n(اللغات) ."},{"id":"furuq-lughawiyya:296","bookId":"furuq-lughawiyya","type":"section","seq":296,"chapter":"* (أ) *","title":"874 - الفرق بين الخلق والتغيير والفعل: أن الخلق في اللغة التقدير يقال خلقت الاديم إذا قدرته خفا أو غيره وخلق الثوب وأخلق لم يبق منه إلا تقدي","page":"ج1 ص224","text":"زال عنه إلى غيره قيل تخلق بغير خلقه، وفي القرآن \" إن هذا إلا خلق الاولين \" (1) قال الفراء يريد عادتهم: والمخلق التام الحسن لانه قدر تقديرا حسنا، والمتخلق المعتدل في طباعه، وسمع بعض الفصحاء كلاما حسنا فقال هذا كلام مخلوق، وجميع ذلك يرجع إلى التقدير، والخلوق من\nالطيب أجزاء خلطت على تقدير، والناس يقولون لا خالق إلا الله والمراد أن هذا اللفظ لا يطلق إلا لله إذ ليس أحد إلا وفي فعله سهو أو غلط يجري منه على غير تقدير غير الله تعالى كما تقول لا قديم إلا الله وإن كنا نقول هذا قديم لانه ليس يصح قول لم يزل موجودا إلا الله."},{"id":"furuq-lughawiyya:297","bookId":"furuq-lughawiyya","type":"section","seq":297,"chapter":"* (أ) *","title":"877 - الفرق بين قولنا الجسم لا يخلو من كذا ولا ينفك من كذا وقولنا لا ببرح ولا يزال ولا يعرى: أن قولنا لا يخلو يستعمل فيما لا يكون هيئة يشاهد","page":"ج1 ص225","text":"ويستعمل في الافتراق أيضا لان الافتراق يقع مع الاجتماع في اللفظ كثيرا وإذا قرب اللفظ من اللفظ في الخطاب اجري مجراه في أكثر الاحوال."},{"id":"furuq-lughawiyya:298","bookId":"furuq-lughawiyya","type":"section","seq":298,"chapter":"* (أ) *","title":"878 - الفرق بين الخلود والبقاء: أن الخلود إستمرار البقاء من وقت مبتدأ على ما وصفنا (1) ، والبقاء يكون وقتين فصاعدا، وأصل الخلود اللزوم ومنه","page":"ج1 ص225","text":"أخلد إلى الارض وأخلد إلى قوله أي لزم معنى ما أتى به فالخلود اللزوم المستمر ولهذا يستعمل في الصخور وما يجري مجراه ومنه قول لبيد: * حمر خوالد ما يبين كلامها * وقال علي بن عيسى: الخلود مضمر بمعنى في كذا ولهذا يقال خلده في الحبس وفي الديوان، ومن أجله قيل للاثافي خوالد فإذا زالت لم تكن خوالد، ويقال لله تعالى دائم الوجود ولا يقال خالد الوجود."},{"id":"furuq-lughawiyya:299","bookId":"furuq-lughawiyya","type":"section","seq":299,"chapter":"* (أ) *","title":"883 - الفرق بين الخوف والحذر والخشية والفزع: أن الخوف توقع الضرر","page":"ج1 ص226","text":"المشكوك في وقوعه ومن يتيقن الضرر لم يكن خائفا له وكذلك الرجاء لا يكون إلا مع الشك ومن تيقن النفع لم يكن راجيا له، والحذر توقي الضرر وسواء كان مظنونا أو متيقنا، والحذر يدفع الضرر، والخوف لا يدفعه ولهذا يقال خذ حذرك ولا يقال خذ خوفك."},{"id":"furuq-lughawiyya:300","bookId":"furuq-lughawiyya","type":"section","seq":300,"chapter":"* (أ) *","title":"889 - الفرق بين الخول والعبيد: أن الخول هم الذين يختصون بالانسان من جهة الخدمة والمهنة ولا تقتضي الملك كما تقتضيه العبيد (3) ولهذا لا يقال","page":"ج1 ص227","text":"الخلق خول الله كما يقال عبيده (1) ."},{"id":"furuq-lughawiyya:301","bookId":"furuq-lughawiyya","type":"section","seq":301,"chapter":"* (أ) *","title":"890 - الفرق بين الخيانة والسرقة (2) : قال ابن قتيبة: لا يكاد الناس يفرقون بين الخائن والسارق.","page":"ج1 ص227","text":"والخائن الذي ائتمن فأخذ (3) ، قال النمر بن تولب (4) : وإن بني ربيعة بعد وهب * كراعي البيت يحفظه فخانا! والسارق من سرقك (5) سرا بأي وجه كان، يقال: كل خائن سارق، وليس كل سارق خائنا.\nوالغاصب: الذي جاهرك ولم يستتر، والقطع في السرقة (6) دون الخيانة والغصب.\nإنتهى.\n(اللغات) ."},{"id":"furuq-lughawiyya:302","bookId":"furuq-lughawiyya","type":"section","seq":302,"chapter":"* (أ) *","title":"896 - الفرق بين الخير والنعمة: أن الانسان يجوز أن يفعل بنفسه الخير كما يجوز أن ينفعها ولا يجوز أن ينعم عليها فالخير والنفع من هذا الوجه متسا","page":"ج1 ص228","text":"(*)"},{"id":"furuq-lughawiyya:303","bookId":"furuq-lughawiyya","type":"section","seq":303,"chapter":"* (أ) *","title":"899 - الفرق بين الدراية والعلم: أن الدراية فيما قال أبو بكر الزبيري (1) : بمعنى الفهم قال وهو لنفي السهو عما يرد على الانسان فيدريه أي يفهمه","page":"ج1 ص229","text":"وحكي عن بعض أهل العربية: أنها مأخوذة من دريت إذا اختلت وأنشد: * يصيب فما يدري ويخطي فما درى * أي ما اختل فيه يفوته وما طلبه من الصيد بغير ختل يناله، فإن كانت مأخوذة من ذاك فهو يجري مجرى ما يفطن الانسان له من المعرفة التي تنال غيره فصار ذلك كالختل منه للاشياء، وهذا لا يجوز على الله سبحانه وتعالى، وجعل أبو علي رحمة الله: الدارية مثل العلم وأجازها على الله واحتج بقول الشاعر: * لاهم لا أدري وأنت الداري * وهذا صحيح لان الانسان إذا سئل عما لا يدري فقال لا أدري فقد أفاد هذا القول منه معنى قوله لا أعلم لانه لا يستقيم أن يسأل عما لا يعلم فيقول لا أفهم لان معنى قوله لا أفهم أي لا أفهم سؤالك وقوله لا أدري إنما هو لا أعلم ما جواب مسألتك، وعلى هذا يكون العلم\nوالدراية سواء لان الدراية علم يشتمل على المعلوم من جميع وجوهه وذلك أن الفعالة للاشتمال مثل العصابة والعمامة والقلادة، ولذلك جاء أكثر أسماء الصناعات على فعالة نحو القصارة والخياطة ومثل ذلك العباة لاشتمالها على ما فيها، فالدراية تفيد ما لا يفيده العلم من هذه الوجه والفعالة أيضا تكون للاستيلاء مثل الخلافة والامارة فيجوز أن تكون بمعنى الاستيلاء فتفارق العلم من هذه الجهة."},{"id":"furuq-lughawiyya:304","bookId":"furuq-lughawiyya","type":"section","seq":304,"chapter":"* (أ) *","title":"902 - الفرق بين الدعاء والامر (1) : قال الطبرسي (2) : الفرق بين الدعاء والامر أن في الامر ترغيبا في الفعل، وزجرا عن تركه، وله صيغة تنبئ","page":"ج1 ص230","text":"عنه، وليس كذلك الدعاء، وكلاهما طلب.\nوأيضا فإن الامر يقتضي أن يكون المأمور دون الامر في الرتبة.\nوالدعاء يقتضي أن يكون فوقه.\n(اللغات) ."},{"id":"furuq-lughawiyya:305","bookId":"furuq-lughawiyya","type":"section","seq":305,"chapter":"* (أ) *","title":"904 - الفرق بين الدفتر والصحيفة: أن الدفتر لا يكون إلا أوراقا مجموعة والصحيفة تكون ورقة واحدة تقول عندي صحيفة بيضاء فاذا قلت صحف أفدت أنها م","page":"ج1 ص231","text":"يقال صحف بيض وانما يقال من صحائف إلى صحف ليفيد أنها مكتوبة، وفي القرآن (وإذا الصحف نشرت) (1) وقال أبو بكر: الصحيفة قطعة من أدم أبيض أو ورق يكتب فيه."},{"id":"furuq-lughawiyya:306","bookId":"furuq-lughawiyya","type":"section","seq":306,"chapter":"* (أ) *","title":"908 - الفرق بين دلالة الآية وتضمين الآية: أن دلالة الآية على الشئ هو ما يمكن الاستدلال به على ذلك الشئ كقوله الحمد لله يدل على معرفة الله إذ","page":"ج1 ص231","text":"ولهذا قال أصحابنا: إن معرفة الله واجبة لان شكره واجب لانه لا يجوز أن يشكر من لا يعرف، وتضمين الآية هو إحتمالها للشئ بلا مانع ألا ترى أنه لو إحتملته لكن منع منه القياس أو سنة أو آية أخرى لم تتضمنه، ولهذا نقول إن قوله \" السارق والسارقة فاقطعوا أيديهما \" (2) لا يتضمن وجوب القطع على من سرق دانقا وإن كان محتملا لذلك لمنع السنة منه، وهذا واضح والحمد لله تعالى."},{"id":"furuq-lughawiyya:307","bookId":"furuq-lughawiyya","type":"section","seq":307,"chapter":"* (أ) *","title":"909 - الفرق بين الدلالة والامارة: أن الدلالة عند شيوخنا ما يؤدي النظر فيه إلى","page":"ج1 ص232","text":"العلم، والامارة ما يؤدي النظر فيه إلى غلبة الظن لنحو ما يطلب به من جهة القبلة ويعرف به جزاء الصيد وقيم المتلفات، والظن في الحقيقة ليس يجب عن النظر في الامارة لوجوب النظر عن العلم في الدلالة وإنما يختار ذلك عنده فالامارة في الحقيقة ما يختار عنده الظن، ولهذا جاز إختلاف المجتهدين مع علم كل واحد منهم بالوجه الذي منه خالفه صاحبه كاختلاف الصحابة في مسائل الجد واختلاف آراء ذوي الرأي في الحروب وغيرها مع تقاربهم في معرفة الامور المتعلقة بذلك، ولهذا تستعمل الامارة فيما كان عقليا وشرعيا."},{"id":"furuq-lughawiyya:308","bookId":"furuq-lughawiyya","type":"section","seq":308,"chapter":"* (أ) *","title":"911 - الفرق بين الدلالة والحجة: قال بعض المتكلمين الادلة تنقسم أقساما وهي دلالة العقل ودلالة الكتاب ودلالة السنة ودلالة الاجماع ودلالة القيا","page":"ج1 ص232","text":"وتسمى طريقة النظر ولا تسمى دلالة لانه يبعد أن يكون الشئ دلالة على نفسه أو على بعض صفات نفسه فلا يبعد أن يكون يدل على غيره وكل ذلك يسم حجة فافترقت الحجة والدلالة من هذا الوجه، وقال قوم لا يسميان حجة ودلالة إلا بعد النظر فيهما وإذا قلنا حجة الله ودلالة الله فالمراد أن الله نصبهما وإذا قلنا حجة العقل ودلالة العقل فالمراد أن النظر فيهما يفضي إلى العلم من غير افتقار إلى أن ينصبهما ناصب، وقال غيره: الحجة هي الاستقامة في النظر والمضي فيه على سنن مستقيم من رد الفرع إلى الاصل وهي مأخوذة من الحجة وهي الطريق المستقيم وهذا هو فعله المستدل وليس من الدلالة في شئ، وتأثير الحجة في النفس كتأثير\nالبرهان فيها وإنما تنقصل الحجة من البرهان لان الحجة مشتقة من معنى الاستقامة في القصد حج يحج إذا استقام في قصده، والبرهان لا يعرف له إشتقاق وينبغي أن يكون لغة مفردة."},{"id":"furuq-lughawiyya:309","bookId":"furuq-lughawiyya","type":"section","seq":309,"chapter":"* (أ) *","title":"913 - الفرق بين الدلالة والعلامة: أن الدلالة على الشئ ما يمكن كل ناظر فيها أن يستدل بها عليه كالعالم لما كان دلالة على الخالق كان دالا عليه","page":"ج1 ص233","text":"يوافقك عليه، ثم يجوز أن تزيل علامة الشئ بينك وبين صاحبك فتخرج من أن تكون علامة له ولا يجوز أن تخرج الدلالة على الشئ من أن تكون دلالة عليه، فالعلامة تكون بالوضع والدلالة بالاقتضاء."},{"id":"furuq-lughawiyya:310","bookId":"furuq-lughawiyya","type":"section","seq":310,"chapter":"* (أ) *","title":"916 - الفرق بين دلالة الكلام ودلالة البرهان: أن دلالة البرهان هي الشهادة للمقالة بالصحة، ودلالة الكلام إحضاره المعنى النفس من غير شهادة له ب","page":"ج1 ص233","text":"المقالة، ومن الكلام ما يتضمن دلالة البرهان ومنه ما لا يتضمن ذلك إذ كل برهان فإنه يمكن أن يظهر بالكلام كما أن كل معنى يمكن ذلك فيه، والاسم دلالة على معناه، وليس برهانا على معناه وكذلك هداية الطريق دلالة عليه وليس برهانا عليه فتأثير دلالة الكلام خلاف تأثير دلالة البرهان."},{"id":"furuq-lughawiyya:311","bookId":"furuq-lughawiyya","type":"section","seq":311,"chapter":"* (أ) *","title":"917 - الفرق بين الدلالة والدليل: أن الدلالة تكون على أربعة أوجه أحدها ما يمكن أن يستدل به قصد فاعله ذلك أو لم يقصد، والشاهد أن أفعال البهائم","page":"ج1 ص234","text":"اللغة معروف يقال قد دل الحارب على نفسه بركوبه الرمل ويقال أسلك الحزن لانه لا يدل على نفسك ويقولون إستدللنا عليه بأثره وليس له أن يحمل هذا على المجاز دون الحقيقة إلا بدليل ولا دليل، والثاني العبارة عن الدلالة يقال للمسؤول اعد دلالتك، والثالث الشبهة يقال دلالة المخالف كذا أي شبهته، والرافع الامارات يقول الفقهاء الدلالة من القياس كذا والدليل فاعل الدلالة ولهذا يقال لمن يتقدم القوم في الطريق دليل إذ كان يفعل من التقدم ما يستدلون به، وقد تسمى الدلالة دليلا مجازا، والدليل أيضا فاعل الدلالة مشتق من فعله، ويستعمل الدليل في العبارة والامارة ولا يستعمل في الشبه، والشبهة هي الاعتقاد الذي يختار صاحبه\nالجهل أو يمنع من إختيار العلم وتسمى العبارة عن كيفية ذلك الاعتقاد شبهة أيضا وقد سمي المعنى الذي يعتقد عنده ذلك الاعتقاد شبهة فيقال هذه الحيلة شبهة لقوم إعتقدوها معجزة."},{"id":"furuq-lughawiyya:312","bookId":"furuq-lughawiyya","type":"section","seq":312,"chapter":"* (أ) *","title":"923 - الفرق بين الدنيا والعالم: أن الدنيا صفة والعالم إسم تقول العالم السفلي والعالم العلوي فتجعل العالم إسما وتجعل العلوي والسفلي صفة وليس","page":"ج1 ص236","text":"الساعة الآخرة وما أشبه ذلك."},{"id":"furuq-lughawiyya:313","bookId":"furuq-lughawiyya","type":"section","seq":313,"chapter":"* (أ) *","title":"925 - الفرق بين الدهر والزمان (2) : هما في اللغة مترادفان.","page":"ج1 ص236","text":"وقيل: الدهر طائفة من الزمان غير محدودة، والزمان مرور الليالي والايام.\nوقال الازهري (3) : الدهر عند العرب يطلق على الزمان، وعلى الفصل من فصول السنة، وعلى أقل من ذلك، ويقع على مدة الدنيا كلها.\nقال: وسمعت غير واحد من العرب يقول: \" أقمنا على ماء كذا دهرا، وهذا المرعى يكفينا دهرا \".\nانتهى.\nولا يخفى أن إطلاق الدهر على الزمن القليل من باب المجاز والاتساع.\nوقالت الحكماء: الدهر هو الآن الدائم الذي هو امتداد الحضرة الآلهية، وهو باطن الزمان، وبه يتجدد الازل والابد.\nوالزمان مقدار حركة الفلك (1) الاطلس.\nوعند المتكلمين: الزمان عبارة عن متجدد معلوم يقدر به متجدد آخر موهوم، كما يقال: آتيك عند طلوع الشمس.\nأن طلوع الشمس (2) معلوم: ومجيئه موهوم، فإذا قرن ذلك الموهوم بذلك المعلوم زال الابهام.\nوقال ابن السيد (3) : الدهر مدة الاشياء الساكنة، والزمان: مدة الاشياء المتحركة، يقال: الزمان مدة الاشياء المحسوسة، والدهر: مدة الاشياء (4) المعقولة.\n(اللغات) ."},{"id":"furuq-lughawiyya:314","bookId":"furuq-lughawiyya","type":"section","seq":314,"chapter":"* (أ) *","title":"926 - الفرق بين الدهر والعصر: أن الدهر هو ما ذكرناه والعصر لكل مختلفين معناهما واحد مثل الشتاء والصيف والليلة واليوم والغداة والسحر يقال","page":"ج1 ص237","text":"لذلك كله العصر، وقال المبرد: في تأويل قوله عزوجل \" والعصر إن الانسان لفي خسر \" (5) قال العصر هاهنا الوقت قال ويقولون أهل هذا العصر كما يقولون أهل هذا الزمان، والعصر إسم للسنين الكثيرة قال الشاعر: أصبح مني الشباب قد نكرا * إن بان مني فقد ثوى عصرا\nوتقول عاصرت فلانا أي كنت في عصره أي زمن حياته."},{"id":"furuq-lughawiyya:315","bookId":"furuq-lughawiyya","type":"section","seq":315,"chapter":"* (أ) *","title":"928 - الفرق بين الدهش والحيرة: أن الدهش حيرة مع تردد واضطراب ولا يكون إلا ظاهرا ويجوز أن تكون الحيرة خافية كحيرة الانسان بين","page":"ج1 ص238","text":"أمرين تروى فيهما ولا يدري على أيهما يقدم ولا يظهر حيرته ولا يجوز أن يدهش ولا يظهر دهشته."},{"id":"furuq-lughawiyya:316","bookId":"furuq-lughawiyya","type":"section","seq":316,"chapter":"* (أ) *","title":"933 - الفرق بين الدين والملة: (2061) .","page":"ج1 ص238","text":"(*)"},{"id":"furuq-lughawiyya:317","bookId":"furuq-lughawiyya","type":"section","seq":317,"chapter":"* (أ) *","title":"ذ","page":"ج1 ص239","text":"لك دوامه فيه، ولذلك وصف سبحانه بالدوام دون الخلود، إلا أن خلود الكفار في النار المراد به التأييد بلا خلاف بين الامة.\n(اللغات) ."},{"id":"furuq-lughawiyya:318","bookId":"furuq-lughawiyya","type":"section","seq":318,"chapter":"* (أ) *","title":"935 - الفرق بين الذات والحقيقة: أنه لم يرف الشئ من لم يعرف ذاته.","page":"ج1 ص240","text":"وقد يعرف ذاته من لم يعرف حقيقته.\nوالحقيقة أيضا من قبيل القول على ما ذكرنا (1) وليست الذات كذلك والحقيقة عند العرب ما يجب على الانسان حفظه يقولون هو حامي الحقيقة وفلان لا يحمي حقيقته."},{"id":"furuq-lughawiyya:319","bookId":"furuq-lughawiyya","type":"section","seq":319,"chapter":"* (أ) *","title":"938 - الفرق بين الذبح والذبح (2) : الذبح بكسر الذال: المهيأ لان يذبح، وبفتح الذال: المصدر.","page":"ج1 ص240","text":"قاله الطبرسي: (اللغات) ."},{"id":"furuq-lughawiyya:320","bookId":"furuq-lughawiyya","type":"section","seq":320,"chapter":"* (أ) *","title":"939 - الفرق بين الذرء والخلق: أن أصل الذرء الاظهار ومعنى ذرأ الله الخلق أظهرهم بالايجاد بعد العدم، ومنه قيل للبياض الذرأة لظهوره وشهرته وملح","page":"ج1 ص241","text":"\" تذروه الرياح \" (1) وليس من هذا ذريت الحنطة فرقت عنها التبن."},{"id":"furuq-lughawiyya:321","bookId":"furuq-lughawiyya","type":"section","seq":321,"chapter":"* (أ) *","title":"الفرق بين الذكر والخاطر","page":"ج1 ص241","text":"(820) ."},{"id":"furuq-lughawiyya:322","bookId":"furuq-lughawiyya","type":"section","seq":322,"chapter":"* (أ) *","title":"945- الفرق بين الذكر والخاطر","page":"ج1 ص241","text":"الفرق بين الذكر والخاطر: (821) ."},{"id":"furuq-lughawiyya:323","bookId":"furuq-lughawiyya","type":"section","seq":323,"chapter":"* (أ) *","title":"946 - الفرق بين الذكر والعلم: أن الذكر وإن كان ضربا من العلم (2) فإنه","page":"ج1 ص241","text":"لا يسمى ذكرا إلا إذا وقع بعد النسيان، وأكثر ما يكون في العلوم الضرورية ولا يوصف الله به لانه لا يوصف بالنسيان، وقال علي بن عيسى: الذكر يضاد السهو، والعلم يضاد الجهل، وقد يجمع الذكر للشئ والجهل به من وجه واحد."},{"id":"furuq-lughawiyya:324","bookId":"furuq-lughawiyya","type":"section","seq":324,"chapter":"* (أ) *","title":"953 - الفرق بين الذليل والذلول (1) : قيل: يقال لكل مطبوع من الناس ذليل: ومن غير الناس ذلول.","page":"ج1 ص242","text":"قال تعالى: \" لا ذلول تثير الأرض \" (2) أي غير مذللة للحرث، أو لا تمنع على طالب.\nوقال بعض المفسرين: الذل - بالكسر - ضد الصعوبة، وبضمها ضد العز، يقال: ذلول من الذل من قوم أذلة، وذليل من الذل من قوم أذلاء، والاول من اللين والانقياد، والثاني من الهون والاستخفاف.\n(اللغات) ."},{"id":"furuq-lughawiyya:325","bookId":"furuq-lughawiyya","type":"section","seq":325,"chapter":"* (أ) *","title":"956 - الفرق بين الذم والهجو: أن الذم نقيض الحمد وهما يدلان على الفعل","page":"ج1 ص242","text":"وحمد المكلف يدل على إستحقاقه للثواب بفعله، وذمه يدل على إستحقاقه للعقاب بفعله، والهجو نقيض المدح وهما يدلان على الفعل والصفة كهجوك الانسان بالبخل وقبح الوجه، وفرق آخر أن الذم يستعمل في\nالفعل والفاعل فتقول ذممته بفعله وذممت فعله، والهجو يتناول الفاعل والموصوف دون الفعل والصفة فتقول هجوته بالبخل وقبح الوجه ولا تقول هجوت قبحه وبخله، وأصل الهجو في العربية الهدم تقول هجوت البيت إذا هدمته وكان الاصل في الهجو أن يكون بعد المدح كما أن الهدم يكون بعد البناء إلا أنه كثر استعماله فجرى في الوجهين."},{"id":"furuq-lughawiyya:326","bookId":"furuq-lughawiyya","type":"section","seq":326,"chapter":"* (أ) *","title":"الفرق بين الذنب والجرم","page":"ج1 ص243","text":"أن الذنب ما يتبعه الذم أو ما يتتبع عليه العبد من قبيح فعله، وذلك أن أصل الكلمة الاتباع على ما ذكرنا فأما قولهم للصبي قد أذنب فإنه مجاز، ويجوز أن يقال الاثم هو القبيح الذي عليه تبعة، والذنب هو القبيح من الفعل ولا يفيد معنى التبعة، ولهذا قيل للصبي قد أذنب ولم نقل قد أثم، والاصل في الذنب الرذل من الفعل كالذنب الذي هو أرذل ما في صاحبه، والجرم ما ينقطع به عن الواجب وذلك أن أصله في اللغة القطع ومنه قيل للصرام الجرام وهو قطع التمر."},{"id":"furuq-lughawiyya:327","bookId":"furuq-lughawiyya","type":"section","seq":327,"chapter":"* (أ) *","title":"959- الفرق بين الذنب والجرم","page":"ج1 ص243","text":"الفرق بين الذنب والجرم (1) : قيل: هما بمعنى.\nإلا (2) أن الفرق بينهما أن أصل الذنب الاتباع، فهو ما يتبع عليه العبد من قبيح عمله، كالتبعة.\nوالجرم أصله: القطع، فهو القبيح الذي ينقطع به عن الواجب.\n(اللغات) ."},{"id":"furuq-lughawiyya:328","bookId":"furuq-lughawiyya","type":"section","seq":328,"chapter":"* (أ) *","title":"ر","page":"ج1 ص244","text":"مستحقا عليه العقاب وقد يكون قبيحا لا عقاب عليه كالقبح يقع من الطفل قالوا ولا يسمى ذلك ذنبا وإنما يسمى الذنب ذنبا لما يتبعه من الذم، وأصل الكلمة على قولهم الاتباع ومنه قيل ذنب الدابة لانه كالتابع لها والذنوب الدلو التي لها ذنب، ويجوز أن يقال إن الذنب يفيد أنه الرذل من الفعل الدنئ وسمي الذنب ذنبا لانه أرذل ما في صاحبه وعلى هذا إستعماله في الطفل حقيقة."},{"id":"furuq-lughawiyya:329","bookId":"furuq-lughawiyya","type":"section","seq":329,"chapter":"* (أ) *","title":"968 - الفرق بين الذوق وإدراك الطعم: أن الذوق ملابسة يحس بها الطعم","page":"ج1 ص244","text":"وإدراك الطعم يتبين به من ذلك الوجه وغير تضمين ملابسة الحبل وكذلك يقال ذقته فلم أجد له طعما."},{"id":"furuq-lughawiyya:330","bookId":"furuq-lughawiyya","type":"section","seq":330,"chapter":"* (أ) *","title":"الفرق بين الرأفة والرحمة","page":"ج1 ص245","text":"أن الرأفة أبلغ من الرحمة ولهذا قال أبو عبيدة: إن في قوله تعالى (رؤوف رحيم) (1) تقديما وتأخيرا أراد أن التوكيد يكون في الابلغ في المعنى فإذا تقدم الابلغ في اللفظ كان المعنى مؤخرا."},{"id":"furuq-lughawiyya:331","bookId":"furuq-lughawiyya","type":"section","seq":331,"chapter":"* (أ) *","title":"971- الفرق بين الرأفة والرحمة","page":"ج1 ص245","text":"الفرق بين الرأفة والرحمة (2) : قيل: الرأفة أشد الرحمة، وقيل: الرحمة أكثر من الرأفة، والرأفة أقوى منها في الكيفية، لانها عبارة عن إيصال النعم صافية عن الالم.\nوالرحمة: إيصال النعم مطلقا.\nوقد يكون مع الكراهة والالم\nللمصلحة كقطع العضو المجذوم.\nوإطلاق الرأفة عليه تعالى كإطلاق الرحمة: (اللغات) ."},{"id":"furuq-lughawiyya:332","bookId":"furuq-lughawiyya","type":"section","seq":332,"chapter":"* (أ) *","title":"975 - الفرق بين الصفة برب والصفة بمالك: أن الصفة برب أفخم من الصفة بمالك لانها من تحقيق القدرة على تدبير ما ملك فقولنا رب يتضمن معنى الملك و","page":"ج1 ص247","text":"وشاة ربى وهي مثل النفساء من النساء وقيل لها ذلك لانها تربي ولدها فالباء في التربية أصلها ياء نقلت إلى حرف العلة كما قيل في الظن\nالتظني."},{"id":"furuq-lughawiyya:333","bookId":"furuq-lughawiyya","type":"section","seq":333,"chapter":"* (أ) *","title":"976 - الفرق بين الرجاء والطمع: أن الرجاء هو الظن بوقوع الخير الذي يعتري صاحبه الشك فيه إلا أن ظنه فيه أغلب وليس هو من قبيل العلم، والشاهد أن","page":"ج1 ص247","text":"ويقال أرجو أن يدخل الجنة إذا لم يعلم ذلك.\nوالرجاء الامل في الخير والخشية والخوف في الشر لانهما يكونان مع الشك في المرجو والمخوف ولا يكون الرجاء إلا عن سبب يدعو إليه من كرم المرجو أو ما به إليه، ويتعدى بنفسه تقول رجوت زيدا والمراد رجوت الخير من زيد لان الرجاء لا يتعدى إلى أعيان الرجال.\nوالطمع ما يكون من غير سبب يدعو إليه فإذا طمعت في الشئ فكأنك حدثت نفسك به من غير أن يكون هناك سبب يدعو إليه، ولهذا ذم الطمع ولم يذم الرجاء، والطمع يتعدى إلى المفعول بحرف فتقول طمعت فيه كما تقول فرقت منه وحذرت منه وإسم الفاعل طمع مثل حذر وفرق ودئب إذا جعلته كالنسبة وإذا بنيته على الفعل قلت طامع."},{"id":"furuq-lughawiyya:334","bookId":"furuq-lughawiyya","type":"section","seq":334,"chapter":"* (أ) *","title":"977 - الفرق بين الرجاح والرزانة: أن الرجاح أصله الميل ومنه رجحت كفة الميزان إذا مالت لثقل ما فيها ومنه زن وأرجح، يوصف الرجل بالرجاح على وجه","page":"ج1 ص247","text":"زيادة الفضل فالفرق بينهما بين."},{"id":"furuq-lughawiyya:335","bookId":"furuq-lughawiyya","type":"section","seq":335,"chapter":"* (أ) *","title":"986 - الفرق بين الرجوع والعود (1) : الرجوع: فعل الشئ ثانية، ومصيره","page":"ج1 ص249","text":"إلى حال كان عليها، والعود: يستعمل في هذا المعنى على الحقيقة، ويسعمل في الابتداء مجازا، قال الزجاج: يقال قد عاد إلي (2) من فلان مكروه، وإن لم يكن قد سبقه مكروه قبل ذلك.\nوتأويله أنه لحقني منه مكروه.\nانتهى.\nقلت: ومنه قوله تعالى: \" قال الملا الذين استكبروا من قومه لنخرجنك يا شعيب والذين امنوا معك من قريتنا أو لتعودون في ملتنا \" (3) والمعنى: أو لتدخلن في ديننا.\nفإنه عليه السلام لم يكن على دينهم قط.\nوقال الشاعر (4) : تلك المكارم لاقعبان من لبن * شيبا بماء فعادا بعد أبوالا! أي صار أبوالا.\n(اللغات) ."},{"id":"furuq-lughawiyya:336","bookId":"furuq-lughawiyya","type":"section","seq":336,"chapter":"* (أ) *","title":"الفرق بين الرحمن والرحيم","page":"ج1 ص249","text":"أن الرحمن على ما قال إبن عباس: أرق من\nالرحيم يريد أنه أبلغ في المعنى لان الرقة والغلظة لا يوصف الله تعالى بهما والرحمة من الله تعالى على عباده ونعمته عليهم في باب الدين والدنيا، وأجمع المسلمون أن الغيث رحمة من الله تعالى، وقيل معنى قوله رحيم أن من شأنه الرحمة وهو على تقدير يديم، والرحمن في تقدير بزمان وهو اسم\nخص به الباري عزوجل، ومثله في التخصيص قولنا فهذا النجم سماك وهو مأخوذ من السمك الذي هن الارتفاع وليس كل مرتفع سماكا وقولنا للنجم الآخر دبران لانه يدبر الثريا، وليس كل ما دبر شيئا يسمى دبرانا فأما قولهم لمسيلمة رحمان اليمامة فشئ وضعه له أصحابه على وجه الخطأ كما وضع غيرهم إسم الالهية لغير الله وعندنا أن الرحيم مبالغة لعدو له وأن الرحمن أشد مبالغة لانه أشد عدولا وإذا كان العدول على المبالغة كلما كان أشد عدولا كان أشد مبالغة."},{"id":"furuq-lughawiyya:337","bookId":"furuq-lughawiyya","type":"section","seq":337,"chapter":"* (أ) *","title":"989 - الفرق بين الرحمن والرحيم (1) : هما مشتقان من الرحمة، وهي لغة: رقة القلب وعطفه.","page":"ج1 ص250","text":"والمراد هنا التفضل والاحسان.\nفإن أسماءه - سبحانه - تؤخذ باعتبار الغايات دون المبادئ.\nوقيل: (الرحمن) أبلغ من (الرحيم) ، لكثرة حروفه، مختص بالله تعالى، لا بطريق العلية لجريانه وصفا، وإطلاقه على غير تعالى كفر.\nومبالغته إما بالكمية لكثرة أفراد الرحمة، وأفراد المرحوم، أو بالكيفية لتخصيصه بجلائل النعم وأصولها المستمرة وتقديمه على الرحيم في البسملة، لاختصاصه به تعالى.\nوروى عن أبي عبد الله عليه السلام أنه قال: \" الرحمن اسم خاص\nبصفة عامة \" (1) والرحيم بالعكس.\nوذلك أن لفظ (الرحمن) لا يطلق على غيره تعالى، كما سبق.\nوأما صفة عمومه، فلان رحمته في الدنيا واسعة شاملة للمؤمن والكافر.\nوأما (الرحيم) فيطلق على غيره تعالى.\nوأما صفة خصوصه فلان رحمته في الآخرة لا تشمل إلا المؤمن.\nفإن قلت: قد ورد في بعض الادعية: (يا رحمن الدنيا ورحيم الآخرة) ، وفي بعضها: (يا رحمن الدنيا والآخرة ورحيم الدنيا) ، وورد في الصحيفة الشريفة: \" يا رحمن الدنيا والآخرة ورحيمهما \" (2) ، فما وجه الاختلاف؟ قلت: قد أجبت عنه بأن اختلاف العبارات باختلاف الاعتبارات فعند اعتبار أن (الرحمن) أبلغ من (الرحيم) لدلالة زيادة المباني على زيادة المعاني، واعتبار الاغلبية فيه باعتبار الكمية نظرا إلى كثرة أفراد المرحومين عبر برحمن الدنيا ورحيم الآخرة لشمول رحمته في الدنيا: للمؤمن والكافر، واختصاص رحمة الآخرة بالمؤمن.\nوعند اعتبار الاغلبية باعتبار الكيفية، وهي جلالة الرحمة ودقتها بالنسبة إلى مجموع كل من الرحمتين عبر برحمن الدنيا والآخرة، ورحيم الدنيا لجلالة رحمة الآخرة بأسرها بخلاف رحمة الدنيا، وباعتبار نسبة بعض أفراد كل من رحمة الدنيا والآخرة إلى بعض عبر برحمن الدنيا والآخرة ورحميهما، لان بعض من كل منهما أجل من البعض، وبعضا من كل منهما أدق.\n(اللغات) ."},{"id":"furuq-lughawiyya:338","bookId":"furuq-lughawiyya","type":"section","seq":338,"chapter":"* (أ) *","title":"992 - الفرق بين الرحمة والنعمة: أن الرحمة الانعام على المحتاج إليه وليس","page":"ج1 ص252","text":"كذلك النعمة لانك إذا أنعمت بمال تعطيه إياه فقد أنعمت عليه ولا تقول إنك رحمته."},{"id":"furuq-lughawiyya:339","bookId":"furuq-lughawiyya","type":"section","seq":339,"chapter":"* (أ) *","title":"996 - الفرق بين الرد والدفع (1) : هما بمعنى.","page":"ج1 ص252","text":"وفرق بعضهم بينهما بأن الدفع قد يكون إلى جهة القدام والخلف والرد لا يكون إلا إلى جهة الخلف.\nويدل عليه قوله تعالى: \" وإنهم آتيهم عذاب غير مردود \" (2) .\nفإنه لا معقب لحكمه.\n(اللغات) ."},{"id":"furuq-lughawiyya:340","bookId":"furuq-lughawiyya","type":"section","seq":340,"chapter":"* (أ) *","title":"998 - الفرق بين الرزانة والوقار: أن الرزانة تستعمل في الانسان وغيره فهي أعم","page":"ج1 ص253","text":"يقال رجل رزين أي ثقيل ولا يقال حجر وقور."},{"id":"furuq-lughawiyya:341","bookId":"furuq-lughawiyya","type":"section","seq":341,"chapter":"* (أ) *","title":"999 - الفرق بين الرزق والحظ: أن الرزق هو العطاء الجاري في الحكم على الادرار ولهذا يقال أرزاق الجند لانها تجري على إدرار، والحظ لا يفيد هذا ا","page":"ج1 ص253","text":"هذا موضع ذكره، وكل ما خلقه الله تعالى في الارض مما يملك فهو رزق للعباد في الجملة بدلالة قوله تعالى \" خلق لكم ما في الارض جميعا \" (2) وإن كان رزقا لهم في الجملة فتفصيل قسمته على ما يصح ويجوز من الاملاك، ولا يكون الحرام رزقا لان الرزق هو العطاء الجاري في الحكم وليس الحرام مما حكم به، وما يفترسه الاسد رزق له بشرط غلبته عليه كما أن غنيمة المشركين رزق لنا لشرط غلبتنا عليه والمشرك يملك ما في يده أما إذا غلبناه عليه بطل ملكه له وصار رزقا لنا، ولا يكون الرزق إلا حلالا فأما قولهم رزق حلال فهو توكيد كما يقال بلاغة حسنة ولا تكون البلاغة إلا حسنة."},{"id":"furuq-lughawiyya:342","bookId":"furuq-lughawiyya","type":"section","seq":342,"chapter":"* (أ) *","title":"1000 - الفرق بين الرزق والغذاء: أن الرزق إسم لما يملك صاحبه الانتفاع به فلا يجوز منازعته فيه لكونه حلالا له، ويجوز أن يكون ما يغتذيه الانسان","page":"ج1 ص254","text":"بإنفاقهم في قوله تعالى \" ومما رزقناهم ينفقون \" (1) ."},{"id":"furuq-lughawiyya:343","bookId":"furuq-lughawiyya","type":"section","seq":343,"chapter":"* (أ) *","title":"1005 - الفرق بين الرسوخ والثبات: أن الرسوخ كمال الثبات والشاهد أنه يقال للشئ المستقر على الارض ثابت وإن لم يتعلق بها تعلقا شديدا، ولا يقال ر","page":"ج1 ص255","text":"الثبات مع العظم والثقل والعلو فإن استعمل في غير ذلك فعلى التشبيه والمقاربة نحو قولهم ارست العود في الارض."},{"id":"furuq-lughawiyya:344","bookId":"furuq-lughawiyya","type":"section","seq":344,"chapter":"* (أ) *","title":"1008 - الفرق بين الرشد والرشد: قال أبو عمرو بن العلاء: الرشد الصلاح قال الله تعالى \" فإن آنستم منهم رشدا فادفعوا إليهم أموالهم \" (1) والرشد","page":"ج1 ص255","text":"وقيل هما لغتان مثل العدم والعدم."},{"id":"furuq-lughawiyya:345","bookId":"furuq-lughawiyya","type":"section","seq":345,"chapter":"* (أ) *","title":"1012 - الفرق بين الرضا والتسليم (3) : التسليم: هو الانقياد لاوامر الله تعالى","page":"ج1 ص256","text":"وأحكامه، والاذعان لما يصدر من الحكمة (1) الالهية، وما يصيبه من الحوادث والنوائب (2) ظاهرا وباطنا وقبول كل (3) ذلك من غير إنكار بالقلب واللسان، وهو مرتبة فوق الرضا، لان الراضي قد يرى لنفسه وجودا وإرادة، إلا أنه يرضى بما صدر من جنابه سبحانه، وبما نطقت به الشريعة الغراء - وإن خالف طبعه - والمسلم برئ من ذلك، وإنما نظره إلى ما يصدر من الحكم ويرد من جانب الشرع، فإن التسليم لذلك أصل من الاصول، وإن كان لا يظهر وجه حكمته للناس، فإن لله تعالى أسرارا ومصالح يخفى بعضها، ولا يعلمها إلا الله وأنبياؤه وحججه (4) .\n(اللغات) ."},{"id":"furuq-lughawiyya:346","bookId":"furuq-lughawiyya","type":"section","seq":346,"chapter":"* (أ) *","title":"1013 - الفرق بين الرضا والرضوان (5) : هما بمعنى في اللغة.","page":"ج1 ص256","text":"وقيل: الرضوان: الكثير من الرضا، ولذلك خص في التنزيل بما كان من الله من حيث إن رضاه إعظم الرضا.\nقال تعالى: \" ورضوان من الله أكبر \" (6) .\n(اللغات) ."},{"id":"furuq-lughawiyya:347","bookId":"furuq-lughawiyya","type":"section","seq":347,"chapter":"* (أ) *","title":"1014 - الفرق بين الرضا والمحبة (7) : قيل: هما نظيران، وإنما يظهر الفرق بضديهما، فالمحبة ضدها البغض، والرضا: ضده السخط.","page":"ج1 ص257","text":"قيل: وهو يرجع إلى الارادة.\nفإذا قيل (رضي عنه) ، فكأنه أراد تعظيمه وثوابه.\nوإذا قيل (رضي عليه) فكأنه أراد ذلك.\nوالسخط إرادة الانتقام.\n(اللغات) ."},{"id":"furuq-lughawiyya:348","bookId":"furuq-lughawiyya","type":"section","seq":348,"chapter":"* (أ) *","title":"1017 - الفرق بين الرفعة والعلو (1) : هما بمعنى في اللغة، وهو الفوقية.","page":"ج1 ص257","text":"وقد يخصص العلو في حقه - سبحانه - بعلوه على الخلق بالقدرة عليهم.\nوالرفعة بارتفاعه عن الاشياء، والاتصاف بصفاتها (2) وبالعكس.\nوقال الطبرسي: الفرق بينهما أن العلو قد يكون بمعنى الاقتدار وبمعنى العلو في المكان، والرفيع من رفع المكان لا غير.\nولذلك لا يوصف الله - سبحانه - بأنه رفيع.\nوأما \" رفيع الدرجات \" (3) فإنه وصف الدرجات بالرفعة (4) .\nانتهى.\nوفيه نظر (5) .\nفإن الرفيع من جملة أسماء الله سبحانه، ذكره الصدوق في التوحيد، وغيره في غيره.\nفمنعه من وصفه - سبحانه - بالرفيع ممنوع! (اللغات) ."},{"id":"furuq-lughawiyya:349","bookId":"furuq-lughawiyya","type":"section","seq":349,"chapter":"* (أ) *","title":"1019 - الفرق بين الرفق واللطف: أن الرفق هو اليسر في الامور والسهولة في التوصل إليها وخلافه العنف وهو التشديد في التوصل إلى المطلوب، وأصل الر","page":"ج1 ص258","text":"ورفيق الرجل في السفر يسمى بذلك لانتفاعه بصحبته وليس هو على معنى الرفق واللطف ويجوز أن يقال سمي رفيقا لانه يرافقه في السير أي\nيسير إلى جانبه فيلي مرفقه."},{"id":"furuq-lughawiyya:350","bookId":"furuq-lughawiyya","type":"section","seq":350,"chapter":"* (أ) *","title":"1024 - الفرق بين الرقي والصعود: أن الرقي أعم من الصعود ألا ترى انه يقال رقى","page":"ج1 ص259","text":"في الدرجة والسلم كما يقال صعد فيهما ويقال رقيت في العلم والشرف إلى أبعد غاية ورقي في الفضل ولا يقال في ذلك صعد والصعود على ما ذكرنا (1) مقصور على المكان، والرقي يستعمل فيه وفي غيره فهو أعم وهو أيضا يفيد التدرج في المعنى شيئا بعد شئ، ولهذ سمي الدرج مراقي وتقول مازلت اراقيه حتى بلغت به الغاية أي أعلو به شيئا شيئا."},{"id":"furuq-lughawiyya:351","bookId":"furuq-lughawiyya","type":"section","seq":351,"chapter":"* (أ) *","title":"1026 - الفرق بين الرقيب والمهيمن: أن الرقيب هو الذي يرقبك مفتشا عن","page":"ج1 ص259","text":"امورك على ما ذكرنا (2) وهو من صفات الله تعالى بمعنى الحفيظ وبمعنى العالم لان الصفة بالتفتيش لا تجوز عليه تعالى.\nوالمهيمن هو القائم على الشئ بالتدبير ومنه قول الشاعر: ألا إن خير الناس بعد نبيهم * مهيمنه التأليه في العرف والنكر يريد القائم على الناس بعده، وقال الاصمعي: \" ومهيمنا عليه \" (3) أي قفانا والقفان فارسي معرب وقال عمر رضي الله عنه: إني لاستعين بالرجل فيه عيب ثم أكون على قفانه أي على تحفظ أخباره والقفان بمعنى المشرف."},{"id":"furuq-lughawiyya:352","bookId":"furuq-lughawiyya","type":"section","seq":352,"chapter":"* (أ) *","title":"الفرق بين الرهبة والخوف","page":"ج1 ص260","text":"أن الرهبة طول الخوف وإستمراره ومن ثم قيل للراهب راهب لانه يديم الخوف، والخوف أصله من قولهم جمل رهب إذا كان طويل العظام مشبوح الخلق والرهابة العظم الذي على رأس المعدة يرجع إلى هذا، وقال علي بن عيسى: الرهبة خوف يقع على شريطة لا مخافة والشاهد أن نقيضها الرغبة وهي السلامة من المخاوف مع حصول فائدة والخوف مع الشك بوقوع الضرر والرهبة مع العلم به يقع على شريطة كذا وإن لم تكن تلك الشريطة لم تقع."},{"id":"furuq-lughawiyya:353","bookId":"furuq-lughawiyya","type":"section","seq":353,"chapter":"* (أ) *","title":"1032 - الفرق بين الرهبة والخوف (1) : هما مترادفان في اللغة، وفرق بعض العارفين بينهما فقال: الخوف: هو توقع الوعيد، وهو سوط الله يقوم به الشار","page":"ج1 ص261","text":"وأما الرهبة (3) فهي انصباب إلى وجهة الهرب، رهب وهرب مثل جبذ وجذب، فصاحبها يهرب أبدا لتوقع العقوبة، ومن علاماتها: حركة القلب إلى الانقباض من داخل، وهربه وإزعاجه عن انبساطه حتى إنه يكاد أن يبلغ الرهابة في الباطن مع ظهور الكمد والكآبة على الظاهر.\n(اللغات) ."},{"id":"furuq-lughawiyya:354","bookId":"furuq-lughawiyya","type":"section","seq":354,"chapter":"* (أ) *","title":"1033 - الفرق بين الروم والطلب: أن الروم على ما قال علي بن عيسى: طلب الشئ إبتداء، ولا يقال رمت إلا لما تجده قبل ويقال طلبت في الامرين","page":"ج1 ص261","text":"ولهذا لا يقال رمت الطعام والماء وقيل لا يستعمل الروم في الحيوان أصلا لا يقال رمت زيدا ولا رمت فرسا وإنما يقال رمت أن يفعل زيد كذا فيرجع الروم إلى فعله وهو الروم والمرام."},{"id":"furuq-lughawiyya:355","bookId":"furuq-lughawiyya","type":"section","seq":355,"chapter":"* (أ) *","title":"1035 - الفرق بين الروية والبديهة: أن الروية فيما قال بعضهم آخر النظر، والبديهة أوله، ولهذا يقال للرجل إذا وصف بسرعة الاصابة في الرأي بديهته","page":"ج1 ص262","text":"كروية غيره، وقال بعضهم الروية طول التفكر في الشئ وهو خلاف البديهة، وبديهة القول ما يكون من غير فكر، والروية إشباع الرأي والاستقصاء في تأمله تقول روأت في الامر بالتشديد وفعلت بالتشديد للتكثير والمبالغة، وتركت همزة الروية لكثرة الاستعمال."},{"id":"furuq-lughawiyya:356","bookId":"furuq-lughawiyya","type":"section","seq":356,"chapter":"* (أ) *","title":"1036 - الفرق بين الرؤية والعلم: أن الرؤية لا تكون الا لموجود، والعلم يتناول الموجود والمعدوم، وكل رؤية لم يعرض معها آفة فالمرئي بها معلوم ضر","page":"ج1 ص262","text":"والرؤية في اللغة على ثلاثة أوجه أحدها العلم وهو قوله تعالى \" ونراه قريبا \" (1) أي نعلمه يوم القيامة وذلك أن كل آت قريب، والآخر بمعنى الظن وهو قوله تعالى \" إنهم يرونه بعيدا \" (2) أي يظنونه، ولا يكون ذلك بمعنى العلم لانه لا يجوز أن يكونوا عالمين بأنها بعيدة وهي قريبة في علم الله، واستعمال\nالرؤية في هذين الوجهين مجاز، والثالث رؤية العين وهي حقيقة."},{"id":"furuq-lughawiyya:357","bookId":"furuq-lughawiyya","type":"section","seq":357,"chapter":"* (أ) *","title":"1039 - الفرق بين الريبة والتهمة: فان الريبة هي الخصلة من المكروه تظن بالانسان فيشك معها في صلاحه، والتهمة الخصلة من المكروه تظن بالانسان أو","page":"ج1 ص263","text":"أن تسمعه فيه فالمتهم هو المقول فيه التهمة والمظنون به ذلك، والمريب المظنون به ذلك فقط، وكل مريب متهم ويجو"},{"id":"furuq-lughawiyya:358","bookId":"furuq-lughawiyya","type":"section","seq":358,"chapter":"* (أ) *","title":"ز","page":"ج1 ص263","text":"أن يكون متهم ليس بمريب."},{"id":"furuq-lughawiyya:359","bookId":"furuq-lughawiyya","type":"section","seq":359,"chapter":"* (أ) *","title":"1040 - الفرق بين الريب والشك (1) : الشك: هو تردد الذهن بين أمرين على حد سواء.","page":"ج1 ص263","text":"وأما الريب فهو شك مع تهمة.\nودل عليه قوله تعالى: \" ذلك الكتاب لا ريب فيه \" (2) .\nوقوله تعالى: \" وإن كنتم في ريب مما نزلنا على عبدنا \" (3) .\nفإن المشركين - مع شكهم في القرآن - كانوا يتهمون النبي بأنه هو الذي افتراه وأعانه عليه قوم آخرون! ويقرب منه (المرية) (4) وهو [17 / ب] بمعناه.\nوأما قوله تعالى: \" إن كنتم في شك من ديني \" (5) فيمكن أن يكون الخطاب مع أهل الكتاب أو غيرهم ممن كان يعرف النبي صلى الله عليه وآله بالصدق والامانة ولا ينسبه إلى الكذب والخيانة.\n(اللغات) ."},{"id":"furuq-lughawiyya:360","bookId":"furuq-lughawiyya","type":"section","seq":360,"chapter":"* (أ) *","title":"1046 - الفرق بين الزرع والشجر والنبات (1) : الزرع: ما ينبت على غير ساق، والشجر ما له ساق وأغصان، يبقى صيفا وشتاء، والنبات يعم الجميع، لانه م","page":"ج1 ص265","text":"(اللغات) ."},{"id":"furuq-lughawiyya:361","bookId":"furuq-lughawiyya","type":"section","seq":361,"chapter":"* (أ) *","title":"1049 - الفرق بين الزكام والنزلة (3) : قد فرق بينهما بأن السيلان المنحدر من الرأس إن نزل من المنخرين سمي زكاما، وإن انصب إلى الصدر والرئة سمي","page":"ج1 ص265","text":"(اللغات) ."},{"id":"furuq-lughawiyya:362","bookId":"furuq-lughawiyya","type":"section","seq":362,"chapter":"* (أ) *","title":"1050 - الفرق بين الزكاة والصدقة (4) : الفرق بينهما أن الزكاة لا تكون إلا","page":"ج1 ص266","text":"فرضا، والصدقة قد تكون [18 / أ] فرضا، وقد تكون نفلا.\nوقوله تعالى: \" إن تبدوا الصدقات فنعما هى \" (1) يحتملهما.\n(اللغات) ."},{"id":"furuq-lughawiyya:363","bookId":"furuq-lughawiyya","type":"section","seq":363,"chapter":"* (أ) *","title":"1056 - الفرق بين الزمان والمدة: أن إسم الزمان يقع على كل جمع من الاوقات وكذلك المدة إلا أن أقصر المدة أطول من أقصر الزمان ولهذا كان معنى قول","page":"ج1 ص267","text":"فاستثقلوا أن يقولوا آخر الازمنة والازمان فاكتفوا بزمان."},{"id":"furuq-lughawiyya:364","bookId":"furuq-lughawiyya","type":"section","seq":364,"chapter":"* (أ) *","title":"1057 - الفرق بين الزمان والوقت: أن الزمان أوقات متوالية مختلفة أو غير مختلفة","page":"ج1 ص267","text":"فالوقت واحد وهو المقدر بالحركة الواحدة من حركات الفلك وهو يجري من الزمان مجرى الجزء من الجسم والشاهد أيضا أنه يقال زمان قصير وزمان طويل ولا يقال وقت قصير."},{"id":"furuq-lughawiyya:365","bookId":"furuq-lughawiyya","type":"section","seq":365,"chapter":"* (أ) *","title":"1059 - الفرق بين الزنا ووطئ الحرام (1) : الزنا: هو وطئ المرأة في الفرج من غير عقد شرعي، ولا شبهة عقد، مع العلم بذلك، أو غلبة الظن.","page":"ج1 ص267","text":"وليس كل وطئ حرام زنا، لان الوطئ في الحيض والنفاس حرام وليس بزنا.\n(اللغات) ."},{"id":"furuq-lughawiyya:366","bookId":"furuq-lughawiyya","type":"section","seq":366,"chapter":"* (أ) *","title":"1067 - الفرق بين الزيغ والميل: أن الزيغ مطلقا لا يكون إلا الميل عن الحق يقال","page":"ج1 ص268","text":"فلان من أهل الزيغ ويقال أيضا زاغ عن الحق ولا أعرف زاغ عن الباطل لان الزيغ إ"},{"id":"furuq-lughawiyya:367","bookId":"furuq-lughawiyya","type":"section","seq":367,"chapter":"* (أ) *","title":"س","page":"ج1 ص268","text":"م لميل مكروه ولهذا قال أهل اللغة الفرغ زيغ في الرسغ، والميل عام في المحبوب والمكروه."},{"id":"furuq-lughawiyya:368","bookId":"furuq-lughawiyya","type":"section","seq":368,"chapter":"* (أ) *","title":"1071 - الفرق بين الصفة بسامع والصفة بعالم: أنه يصح عالم بالمسموع بعد نقضه","page":"ج1 ص269","text":"ولا يصح سامع له بعد نقضه."},{"id":"furuq-lughawiyya:369","bookId":"furuq-lughawiyya","type":"section","seq":369,"chapter":"* (أ) *","title":"1081 - الفرق بين الستر والغطاء: أن الستر ما يسترك عن غيرك وإن لم يكن","page":"ج1 ص271","text":"ملاصقا لك مثل الحائط والجبل، والغطاء لا يكون إلا ملاصقا ألا ترى انك تقول تسترت بالحيطان ولا تقول تغطيت بالحيطان وإنما تغطيت بالثياب لانها ملاصقة لك، والغشاء أيضا لا يكون إلا ملاصقا."},{"id":"furuq-lughawiyya:370","bookId":"furuq-lughawiyya","type":"section","seq":370,"chapter":"* (أ) *","title":"1087 - الفرق بين السحر والكهانة (2) : قال المحقق كمال الدين ميثم","page":"ج1 ص272","text":"البحراني * في شرح الحديث المروي عن مولانا أمير المؤمنين: المنجم كالكاهن، والكاهن كالساحر، والساحر كالكافر، والكافر في النار.\nاعلم أن الكاهن يتميز عن المنجم بكون ما يخبر به من الامور الكائنة إنما هو عن قوة نفسانية له.\nوظاهر أن ذلك أدعى إلى فساد أذهان الخلق وإغوائهم إلى زيادة اعتقادهم فيه على المنجم.\nوأما الساحر فيتميز عن الكاهن بأن له قوة على التأثير في أمر خارج عن بدنه آثارا خارجة عن الشريعة مؤذية للخلق، كالتفريق\nبين الزوجين ونحوه، وتلك زيادة شر آخر على الكاهن أدعى إلى فساد أذهان الناس وزيادة اعتقادهم [18 / ب] فيه، وانفعالهم (1) عنه خوفا ورغبة.\nوأما الكافر فيتميز عن الساحر بالعبد الاكبر عن الله تعالى وعن دينه، وإن شاركه في أصل الانحراف عن سبيل الله.\nوحينئذ صار الضلال والفساد في الارض مشتركا بين الاربعة، إلا أنه مقول عليهم بالاشد والاضعف.\nفالكاهن أقوى في ذلك من المنجم، والساحر أقوى من الكاهن والكافر أقوى من الساحر، ولذلك التفاوت جعل الكاهن أصلا في التشبيه للمنجم لزيادة فساده عليه، ثم ألحق به.\nوجعل الساحر أصلا للكاهن والكافر أصلا للساحر، لان التشبيه يستدعي كون المشبه به أقوى في الاصل الذي فيه التشبيه، وأحق به.\nوقد لاح من ذلك أن وجه التشبيه في الكل ما يشتركون فيه من العدول والانحراف من طريق الله بالتنجيم، والكهانة، والسحر وما يلزم من ذلك من صد كثير من الخلق عن سبيل الله، وإن اختلفت (1) جهات هذا العدول بالشدة والضعف كما بيناه.\nانتهى.\nوهو تحقيق أنيق، وبه يظهر الفرق بين هؤلاء الاربعة المتناسبة (2) : المنجم، والكاهن، والساحر، والكافر.\n(اللغات) ."},{"id":"furuq-lughawiyya:371","bookId":"furuq-lughawiyya","type":"section","seq":371,"chapter":"* (أ) *","title":"الفرق بين السخاء والجود","page":"ج1 ص273","text":"أن السخاء هو أن يلين الانسان عند السؤال ويسهل مهره للطالب من قولهم سخوت النار أسخوها سخوا إذا الينتها وسخوت الاديم لينته وأرض سخاوية لينة ولهذا لا يقال لله تعالى سخي، والجود كثرة العطاء من غير سؤال من قولك جادت السماء إذا جادت بمطر عزيز، والفرس الجواد الكثير الاعطاء للجري والله تعالى جواد لكثرة عطائه فيما تقتضيه الحكمة، فإن قيل فلم لا يجوز على الله تعالى الصفة بسخي وجاز عليه الصفة بكبير وأصل الكبير كبر الجثة أي كبير الشأن، والسخي مصرف من السخاوة كتصريف الحكيم من الحكمة وكل مصرف من أصله فمعناه فيه، وأما المنقول فليس كذلك لانه بمنزلة الاسم العلم في أنه لا يكون فيه معنى ما نقل عنه وإنما يوافقه في اللفظ فقط، ويجوز أن يكون أصل الجواد إعطاء الخير ومنه فرس جواد وشئ جيد كأنه يعطي الخير لظهوره فيه وأجاد في أمره إذا أحكمه لاعطاء الخير الذي ظهر فيه."},{"id":"furuq-lughawiyya:372","bookId":"furuq-lughawiyya","type":"section","seq":372,"chapter":"* (أ) *","title":"1089- الفرق بين السخاء والجود","page":"ج1 ص273","text":"الفرق بين السخاء والجود (3) : يظهر من كلام بعضهم: الترادف.\nوفرق بعضهم بينهما: بأن من أعطى البعض وأبقى لنفسه البعض فهو صاحب سخاء.\nومن بذل الاكثر وأبقى لنفسه شيئا، فهو صاحب جود.\n(اللغات) ."},{"id":"furuq-lughawiyya:373","bookId":"furuq-lughawiyya","type":"section","seq":373,"chapter":"* (أ) *","title":"1091 - الفرق بين السخرية واللعب (1) : قيل: الفرق بينهما أن في السخرية خديعة واستنقاصا لمن يسخر به، ولا يكون إلا بذي حياة.","page":"ج1 ص274","text":"وأما اللعب فقد يكون بجماد، ولذلك أسند - سبحانه - السخرية إلى الكفار بالنسبة إلى الانبياء كقوله سبحانه: \" وكلما مر عليه ملا من قومه سخروا منه \" (2) .\n(اللغات) ."},{"id":"furuq-lughawiyya:374","bookId":"furuq-lughawiyya","type":"section","seq":374,"chapter":"* (أ) *","title":"1092 - الفرق بين السخرية والهزء (3) : قد يفرق بينهما بأن في السخرية معنى طلب الذلة كما مر، لان التسخير في الاصل التذليل.","page":"ج1 ص274","text":"وأما الهزء: فيقتضي (4) طلب صغر القدر بما يظهر في القول.\n(اللغات) ."},{"id":"furuq-lughawiyya:375","bookId":"furuq-lughawiyya","type":"section","seq":375,"chapter":"* (أ) *","title":"الفرق بين السرعة والعجلة","page":"ج1 ص275","text":"(1) : العجلة: التقدم بالشئ قبل وقته - وهو مذموم - والسرعة: تقديم الشئ في أقرب أوقاته - وهو محمود - ويشهد للاول قوله تعالى: \" ولا تعجل بالقران من قبل أن يقضى إليك\nوحيه \" (2) .\nوقوله تعالى: \" أتى أمر الله فلا تستعجلوه \" (3) .\nوللثاني في قوله تعالى: \" وسارعوا إلى مغفرة من ربكم \" (4) .\n(اللغات) ."},{"id":"furuq-lughawiyya:376","bookId":"furuq-lughawiyya","type":"section","seq":376,"chapter":"* (أ) *","title":"1097- الفرق بين السرعة والعجلة","page":"ج1 ص275","text":"الفرق بين السرعة والعجلة: أن السرعة التقدم فيما ينبغي أن يتقدم فيه وهي محمودة ونقيضها مذمون وهو الابطاء، والعجلة التقدم فيما لا ينبغي أن يتقدم فيه وهي مذمومة، ونقيضها محمود وهو الاناة، فأما قوله تعالى \" وعجلت إليك رب لترضى \" (5) فإن ذلك بمعنى أسرعت."},{"id":"furuq-lughawiyya:377","bookId":"furuq-lughawiyya","type":"section","seq":377,"chapter":"* (أ) *","title":"1104 - الفرق بين السرور والفرح: أن السرور لا يكون إلا بما هو نفع أو لذة على","page":"ج1 ص276","text":"الحقيقة، وقد يكون الفرح بما ليس بنفع ولا لذة كفرح الصبي بالرقص والعدو والسباحة وغير ذلك مما يتعبه ويؤذيه ولا يسمى ذلك سرورا ألا ترى أنك تقول الصبيان يفرحون بالسباحة والرقص ولا تقول يسرون بذلك، ونقيض السرور الحزن ومعلوم أن الحزن يكون بالمرازي فينبغي أن يكون السرور بالفوائد وما يجري مجراها من الملاذ، ونقيض الفرح الغم وقد يغتم الانسان بضرر يتوهمه من غير أن يكون له حقيقة وكذلك يفرح بما لا حقيقة له كفرح الحالم بالمنى وغيره، ولا يجوز أن يحزن ويسر بما لا حقيقة له، وصيغة الفرح والسرور في العربية تنبئ عما قلناه فيهما وهو أن الفرح فعل مصدر فعل فعلا وفعل المطاوعة والانفعال فكأنه شئ يحدث في النفس من غير سبب يوجبه، والسرور إسم وضع موضع المصدر في قولك سر سرورا وأصله سرا وهو فعل يتعدى ويقتضي فاعلا فهو مخالف للفرح من كل وجه، ويقال فرح إذا جعلته كالنسبة وفارح إذا بنيته على الفعل، وقال الفراء: الفرح الذي يفرح في وقته والفارح الذي\nيفرح فيما يستقبل مثل طمع وطامع."},{"id":"furuq-lughawiyya:378","bookId":"furuq-lughawiyya","type":"section","seq":378,"chapter":"* (أ) *","title":"1105 - الفرق بين السعير والجحيم والحريق والنار: أن السعير هو النار الملتهبة الحراقة أعني أنها تسمى حريقا في حال إحراقها للاحراق يقال في العو","page":"ج1 ص277","text":"جحمة لشدة توقدها.\nوأما جهنم فيفيد بعد القعر من قولك جهنام إذا كانت بعيدة القعر."},{"id":"furuq-lughawiyya:379","bookId":"furuq-lughawiyya","type":"section","seq":379,"chapter":"* (أ) *","title":"1108 - الفرق بين السفه والطيش: أن السفه نقيض الحكمة على ما وصفنا ويستعار في الكلام القبيح فيقال سفه عليه إذا أسمعه القبيح ويقال للجاهل سفيه،","page":"ج1 ص277","text":"السهم إذا خف فمضى فوق الهدف فشبه به الخفيف المفارق لصواب الفعل."},{"id":"furuq-lughawiyya:380","bookId":"furuq-lughawiyya","type":"section","seq":380,"chapter":"* (أ) *","title":"1110 - الفرق بين السقي والاسقاء (1) : قيل: السقي لما لا كلفة فيه.","page":"ج1 ص278","text":"ولهذا ذكر في شراب أهل الجنة.\nقال سبحانه: \" وسقاهم ربهم شرابا طهورا \" (2) .\nوأما قوله تعالى في وصف أهل النار: \" وسقوا ماء حميما \" (3) .\nفمجاز أو للتهكم (4) .\nوالاستسقاء: لما فيه كلفة، ولهذا ذكر في ماء الدنيا نحو:\n\" لاسقيناهم ماء غدقا \" (5) .\n(اللغات) ."},{"id":"furuq-lughawiyya:381","bookId":"furuq-lughawiyya","type":"section","seq":381,"chapter":"* (أ) *","title":"1111 - الفرق بين السكب والسفوح والصب والهطل والهمول: أن السكب هو الصب المتتابع، ولهذا يقال فرس سكب إذا كان يتابع الحري ولا يقطعه ومنه قوله ت","page":"ج1 ص279","text":"سهولة ومنه يقال همر في كلامه إذا أكثر منه ورجل مهمار كثير الكلام وظبية همير بسيطة الجسم، والهطل دوام السيلان في سكون كذا حكى السكري وقال: الهطلان مطر إلى اللين ما هو، وأما السح فهو عموم الانصباب ومنه يقال شاة ساح كأن جسمها أجمع يصب ودكا أي شحما."},{"id":"furuq-lughawiyya:382","bookId":"furuq-lughawiyya","type":"section","seq":382,"chapter":"* (أ) *","title":"1117 - الفرق يبن السكينة والوقار (4) : المشهور في الفرق بينهما أن السكينة: هيئة بدنية تنشأ من اطمئنان الاعظاء.","page":"ج1 ص280","text":"والوقار: هيئة نفسانية تنشأ من ثبات القلب، ذكر ذلك صاحب التنقيح.\nونقله صاحب مجمع البحرين عن بعض المحققين.\nولا يخفى أنه لو عكس الفرق، لكان أصوب وأحق بأن تكون السكينة هيئة نفسانية، والوقار: هيئة بدنية.\nأما الأول فلقوله تعالى: \" هو الذي أنزل السكينة في قلوب المؤمنين \" (1) .\nحيث جعل القلوب ظرفا للسكينة، ومحطا لها (2) ، وهو عبارة [19 / أ] عما فعل بهم اللطف (3) الذي يحصل لهم عنده من البصيرة بالحق ما تسكن إليه نفوسهم، ويثبتوا في القتال.\nوأما الثاني فلقوله عزوجل مخاطبا لازواج النبي صلى الله عليه وآله: \" وقرن في بيوتكن \" (4) .\nعلى أنه أمر من الوقار، فإن سكونهن في\nالبيوت، وعدم خروجهن وتبرجهن هيئة بنبتة تنشأ من اطمئنان الاعضاء وثباتها.\n(اللغات) ."},{"id":"furuq-lughawiyya:383","bookId":"furuq-lughawiyya","type":"section","seq":383,"chapter":"* (أ) *","title":"الفرق بين السلامة والصحة","page":"ج1 ص280","text":"أن السلامة نقيضة الهلاك ونقيض الصحة الآفة من المرض والكسر وما بسبيل ذلك ألا ترى انه يقال سلم الرجل من علته إذا كان يخاف عليه الهلاك منها أو على شئ من جسده، وإذا لم يكن يخاف عليه ذلك منها لم يقل سلم منها وقيل صح منها، هذا على أن السلامة نقيضة الهلاك وليست الصحة كذلك وفي هذا وقوع الفرق بينهما، ثم كثر استعمال السلامة حتى قيل للمتبرئ من العيب سالم من\nالعيب، والسلامة عند المتكلمين زوال الموانع والآفات عن من يجوز عليه ذلك ولا يقال لله سالم لان الآفات غير جائزة عليه ولا يقال له صحيح لان الصحة تقتضي منافاة المرض والكسر ولا يجوزان على الله تعالى."},{"id":"furuq-lughawiyya:384","bookId":"furuq-lughawiyya","type":"section","seq":384,"chapter":"* (أ) *","title":"1120 - الفرق بين السلامة والصحة (1) : قيل: الصحة البرء من المرض، والبراءة من كل عيب.","page":"ج1 ص281","text":"والسلامة: الخلوص من الآفات.\n(اللغات) ."},{"id":"furuq-lughawiyya:385","bookId":"furuq-lughawiyya","type":"section","seq":385,"chapter":"* (أ) *","title":"1124 - الفرق بين السماء والفلك (1) : قال ابن قتيبة: السماء كل ما علاك، فأظلك، ومنه لسقف البيت \" سماء \" وللسحاب \" سماء \".","page":"ج1 ص282","text":"قال عزوجل: \" ونزلنا من السماء ماء مباركا \" (2) .\nيريد السحاب.\nوالفلك: مدار النجوم الذي يضمها.\nقال عزوجل: \" كل في فلك يسبحون \" (3) .\nسماه تعالى فلكا لاستدارته.\nومنه قيل: فلك المغزل.\nوالفلك قطبان: قطب في الشمال وقطب في الجنوب، متقابلان.\nانتهى.\n(اللغات) ."},{"id":"furuq-lughawiyya:386","bookId":"furuq-lughawiyya","type":"section","seq":386,"chapter":"* (أ) *","title":"1125 - الفرق بين السماجة والقبح: أن السماجة فعل العيب والشاهد قول الهذلي: فمنهم صالح وسمج، وجعل السماجة نقيض الصلاح، والصلاح","page":"ج1 ص282","text":"فعل فكذلك ينبغي أن تكون السماجة فلو كانت السماجة قبح الوجه لم يحسن أن يقول ذلك ألا ترى أنه لا يحسن أن تقول فمنهم صالح وقبيح الوجه، وقال إبن دريد: ربما قيل لمن جاء بعيب سمجا، ثم اتسع في السماجة فاستعمل مكان قبح الصورة فقيل وجه سميج وسمج كما قيل قبيح كأنه جاء بعيب لان القبيح عيب."},{"id":"furuq-lughawiyya:387","bookId":"furuq-lughawiyya","type":"section","seq":387,"chapter":"* (أ) *","title":"1127 - الفرق بين السمة والعلامة: أن السمة ضرب من العلامات مخصوص وهو","page":"ج1 ص283","text":"ما يكون بالنار في جسد حيوان مثل سمات الابل وما يجري مجراها وفي القرآن \" سنسمه على الخرطوم \" (1) وأصلها التأثير في الشئ ومنه الوسمي (2) لانه يؤثر في الارض أثرا، ومنه الموسم لما فيه من آثار أهله والوسمة (3) معروفة سميت بذلك لتأثيرها فيما يخضب بها."},{"id":"furuq-lughawiyya:388","bookId":"furuq-lughawiyya","type":"section","seq":388,"chapter":"* (أ) *","title":"1130 - الفرق بين السمع والاصغاء: أن السمع هو إدراك المسموع والسمع أيضا إسم الآلة التي يسمع بها، والاصغاء هو طلب إدراك المسموع بإمالة","page":"ج1 ص283","text":"السمع إليه يقال صغا يصغو إذا مال وأصغى غيره وفي القرآن \" فقد صغت قلوبكما \" (4) أي مالت، وصغوك مع فلان أي ميلك."},{"id":"furuq-lughawiyya:389","bookId":"furuq-lughawiyya","type":"section","seq":389,"chapter":"* (أ) *","title":"1131 - الفرق بين السميع والسامع (5) : قيل: السميع من كان على صفة يجب لاجلها أن يدرك المسموعات إذا وجدت، فهي ترجع إلى كونه حيا لا آفة به.","page":"ج1 ص283","text":"والسامع: المدرك ويوصف القديم - سبحانه - في الارض بأنه سميع ولا يوصف في الازل بأنه سامع وإنما يوصف به إذا وجدت المسموعات.\n(اللغات) ."},{"id":"furuq-lughawiyya:390","bookId":"furuq-lughawiyya","type":"section","seq":390,"chapter":"* (أ) *","title":"1132 - الفرق بين السن والضرس (1) : يظهر من كلام اللغويين أنهما مترادفان - ويظهر من إطلاقات الاخبار الاخبار وغيرها اختصاص السن بالمقاديم الحد","page":"ج1 ص284","text":"ففي كتاب (العلل والخصال) عن الصادق عليه السلام في احتجاجه على الطبيب الهندي قال: وجعل السن حادا (2) *، لان به يقع الفرض، وجعل الضرس عريضا (3) * لان به يقع الطحن والمضغ، وكان الناب طويلا، ليشد الاضراس والاسنان كالاسطوانة في البناء.\n(اللغات) ."},{"id":"furuq-lughawiyya:391","bookId":"furuq-lughawiyya","type":"section","seq":391,"chapter":"* (أ) *","title":"الفرق بين السؤال والطلب","page":"ج1 ص285","text":"أن السؤال لا يكون إلا كلاما ويكون الطلب السعي وغيره، وفي مثل: عليك الهرب وعلي الطلب."},{"id":"furuq-lughawiyya:392","bookId":"furuq-lughawiyya","type":"section","seq":392,"chapter":"* (أ) *","title":"1146 - الفرق بين السؤال والطلب (1) : قد فرق بينهما بأن السؤال يكون بالفعل والقول.","page":"ج1 ص286","text":"والسؤال يستدعي جوابا إما باللسان أو باليد.\nوالطلب: قد يفتقر إلى جواب، وقد لا، وكل سؤال طلب، وليس كل طلب سؤالا.\n(اللغات) ."},{"id":"furuq-lughawiyya:393","bookId":"furuq-lughawiyya","type":"section","seq":393,"chapter":"* (أ) *","title":"1159 - الفرق بين سيد القوم وكبيرهم: أن سيدهم هو الذي يلي تدبيرهم، وكبيرهم هو الذي يفضلهم في العلم أو السن أو الشرف وقد قال تعالى \" فعله كبير","page":"ج1 ص289","text":"تعالى بمعنى أنه كبير في أنفس العارفين غير أن يكون له نظير."},{"id":"furuq-lughawiyya:394","bookId":"furuq-lughawiyya","type":"section","seq":394,"chapter":"* (أ) *","title":"1163 - الفرق بين الشأن والحال (1) : الشأن لا يقال إلا فيما يعظم من الاحوال والامور، فكل حال شأن، ولا ينعكس.","page":"ج1 ص290","text":"قاله الراغب.\nويؤيده (2) [15 / أ] قوله تعالى شأنه \" كل يوم هو في شأن \" (3) (اللغات) ."},{"id":"furuq-lughawiyya:395","bookId":"furuq-lughawiyya","type":"section","seq":395,"chapter":"* (أ) *","title":"1164 - الفرق بين الشاهد والحاضر: أن الشاهد للشئ يقتضي أنه عالم به ولهذا قيل الشهادة على الحقوق لانها لا تصح إلا مع العلم بها وذلك أن أصل الش","page":"ج1 ص290","text":"لا يتقضي العلم بالمحضور ألا ترى انه يقال حضره الموت ولا يقال شهده الموت إذ لا يصح وصف الموت بالعلم، وأما الاحضار فإنه يدل على سخط وغضب، والشاهد قوله تعالى \" ثم هو يوم القيامة من المحضرين \" (4) ."},{"id":"furuq-lughawiyya:396","bookId":"furuq-lughawiyya","type":"section","seq":396,"chapter":"* (أ) *","title":"1165 - الفرق بين الشاهد والشهيد (1) : قيل: الشاهد بمعنى الحدوث.","page":"ج1 ص291","text":"والشهيد بمعنى الثبوت.\nفإنه إذا تحمل الشهادة فهو شاهد باعتبار حدوث تحمله.\nفإذا ثبت تحمله لها زمانين أو أكثر فهو شهيد.\nثم يطلق الشاهد عليه مجازا، كما في قوله تعالى: \" واستشهدوا شهيدين من رجالكم \" (2) .\nفإن الطلب إنما يكون قبل حصول المطلوب.\n(اللغات) ."},{"id":"furuq-lughawiyya:397","bookId":"furuq-lughawiyya","type":"section","seq":397,"chapter":"* (أ) *","title":"1170 - الفرق بين الشبه والشبيه: أن الشبه أعم من الشبيه ألا تراهم يستعملون الشبه في كل شئ، وقلما يستعمل الشبية إلا في المتجانسين تقول زيد يشب","page":"ج1 ص291","text":"الذي يأتي فعله على فعل ولا يأتي ذلك في الصفات فإذا قلت زيد شبيه عمرو فقد بالغت في تشبيهه به وأجريته مجرى ما ثبت لنفسه وإضافته إليه إضافة صحيحة، وإذا قلت زيد شبه عمرو وعمرو شبه الاسد فهو على\nالانفصال أي شبه لعمرو وشبه للاسد لانه نكرة وكذلك المثل، ولهذا تدخل عليه رب وإن أضيف إلى الكاف قال الشاعر: يا رب مثلك في النساء غريزة * بيضاء قد متعتها بطلاق فأدخل رب على مثلك ولا تدخل رب إلا على النكرات، وأما الشبه فمصدر سمي به يقال الشبه بينهما ظاهر وفي فلان شبه من فلان ولا يقال فلان شبه، والشبه عند الفقهاء الصفة التي إذا اشترك فيها الاصل والفرع وجب اشتراكهما في الحكم، وعند المتكلمين ما إذا اشترك فيه إثنان كانا مثلين، وكذلك الفرق بين العدل والعديل سواء، وذلك أن العدل أعم من العديل وما كان أعم فأنه (1) أخص بالنكرة فهو للجنس وغير الجنس تقول عمرو عدل وزيد عديله وعدل الاسد ولا يقال عديله، وقال بعض النحويين مثل وغير وشبه وسوى لا تتعرف بالاضافة وإن اضيفت إلى المعرفة للزوم الاضافة لمعناها وغلبتها على لفظها وذلك أنك إذا قلت هذا المثل لم تخرجه عن أن يكون له مثل آخر ولا يكاد يستعمل إلا على الاضافة حتى ذكر بعض النحويين أنه لا يجوز الغير إنما تقول غيرك وغير زيد ونحو هذا، وشبيهك معرفة وشبهك نكرة تقول مررت برجل شبهك على الصفة ولا يجوز برجل شبيهك لان شبيها معرفة ورجل\nنكرة ولا يوصف نكرة بمعرفة ولا معرفة بنكرة، والدليل على أن شبيهك نكرة وإن أضفته إلى الكاف أنه يكون صفة لنكرة والمراد به الانفصال ولا يجوز شبه بك كما يجوز شبيه بك وذلك أن معنى شبيه بك المعروف بشبهك فأما شبهك فبمنزلة مثلك عرف بشبهه أو لم يعرف."},{"id":"furuq-lughawiyya:398","bookId":"furuq-lughawiyya","type":"section","seq":398,"chapter":"* (أ) *","title":"1172 - الفرق بين الشبه والمثل: أن الشبه يستعمل فيما يشاهد فيقال السواد شبه السواد ولا يقال القدرة كما يقال مثلها.","page":"ج1 ص293","text":"وليس في الكلام شئ يصلح في المماثلة إلا الكاف والمثل، فأما الشبه والنظير فهما من جنس المثل ولهذا قال الله تعالى \" ليس كمثله شئ \" (1) فأدخل الكاف على المثل وهما الاسمان اللذان جعلا للمماثلة فنفى بهما الشبه عن نفسه فأكد النفي بذلك."},{"id":"furuq-lughawiyya:399","bookId":"furuq-lughawiyya","type":"section","seq":399,"chapter":"* (أ) *","title":"1175 - الفرق بين الشتم والسفه: أن الشتم يكون حسنا وذلك إذا كان المشتوم يستحق الشتم، والسفه لا يكون إلا قبيحا وجاء عن السلف في تفسير قوله","page":"ج1 ص293","text":"تعالى \" صم بكم \" (2) إن الله وصفهم بذلك على وجه الشتم ولم يقل على وجه السفه لما قلناه."},{"id":"furuq-lughawiyya:400","bookId":"furuq-lughawiyya","type":"section","seq":400,"chapter":"* (أ) *","title":"الفرق بين الشح والبخل","page":"ج1 ص294","text":"أن الشح الحرص على منع الخير ويقال زند (1) شحاح إذا لم يور نارا وإن أشح عليه بالقدح كأنه حريص على منع ذلك، والبخل منع الحق فلا يقال لمن يؤدي حقوق الله تعالى بخيل."},{"id":"furuq-lughawiyya:401","bookId":"furuq-lughawiyya","type":"section","seq":401,"chapter":"* (أ) *","title":"1181- الفرق بين الشح والبخل","page":"ج1 ص294","text":"الفرق بين الشح والبخل (2) : قد يفرق بينهما بأن الشح: البخل مع حرص، فهو أشد من البخل.\nوقيل: الشح: اللؤم، وأن تكون النفس حريصة على المنع.\nوقد اضيف إلى النفس في قوله تعالى: \" وأحضرت الأنفس الشح \" (3) .\nلانه غريزة فيها.\nوفي الحديث (4) \" الشح أن ترى القليل سرفا، وما أنفقت تلفا \".\nوفيه أيضا: \" البخيل يبخل بما في يده، والشحيح يشح بما في أيدي الناس، وعلى ما في يده حتى لا يرى في أيدي الناس شيئا إلا تمن أن يكون له بالحل والحرام، ولا يقنع بما رزقه الله تعالى \".\nوفيه أيضا: \" لا يجتمع الشح والايمان في قلب عبد أبدا \".\nوتوجيهه: أن (1) الشح حالة غريزة جبل عليها الانسان فهو كالوصف اللازم له، ومركزها النفس، فإذا انتهى سلطانه إلى القلب، واستولى عليه عري القلب عن الايمان، لانه يشح بالطاعة فلا يسمح بها، ولا يبذل الانقياد لامر الله.\nقال بعض العارفين: \" الشح في نفس الانسان ليس بمذموم، لانها طبيعة خلقها الله تعالى في النفوس، كالشهوة.\nوالحرص للابتلاء ولمصلحة عمارة العالم، وإنما المذموم أن يستولي سلطانه على القلب فيطاع \".\nوقيل: \" الشح إفراط في الحرص على الشئ، ويكون بالمال وبغيره من الاغراض.\nيقال: هو شحيح بمودتك أي حريص على دوامها، ولا يقال بخيل \".\nوالبخيل: يكون بالمال خاصة.\n(اللغات) ."},{"id":"furuq-lughawiyya:402","bookId":"furuq-lughawiyya","type":"section","seq":402,"chapter":"* (أ) *","title":"1185 - الفرق بين الشخص والجسم: أن الشخص ما ارتفع من الاجسام من قولك شخص إلى كذا إذا ارتفع وشخصت بصري إلى كذا أي رفعته إليه","page":"ج1 ص295","text":"وشخص إلى بلد كذا كأنه ارتفع إليه، والاشخاص يدل على السخط والغضب مثل الاحصار."},{"id":"furuq-lughawiyya:403","bookId":"furuq-lughawiyya","type":"section","seq":403,"chapter":"* (أ) *","title":"1196 - الفرق بين الشرعة والمنهاج (3) : المنهج والمنهاج: الطريق الواضح، ثم استعير للطريق في الدين كما استعيرت الشريعة لها.","page":"ج1 ص297","text":"والشرعة بمعنى المنهاج.\nكذا ذكر بعضهم.\nوروي عن ابن عباس (رضي الله عنه) أن الشرعة: ما ورد به\nالقرآن والمنهاج: ما وردت به السنة (1) .\nويؤيده قوله تعالى: \" لكل جعلنا منكم شرعة ومنهاحا \" (2) [19 / ب] إذ العطف ظاهر، في المغايرة إيثارا للتأسيس على التأكيد.\n(اللغات) ."},{"id":"furuq-lughawiyya:404","bookId":"furuq-lughawiyya","type":"section","seq":404,"chapter":"* (أ) *","title":"1198 - الفرق بين الشرق والشجى (3) قيل: الفرق بينهما أن الشرق يكون بالريق والماء ونحوهما من كل مائع، قال الشاعر (4) : لو بغير الماء حلقي شرق","page":"ج1 ص298","text":"والغصص يعمهما.\n(اللغات) ."},{"id":"furuq-lughawiyya:405","bookId":"furuq-lughawiyya","type":"section","seq":405,"chapter":"* (أ) *","title":"1201 - الفرق بين الشريعة والدين: أن الشريعة هي الطريقة المأخوذة فيها إلى الشئ ومن ثم سمي الطريق إلى الماء شريعة ومشرعة وقيل الشارع لكثرة الا","page":"ج1 ص299","text":"ما يفيده الطريق المأخوذ ما لا تفيده الملة، ويقال شرع في الدين شريعة كما يقال طرق فيه طريقا، والملة تفيد إستمرار أهلها عليها."},{"id":"furuq-lughawiyya:406","bookId":"furuq-lughawiyya","type":"section","seq":406,"chapter":"* (أ) *","title":"1209 - الفرق بين الشكر والجزاء: أن الشكر لا يكون إلا على نعمة والنعمة","page":"ج1 ص300","text":"لا تكون الا لمنفعة أو ما يؤدي إلى منفعة كالمرض يكون نعمة لانه يؤدي إلى الانتفاع بعوض، والجزاء يكون منفعة ومضرة كالجزاء على الشر."},{"id":"furuq-lughawiyya:407","bookId":"furuq-lughawiyya","type":"section","seq":407,"chapter":"* (أ) *","title":"الفرق بين الشكر والحمد","page":"ج1 ص300","text":"والمدح: (798) ."},{"id":"furuq-lughawiyya:408","bookId":"furuq-lughawiyya","type":"section","seq":408,"chapter":"* (أ) *","title":"1211- الفرق بين الشكر والحمد","page":"ج1 ص300","text":"الفرق بين الشكر والحمد: أن الشكر هو الاعتراف بالنعمة على جهة التعظيم للمنعم، والحمد الذكر بالجميل على جهة التعظيم المذكور به أيضا ويصح على النعمة وغير النعمة، والشكر لا يصح إلا على النعمة ويجوز أن يحمد الانسان نفسه في امور جميلة يأتيها ولا يجوز أن يشكرها لان الشكر يجري مجرى قضاء الدين ولا يجوز أن يكون للانسان على نفسه دين فالاعتماد في الشكر على ما توجبه النعمة وفي الحمد على ما توجبه الحكمة.\nونقيض الحمد الذم إلا على إساءة ويقال الحمد لله على الاطلاق ولا يجوز أن يطلق إلا لله لان كل إحسان فهو منه في الفعل أو التسبيب، والشاكر هو الذاكر بحق المنعم بالنعمة على جهة التعظيم، ويجوز في صفة الله شاكر مجازا، والمراد أنه يجازي على الطاعة جزاء الشاكرين على النعمة ونظير ذلك قوله تعالى \" من ذا الذي يقرض الله قرضا حسنا \" (1) وهذا تلطف في الاستدعاء إلى النفقة في وجوه البر والمراد أن ذلك بمنزلة القرض في إيجاب الحق، وأصل الشكر إظهار الحال الجميلة فمن ذلك دابة شكور إذا ظهر فيه السمن مع قلة العلف، وأشكر الضرع إذا امتلا وأشكرت\nالسحابة إمتلات ماء، والشكير قضبان غضة تخرج رخصة بين القضبان العاسية، والشكير من الشعر والنبات صغار نبت خرج بين الكبار مشبهة بالقضبان الغضة، والشكر بضع المرأة، والشكر على هذا الاصل إظهار\nحق النعمة لقضاء حق المنعم كما أن الكفر تغطية النعمة لابطال حق المنعم فإن قيل أنت تقول الحمد لله شكرا فتجعل الشكر مصدرا للحمد فلولا إجتماعهما في المعنى لم يجتمعا في اللفظ قلنا هذا مثل قولك قتلته صبرا واتيته سعيا والقتل غير الصبر والاتيان غير السعي، وقال سيبويه: هذا باب ما ينصب من المصادر لانه حال وقع فيها الامر وذلك كقولك قتلته صبرا ومعناه أنه لما كان القتل يقع على ضروب وأحوال بين الحال التي وقع فيها القتل والحال التي وقع فيها الحمد فكأنه قال قتلته في هذه الحال، والحمد لله شكرا أبلغ من قولك الحمد لله حمدا لان ذلك للتوكيد والاول لزيادة معنى وهو أي أحمده في حال إظهار نعمه علي."},{"id":"furuq-lughawiyya:409","bookId":"furuq-lughawiyya","type":"section","seq":409,"chapter":"* (أ) *","title":"1212 - الفرق ين الشاكر والشكور (1) : قيل: الشاكر من وقع منه الشكر، والشكور: المتوفر على أداء الشكر بقلبه ولسانه وجوارحه أكثر أوقاته.","page":"ج1 ص301","text":"ومع ذلك لا يوفي حقه لان توفيقه للشكر نعمة تستدعي شكرا آخر لا إلى نهاية.\nوإليه يشير قوله تعالى: \" وقليل من عبادي الشكور \" (2) .\n(اللغات) ."},{"id":"furuq-lughawiyya:410","bookId":"furuq-lughawiyya","type":"section","seq":410,"chapter":"* (أ) *","title":"1213 - الفرق بين الشكر والمكافأة: أن الشكر على النعمة سمي شكرا عليها وإن لم يكن يوازيها في القدر كشكر العبد لنعم الله عليه ولا تكون المكافأة","page":"ج1 ص302","text":"بالشر مكافأة به حتى تكون مثله وأصل الكلمة ينبئ عن هذا المعنى وهو الكفؤ يقال هذا كفء هذا إذا كان مثله، والمكافأة أيضا تكون بالنفع والضر والشكر لا يكون إلا على النفع أو ما يؤدي إلى النفع على\nما ذكرنا (1) ، والشكر أيضا لا يكون إلا قولا والمكافأة تكون بالقول والفعل وما يجري مع ذلك."},{"id":"furuq-lughawiyya:411","bookId":"furuq-lughawiyya","type":"section","seq":411,"chapter":"* (أ) *","title":"1218 - الفرق بين الشك والظن والوهم (2) : الشك: خلاف اليقين.","page":"ج1 ص302","text":"وأصله\nاضطراب النفس، ثم استعمل في التردد بين الشيئين سواء استوى طرفاه، أو ترجح أحدهما على الآخر قال تعالى: \" فإن كنت في شك مما أنزلنا إليك \" (1) .\nأي غير مستيقن.\nوقال الاصوليون: هو تردد الذهن بين أمرين على حد سواء.\nقالوا: التردد بين الطرفين إن كان على السواء فهو الشك، وإلا فالراجح ظن: والمرجوح وهم.\n(اللغات) ."},{"id":"furuq-lughawiyya:412","bookId":"furuq-lughawiyya","type":"section","seq":412,"chapter":"* (أ) *","title":"1219 - الفرق بين الشكل والشبه (2) : قال الراغب: الشكل في الهيئة والصورة والقدر والمساحة.","page":"ج1 ص303","text":"والشبه في الكيفية، والتساوي في الكمية فقط، والمثل عام في ذلك كله.\nوقوله تعالى: \" واخر من شكله أزواج \" (3) .\nأي مثل له (4) في الهيئة وتعاطي الفعل.\nانتهى.\n(اللغات) ."},{"id":"furuq-lughawiyya:413","bookId":"furuq-lughawiyya","type":"section","seq":413,"chapter":"* (أ) *","title":"1220 - الفرق بين الشكل والمثل: أن الشكل هو الذي يشبه الشئ في أكثر صفاته حتى يشكل الفرق بينهما، ويجوز أن يقال ان إشتقاقه من الشكل وهو الشمال","page":"ج1 ص304","text":"ولا يقال الحلاوة شكل الحلاوة، ومثل الشئ ما يماثله وذاته."},{"id":"furuq-lughawiyya:414","bookId":"furuq-lughawiyya","type":"section","seq":414,"chapter":"* (أ) *","title":"1222 - الفرق بين الشهادة والخبر: أن شهادة الاثنين عند القاضي يوجب العمل","page":"ج1 ص304","text":"عليها ولا يجوز الانصراف عنها، ويجوز الانصراف عن خبر الاثنين والواحد إلى القياس والعمل به ويجوز العمل به أيضا والتعبد أخرج الشهادة عن حكم الخبر المحض، ويفرق بين قولك شهد عليه وشهد على إقراره فتقول إذا جرى الفصل أو الاخذ بحضرة الشاهد كتب شهد عليه، وإذا جرى ذلك رؤية ثم أقربه عنده كتب شهد على إقراره."},{"id":"furuq-lughawiyya:415","bookId":"furuq-lughawiyya","type":"section","seq":415,"chapter":"* (أ) *","title":"الفرق بين الشهوة والتمني","page":"ج1 ص304","text":"أن الشهوة لا تتعلق إلا بما يلذ من المدركات\nبالحواس، والتمني يتعلق بما يلذ وما يكره، مثل أن يتمنى الانسان أن يموت، والشهوة أيضا لا تتعلق بالماضي."},{"id":"furuq-lughawiyya:416","bookId":"furuq-lughawiyya","type":"section","seq":416,"chapter":"* (أ) *","title":"1228 - الفرق بين الشهوة والتمني (1) : قيل التمني: معنى في القلب وليس هو من قبيل الشهوة، ولا من قبيل الارادة، لان الارادة لا تتعلق إلا بما يص","page":"ج1 ص305","text":"والشهوة لا تتعلق إلا بما مضى.\nوالارادة والتمني قد يتعلقان بالماضي.\nوقيل: الفرق بين التمني والارادة: أن الارادة من أفعال القلوب، والتمني قول القائل: ليت كان كذا وليت لم يكن، ويؤيده أن أهل اللغة ذكروا التمني في أقسام الكلام.\n(اللغات) ."},{"id":"furuq-lughawiyya:417","bookId":"furuq-lughawiyya","type":"section","seq":417,"chapter":"* (أ) *","title":"ص","page":"ج1 ص306","text":"فة."},{"id":"furuq-lughawiyya:418","bookId":"furuq-lughawiyya","type":"section","seq":418,"chapter":"* (أ) *","title":"1235 - الفرق بين الشياطين والجن (2) : قيل: الشياطين جنس، والجن جنس، كما أن الانسان جنس، والفرس جنس آخر.","page":"ج1 ص306","text":"وقيل: الجن منهم أخيار ومنهم أشرار، والشياطين اسم أشرار الجن ومتمرديهم.\n(اللغات) ."},{"id":"furuq-lughawiyya:419","bookId":"furuq-lughawiyya","type":"section","seq":419,"chapter":"* (أ) *","title":"1237 - الفرق بين الصاحب والقرين: أن الصحبة تفيد إنتفاع أحد الصاحبين بالآخر ولهذا يستعمل في الآدميين خاصة فيقال صحب زيد عمرا وصحبه عمرو، ولا","page":"ج1 ص307","text":"والمقارنة تفيد قيام أحد القرينين مع الآخر ويجري على طريقته وإن لم ينفعه ومن ثم قيل قران النجوم، وقيل للبعيرين يشد أحدهما إلى الآخر بحبل قرينان فإذا قام أحدهما مع الآخر لبطش فيهما قرنان فإنما خولف بين المثالين لاختلاف المعنيين والاصل واحد."},{"id":"furuq-lughawiyya:420","bookId":"furuq-lughawiyya","type":"section","seq":420,"chapter":"* (أ) *","title":"1238 - الفرق بين الصالح والمصلح (2) : قال الطبرسي: الصالح عامل الصلاح الذي يقوم به حاله في دنياه.","page":"ج1 ص307","text":"وأما المصلح فهو فاعل الصلاح يقوم به أمر من الامور.\nقيل: ولهذا لا يوصف سبحانه بأنه مصلح، ولا يوصف بأنه صالح.\n(اللغات) ."},{"id":"furuq-lughawiyya:421","bookId":"furuq-lughawiyya","type":"section","seq":421,"chapter":"* (أ) *","title":"1243 - الفرق بين الصبغة والصورة: أن الصبغة هيئة مضمنة بجعل جاعل في","page":"ج1 ص308","text":"دلالة الصفة اللغوية، وليس كذلك الصورة لان دلالتها على جعل جاعل قياسية."},{"id":"furuq-lughawiyya:422","bookId":"furuq-lughawiyya","type":"section","seq":422,"chapter":"* (أ) *","title":"1245 - الفرق بين الصحة والعافية: أن الصحة أعم من العافية يقال رجل صحيح وآلة صحيحة وخشبة صحيحة إذا كانت ملتئمة لا كسر فيها ولا يقال خشبة معاف","page":"ج1 ص309","text":"وتكون العافية ابتداء من غير مرض وذلك مجاز كأنه فعل ابتداء ما كان من شأنه أن ينافي المرض يقال خلقه الله معافى صحيحا، ومع هذا فإنه لا يقال صح الرجل ولا عوفي إلا بعد مرض يناله، والعافية مصدر مثل العاقبة والطاغية وأصلها الترك من قوله تعالى \" فمن عفى له من اخيه شئ \" (1) أي ترك له، وعفت الدار تركت حتى درست ومنه \" اعفوا اللحى \" أي أتركوها حتى تطول ومنه العفو عن الذنب وهو ترك المعاقبة عليه وعافاه الله من المرض تركه منه بضده من الصحة، وعفاه يعفوه وإعتفاه يعتفيه إذا أتاه يسأله تاركا لغيره."},{"id":"furuq-lughawiyya:423","bookId":"furuq-lughawiyya","type":"section","seq":423,"chapter":"* (أ) *","title":"1250 - الفرق بين الصداقة والخلة: أن الصداقة إتفاق الضمائر على المودة فإذا","page":"ج1 ص310","text":"أضمر كل واحد من الرجلين مودة صاحبه فصار باطنه فيها كظاهره سميا صديقين ولهذا لا يقال الله صديق المؤمن كما أنه وليه، والخلة الاختصاص بالتكريم ولهذا قيل إبراهيم خليل الله لاختصاص الله إياه بالرسالة وفيها تكريم له، ولا يجوز أن يقال: الله خليل إبراهيم لان إبراهيم لا يجوز أن يخص الله بتكريم (1) ، وقال أبو علي رحمة الله تعالى: يقال للمؤمن إنه خليل الله، وقال علي بن عيسى: لا يقال ذلك إلا لنبي لان الله عزوجل يختصه بوحيه ولا يختص به غيره قال والانبياء كلهم أخلاء الله."},{"id":"furuq-lughawiyya:424","bookId":"furuq-lughawiyya","type":"section","seq":424,"chapter":"* (أ) *","title":"1257 - الفرق بين الصدقة والعطية (1) : قيل: الصدقة ما يرجى به الثواب، بخلاف العطية.","page":"ج1 ص311","text":"قال النيسابوري: يمنع (2) العلماء أن يقال: اللهم تصدق علينا بل يجب أن يقال: [20 / أ] اللهم أعطني، أو تفضل علي، وارحمني، لان الصدقة يرجى بها الثواب عند الله، وهو مستحيل في حقه جل شأنه.\nانتهى.\nقلت: ويرده ما ورد عن سيد الساجدين من دعاء الصحيفة الكاملة: (3) \" وتصدق علي بعافيتك \".\nفإذا ورد ذلك في كلام المعصوم فلا\nعبرة بكلام غيره.\nوحينئذ يكون المراد بالتصدق مطلق العطاء.\n(اللغات) ."},{"id":"furuq-lughawiyya:425","bookId":"furuq-lughawiyya","type":"section","seq":425,"chapter":"* (أ) *","title":"1261 - الفرق بين السبيل والطريق (1) : قد يفرق بينهما بأن السبيل أغلب وقوعا في الخير، ولا يكاد اسم الطريق يراد به الخير إلا مقترنا بوصف أو إض","page":"ج1 ص312","text":"كقوله تعالى: \" يهدي إلى الحق وإلى طريق\nمستقيم \" (2) .\n(اللغات) ."},{"id":"furuq-lughawiyya:426","bookId":"furuq-lughawiyya","type":"section","seq":426,"chapter":"* (أ) *","title":"الفرق بين الصفة والاسم","page":"ج1 ص313","text":"والتسمية واللقب: (185) ."},{"id":"furuq-lughawiyya:427","bookId":"furuq-lughawiyya","type":"section","seq":427,"chapter":"* (أ) *","title":"1269- الفرق بين الصفة والاسم","page":"ج1 ص313","text":"الفرق بين الصفة والاسم: أن الصفة ما كان من الاسماء مخصصا مفيدا مثل زيد الظريف وعمرو العاقل، وليس الاسم كذلك فكل صفة\nإسم وليس كل إسم صفة والصفة تابعة للاسم في إعراب وليس كذلك الاسم من حيث هو إسم ويقع الكذب والصدق في الصفة لاقتضائها الفوائد ولا يقع ذلك في الاسم واللقب فالقائل للاسود أبيض على الصفة كاذب وعلى اللقب غير كاذب، والصحيح من الكلام ضربان أحدهما يفيد فائدة الاشارة فقط وهو الاسم العلم واللقب وهو ما صح تبديله واللغة مجالها كزيد وعمرو لانك لو سميت زيدا عمروا لم تتغير اللغة.\nوالثاني ينقسم أقساما فمنها ما يفيد إبانة موصوف من موصوف كعالم وحي.\nومنها ما يبين نوعا من نوع كقولنا لون وكون واعتقاد وإرادة.\nومنها ما يبين جنسا من جنس كقولنا جوهر وسواء وقولنا شئ يقع على ما يعلم وإن لم يفد أنه يعلم."},{"id":"furuq-lughawiyya:428","bookId":"furuq-lughawiyya","type":"section","seq":428,"chapter":"* (أ) *","title":"1272 - الفرق بين الصفة والحال: أن الصفة تفرق بين إسمين مشتركين في اللفظ.","page":"ج1 ص314","text":"والحال زيادة في الفائدة والخبر.\nقال المبرد: إذا قلت جاءني عبد الله وقصدت إلى زيد فخفت أن يعرف السامع جماعة أو إثنين كل واحد عبد الله أو زيد قلت الراكب أو الطويل أو العاقل وما أشبه ذلك من الصفات لتفصل بين من تعني وبين من خفت أن يلبس به كأنك قلت جاءني زيد المعروف بالركوب أو المعروف بالطول فأن لم ترد هذا ولكن أردت الاخبار عن الحال التي وقع فيها مجيئه قلت جاءني زيد راكبا أو ماشيا فجئت بعده بذكره لا يكون نعتا له لانه معرفة وإنما\nأردت أن مجيئه وقع في هذه الحال ولم ترد جاءني زيد المعروف\nبالركوب فان ادخلت الالف واللام صارت صفة للاسم المعروف وفرقا بينه وبينه."},{"id":"furuq-lughawiyya:429","bookId":"furuq-lughawiyya","type":"section","seq":429,"chapter":"* (أ) *","title":"1280 - الفرق بين الصفوة والصفو: أن الصفو مصدر سمي به الصافي من الاشياء إختصارا واتساعا، والصفوة خالص كل شئ، ولهذ يقال: محمد صلى الله عليه [و","page":"ج1 ص315","text":"فالصفوة والصفو مختلفان وإن كانا من أصل واحد كالخبرة والخبر، ولو كان الصفوة والصفو لغتين على ما ذكر ثعلب في الفصيح لقيل محمد صلى الله عليه [وآله] وسلم صفو الله كما قيل صفوة الله."},{"id":"furuq-lughawiyya:430","bookId":"furuq-lughawiyya","type":"section","seq":430,"chapter":"* (أ) *","title":"1281 - الفرق بين الصلابة والشدة: أن الصلابة هي التئام الاجزاء بعضها","page":"ج1 ص315","text":"إلى بعض من غير خلل مع يبوسة فيها، والشدة هي التزاق الاجزاء بعضها ببعض سواء كان الموصوف بها ملتئما أو متحللا، والشدة مبالغة في وصف الشئ والصلابة خلفه واستعمالها في موضع الصلابة إستعارة."},{"id":"furuq-lughawiyya:431","bookId":"furuq-lughawiyya","type":"section","seq":431,"chapter":"* (أ) *","title":"1284 - الفرق بين الاسلام والايمان (1) : لا يخفى أن الاسلام أعم من الايمان مطلقا، كما نطقت به الاخبار الصحاح، والروايات الصراح المروية عن أهل","page":"ج1 ص317","text":"فقلت: صفهما لي.\nفقال: الاسلام شهادة أن لا إله إلا الله، والتصديق برسول الله صلى الله عليه وآله، به حقنت الدماء، وبه جرت المناكح (1) والمواريث، وعلى ظاهره جماعة الناس.\nوالايمان: الهدى، وما يثبت في القلوب من صفة الاسلام وما ظهر من العمل.\nوالايمان: أرفع من الاسلام بدرجة أن الايمان يشارك الاسلام في الظاهر، والاسلام لا يشارك الايمان في الباطن وإن اجتمعا في القول والصفة.\nومنهما ما رواه في الصحيح عن أبي (2) الصباح الكناني قال: قلت لابي عبد الله عليه السلام: أيهما أفضل: الايمان أو الاسلام، فإن من قبلنا يقولون إن الاسلام أفضل من الايمان؟ فقال: الايمان (3) أرفع من الاسلام.\nقلت: فأوجدني ذلك.\nقال: ما (4) تقول في من أحدث في المسجد الحرام متعمدا؟ قال، قلت: يضرب ضربا شديدا.\nقال: أصبت، فما تقول فيمن أحدث (5) في الكعبة متعمدا؟، قال، قلت: يقتل.\nقال: أصبت، ألا ترى أن الكعبة أفضل من المسجد (6) ، وأن\nالكعبة تشرك المسجد والمسجد لا يشرك الكعبة.\nوكذلك الايمان: يشرك الاسلام، والاسلام لا يشرك الايمان.\nفهذان الخبران، وغيرهما من الاخبار، صريحة في أن الاسلام أعم من الايمان مع اعتضادهما بما نطق (1) به القرآن الكريم في قوله تعالى: \" قالت الاعراب آمنا قل لم تؤمنوا ولكن قولوا أسلمنا ولما يدخل الايمان في قلوبكم \" (2) .\nفإنه سبحانه أثبت لهم الاسلام.\nونفي عنهم الايمان.\nوأما قوله تعالى: \" إن الدين عند الله الاسلام \" (3) .\nوقوله تعالى \" فأخرجنا من كان فيها من المؤمنين فما وجدنا غير بيت من المسلمين \" (4) ، فلا حجة فيها لما عرفت من إن الايمان يشارك الاسلام دائما، والاسلام لا يشاركه دائما، لانه تارة يشاركه، وتارة ينفرد عنه، إذ الخاص مركب من العام وزيادة (5) ، فالعام جزء من الخاص، والخاص ليس بجزء له.\nفالاسلام هنا هو المشارك للايمان (6) لا المنفرد عنه.\nوالمغايرة في اللفظ بين الفقرتين مع اتحاد المعنى تفنن في التعبير، وهو في كلام الفصحاء كثير، وبه ينحل الاشكال في قولهم عليهم السلام، في كثير من الاخبار: الايمان يشارك الاسلام، والاسلام لا يشارك الايمان.\nقيل: وأما ما جاء في الدعوات، وصلوات الاموات: \" اللهم اغفر للمؤمنين والمؤمنات، والمسلمين والمسلمات \".\nفالظاهر أن المراد\nبالمؤمنين هنا: هم الكاملون في الايمان عن اعتقاد راسخ ودليل واضح.\nوالمسلمون: هم المستضعفون من النساء والولدان ونحو ذلك.\nوأن المؤمنين هم أهل الطاعات (1) ، والمسلمون هم أهل الكبائر من الفرقة الناجية، وإلا فسائر فرق المسلمين من غير الفرقة (2) الناجية لا يجوز لهم الدعاء بالمغفرة، كما وردت [5 / ب] (3) به الأخبار وشهدت له الآثار.\n(اللغات) ."},{"id":"furuq-lughawiyya:432","bookId":"furuq-lughawiyya","type":"section","seq":432,"chapter":"* (أ) *","title":"1285 - الفرق بين الصلاح والخبر: أن الصلاح الاستقامة على ما تدعو إليه الحكمة ويكون في الضر والنفع كالمرض يكون صلاحا للانسان في وقت دون الصحة","page":"ج1 ص319","text":"الصحة كان ذلك جائزا، ويقال الله تعالى خير لنا من غيره ولا يقال\nهو أصلح لنا من غيره لان أفعل إنما يزيد على لفظ فاعل مبالغة فإذا لم يصح أن يوصف بأنه أصلح من غيره، والخير إسم من أسماء الله تعالى وفي الصحابة رجل يقال له عبد خير وقال أبو هشام: تسمية الله تعالى بأنه خير مجاز قال ويقال: خار الله لك ولم يجئ أنه خائر."},{"id":"furuq-lughawiyya:433","bookId":"furuq-lughawiyya","type":"section","seq":433,"chapter":"* (أ) *","title":"1286 - الفرق بين الصلاح والفلاح: أن الصلاح ما يتمكن به من الخير أو يتخلص به من الشر.","page":"ج1 ص320","text":"والفلاح نيل الخير والنفع الباقي أثره وسمي الشئ الباقي الاثر فلحا ويقال للاكار فلاح لانه يشق الارض شقا باقيا في الارض (1) والافلح المشقوق الشفة السفلى، يقال هذه علة صلاحه ولا يقال فلاحه بل يقال هي سبب فلاحه ويقال موته صلاحه لانه يتخلص به من الضرر العاجل، ولا يقال هو فلاحه لانه ليس بنفع يناله ويقال أيضا لكل من عقل وحزم وتكاملت فيه حلال الخير قد أفلح ولا يقال صلح إلا إذا تغير إلى إستقامة الحال، والفلاح لا يفيد التغيير ويجوز أن يقال الصلاح وضع الشئ على صفة ينتفع به سواء إنتفع أو لا، ولهذا يقال أصلحنا أمر فلان فلم ينتفع بذلك فهو كالنفع في أنه يجوز أن لا ينتفع به، ويقال فلان يصلح للقضاء ويصلح أمره، ولا يستعمل الفلاح في ذلك."},{"id":"furuq-lughawiyya:434","bookId":"furuq-lughawiyya","type":"section","seq":434,"chapter":"* (أ) *","title":"1289 - الفرق بين الصنع والعمل: أن الصنع ترتيب العمل وإحكامه على ما","page":"ج1 ص321","text":"تقدم علم به وبما يوصل إلى المراد منه، ولذلك قيل للنجار صانع ولا يقال للتاجر صانع لان النجار قد سبق علمه بما يريد عمله من سرير أو باب وبالاسباب التي توصل إلى المراد من ذلك والتاجر لا يعلم إذا اتجر أنه يصل إلى ما يريده من الربح أو لا، فالعمل لا يقتضي العلم بما يعمل له ألا ترى أن المستخرجين والضمناء والعشارين من أصحاب السلطان يسمون عمالا ولا يسمون صناعا إذ لا علم لهم بوجوه ما يعملون من منافع عملهم كعلم النجار أو الصائغ بوجوه ما يصنعه من الحلي والآلات، وفي الصناعة معنى الحرفة التي يتكسب بها وليس ذلك في الصنع، والصنع أيضا مضمن بالجودة، ولهذا يقال ثوب صنيع وفلان صنيعة فلان إذا استخصه على غيره وصنع الله لفلان أي أحسن إليه وكل ذلك كالفعل الجيد."},{"id":"furuq-lughawiyya:435","bookId":"furuq-lughawiyya","type":"section","seq":435,"chapter":"* (أ) *","title":"1290 - الفرق بين الصنع والفعل والعمل (1) : قال الراغب في الفرق بينها: الفعل لفظ عام.","page":"ج1 ص321","text":"يقال لما كان بإجادة وبدونها، ولما كان بعلم أو غير علم، وقصد أو غير قصد، ولما كان من الانسان والحيوان والجماد.\nوأما العمل فإنه لا يقال إلا لما كان من الحيوان دون ما كان من الجماد ولما كان بقصد وعلم دون ما لم يكن عن قصد وعلم.\nقال بعض الادباء: العمل مقلوب عن العلم، فإن العلم فعل القلب، والعمل فعل الجارحة، وهو يبرز عن فعل القلب الذي هو العلم وينقلب عنه.\nوأما الصنع فإنه من الانسان دون سائر الحيوانات، ولا يقال إلا لما كان بإجادة.\nولهذا يقال للحاذق المجيد، والحاذقة المجيدة.\nصنع كبطل وصناع، كسلام.\nوالصنع يكون بلا فكر لشرف فاعله، والفعل قد يكون بلا فكر لنقص فاعله.\nوالعمل لا يكون إلا بفكر لتوسط فاعله.\nفالصنع أخص المعاني الثلاثة، والفعل أعمها، والعمل أوسطها.\nفكل صنع عمل، وليس كل عمل صنعا، وكل عمل فعل، وليس كل فعل عملا.\nوفارسية هذه الالفاظ تنبئ عن الفرق بينهما، فإنه يقال للفعل (كار) وللعمل (كردار) وللصنع (كيش) .\n(اللغات) ."},{"id":"furuq-lughawiyya:436","bookId":"furuq-lughawiyya","type":"section","seq":436,"chapter":"* (أ) *","title":"1292 - الفرق بين الصنم والوثن (1) : قيل: الصنم ما كان مصورا من صفر أو ذهب أو غير ذلك.","page":"ج1 ص322","text":"والوثن: ما كان غير مصور، ولم أقف في ذلك على دليل.\n(اللغات) ."},{"id":"furuq-lughawiyya:437","bookId":"furuq-lughawiyya","type":"section","seq":437,"chapter":"* (أ) *","title":"1294 - الفرق بين الصواب والمستقيم: أن الصواب إطلاق الاستقامة على","page":"ج1 ص323","text":"الحسن والصدق، والمستقيم هو الجاري على سنن فتقول للكلام إذا كان جاريا على سنن لا تفاوت فيه أنه مستقيم وإن كان قبيحا ولا يقال له صواب إلا إذا كان حسنا، وقال سيبويه: مستقيم حسن ومستقيم قبيح ومستقيم صدق ومستقيم كذب قلنا ولا يقال صواب قبيح."},{"id":"furuq-lughawiyya:438","bookId":"furuq-lughawiyya","type":"section","seq":438,"chapter":"* (أ) *","title":"1296 - الفرق بين الصوت والكلام: أن من الصوت ما ليس بكلام مثل صوت الطست وأصوات البهائم والطيور.","page":"ج1 ص323","text":"ومن المشكلة وهي حمرة تخالط بياض العين وغيرها والمختلط بغيره قد يظهر للمتأمل فكذلك المعنى المشكل قد يعرف بالتأمل والذي فيه ليس كالمستور والمستور خلاف الظاهر."},{"id":"furuq-lughawiyya:439","bookId":"furuq-lughawiyya","type":"section","seq":439,"chapter":"* (أ) *","title":"1298 - الفرق بين الصورة والهيئة: أن الصورة إسم يقع على جميع هيئات الشئ لا على بعضها ويقع أيضا على ما ليس بهيئة ألا ترى انه يقال صورة هذا الا","page":"ج1 ص323","text":"ونهايته من الطرفين سواء كان هيئة أو لا، ولهذا لا يقال صورة الله كذا\nلان الله تعالى ليس بذي نهاية."},{"id":"furuq-lughawiyya:440","bookId":"furuq-lughawiyya","type":"section","seq":440,"chapter":"* (أ) *","title":"1301 - الفرق بين الصيام والصوم (1) : قد يفرق بينهما بأن الصيام هو الكف عن المفطرات مع النية، ويرشد إليه قوله تعالى: \" كتب عليكم الصيام كما ك","page":"ج1 ص324","text":"والصوم: هو الكف عن المفطرات، والكلام كما كان في الشرائع السابقة، وإليه يشير قوله تعالى مخاطبا مريم عليها السلام: \" فإما ترين من البشر أحدا فقولي إني نذرت للرحمن صوما فلن أكلم اليوم إنسيا \" (3) .\nحيث رتب عدم التكلم على نذر الصوم.\n(اللغات) ."},{"id":"furuq-lughawiyya:441","bookId":"furuq-lughawiyya","type":"section","seq":441,"chapter":"* (أ) *","title":"1302 - الفرق بين الضبط والحفظ: أن ضبط الشئ شدة الحفظ له لئلا يفلت منه شئ ولهذا لا يستعمل في الله تعالى لانه لا يخاف الافلات ويستعار في الحسا","page":"ج1 ص325","text":"من الغلط."},{"id":"furuq-lughawiyya:442","bookId":"furuq-lughawiyya","type":"section","seq":442,"chapter":"* (أ) *","title":"1304 - الفرق بين الضد والنقيض (1) : قيل: النقيضان: ما كان التقابل بينهما تقابل النفي والاثبات أو (2) العدم، والملكة، ولذا لا يمكن اجتماعهما","page":"ج1 ص325","text":"وأما المتضادان: فيجوز ارتفاعهما ويمتنع اجتماعهما كالسواد والبياض.\n(3) * وأما المتخالفان فيجوز اجتماعهما وارتفاعهما جميعا السواد * والقيام.\nفيصح هذا قائم أسود، وقائم ليس بأسود [20 / ب] ، وأسود\nليس بقائم، وليس بقائم ولا أسود.\n(اللغات) ."},{"id":"furuq-lughawiyya:443","bookId":"furuq-lughawiyya","type":"section","seq":443,"chapter":"* (أ) *","title":"1307 - الفرق بين الضراعة والذل: أن الضراعة مشتقة من الضرع، والضرع معرض لحالبه والشارب منه، فالضارع هو المنقاد الذي لا إمتناع به، ومنه التضرع","page":"ج1 ص326","text":"سبحانه وتعالى في كتابه إنما هو من طعام وذل لا منفعة فيه لآكله كما وصفه الله تعالى بقوله \" لا يسمن ولا يغني من جوع \" (2) ويجوز أن يقال التضرع هو أن يميل أصبعه يمينا وشمالا خوفا وذلا، ومنه سمي الضرع ضرعا لميل اللبن إليه، والمضارعة المشابهة لانها ميل إلى الشبه مثل المقاربة."},{"id":"furuq-lughawiyya:444","bookId":"furuq-lughawiyya","type":"section","seq":444,"chapter":"* (أ) *","title":"1310 - الفرق بين الضرر والضرار (1) : في الحديث: \" لا ضرر ولا ضرار في الاسلام \".","page":"ج1 ص327","text":"قال ابن الاثير في النهاية: (2) الضر: ضد النفع، فقوله: لا ضرر:\nأي لا يضر الرجل أخاه فينقصه شيئا من حقه.\nوالضرار: فعال من الضر، أي لا يجازيه على إضراره بإدخال الضرر عليه، والضر: فعل الواحد، والضرار: فعل الاثنين.\nوالضر: ابتداء الفعل.\nوالضرار: الجزاء عليه.\nوقيل: الضر: ما تضر به صاحبك وتنتفع به أنت.\nوالضرار: أن تضره من غير أن تنتفع! وقيل: هما بمعنى واحد، وتكرارهما للتأكيد.\n(اللغات) ."},{"id":"furuq-lughawiyya:445","bookId":"furuq-lughawiyya","type":"section","seq":445,"chapter":"* (أ) *","title":"1312 - الفرق بين الضر والسوء: أن الضر يكون من حيث لا يعلم المقصود به","page":"ج1 ص328","text":"والسوء لا يكون إلا من حيث يعلم، ومعلوم أنه يقال ضررت فلانا من حيث لا يعلم ولا يقال سؤته إلا إذا جاهرته بالمكروه."},{"id":"furuq-lughawiyya:446","bookId":"furuq-lughawiyya","type":"section","seq":446,"chapter":"* (أ) *","title":"1313 - الفرق بين الضر والشر: أن السقم وعذاب (1) جهنم ضر في الحقيقة وشر مجازا، وشرب الدواء المر رجاء العافية ضرر يدخله الانسان على نفسه وليس","page":"ج1 ص328","text":"المنهمك في الشرب المحظور، والشر عنده ضربان حسن وقبيح فالحسن السقم وعذاب جهنم والقبيح الظلم وما يجري مجراه قال ويجوز أن يقال للشئ الواحد إنه خير وشر إذا أردت بأحد القولين إخبارا عن عاقبته وإنما يكونان نقيضين إذا كانا من وجه واحد."},{"id":"furuq-lughawiyya:447","bookId":"furuq-lughawiyya","type":"section","seq":447,"chapter":"* (أ) *","title":"1315 - الفرق بين الضعة والذل: أن الضعة لا تكون الا بفعل الانسان بنفسه ولا يكون بفعل غيره وضيعا كما يكون بفعل غيره ذليلا، وإذا غلبه غيره قيل","page":"ج1 ص329","text":"في المعنى فلا يجوز أن يكون الوضيع رفيعا."},{"id":"furuq-lughawiyya:448","bookId":"furuq-lughawiyya","type":"section","seq":448,"chapter":"* (أ) *","title":"الفرق بين الضعف والوهن","page":"ج1 ص329","text":"أن الضعف ضد القوة وهو من فعل الله تعالى كما أن القوة من فعل الله تقول خلقه الله ضعيفا أو خلقه قويا، وفي القرآن \" وخلق الانسان ضعيفا \" (2) والوهن هو أن يفعل الانسان فعل الضعيف تقول وهن في الامر يهن وهنا وهو واهن إذا أخذ فيه أخذ الضعيف، ومنه قوله تعالى \" ولا تهنوا ولا تحزنوا وأنتم الاعلون \" (3) أي لا تفعلوا أفعال الضعفاء وأنتم أقوياء على ما تطلبونه\nبتذليل الله أياه لكم، ويدل على صحة ما قلنا أنه لا يقال خلقه الله واهنا كما يقال خلقه الله ضعيفا، وقد يستعمل الضعف مكان الوهن مجازا في مثل قوله تعالى \" وما ضعفوا وما استكانوا \" (4) أي لم يفعلوا فعل الضعيف، ويجوز أن يقال إن الوهن هو انكسار الحد والخوف ونحوه، والضعف نقصان القوة، وأما الاستكانة فقيل هي إظهار الضعف قال الله تعالى \" وما ضعفوا وما استكانوا \" أي لم يضعفوا بنقصان القوة ولا استكانوا بإظهار الضعف عند المقاومة، قال الخليل: إن الوهن الضعف في العمل والامر وكذلك في العظم ونحوه يقال\nوهن العظم يهن وهنا وأوهنه موهنة ورجل واهن في الامر والعمل وموهون في العظم والبدن، والموهن لغة والوهين بلغة أهل مصر رجل يكون مع الاجير يحثه على العمل."},{"id":"furuq-lughawiyya:449","bookId":"furuq-lughawiyya","type":"section","seq":449,"chapter":"* (أ) *","title":"1318 - الفرق بين الضعف والوهن (1) : قد فرق بينهما بأن الوهن انكسار الجسد بالخوف وغيره، والضعف نقصان القوة.","page":"ج1 ص330","text":"قلت: ويدل عليه قوله تعالى في وصف المؤمنين المجاهدين: \" وكأين من نبي قاتل معه ربيون كثير فما وهنوا لما أصابهم في سبيل الله وما ضعفوا \" (2) .\nإشارة إلى نفي الحالتين عنهم في الجهاد.\n(اللغات) ."},{"id":"furuq-lughawiyya:450","bookId":"furuq-lughawiyya","type":"section","seq":450,"chapter":"* (أ) *","title":"الفرق بين الضياء والنور","page":"ج1 ص331","text":"أن الضياء ما يتخلل الهواء من أجزاء النور فيبيض بذلك، والشاهد أنهم يقولون ضياء النهار ولا يقولون نور النهار إلا أن يعنوا الشمس فالنور الجملة التي يتشعب منها، والضوء مصدر ضاء يضوء ضوء يقال ضاء وأضاء أي ضاء هو واضاء غيره."},{"id":"furuq-lughawiyya:451","bookId":"furuq-lughawiyya","type":"section","seq":451,"chapter":"* (أ) *","title":"1325- الفرق بين الضياء والنور","page":"ج1 ص331","text":"الفرق بين الضياء والنور (3) : هما مترادفان لغة.\nوقد يفرق بينهما بأن الضوء: ما كان من ذات الشئ المضئ، والنور: ما كان\nمستفادا من غيره.\nوعليه جرى قوله تعالى: \" هو الذي جعل الشمس ضياء والقمر نورا \" (4) .\nوقال الراغب: النور الضوء المنتشر الذي يعين على الابصار.\nوهو ضربان: دنيوي وأخروي.\nوالدنيوي ضربان: معقول بعين البصيرة، وهو ما انتشر من الانوار الآلهية كنور العقل ونور القرآن.\nومنه: \" قد جاءكم من الله نور \" (5) ومحسوس بعين التبصر وهو ما انتشر من\nالاجسام النيرة، كالقمرين والنجوم النيرات، ومنه: \" هو الذي جعل الشمس ضياء والقمر نورا \" (1) .\nومن النور الاخروي قوله تعالى: \" يسعى نورهم بين أيديهم \" (2) .\n(اللغات) ."},{"id":"furuq-lughawiyya:452","bookId":"furuq-lughawiyya","type":"section","seq":452,"chapter":"* (أ) *","title":"1329 - الفرق بين الطاعة الاجابة (5) : الفرق بينهما أن الطاعة: موافقة الارادة الحادثة إلى الفعل برغبته، أو رهبته.","page":"ج1 ص333","text":"والاجابة: موافقة الداعي إلى الفعل من أجل أنه دعابه، ولذا\nيقال: أجاب الله فلانا، ولا يقال: أطاعه، كذا قال بعضهم.\n(اللغات) ."},{"id":"furuq-lughawiyya:453","bookId":"furuq-lughawiyya","type":"section","seq":453,"chapter":"* (أ) *","title":"1331 - الفرق بين الطاعة والتطوع (1) : قال الطبرسي: الفرق بينهما أن الطاعة موافقة الارادة في الفريضة، والنافلة والتطوع: التبرع بالنافلة خاصة.","page":"ج1 ص334","text":"وأصلهما من الطوع: الذي هو من (2) الانقياد.\n(اللغات) ."},{"id":"furuq-lughawiyya:454","bookId":"furuq-lughawiyya","type":"section","seq":454,"chapter":"* (أ) *","title":"1339 - الفرق بين الطبع والختم: أن الطبع أثر يثبت في المطبوع ويلزمه فهو يفيد من معنى الثبات واللزوم ما لا يفيده الختم، ولهذا يقال طبع الدرهم","page":"ج1 ص335","text":"وهو الاثر الذي يؤثره فيه فلا يزول عنه، كذلك أيضا قيل طبع الانسان لانه ثابت غير زائل، وقيل طبع فلان على هذا الخلق إذا كان لا يزول عنه، وقال بعضهم: الطبع علامة تدل على كنه الشئ قال وقيل طبع الانسان لدلالته على حقيقة مزاجه من الحرارة والبرودة قال وطبع الدرهم علامة جوازه."},{"id":"furuq-lughawiyya:455","bookId":"furuq-lughawiyya","type":"section","seq":455,"chapter":"* (أ) *","title":"1344 - الفرق بين الطغيان والعتو: أن الطغيان مجاوزة الحد في المكروه مع غلبة وقهر ومنه قوله تعالى \" إنا لما طغى الماء \" (1) الآية يقال طغى الم","page":"ج1 ص336","text":"إذا جاوز الحد في الظلم، والعتو المبالغة في المكروه فهو دون الطغيان ومنه قوله تعالى \" وقد بلغت من الكبر عتيا \" (2) قالوا كل مبالغ في كبر أو كفر أو فساد فقد عتا فيه ومنه قوله تعالى \" بريح صرصر عاتية \" (3) أي مبالغة في الشدة، ويقال جبار عات أي مبالغ في الجبرية ومنه قوله تعالى \" عتت عن أمر ربها \" (4) يعني أهلها تكبروا على ربهم فلم يطيعوه."},{"id":"furuq-lughawiyya:456","bookId":"furuq-lughawiyya","type":"section","seq":456,"chapter":"* (أ) *","title":"1345 - الفرق بين ذلك (5) وبين طلاقة الوجه: أن طلاقة الوجه خلاف العبوس والعبوس تكره الوجه عند اللقاء والسؤال وطلاقته إنحلال ذلك عنه وقد طلق ي","page":"ج1 ص337","text":"أطلقته وهو طلق وطليق، ومنه طلقت المرأة لان ذلك تخليص من الحمل"},{"id":"furuq-lughawiyya:457","bookId":"furuq-lughawiyya","type":"section","seq":457,"chapter":"* (أ) *","title":"1346 - الفرق بين الطلب والاقتضاء","page":"ج1 ص337","text":"(252) ."},{"id":"furuq-lughawiyya:458","bookId":"furuq-lughawiyya","type":"section","seq":458,"chapter":"* (أ) *","title":"ظ","page":"ج1 ص338","text":"افة: أن الطهارة تكون في الخلقة والمعاني لانها تقتضي منافاة العيب يقال فلان طاهر الاخلاق وتقول المؤمن طاهر مطهر يعني أنه جامع للخصال المحمودة، والكافر خبيث لانه خلاف المؤمن وتقول هو طاهر الثوب والجسد.\nوالنظافة لا تكون إلا في الخلق واللباس وهي تفيد منافاة الدنس ولا تستعمل في المعاني وتقول هو نظيف الصورة أي حسنها ونظيف الثوب والجسد ولا تقول نظيف\nالخلق."},{"id":"furuq-lughawiyya:459","bookId":"furuq-lughawiyya","type":"section","seq":459,"chapter":"* (أ) *","title":"1365 - الفرق بين الظفر والفور: أن الظفر هو العلو على المناوئ المنازع قال الله تعالى \" من بعد أن أظفركم عليهم \" (1) وقد يستعمل في موضع","page":"ج1 ص339","text":"الفوز يقال ظفر ببغيته ولا يستعمل الفوز في موضع الظفر ألا ترى أنه لا يقال فاز بعدوه كما يقال ظفر بعدوه بعينه فالظفر مفارق للفوز وقال علي بن عيسى: الفوز الظفر بدلا من الوقوع في الشر وأصله نيل الحظ من الخير، وفوز إذا ركب المفازة وفوز أيضا إذا مات لانه قد صار في مثل المفازة."},{"id":"furuq-lughawiyya:460","bookId":"furuq-lughawiyya","type":"section","seq":460,"chapter":"* (أ) *","title":"الفرق بين الظل والفئ","page":"ج1 ص339","text":"أن الظل يكون ليلا ونهارا ولا يكون الفئ إلا\nبالنهار وهو ما فاء من جانب إلى جانب أي رجع، والفئ الرجوع ويقال الفئ التبع لانه يتبع الشمس وإذا ارتفعت الشمس إلى موضع المقال من ساق الشجرة قيل قد عقل الظل."},{"id":"furuq-lughawiyya:461","bookId":"furuq-lughawiyya","type":"section","seq":461,"chapter":"* (أ) *","title":"1367 - الفرق بين الظل والفئ (1) : الظل: الفئ الحاصل من الحاجز بينك وبين الشمس، وقيل هي (2) الطلوع إلى الزوال.","page":"ج1 ص340","text":"والفئ: من الزوال إلى الغروب.\nوقال المبرد: الفئ ما نسخته الشمس، لانه الراجع، والظل: ما كان قائما لم ينسخه ضوء الشمس، قال الشاعر: (3) .\nفلا الظل من بعد الضحى تستطيعه * ولا الفئ من بعد العشي تذوق فجعل الظل وقت الضحى، لان الشمس لم تنسخه ذلك الوقت.\nفكل فئ ظل، وليس كل ظل فيئا.\nوأهل الجنة في ظل لا في فئ، لان الجنة لا شمس فيها.\nوفي التنزيل: \" وظل ممدود \" (4) .\nوجمع الفئ: أفياء وفيوء.\n(اللغات) ."},{"id":"furuq-lughawiyya:462","bookId":"furuq-lughawiyya","type":"section","seq":462,"chapter":"* (أ) *","title":"1368 - الفرق بين الظلم والبغي: أن الظلم ما ذكرناه (5) ، والبغي شدة","page":"ج1 ص341","text":"الطلب لما ليس بحق بالتغليب وأصله في العربية شدة الطلب ومنه يقال دفعنا بغي السماء خلفنا أي شدة مطرها، وبغى الجرح يبغي إذا ترامى إلى فساد يرجع إلى ذلك وكذلك البغاء وهو الزنا وقيل في قوله تعالى \" والاثم والبغي بغير الحق \" (1) أنه يريد الترأس على الناس بالغلبة والاستطالة."},{"id":"furuq-lughawiyya:463","bookId":"furuq-lughawiyya","type":"section","seq":463,"chapter":"* (أ) *","title":"1372 - الفرق بين الظن والتصور: أن الظن ضرب من أفعال القلوب يحدث عند بعض الامارات وهو رجحان أحد طرفي التجوز، وإذا حدث عند أمارات غلبت وزادت ب","page":"ج1 ص341","text":"المدرك تصور نفسه، والشاهد أن الاعراض التي لا تدرك لا تتصور نحو العلم والقدرة، والتمثل مثل التصور إلا أن التصور أبلغ لان قولك تصورت الشئ معناه أني بمنزلة من أبصر صورته، وقولك تمثلته معناه أني بمنزلة من أبصر مثاله، ورؤيتك لصورة الشئ أبلغ في عرفان ذاته من رؤيتك لمثاله."},{"id":"furuq-lughawiyya:464","bookId":"furuq-lughawiyya","type":"section","seq":464,"chapter":"* (أ) *","title":"ع","page":"ج1 ص342","text":"لمك بأنه حي.\nقال أبو هلال رحمه الله تعالى: أصل الحسبان من الحساب تقول أحسبه بالظن قد مات كما تقول أعده قد مات، ثم كثر حتى سمي الظن حسبانا على جهة التوسع وصار كالحقيقة بعد كثرة الاستعمال وفرق بين الفعل منهما فيقال في الظن حسب وفي الحساب حسب ولذلك فرق بين المصدرين فقيل حسب وحسبان، والصحيح في الظن ما ذكرناه (1) ."},{"id":"furuq-lughawiyya:465","bookId":"furuq-lughawiyya","type":"section","seq":465,"chapter":"* (أ) *","title":"1377 - الفرق بين الظن والعلم: أن الظان يجوز أن يكون المظنون على خلاف ما هو ظنه ولا يحققه والعلم يحقق المعلوم وقيل جاء الظن في القرآن بمعنى ا","page":"ج1 ص342","text":"ظاهره."},{"id":"furuq-lughawiyya:466","bookId":"furuq-lughawiyya","type":"section","seq":466,"chapter":"* (أ) *","title":"1378 - الفرق بين الظهور والبدو: أن الظهور يكون بقصد وبغير قصد تقول إستتر فلان ثم ظهر ويدل هذا على قصده للظهور، ويقال ظهر أمر فلان وإن لم يقص","page":"ج1 ص343","text":"والبحر \" (1) فمعنى ذلك الحدوث وكذلك قولك ظهرت في وجهه حمرة أي حدثت ولم يعن أنها كانت فيه فظهرت، والبدو ما يكون بغير قصد تقول بدا البرق وبدا الصبح وبدت الشمس وبدا لي في الشئ لانك لم تقصد للبدو، وقيل في هذا بدو وفي الاول بدء وبين المعنيين فرق والاصل واحد."},{"id":"furuq-lughawiyya:467","bookId":"furuq-lughawiyya","type":"section","seq":467,"chapter":"* (أ) *","title":"1380 - الفرق بين العادة والعرف (1) : الفرق بينهما أن العرف: يستعمل في الالفاظ.","page":"ج1 ص344","text":"والعادة تستعمل في الافعال.\nوذكر المحققون من الاصوليين أن العرف والعادة قد يخصصان العمومات، وفرعوا على ذلك مالو حلف أن لا يأكل الرؤوس، فإنه ينصرف إلى الغالب من رؤوس النعم دون رؤوس الطير والجراد والسمك، لعدم دخولها [22 / أ] عرفا في اسم الرؤوس.\nوكذا لو حلف: لا يأكل البيض لم يحنث بيض بعض السمك ونحوه على الاصح.\nوكذا لو حلف لا يأكل منها\n[ما يؤكل] (2) عادة وهو الثمر دون ما لا يؤكل عادة كالورق والقشر والخشب.\n(اللغات) ."},{"id":"furuq-lughawiyya:468","bookId":"furuq-lughawiyya","type":"section","seq":468,"chapter":"* (أ) *","title":"1381 - الفرق بين العادة والدأب: أن العادة على ضربين إختيار أو اضطرار فالاختيار كتعود شرب النبيذ وما يجري مجراه مما يكثر الانسان فعله فيعتاده","page":"ج1 ص345","text":"الماء لاقامة الجسد وبقاء الروح وما شاكل ذلك، والدأب لا يكون إلا إختيارا ألا ترى أن العادة في الاكل والشرب المقيمين للبدن لا تسمى دأبا."},{"id":"furuq-lughawiyya:469","bookId":"furuq-lughawiyya","type":"section","seq":469,"chapter":"* (أ) *","title":"1390 - الفرق بين العالم والعليم: أن قولنا عالم دال على معلوم لانه من علمت وهو متعد، وليس قولنا عليم جاريا على علمية فهو لا يتعدى، وإنما يفيد","page":"ج1 ص345","text":"أنه إن صح معلوم علمه، كما أن صفة سميع تفيد أنه إن صح مسموع سمعه، والسامع يقتضي مسموعا، وإنما يسمى الانسان وغيره سميعا إذا لم يكن أصم وبصيرا إذا لم يكن أعمى ولا يقتضي ذلك مبصرا ومسموعا ألا ترى أنه يسمى بصيرا وإن كان مغمضا، وسميعا وإن لم يكن بحضرته صوت يسمعه فالسميع والسامع صفتان، وكذلك المبصر والبصير والعليم والعالم والقدير والقادر لان كل واحد منهما يفيد ما لا يفيده الآخر فإن جاء السميع والعليم وما يجري مجراهما متعديا في بعض الشعر فإن ذلك قد جعل بمعنى السامع والعالم، وقد جاء السميع أيضا بمعنى مسمع (1) في قوله: أمن ريحانة الداعي السميع * يؤرقني وأصحابي هجوع"},{"id":"furuq-lughawiyya:470","bookId":"furuq-lughawiyya","type":"section","seq":470,"chapter":"* (أ) *","title":"1392 - الفرق بين العالم والناس: أن بعض العلماء قال: أهل كل زمان عالم وأنشد \" وخندف هامة هذا العالم \"، وقال غيره: ما يحوي الفلك عالم، ويقول ا","page":"ج1 ص346","text":"ويقولون إلى فلان تدبير العالم يعنون الدنيا، وقال آخرون: العالم إسم لاشياء مختلفة وذلك أنه يقع على الملائكة والجن والانس وليس هو مثل الناس لان كل واحد من الناس إنسان وليس كل واحد من العالم ملائكة."},{"id":"furuq-lughawiyya:471","bookId":"furuq-lughawiyya","type":"section","seq":471,"chapter":"* (أ) *","title":"الفرق بين العام والسنة","page":"ج1 ص346","text":"أن العام جمع أيام والسنة جمع شهور ألا ترى\nأنه لما كان يقال أيام الرنج قيل عام الرنج ولما لم يقل شهور الرنج لم يقل سنة الرنج ويجوز أن يقال العام يفيد كونه وقتا لشئ والسنة لا تفيد ذلك ولهذا يقال عام الفيل ولا يقال سنة الفيل ويقال في التاريخ سنة مائة وسنة خمسين ولا يقال عام مائة وعام خمسين إذ ليس وقتا لشئ مما ذكر من هذا العدد ومع هذا فإن العام هو السنة والسنة هي العام وإن اقتضى كل واحد منهما ما لا يقتضيه الآخر مما ذكرناه كما أن الكل هو الجمع والجمع هو الكل وإن كان الكل إحاطة بالابعاض والجمع إحاطة بالاجزاء."},{"id":"furuq-lughawiyya:472","bookId":"furuq-lughawiyya","type":"section","seq":472,"chapter":"* (أ) *","title":"1394 - الفرق بين العام والسنة (1) : قال ابن الجواليقي (2) : ولا يفرق (3) عوام الناس بين السنة والعام ويجعلونهما بمعنى.","page":"ج1 ص347","text":"ويقولون لمن سافر في وقت من السنة أي وقت كان إلى مثله: عام، وهو غلط، والصواب ما أخبرت به عن أحمد بن يحيى (4) أنه قال: السنة من أول يوم عددته إلى مثله، والعام لا يكون إلا شتاء وصيفا.\nوفي التهذيب (5) أيضا: العام: حول يأتي على شتوة وصيفة.\nوعلى هذا فالعام أخص من السنة.\nوليس كل سنة عاما.\nفإذا\nعددت من يوم إلى مثله فهو سنة.\nوقد يكون فيه نصف الصيف، ونصف الشتاء.\nوالعام لا يكون إلا صيفا أو شتاء متوالين.\nانتهى.\nأقول: وتظهر فائدة ذلك في اليمين (1) والنذر، فإذا حلف أو نذر أن يصوم عاما لا يدخل بعضه في بعض إنما هو الشتاء والصيف، بخلاف ما لو حلف (2) ونذر سنة.\n(اللغات) ."},{"id":"furuq-lughawiyya:473","bookId":"furuq-lughawiyya","type":"section","seq":473,"chapter":"* (أ) *","title":"1396 - الفرق بين العبادة والطاعة: أن العبادة غاية الخضوع ولا تستحق إلا بغاية الانعام ولهذا لا يجوز أن يعبد غير الله تعالى ولا تكون العبادة إ","page":"ج1 ص348","text":"الداعي إلى ما دعاه إليه وإن لم يقصد التبع كالانسان يكون مطيعا للشيطان وإن لم يقصد أن يطيعه ولكنه اتبع دعاءه وإرادته."},{"id":"furuq-lughawiyya:474","bookId":"furuq-lughawiyya","type":"section","seq":474,"chapter":"* (أ) *","title":"1403 - الفرق بين العتاب واللوم: أن العتاب هو الخطاب على تضييع حقوق المودة والصداقة في الاخلال بالزيارة وترك المعونة وما يشاكل ذلك ولا يكون ا","page":"ج1 ص349","text":"بينة."},{"id":"furuq-lughawiyya:475","bookId":"furuq-lughawiyya","type":"section","seq":475,"chapter":"* (أ) *","title":"1404 - الفرق بين العترة والآل: أن العترة على ما قال المبرد: \" النصاب ومنه عترة فلان أي منصبه \"، وقال بعضهم: \" العترة أصل الشجرة الباقي بعد ق","page":"ج1 ص349","text":"على كل قول لان الآل هم الاهل والاتباع والعترة هم الاصل في قول والاهل وبنو الاعمام في قول آخر."},{"id":"furuq-lughawiyya:476","bookId":"furuq-lughawiyya","type":"section","seq":476,"chapter":"* (أ) *","title":"1407 - الفرق بين العثو والفساد: أن العثو كثرة الفساد وأصله من قولك ضبع عثواء إذا كثر الشعر على وجهها وكذلك الرجل، وعاث يعيث لغة وعثا","page":"ج1 ص350","text":"يعثو أفصح اللغتين ومنه قوله عزوجل \" ولا تعثوا في الارض مفسدين \" (1) ."},{"id":"furuq-lughawiyya:477","bookId":"furuq-lughawiyya","type":"section","seq":477,"chapter":"* (أ) *","title":"1411 - الفرق بين العجب والكبر: أن العجب بالشئ شدة السرور به حتى لا يعادله شئ عند صاحبه تقول هو معجب بفلانة إذا كان شديد السرور بها، وهو معجب","page":"ج1 ص351","text":"ولهذا يقال أعجبه كما يقال سر به فليس العجب من الكبر في شئ، وقال علي بن عيسى: العجب عقد النفس على فضيلة لها ينبغي أن يتعجب منها وليست هي لها."},{"id":"furuq-lughawiyya:478","bookId":"furuq-lughawiyya","type":"section","seq":478,"chapter":"* (أ) *","title":"1416 - الفرق بين العداوة والشنآن: أن العداوة هي إرادة السوء لما تعاديه وأصله الميل ومنه عدوة الوادي وهي جانبه، ويجوز أن يكون أصله البعد ومنه","page":"ج1 ص351","text":"بعد عن التوسط، والشنآن على ما قال علي بن عيسى: طلب العيب على فعل الغير لما سبق من عداوته، قال وليس هو من العداوة في شئ وإنما اجري على العداوة لانها سببه وقد يسمى المسبب بإسم السبب وجاء في التفسير \" شنآن قوم \" (1) أي بغض قوم فقرئ شنآن قوم بالاسكان أي بغض قوم شني وهو شنآن كما تقول سكر وهو سكران."},{"id":"furuq-lughawiyya:479","bookId":"furuq-lughawiyya","type":"section","seq":479,"chapter":"* (أ) *","title":"1424 - الفرق بين العديل والمثل: أن العديل ما عادل أحكامه أحكام غيره وإن لم يكن مثلا له في ذاته ولهذا سمي العدلان عدلين وإن لم يكونا","page":"ج1 ص353","text":"مثلين في ذاتهما، ولكن لاستوائهما في الوزن فقط."},{"id":"furuq-lughawiyya:480","bookId":"furuq-lughawiyya","type":"section","seq":480,"chapter":"* (أ) *","title":"1430 - الفرق بين عرفة وعرفات (1) : قد عرفت يوم عرفة، وهو اليوم التاسع من ذي الحجة.","page":"ج1 ص353","text":"وعرفة.\nقيل: اسم لموقف الحاج ذلك اليوم، وهي اثنا عشر ميلا من مكة.\nوسمي عرفات أيضا، وهو المذكور في التنزيل.\nقال تعالى فإذا أفضتم من عرفات \" (2) .\nوقال النيسابوري: عرفات جمع عرفة.\nوكلاهما علم للموقف، كأن كل قطعة من تلك الارض عرفة، فسمي مجموع تلك القطعة بعرفات.\nوكذا قال ابن الحاجب (3) في شرح المفصل.\nقال الطبرسي: عرفات: اسم للبقعة المعروفة التي يجب الوقوف بها، ويوم عرفة يوم الوقوف بها (1) .\nووافق على ذلك الفيروز آبادي.\nوهذا القول مبني على إنكار كون عرفة اسما للموقف.\nوهو قول الفراء.\n(اللغات) ."},{"id":"furuq-lughawiyya:481","bookId":"furuq-lughawiyya","type":"section","seq":481,"chapter":"* (أ) *","title":"1435 - الفرق بين العز والشرف: أن العز يتضمن معنى الغلبة (2) والامتناع على ما قلنا، فأما قولهم عز الطعام فهو عزيز فمعناه قل حتى لا يقدر عليه","page":"ج1 ص355","text":"مذكور عند العرب شريف، ولهذا لا يقال لله تعالى شريف كما يقال له عزيز."},{"id":"furuq-lughawiyya:482","bookId":"furuq-lughawiyya","type":"section","seq":482,"chapter":"* (أ) *","title":"1436 - الفرق بين العزم والحزم (1) : قيل: الاول: التأهب للامر، والثاني: النفاذ فيه.","page":"ج1 ص355","text":"(اللغات) ."},{"id":"furuq-lughawiyya:483","bookId":"furuq-lughawiyya","type":"section","seq":483,"chapter":"* (أ) *","title":"1440 - الفرق بين العزم والهم (2) : قال الطبرسي، العزم هو تصميم القلب على الشئ، والنفاذ فيه بقصد ثابت.","page":"ج1 ص355","text":"والهم يأتي على وجوه: ومنها العزم على الفعل كقوله تعالى: \" إذ هم قوم أن يبسطوا إليكم أيديهم \" (3) أي صمموا النية وعزموا عليه، فيرادف العزم.\nومنها خطور الشئ في البال، وإن لم يقع العزم عليه، لقوله تعالى: \" إذ همت طائفتان منكم أن تفشلا والله وليهما \" (1) .\nيعنى أن الفشل خطر ببالهم، ولو كان هنا عزما لما كان الله وليهما، لان العزم على المعصية معصية.\nولا يجوز أن يكون الله ولي من عزم على الفرار عن نصره به، ويقوي ذلك قول كعب بن زهير بن أبي سلمى: (2) وكم فيهم من فارس متوسع * ومن فاعل للخير إن هم أو عزم ففرق بين الهم والعزم.\nومنها: أن يكون بمعنى المقاربة.\nقال ذو الرمة: (3) أقول لمسعود بجرعاء مالك * وقد هم دمعي أن تلج أوائله والدمع لا يجوز عليه العزم.\nومعناه كاد وقرب.\nومنها الشهوة (4) وميل الطبع.\nيقول القائل فيما يشتهيه، ويميل طبعه إليه: هذا أهم الاشياء إلي.\nوفي ضده: ليس هذا من همي! (اللغات) ."},{"id":"furuq-lughawiyya:484","bookId":"furuq-lughawiyya","type":"section","seq":484,"chapter":"* (أ) *","title":"1441 - الفرق بين العزيز والقاهر: أن العزيز هو الممتنع الذي لا ينال بالاذى","page":"ج1 ص357","text":"ولذلك سمي أبو ذؤيب العقاب عزيزة لانها تتخذ وكرها في أعلى الجبل فهي ممتنعة على من يريدها فقال: حتى إنتهيت إلى فراش عزيزة * سوداء روية أنفها كالمخصف ويقال عز يعز اذا صار عزيزا وعز يعز عزا إذا قهر بإقتدار على المنع، والمثل من عزيز والعزاز الارض الصلبة لامتناعها على الحافر بصلابتها كالامتناع من الضيم، والصفة بعزيز لا تتضمن معنى القهر، والصفة بقاهر تتضمن معنى العز يقال قهر فلان فلانا إذا غلبه وصار مقتدرا على إنفاذ أمره فيه."},{"id":"furuq-lughawiyya:485","bookId":"furuq-lughawiyya","type":"section","seq":485,"chapter":"* (أ) *","title":"1442 - الفرق بين العزيز والكريم (1) : قيل: هما بمعنى.","page":"ج1 ص357","text":"وفرق بعضهم بينهما فقال: العزيز يأبى أن يقضى عليه، والكريم يأبى أن يقضى له.\nانتهى.\nقلت: وهذا يرجع إلى معنى العزيز في الاصل، فإنه الغالب الذي لا يفوته شئ، ولا يعجزه شئ.\n(اللغات) ."},{"id":"furuq-lughawiyya:486","bookId":"furuq-lughawiyya","type":"section","seq":486,"chapter":"* (أ) *","title":"1445 - الفرق بين العشق والمحبة: أن العشق شدة الشهوة لنيل المراد من","page":"ج1 ص358","text":"المعشوق إذا كان إنسانا والعزم على مواقعته عند التمكن منه، ولو كان العشق مفارقا للشهوة لجاز أن يكون العاشق خاليا من أن يشتهي النيل ممن يعشقه، إلا أنه شهوة مخصوصة لا تفارق موضعها وهي شهوة الرجل للنيل ممن يعشقه، ولا تسمى شهوته لشرب الخمر وأكل الطيب عشقا، والعشق أيضا هو الشهوة التي إذا أفرطت وإمتنع نيل ما يتعلق بها قتلت صاحبها ولا يقتل من الشهوات غيرها ألا ترى أن أحدا لم يمت من شهوة الخمر والطعام والطيب ولا من محبة داره أو ماله ومات خلق كثير من شهوة الخلوة مع المعشوق والنيل منه."},{"id":"furuq-lughawiyya:487","bookId":"furuq-lughawiyya","type":"section","seq":487,"chapter":"* (أ) *","title":"1448 - الفرق بين عطف البيان وبين الصفة: أن عطف البيان يجري مجرى الصفة في أنه تبيين للاول، ويتبعه في الاعراب كقولك مررت بأخيك زيد إذا كان له","page":"ج1 ص358","text":"زيدا كما لو وافقه في كل شئ لوجب أن يكون له مثل صفته\nولا يجب أن يكون له مثل إسمه.\nقال أبو هلال أيده الله: والبيان عند المتكلمين الدليل الذي تتبين به الاحكام، ولهذا قال أبو علي وأبو هاشم رحمهما الله: الهداية هي الدلالة والبيان فجعلا الدلالة والبيان واحدا، وقال بعضهم هو العلم الحادث الذي يتبين به الشئ، ومنهم من قال: البيان حصر القول دون ما عداه من الادلة، وقال غيره: البيان هو الكلام والحظ والاشارة، وقيل البيان هو الذي أخرج الشئ من حيز الاشكال إلى حد التجلي، ومن قال هو الدلالة ذهب إلى أنه يتوصل بالدلالة إلى معرفة المدلول عليه، والبيان هو ما يصح أن يتبين به ما هو بيان له، وكذلك يقال إن الله قد بين الاحكام بأن دل عليها بنصية الدلالة في الحكم المظهر ظنا، وكذلك يقال للمدلول عليه قد بان، ويوصف الدال بأنه يبين وتوصف الامارات الموصلة إلى غلبة الظن بأنها بيان كما يقال إنها دلالة تشبيها لها بما يوجب العلم من الادلة."},{"id":"furuq-lughawiyya:488","bookId":"furuq-lughawiyya","type":"section","seq":488,"chapter":"* (أ) *","title":"1454 - الفرق بين العظيم والكبير: أن العظيم قد يكون من جهة الكثرة ومن غير جهة الكثرة، ولذلك جاز أن يوصف الله تعالى بأنه عظيم وإن لم يوصف بأنه","page":"ج1 ص360","text":"وفرق بعضهم بين الجليل والكبير بأن قال الجليل في أسماء الله تعالى هو العظيم الشأن المستحق الحمد، والكبير فيما يجب له من صفة الحمد، والاجل بما ليس فوقه من هو أجل منه، وأما الاجل من ملوك الدنيا فهو الذي ينفرد في الزمان بأعلى مراتب الجلالة، والجلال إذا أطلق كان مخصوصا بعظم الشأن، ويقال حكم جليلة للنفع بها ويوصف المال الكثير بأنه جليل ولا يوصف الرمل الكثير بذلك لما كان من عظم النفع في المال، وسميت الجلة جلة لعظمها والمجلة الصحيفة سميت بذلك لما فيها من عظم الحكم والعهود."},{"id":"furuq-lughawiyya:489","bookId":"furuq-lughawiyya","type":"section","seq":489,"chapter":"* (أ) *","title":"1455 - الفرق بين عظيم القوم وكبير القوم: أن عظيم القوم هو الذي ليس فوقه أحد منهم فلا تكون الصفة به إلا مع السؤدد والسلطان فهو مفارق للكبير،","page":"ج1 ص361","text":"عظيما لعظم ما فيه من الآلام والبلاء، وما اتسع لان يكون فيه العظم استحق بأن يوصف أنه عظيم."},{"id":"furuq-lughawiyya:490","bookId":"furuq-lughawiyya","type":"section","seq":490,"chapter":"* (أ) *","title":"1456 - الفرق بين العظيم والمتعظم (1) : قيل: العظيم: الذي جاوز حدود العقول أن تقف على صفات كماله، ونعوت جلاله.","page":"ج1 ص361","text":"وأصل العظم في الاجسام ثم استعمل في مدركات البصائر، وهي متفاوتة في العظم تفاوت الاجسام.\nفما لا يتصور أن يكون (2) يحيط العقل أصلا بكنه حقيقته وصفته منها، فهو العظيم المطلق، وهو الله تعالى.\nوالمتعظم: البليغ العظمة أو (3) المستنكف أن يكون له نظير في عظمته.\n(اللغات) ."},{"id":"furuq-lughawiyya:491","bookId":"furuq-lughawiyya","type":"section","seq":491,"chapter":"* (أ) *","title":"1457 - الفرق بين العفو والصفح (4) : هما بمعنى في اللغة.","page":"ج1 ص361","text":"وقال الراغب: الصفح: ترك التثريب، وهو أبلغ من العفو وقد يعفو الانسان ولا يصفح.\nوقال البيضاوي: العفو ترك عقوبة المذنب، والصفح: ترك لومه.\nقلت: ويدل عليه قوله تعالى: \" فاعفوا واصفحوا \" (5) .\nترقيا في الامر بمكارم الاخلاق من الحسن إلى الاحسن، ومن الفضل إلى الافضل.\n(اللغات) ."},{"id":"furuq-lughawiyya:492","bookId":"furuq-lughawiyya","type":"section","seq":492,"chapter":"* (أ) *","title":"1458 - الفرق بين العفو والعافية والمعافاة (1) : قيل: الاول هو التجاوز عن الذنوب ومحوها.","page":"ج1 ص362","text":"الثاني: دفاع الله - سبحانه - الاسقام والبلايا عن العبد.\nوهو اسم من عافاه الله وأعفاه، وضع موضع المصدر.\nوالثالث: أن يعافيك الله عن الناس ويعافيهم عنك، أي: يغنيك عنهم ويغنيهم عنك، ويصرف أذاهم عنك وأذاك عنهم.\n(اللغات) ."},{"id":"furuq-lughawiyya:493","bookId":"furuq-lughawiyya","type":"section","seq":493,"chapter":"* (أ) *","title":"1459 - الفرق بين العفو والمغفرة (2) : قد فرق بينهما بأن العفو: ترك العقاب على الذنب، والمغفرة: تغطية الذنب بإيجاب المثوبة.","page":"ج1 ص362","text":"ولذلك كثرت المغفرة من صفات الله تعالى دون صفات العباد، فلا يقال: استغفر السلطان كما يقال: استغفر الله.\nوقيل: العفو: إسقاط العذاب.\nوالمغفرة أن يستر عليه بعد ذلك جرمه صونا له عن عذاب الخزي والفضيحة، فإن الخلاص من عذاب النار إنما يطلب إذا حصل عقيبه الخلاص من عذاب الفضيحة.\nفالعفو: إسقاط العذاب الجسماني.\nوالمغفرة: إسقاط العذاب الروحاني، والتجاوز يعمهما.\nوقال الغزالي (3) : في العفو مبالغة ليست في الغفور، فإن الغفران\nينبئ عن الستر والعفو ينبئ عن المحو، وهو أبلغ من الستر، لان السبر للشئ قد يحصل مع إبقاء (1) أصله، بخلاف المحو فإنه إزالته جملة ورأسا.\n(اللغات) ."},{"id":"furuq-lughawiyya:494","bookId":"furuq-lughawiyya","type":"section","seq":494,"chapter":"* (أ) *","title":"الفرق بين العقاب والعذاب","page":"ج1 ص363","text":"أن العقاب ينبئ عن استحقاق وسمي بذلك لان الفاعل يستحقه عقيب فعله، ويجوز أن يكون العذاب مستحقا وغير مستحق، وأصل العقاب التلو وهو تأدية الاول إلى الثاني يقال عقب الثاني الاول إذا تلاه، وعقب الليل النهار، والليل والنهار هما عقيبان، وأعقبه بالغبطة حسرة إذا أبدله بها وعقب باعتذار بعد إساءة وفي التنزيل \" ولى مدبرا ولم يعقب \" (2) أي لم يرجع بعد ذهابه تاليا له مجيئه وفيه \" لا معقب لحكمه \" (3) وتعقبت فلانا تتبعت أمره واستعقبت منه خيرا وشرا أي استبدلت بالاول ما يتلوه من الثاني، وتعاقبا الامر تناوباه بما يتلو كل واحد منهما الآخر وعاقبت اللص بالقطع الذي يتلو سرقته، واعتقب الرجلان العقبة إذا ركبها كل واحد منهما على مناوبة الآخر \" والعاقبة للمتقين \" (4) وعلى المجرمين لانها تعقب المتقين خيرا والمجرمين شرا كما تقول الدائرة لفلان على فلان."},{"id":"furuq-lughawiyya:495","bookId":"furuq-lughawiyya","type":"section","seq":495,"chapter":"* (أ) *","title":"1463 - الفرق بين العقاب والعذاب (1) : الفرق بينهما أن الاول يقتضي بظاهره الجزاء على فعله المعاقب، لانه من التعقيب والمعاقبة.","page":"ج1 ص364","text":"والعذاب ليس كذلك إذ يقال للظالم المبتدي بالظلم إنه معذب.\nوإن قيل معاقب فهو على سبيل المجاز لا الحقيقة.\nفبينهما عموم وخصوص.\n(اللغات) ."},{"id":"furuq-lughawiyya:496","bookId":"furuq-lughawiyya","type":"section","seq":496,"chapter":"* (أ) *","title":"الفرق بين العقد والعهد","page":"ج1 ص364","text":"أن العقد أبلغ من العهد تقول عهدت إلى فلان بكذا أي ألزمته إياه وعقدت عليه وعاقدته ألزمته باستيثاق وتقول عاهد العبد ربه ولا تقول عاقد العبد ربه إذ لا يجوز أن يقال إستوثق من ربه وقال تعالى \" أوفوا بالعقود \" (2) وهي ما يتعاقد عليه إثنان وما يعاهد العبد ربه عليه، أو يعاهده ربه على لسان نبيه عليه السلام، ويجوز أن يكون العقد ما يعقد بالقلب واللغو ما يكون غلطا والشاهد قوله تعالى \" ولكن يؤاخذكم بما كسبت قلوبكم \" (3) ولو كان العقد هو اليمين لقال تعالى: ولكن يؤاخذكم بما عقدتم أي حلفتم ولم يذكر الايمان فلما أتى بالمعقود به الذي وقع به العقد علم أن العقد غير اليمين، وأما قول القائل: إن فعلت كذا فعبدي حر فليس ذلك\nبيمين في الحقيقة وإنما هو شرط وجزاء به، فمتى وقع الشرط وجب الجزاء فسمي ذلك يمينا مجازا وتشبيها كأن الذي يلزمه من العتق مثل ما يلزم المقسم من الحنث، وأما قول القائل عبده حر وامرأته طالق فخبر مثل قولك عبدي قائم إلا أنه ألزم نفسه في قوله عبدي حر عتق العبد فلزمه ذلك ولم يكن في قوله عبدي قائم إلزام."},{"id":"furuq-lughawiyya:497","bookId":"furuq-lughawiyya","type":"section","seq":497,"chapter":"* (أ) *","title":"1466 - الفرق بين العقد والعهد (1) : قيل: الفرق بينهما أن العقد فيه معنى الاستيثاق والشد، ولا يكون إلا بين متعاقدين.","page":"ج1 ص365","text":"والعهد قد ينفرد به الواحد فبينهما عموم وخصوص.\n(اللغات) ."},{"id":"furuq-lughawiyya:498","bookId":"furuq-lughawiyya","type":"section","seq":498,"chapter":"* (أ) *","title":"1472 - الفرق بين العقل والعلم: أن العقل هو العلم الاول الذي يزجر عن القبائح وكل من كان زاجره أقوى كان أعقل، وقال بعضهم العقل","page":"ج1 ص366","text":"يمنع صاحبه عن الوقوع في القبيح وهو من قولك عقل البعير إذا شده فمنعه من أن يثور ولهذا لا يوصف الله تعالى به، وقال بعضهم العقل الحفظ يقال أعقلت دراهمي أي حفظتها وأنشد قول لبيد: وأعقلي إن كنت لما تعقلي * ولقد أفلح من كان عقل قال ومن هذا الوجه يجوز أن يقال ان الله عاقل كما يقال له حافظ إلا أنه لم يستعمل فيه ذلك، وقيل العاقل يفيد معنى الحصر والحبس، وعقل الصبي إذا وجد له من المعارف ما يفارق به حدود الصبيان وسميت المعارف التي تحصر معلوماته عقلا لانها أوائل العلوم ألا ترى انه يقال للمخاطب اعقل ما يقال لك أي احصر معرفته لئلا يذهب عنك، وخلاف العقل الحمق وخلاف العلم الجهل، وقيل لعاقلة الرجل عاقلة لانهم يحبسون عليه حياته، والعقال ما يحبس الناقة عن الانبعاث، قال وهذا أحب إلي في حد العقل من قولهم هو علم بقبح القبائح والمنع من ركوبها لان في أهل الجنة عقلا لا يشتهون القبائح وليست علومهم منعا، ولو كان العقل منعا لكان الله تعالى عاقلا لذاته وكنا معقولين لانه الذي منعنا، وقد يكون الانسان عاقلا كاملا مع ارتكابه القبائح، ولما لم يجز أن يوصف الله بأن له علوما حصرت معلوماته لم يجز أن يسمى عاقلا وذلك أنه عالم لذاته بما لا نهاية له من المعلومات، ولهذه العلة لم يجز أن يقال ان الله معقول لنا لانه لا يكون محصورا بعلومنا كما لا تحيط به علومنا."},{"id":"furuq-lughawiyya:499","bookId":"furuq-lughawiyya","type":"section","seq":499,"chapter":"* (أ) *","title":"1475 - الفرق بين العكوف والاقامة: أن العكوف هو الاقبال على الشئ","page":"ج1 ص366","text":"والاحتباس فيه، ومنه قول الراجز: باتت بيتا حوضها عكوفا، ومنه الاعتكاف لان صاحبه مقبل عليه يحبس فيه غير مشتغل بغيره والاقامة لا تقتضي ذلك."},{"id":"furuq-lughawiyya:500","bookId":"furuq-lughawiyya","type":"section","seq":500,"chapter":"* (أ) *","title":"1483 - الفرق بين علام وعلامة: أن الصفة بعلام صفة مبالغة وكذلك كل ما كان على فعال، وعلامة وإن كان للمبالغة فإن معناه ومعنى دخول","page":"ج1 ص368","text":"الهاء فيه أنه يقوم مقام جماعة علماء فدخلت الهاء فيه لتأنيث الجماعة التي هي في معناه، ولهذا يقال الله علام ولا يقال له علامة كما يقال إنه يقوم مقام جماعة علماء، فأما قول من قال إن الهاء دخلت في ذلك على معنى الداهية فإن إبن درستويه رده واحتج فيه بأن الداهية لم توضع للمدح خاصة ولكن يقال في الذم والمدح وفي المكروه والمحبوب قال وفي القرآن \" والساعة أدهى وأمر \" (1) وقال الشاعر: لكل أخي عيش وإن طال عمره * دويهية تصفر منها الأنامل يعني الموت، ولو كانت الداهية صفة مدح خاصة لكان ما قاله مستقيما وكذلك قوله لحانة شبهوه بالبهيمة غلط لان البهيمة لا تلحن وإنما يلحن من يتكلم، والداهية إسم من أسماء الفاعلين الجارية على الفعل يقال دهى يدهي فهو داه وللانثى داهية ثم يلحقها التأنيث على ما يراد به للمبالغة فيستوي فيه الذكر والانثى مثل الرواية ويجوز أن يقال إن الرجل سمي داهية كأنه يقوم مقام جماعة دهاة، وراوية كأنه يقوم مقام جماعة رواة على ما ذكر قبل وهو قول المبرد."},{"id":"furuq-lughawiyya:501","bookId":"furuq-lughawiyya","type":"section","seq":501,"chapter":"* (أ) *","title":"الفرق بين العلة والسبب","page":"ج1 ص369","text":"أن من العلة ما يتأخر عن المعلول كالربح وهو علة التجارة يتأخر ويوجد بعدها والدليل على أنه علة لها أنك تقول إذا قيل لك لم تتجر قلت للربح.\nوقد أجمع أهل العربية أن قول القائل لم مطالبة بالعلة لا بالسبب فإن قيل ما أنكرت إن الربح علة لحسن التجارة وسبب له أيضا، قلنا أول ما في ذلك أنه يوجب أن كل تجارة فيها ربح حسنة لانه قد حصل فيها علة الحسن، كما أن كل ما حصل فيه ربح فهو تجارة، والسبب لا يتأخر عن مسببه على وجه من الوجوه، ألا ترى أن الرمي الذي هو سبب لذهاب السهم لا يجوز أن يكون بعد ذهاب السهم، والعلة في اللغة ما يتغير حكم غيره به ومن ثم قيل للمرض علة لانه يغير حال المريض ويقال للداعي إلى الفعل علة له تقول فعلت كذا لعلة كذا، وعند بعض المتكلمين أن العلة ما توجب حالا لغيره كالكون والقدرة ولا تقول ذلك في السواد لما لم يوجب حالا، والعلة في الفقه ما تعلق الحكم به من صفات الاصل المنصوص عليه عند القايس."},{"id":"furuq-lughawiyya:502","bookId":"furuq-lughawiyya","type":"section","seq":502,"chapter":"* (أ) *","title":"1486- الفرق بين العلة والسبب","page":"ج1 ص369","text":"الفرق بين العلة والسبب (1) : قال الطبرسي (2) : الفرق بينهما في عرف المتكلمين: أن السبب ما يوجب ذاتا، والعلة (3) ما توجب صفة.\n(اللغات) ."},{"id":"furuq-lughawiyya:503","bookId":"furuq-lughawiyya","type":"section","seq":503,"chapter":"* (أ) *","title":"الفرق بين العلم والشعور","page":"ج1 ص371","text":"أن العلم هو ما ذكرناه (1) : والشعور علم يوصل إليه من وجه دقيق كدقة الشعر ولهذا قيل للشاعر شاعر لفطنته لدقيق المعاني، وقيل للشعير شعيرا للشظية الدقيقة التي في طرفه خلاف الحنطة، ولا يقال الله تعالى يشعر لان الاشياء لا تدق عنه، وقال بعضهم الذم للانسان بأنه لا يشعر أشد مبالغة من ذمه بأنه لا يعلم لانه إذا قال لا يشعر فكأنه أخرجه إلى معنى الحمار وكأنه قال لا يعلم من وجه واضح ولا خفي وهو كقولك لا يحس، وهذا قول من يقول إن الشعور هو أن يدرك بالمشاعر وهي الحواس كما أن الاحساس هو الادراك بالحاسة ولهذا لا يوصف الله بذلك."},{"id":"furuq-lughawiyya:504","bookId":"furuq-lughawiyya","type":"section","seq":504,"chapter":"* (أ) *","title":"1501 - الفرق بين العلم والشعور (1) : قال الطبرسي: الشعور: هو ابتداء العلم بالشئ من جهة المشاعر وهي الحواس.","page":"ج1 ص372","text":"ولذلك لا يوصف تعالى بأنه شاعر ولا بأنه يشعر، وإنما يوصف بأنه عالم، ويعلم.\nوقيل: إن الشعور هو إدراك ما دق للطف الحس، مأخوذ من\nالشعر لدقته.\nومنه الشاعر، لانه يفطن من إقامة الوزن وحسن النظر لما لا يفطن له غيره.\n(اللغات) ."},{"id":"furuq-lughawiyya:505","bookId":"furuq-lughawiyya","type":"section","seq":505,"chapter":"* (أ) *","title":"الفرق بين العلم واليقين","page":"ج1 ص372","text":"(2) : قد سبق تعريف العلم، وأما اليقين\nفهو العلم بالشئ استدلالا بعد أن كان صاحبه شاكا فيه.\nقبل: ولذك لا يوصف الباري - سبحانه - بأنه متيقن.\nولا يقال: تيقنت أن السماء فوقي.\nفكل يقين علم، وليس كل علم يقينا.\nوقيل: هو العلم بالحق مع العلم بأنه لا يكون غيره، ولذلك قال المحقق الطبرسي: هو مركب من علمين.\n(اللغات) ."},{"id":"furuq-lughawiyya:506","bookId":"furuq-lughawiyya","type":"section","seq":506,"chapter":"* (أ) *","title":"1512 - الفرق بين العلو والرفعة: ذيل (1019) .","page":"ج1 ص373","text":"(*)"},{"id":"furuq-lughawiyya:507","bookId":"furuq-lughawiyya","type":"section","seq":507,"chapter":"* (أ) *","title":"1513 - الفرق بين العلي والمتعال (1) : العلي: الذي رتبته أعلى المراتب العقلية، وهي المرتبة العلية، فإن ذاته المقدسة هي مبدأ كل موجود حسي وعقل","page":"ج1 ص374","text":"والمتعالي هو المستعلي على كل شئ بقدرته، أو المتنزه عن نعوت\nالمخلوقات وعن كل شئ (2) لا يجوز عليه في ذاته وصفاته وأفعاله.\n(اللغات) ."},{"id":"furuq-lughawiyya:508","bookId":"furuq-lughawiyya","type":"section","seq":508,"chapter":"* (أ) *","title":"1514 - الفرق بين الصفة منه عزوجل بأنه علي وبين الصفة للسيد من العباد بأنه رفيع: أن الصفة بعلي منقولة إلى علم إنسان بالقهر والاقتدار ومنه \" ا","page":"ج1 ص375","text":"الصفة برفيع لا تجوز على الله تعالى لان الارتفاع يقتضي الزوال.\nفأما قوله تعالى \" رفيع الدرجات \" (1) فهو كقوله كثير الاحسان في أن الصفة للثاني في الحقيقة."},{"id":"furuq-lughawiyya:509","bookId":"furuq-lughawiyya","type":"section","seq":509,"chapter":"* (أ) *","title":"1516 - الفرق بين العمرى والرقبى: أن العمرى هي أن يقول الرجل للرجل","page":"ج1 ص375","text":"هذه الدار لك عمرك أو عمري، والرقبى أن يقول إن مت قبلي رجعت إلي وإن مت قبلك فهي لك، وذلك أن كل واحد منهما وقت موت صاحبه."},{"id":"furuq-lughawiyya:510","bookId":"furuq-lughawiyya","type":"section","seq":510,"chapter":"* (أ) *","title":"1517 - الفرق بين العمل والجعل: أن العمل هو إيجاد الاثر في الشئ على ما ذكرنا (2) ، والجعل تغيير صورته بايجاد الاثر فيه وبغير ذلك، ألا ترى انك","page":"ج1 ص376","text":"فدل على تحلل شيئا بعد شئ، وجاء أيضا بمعنى الخبر في قوله تعالى \" وجعلوا الملائكة الذين هم عباد الرحمن اناثا \" (1) أي أخبروا بذلك، وبمعنى الحكم في قوله تعالى \" أجعلتم سقاية الحاج \" (2) أي حكمتم بذلك، ومثله جعله الله حراما وجعله حلالا أي حكم بتحليله وتحريمه، وجعلت المتحرك متحركا أي جعلت ماله صار متحركا، وله\nوجوه كثيرة أوردناها في كتاب الوجوه والنظائر، والجعل أصل الدلالة على الفعل لانك تعلمه ضرورة وذلك أنك إذا رأيت دارا مهدمة ثم رأيتها مبنية علمت التغير ضرورة ولم تعلم حدوث شئ إلا بالاستدلال."},{"id":"furuq-lughawiyya:511","bookId":"furuq-lughawiyya","type":"section","seq":511,"chapter":"* (أ) *","title":"1518 - الفرق بين العمل والفعل: أن العمل إيجاد الاثر في الشئ يقال فلان يعمل الطين خزفا ويعمل الخوص زنبيلا والاديم سقاء، ولا يقال يفعل ذلك لان","page":"ج1 ص377","text":"أي من الدؤوب في السير، وقال غيره: * والبرق يحدث شوقا كلما عملا * ويقال عمل الرجل يعمل واعتمل إذا عمل بنفسه وأنشد الخليل:\nإن الكريم وأبيك يعتمل * إن لم يجد يوما على من يتكل"},{"id":"furuq-lughawiyya:512","bookId":"furuq-lughawiyya","type":"section","seq":512,"chapter":"* (أ) *","title":"1525 - الفرق بين العهد والوعد: أن العهد ما كان من الوعد مقرونا بشرط نحو قولك إن فعلت كذا فعلت كذا وما دمت على ذلك فأنا عليه، قال الله تعالى","page":"ج1 ص378","text":"يقتضي الايجاز، ويقال نقض العهد وأخلف الوعد."},{"id":"furuq-lughawiyya:513","bookId":"furuq-lughawiyya","type":"section","seq":513,"chapter":"* (أ) *","title":"1526 - الفرق بين العوج والعوج (2) - بالكسر والفتح -: الاول في المعاني، والثاني في الاعيان.","page":"ج1 ص378","text":"قال في الكشاف عند تفسير قوله تعالى: \" فيذرها قاعا صفصفا لا ترى فيها عوجا ولا أمتا \" (3) : فإن قلت: الارض عين فكيف صح فيها مكسور العين؟ قلت: اعتبار هذا اللفظ له موقع حسن بديع في وصف الارض بالاستواء ونفي الاعوجاج.\nوذلك أنك لو عمدت إلى قطعة أرض وبالغت في تسويتها على عيون البصراء، واتفقوا على أنه لم يكن فيها اعوجاج، ثم استطلعت، رأي المهندس فيها، وأمرته أن يعرض استواءها على المقاييس الهندسية، لعثر فيها على عوج لا يدرك بحاسة البصر.\nفنفى الله ذلك العوج الذي لطف عن الادراك إلا بمقاييس الهندسة.\nوذلك الاعوجاج لما لم يدرك إلا بالقياس دون الاحساس لحق بالمعاني، فقيل: فيه (عوج) بالكسر.\n(اللغات) ."},{"id":"furuq-lughawiyya:514","bookId":"furuq-lughawiyya","type":"section","seq":514,"chapter":"* (أ) *","title":"1528 - الفرق بين العوض والبدل: أن العوض ما تعقب به الشئ على جهة المثامنة تقول هذا الدرهم عوض من خاتمك وهذا الدينار عوض من ثوبك ولهذا يسمى ما","page":"ج1 ص379","text":"ترى انك تقول لمن أساء ألى من أحسن إليه أنه بدل نعمته كفرا لانه أقام الكفر مقام الشكر فلا تقول عوضه كفرا لان معنى المثامنة لا يصح في ذلك، ويجوز أن يقال العوض هو البدل الذي ينتفع به وإذا لم يجعل على الوجه الذي ينتفع به لم يسم عوضا، والبدل هو الشئ الموضوع مكان غيره لينتفع به أو لا، قال إبن دريد: الابدال جمع بديل مثل أشراف وشريف وفنيق وأفناق، وقد يكون البدل الخلف من الشئ، والبدل عند النحويين مصدر سمي به الشئ الموضوع مكان آخر قبله جاريا عليه حكم الاول وقد يكون من جنسه وغير جنسه ألا ترى أنك تقول مررت برجل زيد فتجعل زيدا بدلا من رجل وزيد معرفة ورجل نكرة والمعرفة من غير جنس النكرة."},{"id":"furuq-lughawiyya:515","bookId":"furuq-lughawiyya","type":"section","seq":515,"chapter":"* (أ) *","title":"1529 - الفرق بين البدل والثمن والعوض (1) : البدل: هو الشئ الذي يجعل مكان غيره.","page":"ج1 ص379","text":"والثمن: هو البدل في البيع من العين أو الورق.\nوإذا استعمل في غيرهما كان مشبها بهما كقوله تعالى: \" ولا تشتروا بآياتى ثمنا\nقليلا \" (1) .\nإن المراد به الرئاسة، والجاه والحطام الدنية الدنيوية.\nوالعوض: هو البدل الذي ينتفع به كائنا ما كان.\n(اللغات)"},{"id":"furuq-lughawiyya:516","bookId":"furuq-lughawiyya","type":"section","seq":516,"chapter":"* (أ) *","title":"1531 - الفرق بين العوض والثواب: أن العوض يكون على فعل العوض، والثواب لا يكون على فعل المثيب وأصله المرجوع وهو ما يرجع إليه","page":"ج1 ص380","text":"العامل، والثواب من الله تعالى نعيم يقع على وجه الاجلال وليس كذلك العوض لانه يستحق بالالم فقط وهو مثامنة من"},{"id":"furuq-lughawiyya:517","bookId":"furuq-lughawiyya","type":"section","seq":517,"chapter":"* (أ) *","title":"غ","page":"ج1 ص380","text":"ير تعظيم فالثواب يقع على جهة المكافأة على الحقوق والعوض يقع على جهة المثامنة في البيوع."},{"id":"furuq-lughawiyya:518","bookId":"furuq-lughawiyya","type":"section","seq":518,"chapter":"* (أ) *","title":"1535 - الفرق بين غاية الشئ والمدى: أن أصل الغاية الراية وسميت نهاية الشئ غايته لان كل قوم ينتهون إلى غايتهم في الحرب أي رايتهم، ثم كثر حتى ق","page":"ج1 ص381","text":"يعني مدى العمر والمعنى ان الامل منفسح لما بينه وبين الموت، ومن ذلك قولهم هو مني مدى البصر أي هو حيث يناله بصري كأن بصري ينفسح بيني وبينه، ثم كثر ذلك حتى قيل للغاية مدى كما يسمى الشئ بإسم ما يقرب منه."},{"id":"furuq-lughawiyya:519","bookId":"furuq-lughawiyya","type":"section","seq":519,"chapter":"* (أ) *","title":"1536 - الفرق بين الغبط والحسد: أن الغبط هو أن تتمنى أن يكون مثل حال المغبوط لك من غير أن تريد زوالها عنه، والحسد أن تتمنى أن تكون حاله لك دو","page":"ج1 ص381","text":"بالنعمة، والغبطة الحالة الحسنة التي يغبط عليها صاحبها."},{"id":"furuq-lughawiyya:520","bookId":"furuq-lughawiyya","type":"section","seq":520,"chapter":"* (أ) *","title":"1537 - الفرق بين الغداة والأصيل والبكرة والعشاء والعشي والمساء: أن الغداة إسم لوقت والبكرة فعلة من بكر يبكر بكورا ألا ترى انه يقال صلاة الغد","page":"ج1 ص382","text":"يبادر حاجة قد أمسيت وذلك على المبالغة."},{"id":"furuq-lughawiyya:521","bookId":"furuq-lughawiyya","type":"section","seq":521,"chapter":"* (أ) *","title":"1541 - الفرق بين الغرور والخدع: أن الغرور إيهام يحمل الانسان على فعل ما يضره مثل أن يرى السراب فيحسبه ماء فيضيع ماءه فيهلك عطشا وتضييع الماء","page":"ج1 ص382","text":"ففعل آدم الاكل الضار له.\nوالخدع أن يستر عنه وجه الصواب فيوقعه في مكروه، وأصله من قولهم خدع الضب إذا توارى في حجره وخدعه في الشراء أو البيع إذا أظهر له خلاف ما أبطن فضره في ماه، وقال علي بن عيسى: الغرور إيهام حال السرور فيما الامر بخلافه في المعلوم وليس كل إيهام غرورا لانه قد يوهمه مخوفا ليحذر منه فلا يكون قد غره، والاغترار ترك الحزم فيما يمكن أن يتوثق فيه فلا عذر في ركوبه، ويقال في الغرور غره فضيع ماله وأهلك نفسه، والغرور قد يسمى خدعا، والخدع يسمى غرورا على التوسع والاصل ما قلناه، واصل الغرور الغفلة، والغر الذي لم يجرب الامور يرجع إلى هذا فكأن الغرور يوقع المغرور فيما هو غافل عنه من الضرر، والخدع مرجع يستر عنه وجه الامر."},{"id":"furuq-lughawiyya:522","bookId":"furuq-lughawiyya","type":"section","seq":522,"chapter":"* (أ) *","title":"1542 - الفرق بين الغرور والوهم (1) : قيل: الغرور: إيهام حال السرور فيما الامر بخلافه في المعلوم، وليس كل وهم غرورا، لانه قد يتوهمه مخوفا","page":"ج1 ص383","text":"فيحذر منه، فلا يقال: غره.\n(اللغات) ."},{"id":"furuq-lughawiyya:523","bookId":"furuq-lughawiyya","type":"section","seq":523,"chapter":"* (أ) *","title":"1544 - الفرق بين الغزو والجهاد (2) : الغزو: إنما يكون في بلاد العدو.","page":"ج1 ص383","text":"والجهاد: مطلق، فكل غاز مجاهد، دون العكس.\n* كذا قيل، والاظهر في الفرق أن يقال أن الغزو ما كان الغرض\nالاصلي فيه الغنيمة، وتحصيل المال - وإن استلزم ذلك الحرب والمقاتلة.\nوالجهاد: ما كان الغرض فيه المحاربة لقهر العدو - وإن استلزم ذلك تحصيل الغنائم والفوائد (1) *.\n(اللغات) ."},{"id":"furuq-lughawiyya:524","bookId":"furuq-lughawiyya","type":"section","seq":524,"chapter":"* (أ) *","title":"1545 - الفرق بين الغشاء والغطاء: أن الغشاء قد يكون رقيقا يبين ما تحته ويتوهم الرائي أنه لا شئ عليه لرقته، ومن ثم سميت أغشية البدن وهي أعصاب","page":"ج1 ص384","text":"موضع الغطاء فعلى التوسع."},{"id":"furuq-lughawiyya:525","bookId":"furuq-lughawiyya","type":"section","seq":525,"chapter":"* (أ) *","title":"1547 - الفرق بين الغضب وإرادة الانتقام: أن الغضب معنى يقتضي العقاب","page":"ج1 ص385","text":"من طريق جنسه من غير توطين النفس عليه ولا يغير حكمه، وليس كذلك الارادة لانها تقدمت فكانت عما توطن النفس على الفعل فإذا صحبت الفعل غيرت حكمه، وليس كذلك الغضب، وأيضا فإن المغضوب عليه من نظير المراد وهو مستقل."},{"id":"furuq-lughawiyya:526","bookId":"furuq-lughawiyya","type":"section","seq":526,"chapter":"* (أ) *","title":"1556 - الفرق بين الغفران والستر: أن الغفران أخص وهو يقتضي إيجاب الثواب.","page":"ج1 ص386","text":"والستر سترك الشئ بستر ثم استعمل في الاضراب عن ذكر الشئ فيقال ستر فلان على فلان إذا لم يذكر ما اطلع عليه من عثراته وستر الله عليه خلاف فضحه ولا يقال لمن يستر عليه في الدنيا إنه غفر له لان الغفران ينبئ عن إستحقاق الثواب على ما ذكرنا ويجوز أن يستر في الدنيا على الكافر والفاسق."},{"id":"furuq-lughawiyya:527","bookId":"furuq-lughawiyya","type":"section","seq":527,"chapter":"* (أ) *","title":"1557 - الفرق بين الغفران والصفح: أن الغفران ما ذكرناه (1) .","page":"ج1 ص386","text":"والصفح التجاوز عن الذنب من قولك صفحت الورقة إذا تجاوزتها وقيل هو ترك مؤاخذة المذنب بالذنب وإن تبدي له صفحة جميلة ولهذا لا يستعمل في الله تعالى."},{"id":"furuq-lughawiyya:528","bookId":"furuq-lughawiyya","type":"section","seq":528,"chapter":"* (أ) *","title":"1558 - الفرق بين الغفران والعفو: أن الغفران يقتضي إسقاط العقاب وإسقاط العقاب هو إيجاب الثواب فلا يستحق الغفران إلا المؤمن المستحق للثواب، وه","page":"ج1 ص386","text":"ولا يقال غفر زيد لك إلا شاذا قليلا والشاهد على شذوذه أنه لا يتصرف في صفات العبد كما يتصرف في صفات الله تعالى، ألا ترى انه يقال إستغفرت الله تعالى ولا يقال إستغفرت زيدا.\nوالعفو يقتضي\nإسقاط اللوم والذم ولا يقتضي إيجاب الثواب، ولهذا يستعمل في العبد فيقال عفا زيد عن عمرو وإذا عفا عنه لم يجب عليه إثابته، إلا أن العفو والغفران لما تقارب معناهما تداخلا واستعملا في صفات الله جل إسمه على وجه واحد فيقال عفا الله عنه وغفر له بمعنى واحد، وما تعدى به اللفظان يدل على ما قلنا وذلك أنك تقول عفا عنه فيقتضي ذلك إزالة شئ عنه وتقول غفر له فيقتضي ذلك إثبات شئ له."},{"id":"furuq-lughawiyya:529","bookId":"furuq-lughawiyya","type":"section","seq":529,"chapter":"* (أ) *","title":"1559 - الفرق بين قوله لا يغفر أن يشرك به وقوله لا يغفر الشرك به: فيما قال علي بن عيسى: إن لا تدل على الاستقبال وتدل على وجه الفعل في الارادة","page":"ج1 ص387","text":"والفرق من جهة اخرى أن المصدر لا يدل على زمان وان يفعل على (1) يدل على زمان ففي قولك إن مع الفعل زيادة ليست في الفعل."},{"id":"furuq-lughawiyya:530","bookId":"furuq-lughawiyya","type":"section","seq":530,"chapter":"* (أ) *","title":"الفرق بين الغفلة والسهو","page":"ج1 ص387","text":"أن الغفلة تكون عما يكون، والسهو يكون عما لا يكون تقول غفلت عن هذا الشئ حتى كان ولا تقول سهوت عنه حتى كان لانك إذا سهوت عنه لم يكن ويجوز أن تغفل عنه ويكون، وفرق آخر أن الغفلة تكون عن فعل الغير تقول كنت غافلا عما كان من فلان ولا يجوز أن يسهى عن فعل الغير."},{"id":"furuq-lughawiyya:531","bookId":"furuq-lughawiyya","type":"section","seq":531,"chapter":"* (أ) *","title":"1561- الفرق بين الغفلة والسهو","page":"ج1 ص387","text":"الفرق بين الغفلة والسهو (2) : قيل: السهو عدم التفطن للشئ مع بقاء صورته أو معناه في الخيال أو الذكر بسبب اشتغال النفس\nوالتفاتها إلى بعض مهماتها.\nوالغفلة: عدم حضور الشئ في البال بالفعل.\nفهي أعم من السهو ولما كان ذلك من لواحق الفوى الانسانية كان مسلوبا عن الملائكة.\n(اللغات) ."},{"id":"furuq-lughawiyya:532","bookId":"furuq-lughawiyya","type":"section","seq":532,"chapter":"* (أ) *","title":"1562 - الفرق بين الغفلة والنسيان (1) : الغفلة: عبارة عن عدم التفطن للشئ وعدم عقليته بالفعل، سواء بقيت صورتها أو معناه في الخيال، أو الذكر، أ","page":"ج1 ص388","text":"وهي أعم من النسيان، لانه عبارة عن الغفلة عن الشئ مع انمحاء صورته أو معناه عن الخيال، أو الذكر، بالكلية، ولذلك يحتاج الناسي إلى تجشم كسب جديد وكلفة في تحصيله ثانيا.\nكذا حققه بعض المتأخرين.\n(اللغات) ."},{"id":"furuq-lughawiyya:533","bookId":"furuq-lughawiyya","type":"section","seq":533,"chapter":"* (أ) *","title":"1563 - الفرق بين الغلبة والقدرة: أن الغلبة من فعل الغالب وليست القدرة من فعل القادر يقال غلب خصمه غلبا كما تقول طلب طلبا وفي القرآن \" وهم من","page":"ج1 ص388","text":"والقاهر القادر على المستعصب من الامور."},{"id":"furuq-lughawiyya:534","bookId":"furuq-lughawiyya","type":"section","seq":534,"chapter":"* (أ) *","title":"1564 - الفرق بين الغلبة والقهر: أن الغلبة تكون بفضل القدرة وبفضل العلم","page":"ج1 ص389","text":"يقال قاتله فغلبه وصارعه فغلبه وذلك لفضل قدرته وتقول حاجه فغلبه ولاعبه بالشطرنج فغلبه بفضل علمه وفطنته، ولا يكون القهر إلا بفضل القدرة، ألا ترى أنك تقول ناوأه فقهره ولا تقول حاجه فقهره ولا تقول قهره بفضل علمه كما تقول غلبه بفضل علمه."},{"id":"furuq-lughawiyya:535","bookId":"furuq-lughawiyya","type":"section","seq":535,"chapter":"* (أ) *","title":"الفرق بين الغنيمة والفئ","page":"ج1 ص389","text":"(1) : الغنيمة: ما أخذ من أموال أهل\nالحرب من الكفار بقتال، وهي للمسلمين هبة من الله عزوجل لهم.\nوالفئ: ما اخذ بغير قتال، وهو خاص للنبي صلى الله عليه وآله، ومن بعده للامام.\nوهو المروي عن الائمة عليهم السلام.\nفلا عبرة بقول من قال: هما واحد (1) .\n(اللغات) ."},{"id":"furuq-lughawiyya:536","bookId":"furuq-lughawiyya","type":"section","seq":536,"chapter":"* (أ) *","title":"1573 - الفرق بين الغيث والمطر (2) : الغيث: المطر الذي يغيث من الجدب.","page":"ج1 ص390","text":"وكان نافعا في وقته.\nوالمطر: قد يكون نافعا وقد يكون ضارا في وقته، وفي غير وقته، قاله الطبرسي.\n(اللغات) ."},{"id":"furuq-lughawiyya:537","bookId":"furuq-lughawiyya","type":"section","seq":537,"chapter":"* (أ) *","title":"الفرق بين الغيظ والغضب","page":"ج1 ص390","text":"(3) : قد فرق بينهما بأن الغضب ضد الرضا، وهو إرادة العقاب المستحق بالمعاصي.\nوالغيظ: هيجان [22 / ب] الطبع بكثرة (1) ما يكون من المعاصي، ولذلك يقال: (غضب الله على الكفار) ، ولا يقال: اغتاظ منهم.\nوعرف الغزالي وغيره الغضب بأنه: غليان دم القلب لطلب الانتقام.\nوعلى هذا فالغيظ والغضب مترادفان، ويكون إطلاق الغضب عليه - تعالى - باعتبار غاية الغاية كأكثر الصفات، فإنها باعتبار الغايات لا المبادي.\n(اللغات) ."},{"id":"furuq-lughawiyya:538","bookId":"furuq-lughawiyya","type":"section","seq":538,"chapter":"* (أ) *","title":"1577 - الفرق بين الغي والضلال: أن أصل الغي الفساد ومنه يقال غوى الفصيل إذا بشم من كثرة شرب اللبن وإذا لم يرو من لبن امه فمات هزلا.","page":"ج1 ص391","text":"فالكلمة من الأضداد، وأصل الضلال الهلاك ومنه قولهم ضلت الناقة إذا هلكت بضياعها وفي القرآن \" أءذا ضللنا في الارض \" (2) أي هلكنا بتقطع أوصالنا فالذي يوجبه أصل الكلمتين أن يكون الضلال عن الدين أبلغ من الغي فيه ويستعمل الضلال أيضا في الطريق كما يستعمل في الدين فيقال ضل عن الطريق إذا فارقه ولا يستعمل الغي إلا في الدين خاصة فهذا فرق آخر وربما استعمل\nالغي في الخيبة يقال غوى الرجل إذا خاب في مطلبه وأنشد قول\nالشاعر: فمن يلق خيرا يحمد الناس أمره * ومن يغو لا يعدم على الغي لائما وقيل أيضا معنى البيت أن من يفعل الخير يحمد ومن يفعل الشر يذم فجعل من المعنى الاول ويقال أيضا ضل عن الثواب ومنه قوله تعالى \" كذلك يضل الله الكافرين \" (1) والضلال بمعنى الضياع يقال هو ضال في قومه أي ضائع ومنه قوله تعالى \" ووجدك ضالا فهدى \" (2) أي ضائعا في قومك لا يعرفون منزلتك ويجوز أن يكون ضالا أي في قوم ضالين لان من أقام في قوم نسب إليهم كما قيل خالد الحذاء لنزوله بين الحذائين وأبو عثمان المازني لاقامته في بني مازن لم يكن منهم، وقال أبو علي رحمة الله: \" ووجد ضالا فهدى \" (3) أي وجدك ذاهبا إلى النبوة فهي ضالة عنك كما قال تعالى \" أن تضل إحداهما \" (4) وإنما الشهادة هي الضلالة عنها وهذا من المقلوب المستفيض في كلامهم ويكون الضلال الابطال ومنه \" أضل أعمالهم \" (5) أي أبطلها، ومنه \" ألم يجعل كيدهم في تضليل \" (6) ويقال ضللني فلان أي سماني ضالا، والضلال يتصرف في وجوه لا يتصرف الغي فيها."},{"id":"furuq-lughawiyya:539","bookId":"furuq-lughawiyya","type":"section","seq":539,"chapter":"* (أ) *","title":"1579 - الفرق بين الغواية والضلال (1) : قال النيسابوري * عند تفسير قوله تعالى: \" ما ضل صاحبكم وما غوى \" (2) : الظاهر أن الضلال أعم، وهو أن لا","page":"ج1 ص393","text":"والغواية: أن لا يكون المقصد طريقا، فكأنه - سبحانه - نفى الاعم أولا، ثم نفى عنه الاخص، ليفيد أنه على الجادة، غير منحرف عنها أصلا.\n(اللغات) ."},{"id":"furuq-lughawiyya:540","bookId":"furuq-lughawiyya","type":"section","seq":540,"chapter":"* (أ) *","title":"1585 - الفرق بين قولنا فاض وبين قولنا سال: أنه يقال فاض إذا سال بكثرة ومنه الافاضة من عرفة وهو أن يندفعوا منها بكثرة.","page":"ج1 ص394","text":"وقولنا سال لا يفيد الكثرة، ويجوز أن يقال فاض إذا سال بعد الامتلاء وسال على كل وجه."},{"id":"furuq-lughawiyya:541","bookId":"furuq-lughawiyya","type":"section","seq":541,"chapter":"* (أ) *","title":"1589 - الفرق بين الفتح والفصل: أن الفتح هو الفصل بين الشيئين ليظهر ما وراءهما ومنه فتح الباب ثم اتسع فيه فقيل فتح إلى المعنى فتحا إذا","page":"ج1 ص395","text":"كشفه، وسمت الامطار فتوحا والفاتح الحاكم وقد فتح بينهما أي حكم ومنه قوله تعالى \" افتح بيننا وبين قومنا بالحق \" (2) ."},{"id":"furuq-lughawiyya:542","bookId":"furuq-lughawiyya","type":"section","seq":542,"chapter":"* (أ) *","title":"1591 - الفرق بين الفتنة والاختبار: أن الفتنة أشد الاختبار وأبلغه، وأصله عرض الذهب على النار لتبين صلاحه من فساده ومنه قوله تعالى","page":"ج1 ص396","text":"\" يوم هم على النار يفتنون \" (1) ويكون في الخير والشر ألا تسمع قوله تعالى \" إنما أموالكم وأولادكم فتنة \" (2) وقال تعالى \" لاسقيناهم ماء غدقا لنفتنهم فيه \" (3) فجعل النعمة فتنة لانه قصد بها المبالغة في إختبار المنعم عليه بها كالذهب إذا اريد المبالغة في تعرف حاله فيراني أدخل النار، والله تعالى لا يختبر العبد لتغيير حاله في الخير والشر وإنما المراد بذلك شدة التكليف."},{"id":"furuq-lughawiyya:543","bookId":"furuq-lughawiyya","type":"section","seq":543,"chapter":"* (أ) *","title":"1594 - الفرق بين الفحش والقبح: أن الفاحش الشديد القبح ويستعمل القبح في الصور فيقال القرد فبيح الصورة ولا يقال فاحش الصورة","page":"ج1 ص396","text":"ويقال هو فاحش القبح وهو فاحش الطول وكل شئ جاوز حد الاعتدال مجاوزة شديدة فهو فاحش وليس كذلك القبيح."},{"id":"furuq-lughawiyya:544","bookId":"furuq-lughawiyya","type":"section","seq":544,"chapter":"* (أ) *","title":"1595 - الفرق بين فحوى الخطاب ودليل الخطاب: أن فحوى الخطاب ما يعقل عند الخطاب لا بلفظه كقوله تعالى \" فلا تقل لهما اف \" (4) فالمنع من ضربهما ي","page":"ج1 ص397","text":"قوله تعالى \" حتى يطهرن \" (1) فيه دليل على أن الوطئ قبل ذلك محظور، والحال مثل ما روي أن يعلى بن أمية: قال لعمر مالنا نقصر وقد أمنا يعني الصلاة فقال عمر تعجبت مما تعجبت منه وسأل رسول الله صلى الله عليه [وآله] وسلم عن ذلك فقال صدقة تصدق الله بها عليكم فاقبلوا صدقته، وهذا مذهب بعض الفقهاء، وآخرون يقولون إن جميع ذلك يعرف بدلائل اخر دون دلائل الخطاب المذكورة هاهنا، وفيه كلام كثير ليس هذا موضع ذكره، والدليل لو قرن به دليل لم يكن مناقضة ولو قرن باللفظ فحواه لكان ذلك مناقضة ألا ترى انه لو قال في سائمة الغنم الزكاة وفي المعلوفة الزكاة لم يكن تناقضا، ولو قال فلا تقل لهما اف واضربهما لكان تناقضا، وكذلك لو قال هو مؤتمن على قنطار ثم قال يخون في الدرهم يعد تناقضا وقوله تعالى \" ولا تظلمون\nفتيلا \" (2) يدل فحواه على نفي الظلم فيم زاد على ذلك، ودلالة هذا كدلالة النص لان السامع لا يحتاج في معرفته إلى تأمل، وأما قوله تعالى \" فمن كان منكم مريضا أو على سفر فعدة من أيام أخر \" (3) فمعناه فافطر بعده، وقد جعله بعضهم فحوى الخطاب، وليس ذلك بفحوى عندهم ولكنه من باب الاستدلال ألا ترى أنك لو قرنت به فحوان لم يكن تناقضا فأما قوله تعالى \" والسارق والسارقة فاقطعوا أيديهما \" (4) فإنه يدل على المراد بفائدته لا بصريحه ولا فحواه وذلك أنه لما ثبت أنه زجر أفاد أن القطع هو لاجل السرقة وكذلك قوله تعالى \" الزانية والزاني \" (5) ."},{"id":"furuq-lughawiyya:545","bookId":"furuq-lughawiyya","type":"section","seq":545,"chapter":"* (أ) *","title":"1600 - الفرق بين الفرد والمتفرد (3) : قيل: الفرد من لا نظير له، والمتفرد البليغ الفردانية.","page":"ج1 ص398","text":"وقيل: هو الذي تفرد بخصوص وجود تفردا لا يتصور أن يشاركه فيه غيره، فهو - سبحانه - الفرد المطلق أزلا وأبدا.\nوالمخلوق إنما يكون فردا إذا لم يكن له في أبناء جنسه نظير من خصلة من خصال الخير، وذلك بالاضافة على أبناء جنسه، وبالاضافة إلى الوقت، إذ يمكن أن يظهر في وقت آخر مثله بالاضافة\nإلى بعض الخصال دون الجميع.\nفلا فردانية إلا لله سبحانه.\n(اللغات) ."},{"id":"furuq-lughawiyya:546","bookId":"furuq-lughawiyya","type":"section","seq":546,"chapter":"* (أ) *","title":"1601 - الفرق بين الفرد والواحد: أن الفرد يفيد الانفراد من القرن، والواحد يفيد الانفراد في الذات أو الصفة.","page":"ج1 ص399","text":"ألا ترى أنك تقول فلان فرد في داره ولا تقول واحد في داره، وتقول هو واحد أهل عصره تريد أنه قد انفرد بصفة ليس لهم مثلها وتقول الله واحد تريد أن ذاته منفردة عن المثل والشبه، وسمي الفرد فردا بالمصدر يقال فرد يفرد فردا وهو فارد وفرد والفرد مثله.\nوقال علي بن عيسى رحمه الله تعالى: الواحد ما لا ينقسم في نفسه أو معنى في صفته دون جملته كإنسان واحد ودينار واحد،\nوما لا ينقسم في معنى جنسه كنحو هذا الذهب كله واحد وهذا الماء كله واحد، والواحد في نفسه ومعنى صفته بما لا يكون لغيره أصلا هو الله جل ثناوه."},{"id":"furuq-lughawiyya:547","bookId":"furuq-lughawiyya","type":"section","seq":547,"chapter":"* (أ) *","title":"الفرق بين الفرض والوجوب","page":"ج1 ص399","text":"أن الفرض لا يكون إلا من الله، والايجاب يكون منه ومن غيره تقول فرض الله تعالى على العبد كذا وأوجبه عليه، وتقول أوجب زيد على عبده والملك على رعيته كذا ولا يقال فرض عليهم ذلك وإنما يقال فرض لهم العطاء ويقال فرض له القاضي، والواجب يجب في نفسه من غير إيجاب يجب له من حيث إنه غير متعد وليس كذلك الفرض لانه متعد ولهذا صح وجوب\nالثواب على الله تعالى في حكمته ولا يصح فرضه، ومن وجه آخر أن السنة المؤكدة تسمى واجبا ولا تسمى فرضا مثل سجدة التلاوة هي واجبة على من يسمعها وقيل على من قعد لها ولم يقل إنها فرض ومثل ذلك الوتر في أشباه له كثيرة، وفرق آخر أن العقليات لا يستعمل فيها الفرض ويستعمل فيها الوجوب تقول هذا واجب في العقل ولا يقال فرض في العقل، وقد يكون الفرض والواجب سواء في قولهم صلاة الظهر واجبة وفرض لا فرق بينهما هاهنا في المعنى، وكل واحد منهما من أصل فأصل الفرض الحز في الشئ تقول فرض في العود فرضا إذا حز فيه حزا، وأصل الوجوب السقوط يقال وجبت الشمس للمغيب إذا سقطت ووجب الحائط وجبة أي سقط، وحد الواجب والفرض عند\nمن يقول إن القادر لا يخلو من الفعل والترك ما له ترك قبيح وعند من يجيز خلو القادر من الفعل والترك ما إذا لم يفعله إستحق العقاب وليس يجب الواجب لايجاب موجب له ولو كان كذلك لكان القبيح واجبا إذا أوجبه موجب، والافعال ضربان أحدهما ألا يقارنه داع ولا قصد ولا علم فليس له حكم زائد على وجوده كفعل الساهي والنائم، والثاني يقع مع قصد وعلم أو داع وهذا على أربعة أضرب أحدها ما كان لفاعله أن يفعله من غير أن يكون له فيه مثل المباح، والثاني ما يفعله لعاقبة محمودة وليس عليه في تركه مضرة ويسمى ذلك ندبا ونفلا وتطوعا، وإن لم يكن شرعيا سمي تفضلا وإحسانا وهذا هو زائد (1) على كونه مباحا، والثالث ماله فعله وإن لم يفعله لحقه مضرة وهو الواجب والفرض وقد يسمى المحتم واللازم، والرابع\nالذي ليس له فعله وإن فعله إستحق الذم وهو القبيح والمحظور والحرام."},{"id":"furuq-lughawiyya:548","bookId":"furuq-lughawiyya","type":"section","seq":548,"chapter":"* (أ) *","title":"1605 - الفرق بين الفرض والوجوب (1) : قال الطبرسي: الفرق بينهما أن الفرض يقتضي فارضا فرضه، وليس كذلك الواجب، لانه قد يجب الشئ في نفسه من غير","page":"ج1 ص401","text":"وقال بعضهم: الفرق بين الفريضة والواجب هو أن الفريضة أخص من الواجب، لانها الواجب الشرعي، والواجب إذا كان مطلوبا (2) يجوز حمله على العقلي والشرعي.\nوقيل: الفرض ما أمر الله عباده أن يفعلوه كالصلاة، والزكاة، والصوم، والحج، فهو أخص من الواجب.\n(اللغات) ."},{"id":"furuq-lughawiyya:549","bookId":"furuq-lughawiyya","type":"section","seq":549,"chapter":"* (أ) *","title":"الفرق بين الفرق والتفريق","page":"ج1 ص401","text":"أن الفرق خلاف الجمع، والتفريق جعل\nالشئ مفارقا لغيره حتى كأنه جعل بينهما فرقا بعد فرق حتى تباينا وذلك أن التفعيل لتكثير الفعل وقيل فرق الشعر فرقا بالتخفيف لانه جعله فرقتين ولم يتكرر فعله فيه، والفرق أيضا الفصل بين الشيئين حكما أو خبرا ولهذا قال الله تعالى \" فافرق بيننا وبين القوم الفاسقين \" (1) أي أفصل بيننا حكما في الدنيا والآخرة ومن هذا فرق بين الحق والباطل."},{"id":"furuq-lughawiyya:550","bookId":"furuq-lughawiyya","type":"section","seq":550,"chapter":"* (أ) *","title":"1609 - الفرق بين الفرق والتفريق (2) : قيل: التفريق: جعل الشئ مفارقا لغيره.","page":"ج1 ص402","text":"والفرق: نقيض الجمع، والجمع: جعل الشئ مع غيره، فالفرق جعل الشئ لا مع غيره.\nويؤيد هذا الفرق قوله تعالى: \" لا نفرق\nبين أحد من رسله \" (3) .\nأي لا نجعل الانبياء مفارقين بعضهم من بعض، بأن نؤمن ببعض، ونكفر ببعض.\n(اللغات) ."},{"id":"furuq-lughawiyya:551","bookId":"furuq-lughawiyya","type":"section","seq":551,"chapter":"* (أ) *","title":"1614 - الفرق بين الفزع والخوف (1) : قيل: الفزع انقباض ونفار يعرض للانسان من الشئ المخيف وهو من جنس الجزع.","page":"ج1 ص403","text":"وقيل: هو الخوف الشديد، ومنه قوله تعالى: \" لا يحزنهم الفزع الأكبر \" (2) .\nقيل هو الخوف من دخول النار وعذابها.\nوقيل: هو النفخة الاخيرة لقوله تعالى \" ويوم ينفخ في الصور ففزع من في السماوات ومن في الارض \" (3) .\nوقيل: هو الانصراف إلى النار.\nوقيل: هو حين تطبق النار على أهلها، وعلى كل من التفاسير (4) .\nفلا خوف أشد منه ولا أعظم.\nأعاذنا الله منه، بجوده، ومنه.\n(اللغات) ."},{"id":"furuq-lughawiyya:552","bookId":"furuq-lughawiyya","type":"section","seq":552,"chapter":"* (أ) *","title":"1615 - الفرق بين الفزع والخوف والهلع: أن الفزع مفاجأة الخوف عند هجوم غارة أو صوت هدة وما أشبه ذلك، وهو إنزعاج القلب بتوقع مكروه","page":"ج1 ص403","text":"عاجل وتقول فزعت منه فتعديه بمن وخفته فتعديه بنفسه فمعنى خفته أي هو نفسه خوفي ومعنى فزعت منه أي هو إبتداء فزعي لان من لابتداء الغاية وهو يؤكد ما ذكرناه، وأما الهلع فهو أسوأ الجزع وقيل الهلوع على ما فسره الله تعالى في قوله تعالى \" إن الانسان خلق هلوعا إذا مسه الشر جزوعا وإذا مسه الخير منوعا \" (5) ولا يسمى هلوعا حتى تجتمع فيه هذه الخصال."},{"id":"furuq-lughawiyya:553","bookId":"furuq-lughawiyya","type":"section","seq":553,"chapter":"* (أ) *","title":"الفرق بين الفساد والقبيح","page":"ج1 ص404","text":"أن الفساد هو التغيير عن المقدار الذي تدعو إليه الحكمة والشاهد أنه نقيض الصلاح وهو الاستقامة على ما تدعو إليه الحكمة وإذا قصر عن المقدار أو أفرط لم يصلح وإذا كان على المقدار أصلح والقبيح ما تزجر عنه الحكمة وليس فيه معنى المقدار."},{"id":"furuq-lughawiyya:554","bookId":"furuq-lughawiyya","type":"section","seq":554,"chapter":"* (أ) *","title":"1619- الفرق بين الفساد والقبيح","page":"ج1 ص404","text":"الفرق بين الفساد والقبيح (1) : قيل: الفرق بينهما أن الفساد تغيير عن المقدار الذي تدعو إليه الحكمة وليس كذلك القبيح، لانه ليس فيه معنى المقدار، وإنما هو ما تزجر عنه الحكمة، كما أن الحسن ما تدعو إليه الحكمة.\n(اللغات) ."},{"id":"furuq-lughawiyya:555","bookId":"furuq-lughawiyya","type":"section","seq":555,"chapter":"* (أ) *","title":"1620 - الفرق بين الفسق والخروج: أن الفسق في العربية خروج مكروه ومنه","page":"ج1 ص404","text":"يقال للفأرة الفويسقة لانها تخرج من جحرها للافساد، وقيل فسقت الرطبة إذا خرجت من قشرها لان ذلك فساد لها ومنه سمي الخروج من طاعة الله بكبيرة فسقا ومن الخروج مذموم ومحمود والفرق بينهما بين."},{"id":"furuq-lughawiyya:556","bookId":"furuq-lughawiyya","type":"section","seq":556,"chapter":"* (أ) *","title":"1621 - الفرق بين الفسق والفجور: أن الفسق هو الخروج من طاعة الله بكبيرة، والفجور الانبعاث في المعاصي والتوسع فيها وأصله من قولك","page":"ج1 ص405","text":"أفجرت السكر إذا خرقت فيها خرقا واسعا فانبعث الماء كل منبعث فلا يقال لصاحب الصغيرة فاجر كما لا يقال لمن خرق في السكر خرقا صغيرا أنه قد فجر السكر ثم كثر إستعمال الفجور حتى خص بالزنا واللواط وما أشبه ذلك."},{"id":"furuq-lughawiyya:557","bookId":"furuq-lughawiyya","type":"section","seq":557,"chapter":"* (أ) *","title":"1625 - الفرق بين الفصل والفرق: أن الفصل يكون في جملة واحدة، ولهذا يقال فصل الثوب وهذا فصل في الكتاب لان الكتاب جملة واحدة ثم كثر حتى سمي ما","page":"ج1 ص405","text":"منه صارا كالشئ الواحد ويقال أيضا فصلت العضو وهذا مفصل الرسغ وغيره لان العضو من جملة الجسد ولا يقال في ذلك فرقت لانه ليس بائنا منه، وقال بعضهم ما كان من الفرق ظاهرا ولهذا يقال لما تضمن جنسا من الكلام فصل واحد لظهوره وتجليه ولما كان الفصل لا يكون إلا ظاهرا قالوا فصل الثوب ولم يقولوا فرق الثوب ثم قد تتداخل الكلمتان لتقارب معناهما."},{"id":"furuq-lughawiyya:558","bookId":"furuq-lughawiyya","type":"section","seq":558,"chapter":"* (أ) *","title":"1626 - الفرق بين الفصل والقطع: أن الفصل هو القطع الظاهر ولهذا يقال","page":"ج1 ص405","text":"فصل الثوب والقطع يكون ظاهرا وخافيا كالقطع في الشئ الملزق المموه ولا يقال لذلك فصل حتى يبين أحد المفصولين عن الآخر، ومن ثم يقال فصل بين الخصمين إذا ظهر الحق على أحدهما فزال تعلق أحدهما بصاحبه فتباينا ولا يقال في ذلك قطع، ويقال قطعه في المناظرة لانه قد يكون ذلك من غير أن يظهر ومن غير أن يقطع شغبه وخصومته."},{"id":"furuq-lughawiyya:559","bookId":"furuq-lughawiyya","type":"section","seq":559,"chapter":"* (أ) *","title":"1630 - الفرق بين الفطر والفعل: أن الفطر إظهار الحادث بإخراجه من العدم إلى الوجود كأنه شق عنه فظهر، وأصل الباب الشق ومع الشق الظهور ومن ثم قي","page":"ج1 ص406","text":"بالاخراج إلى الوجود قبل ما لا يستعمل فيه الظهور ولا يستعمل فيه الوجود، ألا ترى أنك لا تقول إن الله فطر الطعام والرائحة كما تقول فعل ذلك، وقال علي بن عيسى: الفاطر العامل للشئ بايجاده بمثل الانشقاق عنه."},{"id":"furuq-lughawiyya:560","bookId":"furuq-lughawiyya","type":"section","seq":560,"chapter":"* (أ) *","title":"1641 - الفرق بين الفقد والعدم (1) : الفقد: عدم الشئ بعد وجوده، فهو","page":"ج1 ص408","text":"أخص من العدم، لان العدم يقال فيه وفيما لا يوجد.\nفعلى هذا لا يقال: شريك الباري مفقود بل يقال: معدوم.\n(اللغات) ."},{"id":"furuq-lughawiyya:561","bookId":"furuq-lughawiyya","type":"section","seq":561,"chapter":"* (أ) *","title":"1645 - الفرق بين الفقير والمسكين (1) : لا خلاف في اشتراكهما في وصف عدمي هو [23 / أ] عدم وفاء الكسب بالكلية، والمال لمؤنته، ومؤونة عياله.","page":"ج1 ص408","text":"وإنما الخلاف في أيهما أسوأ حالا.\nومنشأ هذا الخلاف اختلاف أهل اللغة في ذلك، فقال الشيخ في المبسوط والجمل: الفقير أسوأ حالا لوجوه: الأول: أنه ابتدئ به في الآية، وهو يدل على الاهتمام بشأنه في الحاجة.\nوالثاني: أنه صلى الله عليه وآله قال: تعوذ من الفقر وسأل المسكنة، حيث قال: \" اللهم إني أعوذ بك من الفقر \" (2) وقال: \" اللهم أحيني مسكينا، وأمتني مسكينا، واحشرني في زمرة المساكين \" (3) .\nالثالث: قوله تعالى: \" أما السفينة فكانت لمساكين \" (1) فقد أثبت للمسكين مالا، وبه قال ابن حمزة، وابن البراج، وابن إدريس.\nوقال الشيخ في النهاية: المسكين أسوأ حالا لوجوه: الاول: التأكيد به.\nفإنه يقال: فقير مسكين، ولا يقال العكس.\nوالتأكيد إنما يكون بالاقوى.\nالثاني: قوله تعالى: \" أو مسكينا ذا متربة \" (2) وهو المطروح على التراب لشدة الاحتياج.\nالثالث: ما رواه أبو بصير.\n[عن المعصوم عليه السلام] قال: قلت لابي عبد الله عليه السلام: قول الله عزوجل: \" إنما الصدقات للفقراء والمساكين \" (3) .\nقال: الفقير: الذي لا يسأل الناس، والمسكين: أجهد منه، والبائس أجهدهم.\nقال شيخنا البهاء (4) طاب ثراه: قوله: \" الفقير الذي لا يسأل الناس \".\nالظاهر أنه كناية عن أن له مالا أو كسبا في الجملة، وهو (5) يقنع به.\nوكان قاصرا عن مؤونته، ولا يسأل الناس.\nوقوله: \" المسكين أجهد منه \" أي: أشق حالا.\nوالجهد: - بالفتح - المشتقة بمعنى أنه لا مال له ولا كسب أصلا.\nوعلى هذا فيشكل جعل البائس أجهد منه.\nاللهم إلا أن يعتبر فيه\nالضعف البدني كالزمانة ونحوها.\nانتهى كلامه، رفع مقامه.\nوتظهر الفائدة في النذر والوصية لاسوئهما حالا وفي الكفارة أيضا، فإنها مخصوصة بالمساكين.\nأما الزكاة فكلاهما مستحقان، بكون الضابط في ذلك عدم ملك مؤونة السنة كما مر.\nوهو المشهور عند الاصحاب، رضوان الله عليهم.\n(اللغات) ."},{"id":"furuq-lughawiyya:562","bookId":"furuq-lughawiyya","type":"section","seq":562,"chapter":"* (أ) *","title":"1646 - الفرق بين الفقر والمسكنة: أن الفقر فيما قال الازهري: في تأويل قوله تعالى \" إنما الصدقات للفقراء والمساكين \" (1) الفقير الذي لا يسأل و","page":"ج1 ص410","text":"فجعل للفقير حلوبة والمسكين الذي لا شئ له فأما قوله تعالى \" فكانت لمساكين يعملون في البحر \" (5) فأثبت لهم ملك سفينة وسماهم مساكين فإنه روي أنهم كانوا أجراء فيها ونسبها إليهم\nلتصرفهم فيها والكون بها كما قال تعالى \" لا تدخلوا بيوت النبي \" (1) ثم قال \" وقرن في بيوتكن \" (2) وعن أبي حنيفة فيمن قال مالي للفقراء والمساكين أنهما صنفان.\nوعن أبي يوسف: أن نصف المال لفلان ونصفه للفقراء والمساكين، وهذا يدل على أنه جعلهما صنفا واحدا والقول قول أبي حنيفة، ويجوز أن يقال المسكين هو الذي يرق له الانسان إذا تأمل حاله وكل من يرق له الانسان يسميه مسكينا."},{"id":"furuq-lughawiyya:563","bookId":"furuq-lughawiyya","type":"section","seq":563,"chapter":"* (أ) *","title":"1650 - الفرق بين الفقه والعلم: أن الفقه هو العلم بمقتضى الكلام على تأمله ولهذا لا يقال إن الله بفقه لانه لا يوصف بالتأمل، وتقول لمن تخاطبه ت","page":"ج1 ص411","text":"لكم \" (5) عقب قوله \" كل يوم هو في شأن \" (6) قال الشيخ أبو هلال رحمه الله: وسمي علم الشرع فقها لانه مبني عن معرفة كلام\nالله تعالى وكلام رسول الله صلى الله عليه [وآله] وسلم."},{"id":"furuq-lughawiyya:564","bookId":"furuq-lughawiyya","type":"section","seq":564,"chapter":"* (أ) *","title":"1655 - الفرق بين الفلق والشق: أن الفلق على ما جاء في التفسير هو الشق على أمر كبير ولهذا قال تعالى \" فالق الاصباح \" (1) ويقال فلق الحبة عن ال","page":"ج1 ص412","text":"الفلق المعنى الذي ذكرناه ومن ثم سميت الداهية فلقا وفليقة."},{"id":"furuq-lughawiyya:565","bookId":"furuq-lughawiyya","type":"section","seq":565,"chapter":"* (أ) *","title":"الفرق بين الفهم والعلم","page":"ج1 ص413","text":"أن الفهم هو العلم بمعاني الكلام عند سماعه خاصة ولهذا يقال فلان سئ الفهم إذا كان بطئ العلم بمعنى ما يسمع ولذلك كان الاعجمي لا يفهم كلام العربي، ولا يجوز أن يوصف الله بالفهم لانه عالم بكل شئ على ما هو به فيما لم يزل، وقال بعضهم لا يستعمل الفهم إلا في الكلام ألا ترى انك تقول فهمت كلامه ولا تقول فهمت ذهابه ومجيئه كما تقول علمت ذلك.\nوقال أبو أحمد بن أبي سلمة رحمه الله: الفهم يكون في الكلام وغيره من البيان كالاشارة ألا ترى أنك تقول فهمت ما قلت وفهمت ما أشرت به إلي.\nقال الشيخ أبو هلال رحمه الله: الاصل هو الذي تقدم وإنما استعمل الفهم في الاشارة لان الاشارة تجري مجرى الكلام في الدلالة على المعنى."},{"id":"furuq-lughawiyya:566","bookId":"furuq-lughawiyya","type":"section","seq":566,"chapter":"* (أ) *","title":"1659- الفرق بين الفهم والعلم","page":"ج1 ص413","text":"الفرق بين الفهم والعلم (1) : قيل: الفهم: تصور المعنى من لفظ المخاطب، وقيل: أدراك خفي، دقيق، فهو أخص من العلم، لان العلم نفس الادراك سواء كان خفيا أو جليا، ولهذا قال سبحانه في قصة داود وسليمان عليهما السلام: \" ففهمناها سليمان وكلا آتينا حكما وعلما \" (2) .\nخص الفهم بسليمان، وعمم العلم لداود وسليمان.\n(اللغات) ."},{"id":"furuq-lughawiyya:567","bookId":"furuq-lughawiyya","type":"section","seq":567,"chapter":"* (أ) *","title":"1664 - الفرق بين الفئ والرجوع: أن الفئ هو الرجوع من قرب ومنه قوله تعالى \" فإن فاءوا فإن الله غفور رحيم \" (3) يعني الرجوع ليس ببعيد","page":"ج1 ص415","text":"ومنه سمي مال المشركين فيئا لذلك كأنه فاء من جانب إلى جانب."},{"id":"furuq-lughawiyya:568","bookId":"furuq-lughawiyya","type":"section","seq":568,"chapter":"* (أ) *","title":"1668 - الفرق بين القادر والقدير (2) : القادر: هو الذي إن شاء فعل، وإن","page":"ج1 ص417","text":"شاء لم يفعل.\nوالقدير: الفعال لكل ما يشاء، ولذلك لم يوصف به غير الباري تعالى شأنه.\n(اللغات) ."},{"id":"furuq-lughawiyya:569","bookId":"furuq-lughawiyya","type":"section","seq":569,"chapter":"* (أ) *","title":"1674 - الفرق بين القاضي والمفتي (1) : الفرق بينهما أن المفتي يقرر القوانين الشرعية.","page":"ج1 ص417","text":"والقاضي: يشخص تلك القوانين في المواد الجزئية، مثل أن يقول للمشار إليه: عليك البينة، وعلى خصمك اليمين."},{"id":"furuq-lughawiyya:570","bookId":"furuq-lughawiyya","type":"section","seq":570,"chapter":"* (أ) *","title":"1688 - الفرق بين القتل والموت: أن القتل هو نقض البنية الحيوانية ولا يقال له قتل في أكثر الحال إلا إذا كان من فعل آدمي، وقال بعضهم القتل إمات","page":"ج1 ص419","text":"ومنه يقال ناقة مقتلة إذا كثر عليها الاتعاب حتى تموت حركتها، والموت عرض أيضا يضاد الحياة مضادة الروك ولا يكون إلا من فعل الله، والميتة الموت بعينه إلا أنه يدل على الحال،\nوالموت ينفي الحياة مع سلامة البنية، ولابد في القتل من إنتقاض البنية، ويقال لمن حبس الانسان حتى يموت أنه قتله ولم يكن (1) بقاتل في الحقيقة لانه لم ينقض البنية، ويستعار الموت في أشياء فيقال مات قلبه إذا صار بلدا ومات المتاع أي كسد ومات الشئ بينهم نقص وحظ ميت ضعيف ونبات ميت ذابل ووقع في المال موتان إذا تماوتت وموتان الارض إذا لم تعمر."},{"id":"furuq-lughawiyya:571","bookId":"furuq-lughawiyya","type":"section","seq":571,"chapter":"* (أ) *","title":"1692 - الفرق بين القدرة والحياة: أن قدرة الحي قد تتناقض مع بقاء حياته على حد واحد ألا ترى انه قد يتعذر عليه في حال المرض والكبر كثير من أفعا","page":"ج1 ص420","text":"متناقض، وفرق آخر أن العضو قد يكون فيه الحياة بدليل صحة إدراكه وإن لم تكن فيه القدرة كالاذن ألا ترى انه يتعذر تحريكها مباشرا وإن كانت منفصلة، وفرق آخر أن الحياة جنس واحد والقدرة مختلفة ولو كانت متفقة لقدرتا بقدرتين على مقدور واحد."},{"id":"furuq-lughawiyya:572","bookId":"furuq-lughawiyya","type":"section","seq":572,"chapter":"* (أ) *","title":"1697 - الفرق بين القدرة والقوة (1) : قيل: القدرة: كون الحي [24 / أ] بحيث إن شاء فعل، وإن شاء ترك.","page":"ج1 ص420","text":"والقوة: هي المعنى الذي يتمكن بها الحي من مزاولة الافعال الشاقة.\n(اللغات) ."},{"id":"furuq-lughawiyya:573","bookId":"furuq-lughawiyya","type":"section","seq":573,"chapter":"* (أ) *","title":"الفرق بين القدر والقضاء","page":"ج1 ص421","text":"أن القدر هو وجود الافعال على مقدار الحاجة إليها والكفاية لما فعلت من أجله ويجوز أن يكون القدر هو الوجه الذي أردت إيقاع المراد عليه، والمقدر الموجد له على ذلك الوجه، وقيل أصل القدر هو وجود الفعل على مقدار ما أراده الفاعل، وحقيقة ذلك في أفعال الله تعالى وجودها على مقدار المصلحة، والقضاء هو فصل الامر على التمام."},{"id":"furuq-lughawiyya:574","bookId":"furuq-lughawiyya","type":"section","seq":574,"chapter":"* (أ) *","title":"1701- الفرق بين القدر والقضاء","page":"ج1 ص421","text":"الفرق بين القدر والقضاء (1) : القضاء عبارة عن وجود الصور العقلية لجميع الموجودات بإبداعه - سبحانه - إياها في العالم العقلي على الوجه الاكمل (2) بلا زمان على ترتيبها الطولي (3) الذي هو باعتبار\nسلسلة العلل والمعلومات.\nوالعرضي: الذي باعتبار سلسلة الزمانيات والمعدات بحسب مقارنة جزئيات الطبيعة المنتشرة في أفراد أحزاء (4) الزمان، كما قال تعالى: \" وإن من شئ إلا عندنا خزائنه \" (5) .\nوالقدر: عبارة عن ثبوت جميع الموجودات في العالم النفسي الفلكي على الوجه الجزئي مطابقة لما في مواردها الخارجية الشخصية مستندة إلى أسبابها الجزئية واجبة بها، لازمة لاوقاتها المعينة.\nكما قال عزوجل: \" وما ننزله إلا بقدر معلوم \" (6) .\nكذا حققه المحقق الكاشي\nفي (عين اليقين) *.\nوقال الراغب: القضاء من الله أخص من القدر: لان القضاء: الفصل، والقدر: هو التقدير.\nوذكر بعض العلماء أن القدر بمنزلة المقدر للكيل، والقضاء بمنزلة الكيل.\n- وقد سبق في باب الالف عند ذكر الفرق بين الإرادة والمشيئة (1) كلام في هذا الباب به يتضح المرام، وينكشف المقام، فارجع إليه.\n(اللغات) ."},{"id":"furuq-lughawiyya:575","bookId":"furuq-lughawiyya","type":"section","seq":575,"chapter":"* (أ) *","title":"الفرق بين القرآن والفرقان","page":"ج1 ص423","text":"أن القرآن يفيد جمع السور وضم بعضها إلى بعض، والفرقان يفيد أنه يفرق بين الحق والباطل والمؤمن والكافر."},{"id":"furuq-lughawiyya:576","bookId":"furuq-lughawiyya","type":"section","seq":576,"chapter":"* (أ) *","title":"1709- الفرق بين القرآن والفرقان","page":"ج1 ص423","text":"الفرق بين القرآن والفرقان (1) : قال الجوهري (2) : الفرقان: القرآن.\nوكل ما فرق به بين الحق والباطل فهو فرقان، ولهذا قال تعالى: \" ولقد آتينا موسى وهارون الفرقان \" (3) .\nوالفرق: الفرقان أيضا ونظيره: الخسر والخسران.\nانتهى.\nوذكر المفسرون لتسمية القرآن بالفرقان وجوها منها: - أنه سمي به لنزوله متفرقا مدة الزمان.\n- ومنها أنه مفروق بعضه من بعض، لانه مفصل بالسور والآيات.\n- ومنها: افتراقه عن سائر المعجزات ببقائه على صفحات الايام والدهور.\n- ومنها: فرقه بين الحق والباطل، والحلال والحرام.\n- وروى ابن سنان * عمن ذكره قال: سألت أبا عبد الله عليه السلام عن القرآن والفرقان أهما شئ واحد، أم شيئان؟ فقال عليه السلام: القرآن جملة الكتاب، والفرقان: المحكم الواجب العمل به.\nوأقول (1) : كفى بالحديث فارقا، ولعمري لا يفرق بين القرآن والفرقان إلا من نزل في نبيهم القرآن، وعرفوا ظاهره وخوا فيه، وأهل البيت أعلم بما فيه! (اللغات) ."},{"id":"furuq-lughawiyya:577","bookId":"furuq-lughawiyya","type":"section","seq":577,"chapter":"* (أ) *","title":"1711 - الفرق بين القرب والقربة والقرباء والقرابة (2) : الاول: يقال في المكان، والثاني في المنزلة، والثالث والرابع في النسب.","page":"ج1 ص424","text":"قاله الفيومي في المصباح (3) .\nوقد يطلق احدهما على الآخر من باب المجاز والمشاركة.\n(اللغات) ."},{"id":"furuq-lughawiyya:578","bookId":"furuq-lughawiyya","type":"section","seq":578,"chapter":"* (أ) *","title":"الفرق بين القرض والدين","page":"ج1 ص424","text":"أن القرض أكثر ما يستعمل في العين والورق هو أن تأخذ من مال الرجل درهما لترد عليه بدله درهما فيبقى دينا عليك إلى أن ترده فكل قرض دين وليس كل دين قرضا وذلك أن أثمان ما يشترى بالنسأ ديون وليست بقروض، فالقرض يكون من جنس ما اقترض وليس كذلك الدين، ويجوز أن يفرق بينهما فنقول قولنا يداينه يفيد أنه يعطيه ذلك ليأخذ منه بدله، ولهذا يقال قضيت\nقرضه وأديت دينه وواجبه، ومن أجل ذلك أيضا يقال أديت صلاة الوقت وقضيت ما نسيت من الصلاة لانه بمنزلة القرض."},{"id":"furuq-lughawiyya:579","bookId":"furuq-lughawiyya","type":"section","seq":579,"chapter":"* (أ) *","title":"1714 - الفرق بين القرض والدين (1) : قال في القاموس: (2) الدين: ماله أجل، ومالا أجل له فقرض.","page":"ج1 ص425","text":"انتهى.\nوقيل: الدين: كل معاوضة يكون أحد العوضين فيها مؤجلا.\nوأما القرض: فهو إعطاء الشئ ليستعيد (3) عوضا وقتا آخر من غير تعيين الوقت.\nقلت: ويدل عليه قوله تعالى: \" إذا تداينتم بدين إلى أجل مسمى \" (4) .\nحيث اعتبر الاجل في مفهوم الدين ولم يعتبر ذلك في القرض، كما في قوله تعالى: \" من ذا الذي يقرض الله قرضا\nحسنا \" (5) .\nهذا وقد يراد من الدين ما ثبت في الذمة من مال الآخر، سواء كان مؤجلا أم لم يكن.\n(اللغات) ."},{"id":"furuq-lughawiyya:580","bookId":"furuq-lughawiyya","type":"section","seq":580,"chapter":"* (أ) *","title":"1715 - الفرق بين القرض والفرض: أن القرض ما يلزم إعطاؤه، والفرض ما لا يلزم إعطاؤه ويقال ما عنده قرض ولا فرض أي ما عنده خير لمن يلزمه أمره ولا","page":"ج1 ص426","text":"قرضا لتساوي ما يأخذ وما يرد، والعرب تقول تقارض الرجلان الثناء إذا أثنى كل واحد منهما على صاحبه، وقال الشاعر: * وأيدي الندى في الصالحين قروض * وقال بعضهم هما يتقارظان ولا يقال يتقارضان، وكلاهما عندنا جيد بل الضاد أكثر من الظاء في هذا وأشهر ورواه علي بن عيسى: في تفسيره."},{"id":"furuq-lughawiyya:581","bookId":"furuq-lughawiyya","type":"section","seq":581,"chapter":"* (أ) *","title":"1716 - الفرق بين القرن والقوم: أن القرن إسم يقع على من يكون من الناس في مدة سبعين سنة والشاهد قول الشاعر: إذا ذهب القرن الذي أنت فيهم * وخلف","page":"ج1 ص426","text":"ومنه قوله صلى الله عليه [وآله] وسلم \" فإنها تطلع بين قرني الشيطان \" أراد أن الشيطان في ذلك الوقت أقوى ويجوز أن يقال إنهم سموا قرناء لاقترانهم في العصر، وقال بعضهم: أهل كل عصر قرن.\nوقال الزجاج: القرن أهل كل عصر فيهم نبي أو من له طبقة عالية في العالم فجعله من اقتران أهل العصر بأهل العلم فإذا كان في زمان فترة وغلبة جهل لم يكن قرنا، وقال بعضهم القرن إسم من أسماء الازمنة فكل قرن سبعون سنة، وأصله من المقارنة وذلك أن أهل كل عصر أشكال ونظراء ورد وأسنان متقاربة، ومن ثم قيل هو قرنه أي على سنه ومنه هو قرنه لاقترانه معه في القتال، والقوم هم الرجال الذين يقوم بعضهم مع بعض في الامور ولا يقع على النساء إلا على وجه التبع كما قال عزوجل \" كذبت قوم نوح المرسلين \" (1) والمراد الرجال والنساء تبع لهم، والشاهد على ما قلناه قول زهير:\nوما أدري وسوف إخال أدري * أقوم آل حصن أم نساء فأخرج النساء من القوم."},{"id":"furuq-lughawiyya:582","bookId":"furuq-lughawiyya","type":"section","seq":582,"chapter":"* (أ) *","title":"1723 - الفرق بين القسم والحلف: أن القسم أبلغ من الحلف لان معنى قولنا","page":"ج1 ص427","text":"أقسم بالله أنه صار ذا قسم بالله، والقسم النصيب والمراد أن الذي أقسم عليه من المال وغيره قد أحرزه ودفع عنه الخصم بالله، والحلف من قولك سيف حليف أي قاطع ماض فإذا قلت حلف بالله فكأنك قلت قطع المخاصمة بالله فالاول أبلغ لانه يتضمن معنى الآخر مع دفع الخصم ففيه معنيان وقولنا حلف يفيد معنى واحدا وهو قطع المخاصمة فقط وذلك أن من أحرز الشئ باستحقاق في الظاهر فلا خصومة بينه وبين أحد فيه وليس كل من دفع الخصومة في الشئ فقد أحرزه، واليمين إسم للقسم مستعار وذلك أنهم كانوا إذا تقاسموا على شئ تصافقوا بأيمانهم ثم كثر ذلك حتى سمي القسم يمينا."},{"id":"furuq-lughawiyya:583","bookId":"furuq-lughawiyya","type":"section","seq":583,"chapter":"* (أ) *","title":"1729 - الفرق بين القصد والقناعة: أن القصد هو ترك الاسراف والتقتير جميعا، والقناعة الاقتصار على القليل والتقتير ألا ترى أنه لا يقال هو","page":"ج1 ص428","text":"قنوع إلا إذا استعمل دون ما يحتاج إليه ومقتصد لمن لا يتجاوز الحاجة ولا يقصر دونها وترك الاقتصاد مع الغنى ذم وترك القناعة معه ليس بذم وذلك أن نقيض الاقتصاد الاسراف، وقيل الاقتصاد من أعمال الجوارح لانه نقيض الاسراف وهو من أعمال الجوارح والقناعة من أعمال القلوب."},{"id":"furuq-lughawiyya:584","bookId":"furuq-lughawiyya","type":"section","seq":584,"chapter":"* (أ) *","title":"1732 - الفرق بين القصص والحديث: أن القصص ما كان طويلا من الاحاديث متحدثا به عن سلف ومنه قوله تعالى \" نحن نقص عليك أحسن القصص \" (1) وقال \" نق","page":"ج1 ص429","text":"القصص صناعة، وأصل القصص في العربية اتباع الشئ بالشئ ومنه قوله تعالى \" وقالت لاخته قصيه \" (3) وسمي الخبر الطويل قصصا لان بعضه يتبع بعضا حتى يطول وإذا استطال السامع الحديث قال هذا قصص والحديث يكون عمن سلف وعمن حضر ويكون طويلا وقصيرا، ويجوز أن يقال القصص هو الخبر عن الامور التي يتلو بعضها بعضا، والحديث يكون عن ذلك وعن غيره، والقص قطع يستطيل ويتبع بعضه بعضا مثل قص الثوب بالمقص وقص الجناح وما أشبه ذلك، وهذه قصة الرجل يعني الخبر عن مجموع أمره وسميت قصة لانها يتبع بعضها بعضا حتى تحتوي على جميع أمره."},{"id":"furuq-lughawiyya:585","bookId":"furuq-lughawiyya","type":"section","seq":585,"chapter":"* (أ) *","title":"1733 - الفرق بين القصم والفصم: أن القصم بالقاف الكسر مع الابانة قال أبو بكر: القصم مصدر قصمت الشئ قصما إذا كسرته والقصمة من الشئ القطعة منه","page":"ج1 ص430","text":"والفصم بالفاء كسر من غير إبانة قال أبو بكر: إنفصم الشئ إنفصاما إذا تصدع ولم ينكسر، قال أبو هلال ومنه قوله تعالى \" لا انفصام لها \" (1) ولم يقل لا انقصام لها لان الانفصام أبلغ فيما اريد به هاهنا وذلك أنه إذا لم يكن لها إنفصام كان أحرى أن لا يكون لها إنقصام."},{"id":"furuq-lughawiyya:586","bookId":"furuq-lughawiyya","type":"section","seq":586,"chapter":"* (أ) *","title":"1734 - الفرق بين القضاء والحكم: أن القضاء يقتضي فصل الامر على التمام من قولك قضاه إذا أتمه وقطع عمله ومنه قوله تعالى \" ثم قضى أجلا \" (2) أي","page":"ج1 ص430","text":"موته \" فقضاهن سبع سماوات في يومين \" (5) أي فصل الأمر به، والحكم يقتضي المنع عن الخصومة من قولك أحكمته إذا منعته قال الشاعر: أبني حنيفة أحكموا سفهاءكم * إني أخاف عليكم أن أغضبا ويجوز أن يقال الحكم فصل الامر على الاحكام بما يقتضيه العقل والشرع فإذا قيل حكم بالباطل فمعناه أنه جعل الباطل موضع الحق، ويستعمل الحكم في مواضع لا يستعمل فيها القضاء كقولك حكم هذا كحكم هذا أي هما متماثلان في السبب أو العلة أو نحو ذلك\nوأحكام الاشياء تنقسم قسمين (1) حكم يرد إلى أصل وحكم لا يرد إلى أصل لانه أول في بابه."},{"id":"furuq-lughawiyya:587","bookId":"furuq-lughawiyya","type":"section","seq":587,"chapter":"* (أ) *","title":"الفرق بين القط والقد","page":"ج1 ص431","text":"(4) : القد: قطع الشئ طولا، والقط: قطعه عرضا، وفي وصف ضربات علي: \" كان إذا اعتلى قد، وإذا اعترض قط \".\nومنه قط القلم، وهو قطع طرفه.\nقاله الحريري.\n(اللغات) ."},{"id":"furuq-lughawiyya:588","bookId":"furuq-lughawiyya","type":"section","seq":588,"chapter":"* (أ) *","title":"1739- الفرق بين القط والقد","page":"ج1 ص431","text":"الفرق بين القط والقد: أن القط هو القطع عرضا ومنه قط القلم والمقط بفتح الميم موضع القط من رأس القلم ويكون مصدرا ومكانا، والمقط بكسر الميم ما يقط عليه، والقد القطع طولا وكل\nشئ قطعته طولا فقد قددته وفي الحديث أن عليا عليه السلام كان إذا علا بالسيف قد وإذا اعترض قط."},{"id":"furuq-lughawiyya:589","bookId":"furuq-lughawiyya","type":"section","seq":589,"chapter":"* (أ) *","title":"1741 - الفرق بين القلب والبال: أن القلب إسم للجارحة وسمي بذلك لانه وضع في موضعه من الجوف مقلوبا، والبال والحال وحال الشئ عمدته فلما كان القل","page":"ج1 ص432","text":"حسن فيفرق بذلك."},{"id":"furuq-lughawiyya:590","bookId":"furuq-lughawiyya","type":"section","seq":590,"chapter":"* (أ) *","title":"1742 - الفرق بين القلب والفؤاد (1) : لم يفرق بينهما أهل اللغة، بل عرفوا كلا منهما بالآخر، وقال بعض أصحابنا من أهل الحديث، الافئدة [23 / ب] ت","page":"ج1 ص432","text":"والقلوب باللين، لان الفؤاد: غشاء القلب، إذ رق نفذ القول فيه وخلص إلى ما وراءه.\nوإذا غلظ تعذر وصوله إلى داخله.\nوإذا صادف القلب شيئا علق به إذا كان لينا.\n(اللغات) ."},{"id":"furuq-lughawiyya:591","bookId":"furuq-lughawiyya","type":"section","seq":591,"chapter":"* (أ) *","title":"1744 - الفرق بين القليل واليسير: أن القلة تقتضي نقصان العدد يقال قوم قليل وقليلون وفي القرآن \" لشرذمة قليلون \" (1) يريد أن عددهم ينقص عن عدة","page":"ج1 ص433","text":"طلبه ولا يقتضي ما يقتضيه القليل من نقصان العدد ألا ترى أنه يقال عدد قليل ولا يقال عدد يسير ولكن يقال مال يسير لان جمع مثله يتيسر فإن استعمل اليسير في موضع القليل فقد يجري إسم الشئ على غيره إذا قرب منه."},{"id":"furuq-lughawiyya:592","bookId":"furuq-lughawiyya","type":"section","seq":592,"chapter":"* (أ) *","title":"1750 - الفرق بين الخيبة واليأس (1) : الخائب: المنقطع عما أمل، ولا تكون الخيبة إلا بعد الامل، لانها إمتناع نيل ما أمل.","page":"ج1 ص435","text":"واليأس قد يكون قبل الامل.\nكذا قيل (1) .\n(اللغات)"},{"id":"furuq-lughawiyya:593","bookId":"furuq-lughawiyya","type":"section","seq":593,"chapter":"* (أ) *","title":"1751 - الفرق بين القنوط واليأس (2) : اليأس: انقطاع الطمع من الشئ، والقنوط: أخص منه، فهو أشد اليأس.","page":"ج1 ص435","text":"ويدل عليه قول سيد الساجدين في دعاء الصحيفة الشريفة السجادية (3) : \" تفعل ذلك يا آلهي بمن خوفه منك أكثر من طمعه فيك، وبمن يأسه من النجاة أوكد من رجائه للخلاص لا أن يكون يأسه قنوطا \".\nوقال الراغب: القنوط: اليأس، وقيل هو من الخير، فهو أخص من مطلق اليأس، ويدل عليه قوله تعالى: \" لا تقنطوا من رحمة الله \" (4) .\n(اللغات) ."},{"id":"furuq-lughawiyya:594","bookId":"furuq-lughawiyya","type":"section","seq":594,"chapter":"* (أ) *","title":"1752 - الفرق بين القنوع والسؤال: أن القنوع سؤال الفضل والصلة خاصة، والسؤال عام في ذلك وفي غيره يقال قنع يقنع قنوعا إذا سأل وهو قانع وفي القر","page":"ج1 ص435","text":"المسكين الطواف، وقال مجاهد: القانع هنا جارك ولو كان (6) غنيا وقال الحسن: القانع الذي يسأل ويقنع بما تعطيه، وقال الفراء: القانع\nالذي إن أعطيته شيئا قبله، وقال أبو عبيدة: القانع السائل الذي قنع إليك أي خضع، وقال أبو علي: هو الفقير الذي يسأل، وقال إبراهيم: القانع الذي يجلس في بيته والمعتر الذي يعتريك."},{"id":"furuq-lughawiyya:595","bookId":"furuq-lughawiyya","type":"section","seq":595,"chapter":"* (أ) *","title":"1761 - الفرق بين القول والعبارة والكلمة: أن القول يقتضي المقول بعينه مفردا كان أو جملة أو ما يقوم مقام ذلك ولذلك تعدى تعديا مطلقا ولم","page":"ج1 ص436","text":"يتعد إلى غير المقول، والعبارة تعدت إلى معنى القول بحرف فقيل عبرت عنه."},{"id":"furuq-lughawiyya:596","bookId":"furuq-lughawiyya","type":"section","seq":596,"chapter":"* (أ) *","title":"1762 - الفرق بين القول والكلام (1) : قال الطبرسي في القرق بينهما","page":"ج1 ص437","text":"القول يدل على الحكاية.\nوليس كذلك الكلام.\nنحو قال الحمد لله.\nفإذا أخبرت عنه بالكلام قلت: تكلم بالحمد قال: والحكاية على ثلاثة أوجه.\nأحدها: حكاية على اللفظ والمعنى، نحو: \" قال ءاتوني افرغ عليه قطرا \" (1) .\nإذا حكاه من يعرف لفظه ومعناه.\nوحكاية على المعنى، وحكاية على اللفظ، نحو ما إذا حكاه من يعرف لفظه دون معناه، نحو أن يقول نحاسا بدل قوله: قطرا.\n(اللغات) ."},{"id":"furuq-lughawiyya:597","bookId":"furuq-lughawiyya","type":"section","seq":597,"chapter":"* (أ) *","title":"1765 - الفرق بين القياس وبن الاجتهاد: أن القياس حمل الشئ على الشئ في بعض أحكامه لوجه من الشبه وقيل حمل الشئ على الشئ وإجراء حكمه عليه لشبه ب","page":"ج1 ص437","text":"رحمه الله: \" حمل شئ على شئ وإجراء حكمه عليه \" ولذلك سمي المكيال مقياسا من حيث كان يحمل عليه ما يراد كيله، وكذلك يسمون ما يقدر به النعال مقياسا أيضا، ولذلك يستعمل القياس في شئ من غير إعتبار له بغيره وإنما يقال قست الشئ بالشئ\nفلا (1) يقال لمن شبه شيئا بشئ من غير أن يحمل أحدهما على الآخر ويجري حكمه عليه قايس، ولو جاز ذلك لجاز أن يسمى الله تعالى قايسا لتشبيه الكافر بالميت والمؤمن بالحي والكفر بالظلمة والايمان بالنور، ومن قال القياس إستخراج الحق من الباطل فقد أبعد لان النصوص قد يستخرج بها ذلك ولا يسمى قياسا، ومثال القياس قولك إذا كان ظلم المحسن لا يجوز من حكيم فعقوبة المحسن لا تجوز منه، والفقهاء يقولون هو حمل الفرع على الاصل لعلة الحكم، والاجتهاد موضوع في أصل اللغة لبذل المجهود، ولهذا يقال إجتهد في حمل الحجر إذا بذل مجهوده فيه ولا يقال إجتهدت في حمل النواة، وهو عند المتكلمين ما يقتضي غلبة الظن في الاحكام التي كل مجتهد فيها مصيب ولهذا يقولون قال أهل الاجتهاد كذا وقال أهل القياس كذا فيفرقون بينهما، فعلى هذا الاجتهاد أعم من القياس لانه يحتوي على القياس وغيره، وقال الفقهاء الاجتهاد بذل المجهود في تعرف حكم الحادثة من النص لا بظاهره ولا فحواه، ولذلك قال معاذ: أجتهد رأيي فيما لا أجد فيه كتابا ولا سنة، وقال الشافعي: الاجتهاد والقياس واحد وذلك أن الاجتهاد عنده هو أن يعلل أصلا ويرد غيره إليه بها،\nفأما الرأي فما أوصل إليه الحكم الشرعي من الاستدلال والقياس ولذلك قال معاذ: أجتهد رأيي، وكتب عمر هذا ما رأى عمر وقال علي عليه السلام: رأي ورأي عمر أن لا يبعن ثم رأيت بيعهن، يعني امهات الاولاد، وفيه دلالة على بطلان قول من يرد الرأي ويذمه، والترجيح ما أيد به العلة والخبر إذا قابله ما يعارضه، والاستدلال أن يدل على أن\nالحكم في الشئ ثابت من غير رده إلى أصل، والاجتهاد لا يكون إلا في الشرعيات وهو مأخوذ من بذل المجهود واستفراغ الوسع في النظر في الحادث ليرده إلى المنصوص على حسب ما يغلب في الظن وإنما يوسع ذلك مع عدم الدلالة والنص ألا ترى انه لا يجوز لاحد أن يقول إن العلم بحدوث الاجسام إجتهاد"},{"id":"furuq-lughawiyya:598","bookId":"furuq-lughawiyya","type":"section","seq":598,"chapter":"* (أ) *","title":"ك","page":"ج1 ص439","text":"ما أن سهم الجد إجتهاد، ولا يجوز أن يقال وجوب خمسة دراهم في مائتي درهم مسألة إجتهاد لكون ذلك مجمعا عليه، وقد يكون القياس في العقليات فالفرق بينه وبين الاجتهاد ظاهر."},{"id":"furuq-lughawiyya:599","bookId":"furuq-lughawiyya","type":"section","seq":599,"chapter":"* (أ) *","title":"1766 - الفرق بين القيمة والثمن: أن القيمة هي المساوية لمقدار المثمن من غير نقصان ولا زيادة، والثمن قد يكون بخسا وقد يكون وفقا وزائدا والملك","page":"ج1 ص439","text":"والدنانير وضعت الباء في الثمن لان الدراهم أبدا ثمن."},{"id":"furuq-lughawiyya:600","bookId":"furuq-lughawiyya","type":"section","seq":600,"chapter":"* (أ) *","title":"1767 - الفرق بين الثمن والقيمة (3) : الفرق بينهما أن القيمة: ما يوافق مقدار","page":"ج1 ص440","text":"الشئ، ويعادله.\nويدل عليه قول أمير المؤمنين عليه السلام: \" وقيمة المرء ما قد كان يحسنه \" (1) والثمن: ما يقع التراضي به مما يكون وفقا له، أو أزيد، أو انقص.\nويرشد إليه قوله - سبحانه -: (وشروه بثمن بخس) (2) .\nفإن تلك الدراهم العديدة لم تكن قيمة يوسف، وإنما وقع عليها التراضي، وجرى عليها البيع."},{"id":"furuq-lughawiyya:601","bookId":"furuq-lughawiyya","type":"section","seq":601,"chapter":"* (أ) *","title":"1769 - الفرق بين الكائن والواقع (1) : والفرق بينهما: أن الواقع لا يكون إلا حادثا، تشبيها بالحائط الواقع، لانه من أبين الاشياء في الحدوث.","page":"ج1 ص441","text":"والكائن أعم منه، لانه بمنزلة الموجود الثابت، يكون حادثا وغير حادث.\nقاله الطبرسي.\n(اللغات) ."},{"id":"furuq-lughawiyya:602","bookId":"furuq-lughawiyya","type":"section","seq":602,"chapter":"* (أ) *","title":"1771 - الفرق بين الكأس والقدح: وذلك أن الكأس لا تكون إلا مملؤة والقدح تكون مملؤة وغير مملؤة.","page":"ج1 ص441","text":"وكذلك الفرق بين الخوان والمائدة وذلك أنها لا تسمى مائدة إلا إذا كان عليها طعام وإلا فهو خوان.\nوالله سبحانه\nوتعالى أعلم."},{"id":"furuq-lughawiyya:603","bookId":"furuq-lughawiyya","type":"section","seq":603,"chapter":"* (أ) *","title":"1773 - الفرق بين قولك تكأدني الشئ وقولك شق علي: أن معنى قولك يكأدني آذانى ومعنى قولك شق علي، والاشق الطويل سمي بذلك لبعد أوله من آخره والشقة","page":"ج1 ص442","text":"تكلف ومنه قيل القمر الباهر."},{"id":"furuq-lughawiyya:604","bookId":"furuq-lughawiyya","type":"section","seq":604,"chapter":"* (أ) *","title":"1775 - الفرق بين الكافر والمشرك (1) : قال بعض المتأخرين: الكافر اسم لمن لا إيمان له، فإن أظهر الايمان خص باسم المنافق، وإن أظهر الكفر","page":"ج1 ص443","text":"بعد الاسلام خص باسم المرتد، لرجوعه عن الاسلام.\nفإن قال بإلهين فصاعدا خص باسم المشرك، وإن كان متدينا ببعض الاديان والكتب المنسوخة خص باسم الكتابي، وإن كان يقول بقدم الدهر وإستناد الحوادث إليه سمي باسم الدهري.\nوإن كان لا يثبت البارئ خص باسم المعطل، وإن كان مع اعترافه بنبوة نبينا محمد صلى الله عليه وآله، وإظهار شرائع الاسلام، ويبطن عقائد من كفر بالاتفاق خص باسم الزنديق.\n(اللغات) ."},{"id":"furuq-lughawiyya:605","bookId":"furuq-lughawiyya","type":"section","seq":605,"chapter":"* (أ) *","title":"1776 - الفرق بين كاف التشبيه وبين المثل: أن الشئ يشبه بالشئ من وجه واحد لا يكون مثله في الحقيقة إلا إذا أشبهه من جميع الوجوه لذاته فكأن الله","page":"ج1 ص443","text":"وبالمثل يفيد تشبيه الذوات بعضها ببعض تقول ليس كزيد رجل أي في بعض صفاته لان كل أحد مثله في الذات، وفلان كالاسد أي في الشجاعة دون الهيئة وغيرها من صفاته وتقول السواد عرض كالبياض ولا تقول مثل البياض."},{"id":"furuq-lughawiyya:606","bookId":"furuq-lughawiyya","type":"section","seq":606,"chapter":"* (أ) *","title":"1777 - الفرق بين الكبر والتيه: أن الكبر هو إظهار عظم الشأن وهو في صفات الله تعالى مدح لان شأنه عظيم، وفي صفاتنا ذم لان شأننا صغير وهو أهل لل","page":"ج1 ص444","text":"أعلى مراتب التعظيم ويستحيل مساواة الاصغر له فيها على وجه من الوجوه، والكبير الشخص والكبير في السن والكبير في الشرف والعلم يمكن مساواة الصغير له، أما في السن فبتضاعف مدة البقاء في الشخص تتضاعف أجزاؤه، وأما بالعلم فباكتساب مثل ذلك العلم.\nوالتيه أصله الحيرة والضلال وإنما سمي المتكبر تائها على وجه التشبيه بالضلال والتحير ولا يوصف الله به، والتيه من الارض ما يتحير فيه وفي القرآن \" يتيهون في الارض \" (1) أي يتحيرون."},{"id":"furuq-lughawiyya:607","bookId":"furuq-lughawiyya","type":"section","seq":607,"chapter":"* (أ) *","title":"1781 - الفرق بين الكبر والكبرياء: أن الكبر ما ذكرناه (2) والكبرياء هي العز والملك وليست من الكبر في شئ والشاهد قوله تعالى \" وتكون لكما الكبر","page":"ج1 ص445","text":"فهو إظهار الكبر مثل التشجع إظهار الشجاعة إلا أنه في صفات الله تعالى بمعنى أنه يحق له أن يعتقد أنه الكبير وهو على معنى قولهم تقدس وتعالى، لا على ترفع علينا وتعظيم.\nوقيل المتكبر في صفاته بمعنى أنه المتكبر عن ظلم عباده."},{"id":"furuq-lughawiyya:608","bookId":"furuq-lughawiyya","type":"section","seq":608,"chapter":"* (أ) *","title":"1787 - الفرق بين الكتاب والباب والفصل (1) : قال شيخنا الرنيني طاب ثراه: الكتاب هو الجامع لمسائل متحدة في الجنس مختلفة في النوع.","page":"ج1 ص445","text":"والباب: هو الجامع لمسائل متحدة في النوع، مختلفة في الصنف.\nوالفصل: هو الجامع لمسائل متحدة في الصنف، مختلفة في الشخص.\n(اللغات) ."},{"id":"furuq-lughawiyya:609","bookId":"furuq-lughawiyya","type":"section","seq":609,"chapter":"* (أ) *","title":"1795 - الفرق بين الكتمان والاختفاء: أن الكتمان هو السكوت عن المعنى وقوله تعالى \" إن الذين يكتمون ما أنزلنا من البينات \" (2) أي","page":"ج1 ص447","text":"يسكتون عن ذكره، والاخفاء يكون في ذلك وفي غيره، والشاهد أنك تقول أخفيت الدرهم في الثوب ولا تقول كتمت ذلك وتقول كتمت المعنى وأخفيته فالاخفاء أعم من الكتمان."},{"id":"furuq-lughawiyya:610","bookId":"furuq-lughawiyya","type":"section","seq":610,"chapter":"* (أ) *","title":"1796 - الفرق بين الكتمان والسر (1) : قيل: المكتوم يختص بالمعاني كالاسرار والاخبار، لان الكتمان لا يستعمل إلا فيهما.","page":"ج1 ص447","text":"والمستور يختص بالجثث والاعيان، لان الاصل في السر تغطية الشئ بغطاء.\nثم استعمل في غيرها تجوزا.\nقلت: ويؤيده عبارة الدعاء في الصحيفة الشريفة: (2) \" ولا تبرز مكتومي ولا تكشف مستوري \".\nوالعطف ظاهر في المغايرة فهو من باب عطف (3) الشئ على مغايره، أو من عطف العام على الخاص.\n(اللغات) ."},{"id":"furuq-lughawiyya:611","bookId":"furuq-lughawiyya","type":"section","seq":611,"chapter":"* (أ) *","title":"1798 - الفرق بين الكثير والكبير (4) : وقد فرق بينهما بأن الكبير - بالباء الموحدة - بحسب الشأن والخطر، كالجليل والعظيم.","page":"ج1 ص447","text":"والكثير - بالمثلثة - بحسب الكمية والعدد (5) فيقال: دار واحدة كبيرة.\nولا يجوز: كثيرة.\nويقال: جنود كثيرة ولا يجوز: كبيرة، وأيضا: الكبير نقيض الكثير، والكثير نقيض القليل (1) .\n(اللغات) ."},{"id":"furuq-lughawiyya:612","bookId":"furuq-lughawiyya","type":"section","seq":612,"chapter":"* (أ) *","title":"1801 - الفرق بين الكذب والافتراء والبهتان (3) : الكذب: هو عدم مطابقة الخبر للواقع، أو (4) لاعتقاد المخبر لهما على خلاف في ذلك.","page":"ج1 ص448","text":"والافتراء: أخص منه، لانه الكذب في حق الغير بما لا يرتضيه، بخلاف الكذب فإنه قد يكون في حق المتكلم نفسه، ولذا يقال لمن قال: (فعلت كذا ولم أفعل كذا) مع عدم صدقه في ذلك: هو\nكاذب، ولا يقال: هو مفتر، وكذا من مدح أحدا بما ليس فيه، يقال: إنه كاذب في وصفه، ولا يقال: هو مفتر، لان في ذلك مما يرتضيه المقول فيه غالبا.\nوقال سبحانه حكاية عن الكفار: \" افترى على الله كذبا \" (1) .\nلزعمهم أنه أتاهم بما لا يرتضيه الله سبحانه مع نسبته إليه.\nوأيضا قد يحسن الكذب على بعض الوجوه، كالكذب في الحرب، وإصلاح ذات البين، وعدة الزوجة، كما وردت به الرواية، بخلاف الافتراء.\nوأما البهتان: فهو الكذب الذي يواجه به صاحبه على وجه المكابرة له.\nقال تعالى: \" وقولهم على مريم بهتانا عظيما \" (2) .\nفإن اليهود كانوا يواجهون مريم - عليها السلام - بالقذف، وينسبونها إلى ما لا ينبغي من القول بالمشافهة.\n(اللغات) ."},{"id":"furuq-lughawiyya:613","bookId":"furuq-lughawiyya","type":"section","seq":613,"chapter":"* (أ) *","title":"1802 - الفرق بين الكذب والافك: أن الكذب إسم موضوع للخبر الذي لا مخبر له على ما هو به، وأصله في العربية التقصير ومنه قولهم كذب عن قرنه في الح","page":"ج1 ص449","text":"قبحها على ما ذكرنا وأصله في العربية الصرف وفي القرآن \" أنى\nيؤفكون \" (1) أي يصرفون عن الحق، وتسمى الرياح المؤتفكات لانها تقلب الارض فتصرفها عما عهدت عليه، وسميت ديار قوم لوط المؤتفكات لانها قلبت بهم."},{"id":"furuq-lughawiyya:614","bookId":"furuq-lughawiyya","type":"section","seq":614,"chapter":"* (أ) *","title":"1810 - الفرق بين الكراهة ونفور الطبع: أن الكراهة ضد الارادة، ونفور الطبع ضد الشهوة وقد يريد الانسان شرب الدواء المر مع نفور طبعه منه، ولو كا","page":"ج1 ص451","text":"لكثرة ما يكره الانسان ما ينفر طبعه منه، ولذلك تسمى الشهوة محبة والمشتهي محبوبا لكثرة ما يحب الانسان ما يشتهيه ويميل إليه طبعه، ونفور الطبع يختص بما يؤلم ويشق على النفس، والكراهة قد تكون كذلك ولما يلذ ويشتهي من المعاصي وغيرها."},{"id":"furuq-lughawiyya:615","bookId":"furuq-lughawiyya","type":"section","seq":615,"chapter":"* (أ) *","title":"1814 - الفرق بين الكريم والمتكرم (1) : قال الراغب: إذا وصف الله بالكرم بمعنى انتفاء النقائص عن الشئ، واتصافه بجميع المحامد فهذا المعنى صحيح","page":"ج1 ص451","text":"والمتكرم: البليغ الكرم أو المتنزه عما لا يليق بجنابه الاقدس.\nمن قولهم: تكرم عن كذا بمعنى: تنزه.\n(اللغات) ."},{"id":"furuq-lughawiyya:616","bookId":"furuq-lughawiyya","type":"section","seq":616,"chapter":"* (أ) *","title":"1816 - الفرق بين الكسب والاكتساب: (2) : قيل: الاول أخص، لان الكسب لنفسه ولغيره، والاكتساب ما يكتسبه لنفسه خاصة.","page":"ج1 ص451","text":"وقيل: في الاكتساب مزيد أعمال، وتصرف، لهذا خص بجانب الشرفي قوله تعالى: \" لها ما كسبت وعليها ما اكتسبت \" (3) .\nدلالة\nعلى أن العبد لا يؤاخذ من السيئات إلا بما عقد الهمة عليه، وربط القلب به، بخلاف الخير، فإنه يثاب عليه كيفما صدر عنه.\n(اللغات) ."},{"id":"furuq-lughawiyya:617","bookId":"furuq-lughawiyya","type":"section","seq":617,"chapter":"* (أ) *","title":"1821 - الفرق بين الكفالة والضمان: أن الكفالة تكون بالنفس والضمان","page":"ج1 ص452","text":"يكون بالمال، ألا ترى أنك تقول كفلت زيدا وتريد إذا التزمت (1) تسليمه، وضمنت الارض إذا التزمت أداء الاجر عنها ولا يقال كفلت بالارض لان عينها لا تغيب فيحتاج إلى إحضارها فالضمان إلتزام شئ عن المضمون والكفالة إلتزام نفس المكفول به ومنه كفلت الغلام إذا ضممته إليك لتعوله، ولا تقول ضمنته لانك إذا طولبت به لزمك تسليمه ولا يلزمك تسليم شئ عنه وفي القرآن \" وكفلها زكريا \" (2) ولم يقل ضمنها، ومن الدليل على أن الضمان يكون للمال والكفالة للنفس أن الانسان يجوز أن يضمن عمن لا يعرفه، ولا يجوز أن يكفل من لا يعرفه لانه إذا لم يعرفه لم يتمكن من تسليمه ويصح أن يؤدي عنه وإن لم يعرفه."},{"id":"furuq-lughawiyya:618","bookId":"furuq-lughawiyya","type":"section","seq":618,"chapter":"* (أ) *","title":"1823 - الفرق بين الكفر والشرك: أن الكفر خصال كثيرة على ما ذكرنا (3) وكل خصلة منها تضاد خصلة من الايمان لان العبد إذا فعل خصلة","page":"ج1 ص454","text":"من الكفر فقد ضيع خصلة من الايمان، والشرك خصلة واحدة وهو إيجاد الهية مع الله أو دون الله واشتقاقه ينبئ عن هذا المعنى ثم كثر حتى قيل لكل كفر شرك على وجه التعظيم له والمبالغة في صفته وأصله كفر النعمة ونقيضه الشكر ونقيض الكفر بالله الايمان، وإنما قيل لمضيع الايمان كافر لتضييعه حقوق الله تعالى وما يجب عليه من شكر نعمه فهو بمنزلة الكافر لها ونقيض الشرك في الحقيقة الاخلاص ثم لما استعمل في كل كفر صار نقيضه الايمان ولا يجوز أن يطلق إسم الكفر إلا لمن كان بمنزلة الجاحد لنعم الله وذلك لعظم ما معه من المعصية وهو إسم شرعي كما أن الايمان إسم شرعي."},{"id":"furuq-lughawiyya:619","bookId":"furuq-lughawiyya","type":"section","seq":619,"chapter":"* (أ) *","title":"1835 - الفرق بين الكل والكلي (2) : قد فرق بينهما بوجوه منها: أن الكل","page":"ج1 ص456","text":"متقوم بأجزائه، والكلي متقوم بجزئياته.\n- ومنها: أن الكل في الخارج، والكلي في الذهن.\n- ومنها: أن أجزاء الكل تتناهى وجزئيات الكلي غير متناهية.\n- ومنها: أن الكل لا يحمل على أجزائه كالسكنجبين مثلا، فإنه لا يطلق على كل من العسل والخل بانفراده، إنه سكنجبين.\nوالكلي يحمل على جزئياته، كالانسان بالنسبة إلى أفراده، فإنه يطلق على زيد وعمر وأنه إنسان.\n(اللغات) ."},{"id":"furuq-lughawiyya:620","bookId":"furuq-lughawiyya","type":"section","seq":620,"chapter":"* (أ) *","title":"1836 - الفرق بين الكلمة والعبارة: أن الكلمة الواحدة من جملة الكلام ثم سميت القصيدة كلمة لانها واحدة من جملة القصائد.","page":"ج1 ص456","text":"والعبارة عن الشئ هي الخبر عنه بما هو عليه من غير زيادة ولا نقصان ألا ترى انه لو سئل عن الجسم فقيل هو الطويل العريض العميق المانع لم يكن ذلك عبارة عن الجسم لزيادة المانع في صفته ولو قيل هو الطويل العريض لم يكن ذلك عبارة عنه أيضا لنقصان العمق من حده.\nويقال فلان يعبر عن فلان إذا كان يؤدي معاني كلامه على وجهها من غير زيادة فيها ولا نقصان منها وإذا زاد فيها أو نقص منها لم يكن معبرا عنه.\nوقيل العبارة من قولك عبرت الدنانير وإنما يعبر ليعرف مقدار وزنها فيرتفع الاشكال في صفتها بالزيادة والنقصان.\nوسميت العبارة عبارة لانها تعبر المعنى إلى المخاطب، والتعبير وزن الدنانير لانها تعبر به من حال المقدار إلى ظهره.\nوالعبرة الدمعة المترددة في العين لعبورها من أحد الجانبين إلى الآخر، والعبرة الآية التي يعبر بها من منزلة الجهل إلى العلم، والتعبير تفسير الرؤيا لانه يعبر بها من حال النوم إلى اليقظة، والعبارة بمنزلة القول في أنها إسم لما يتكلم به المتكلم أجمع\nوأنها تقتضي معبرا عنه، وتكون مفردا وجملة فالمفرد قولك عبرت عن الرجل بزيد، والجملة قولك عبرت عما قلته بقام زيد وبزيد منطلق."},{"id":"furuq-lughawiyya:621","bookId":"furuq-lughawiyya","type":"section","seq":621,"chapter":"* (أ) *","title":"1841 - الفرق بين قولك كننته وقولك سترته: أن معنى كننته صنته والموضع الكنين هو المصون وذلك أنه يكون كنينا وإن لم يكن مستورا، وقيل","page":"ج1 ص458","text":"الدر المكنون لانه في حق يصان فيه، وجارية مكنونة في الحجاب أي مصونة قال الاعشى: * وبيضة في الدعص مكنونة * والبيضة ليست بمستورة وإنما هي مصونة عن الترجرج والانكسار، واكتننت الشئ في نفسي إذا صنته عن الاداء ودخلت فيه الالف واللام على معنى جعلت له كذا، وفي القرآن \" ما تكن صدورهم \" (1) ."},{"id":"furuq-lughawiyya:622","bookId":"furuq-lughawiyya","type":"section","seq":622,"chapter":"* (أ) *","title":"1845 - الفرق بين الكون والسكون: أن الجوهر في حال وجوده كائن وليس بساكن، والكون في حال خلق الله تعالى الجسم يسمى كونا فقط وما يوجد عقيب ضده م","page":"ج1 ص459","text":"عدم، والسكون هو الذي يوجب كون الجسم في المحاذاة التي كان فيها بلا فصل ودخل فيه الباقي والحادث، واعلم أن القيام والقعود والاضطجاع والصعود والنزول وما شاكل ذلك عبارات عن أكوان\nتقع على صفات معقولة."},{"id":"furuq-lughawiyya:623","bookId":"furuq-lughawiyya","type":"section","seq":623,"chapter":"* (أ) *","title":"ل","page":"ج1 ص459","text":"ا توجد إلا في الجزئين وأيضا فإنك تبطل الكون من الحجر بنقلك اياه من غير أن تبطل مماسته، وتبطل مماسة الجسم بنقل جسم عنه من غير أن يبطل كونه، وأيضا فإن الجسم قد تم بين الجسم من الجهات الست ولا يكون كائنا إلا في مكان واحد وأيضا فإنه يوجد الكون والمكان معدوم ولا توجد المماسة والمماس معدوم، وأيضا فإن المماسة تحل المماس وتحل (1) مكانه، والكون لا يحل إلا مكانه."},{"id":"furuq-lughawiyya:624","bookId":"furuq-lughawiyya","type":"section","seq":624,"chapter":"* (أ) *","title":"1850 - الفرق بين لا وما: أن لا سؤال إستفهام كقولك أتقول كذا فيكون","page":"ج1 ص460","text":"الجواب لا، وما جواب عن الدعوى تقول قلت كذا فيكون الجواب ما قلت."},{"id":"furuq-lughawiyya:625","bookId":"furuq-lughawiyya","type":"section","seq":625,"chapter":"* (أ) *","title":"1852 - الفرق بين اللئيم والبخيل (1) : قال صاحب أدب الكاتب: \" يذهب الناس إلى أنهما سواء، وليس كذلك، إنما البخيل: الشحيح الضنين (2) ، واللئيم:","page":"ج1 ص460","text":"يقال لكل لئيم بخيل، وليس كل بخيل لئيما \".\n(اللغات) ."},{"id":"furuq-lughawiyya:626","bookId":"furuq-lughawiyya","type":"section","seq":626,"chapter":"* (أ) *","title":"1855 - الفرق بين اللحن والخطأ: أن اللحن صرفك الكلام عن جهته ثم صار إسما لازما لمخالفة الاعراب، والخطأ إصابة خلاف ما يقصد وقد يكون","page":"ج1 ص461","text":"في القول والفعل، واللحن لا يكون إلا في القول تقول لحن في كلامه ولا يقال لحن في فعله كما يقال أخطأ في فعله إلا على إستعارة بعيدة، ولحن القول ما دل عليه القول وفي القرآن \" ولتعرفنهم في لحن القول \" (1) وقال إبن الانباري: لحن القول معنى القول ومذهبه واللحن أيضا اللغة يقال هذا بلحن اليمن، واللحن بالتحريك الفطنة ومنه قوله عليه السلام فلعل بعضكم ألحن بحجته."},{"id":"furuq-lughawiyya:627","bookId":"furuq-lughawiyya","type":"section","seq":627,"chapter":"* (أ) *","title":"1859 - الفرق بين اللذة والنعمة: أن اللذة لا تكون الا مشتهاة ويجوز أن تكون نعمة لا تشتهي كالتكليف، وإنما صار التكليف نعمة لانه يعود عليها بمن","page":"ج1 ص462","text":"كما يسمى الشئ بإسم سببه."},{"id":"furuq-lughawiyya:628","bookId":"furuq-lughawiyya","type":"section","seq":628,"chapter":"* (أ) *","title":"1860 - الفرق بين اللذع واللسع (1) : الفرق بينهما أن اللذع: يقال لما يضرب بفيه كالحية.","page":"ج1 ص462","text":"ومنه قول بعض الرجاز (2) .\nإن العجوز حين شاب صدغها * كالحية الصماء طال لدغها!\nواللسع: يقال لكل ما يضرب بمؤخره كالزنبور والعقرب قال أبو ذؤيب (3) : إذا لسعته النحل لم يرج لسعها * وخالفها في بيت نوب عواسل قال الحريري: وأكثر أهل اللغة لم يفرقوا بينهما.\n(اللغات) ."},{"id":"furuq-lughawiyya:629","bookId":"furuq-lughawiyya","type":"section","seq":629,"chapter":"* (أ) *","title":"1864 - الفرق بين اللطف والتوفيق: أن اللطف هو فعل تسهل به الطاعة على العبد ولا يكون لطفا إلا مع قصد فاعله وقوع ما هو لطف فيه من الخير خاصة، ف","page":"ج1 ص463","text":"والتوفيق فعل ما تتفق معه الطاعة وإذا لم\nتتفق معه الطاعة لم يسم توفيقا ولهذا قالوا إنه لا يحسن الفعل.\nوفرقا آخر وهو أن التوفيق لطف يحدث قبل الطاعة بوقت فهو كالمصاحب لها في وقته لان وقته يلي وقت فعل الطاعة ولا يجوز أن يكون وقتهما واحدا لانه بمنزلة مجئ زيد مع عمرو وإن كان بعده بلا فصل فأما إذا جاء بعده بأوقات فإنه لم يجئ معه، واللطف قد يتقدم الفعل بأوقات يسيرة يكون له معها تأثير في نفس الملطوف له ولا يجوز أن يتقدمه بأوقات كثيرة حتى لا يكون له معها في نفسه تأثير، فكل توفيق لطف وليس كل لطف توفيقا ولا يكون التوفيق ثوابا لانه يقع قبل الفعل ولا يكون الثواب ثوابا لما لم يقع ولكن التسمية بموفق على جهة المدح يكون ثوابا على ما سلف من الطاعة، ولا يكون التوفيق إلا لما حسن من الافعال يقال وفق فلان للانصاف ولا تقول وفق للظلم ويسمى توفيقا وإن كان منقضيا في حال ما وصف به أنه توفيق فيه\nكما يقال زيد وافق عمروا في هذا القول وإن كان قول عمرو قد انقضى، واللطف يكون التدبير الذي ينفذ في صغير الامور وكبيرها فالله تعالى لطيف ومعناه أن تدبيره لا يخفى عن شئ ولا يكون ذلك إلا باجرائه على حقه.\nوالاصل في اللطيف التدبير ثم حذف واجريت الصفة للمدبر على جهة المبالغة وفلان لطيف الحيلة إذا كان يتوصل إلى بغيته بالرفق والسهولة ويكون اللطف حسن العشرة والمداخلة في الامور بسهولة، واللطف أيضا صغر الجسم خلاف الكثافة واللطف أيضا صغر الجسم وهو خلاف الخفاء في المنظر، وفي اللطيف\nمعنى المبالغة لانه فعيل، وفي موفق معنى تكثير الفعل وتكريره لانه مفعل، والعصمة هي اللطيفة التي يمتنع بها عن المعصية إختيارا والصفة بمعصوم إذا أطلقت فهي صفة مدح وكذلك الموفق فإذا اجري على التقييد فلا مدح فيه ولا يجوز أن يوصف غير الله بأنه يعصم ويقال عصمه من كذا ووفقه لكذا ولطف له في كذا فكل واحد من هذه الافعال يعدي بحرف وهاهنا يوجب أيضا أن يكون بينهما فروق من غير هذا الوجه الذي ذكرناه وشرح هذا يطول فتركته كراهة الاكثار واصولهما في اللغة واشتقاقاتهما أيضا توجب فروقا من وجوه اخر فاعلم ذلك."},{"id":"furuq-lughawiyya:630","bookId":"furuq-lughawiyya","type":"section","seq":630,"chapter":"* (أ) *","title":"1872 - الفرق بين اللغز والمعمى (1) : قد فرق بينهما بأن الكلام إذا دل على","page":"ج1 ص465","text":"اسم شئ من الاسماء بذكر صفات له تميزه عما عداه، كان ذلك لغزا، وإذا دل على اسم خاص بملاحظة كونه لفظا بدلالة بينة تؤثره، سمي ذلك معمى.\nفالكلام الدال على بعض الاسماء يكون معمى من حيث إن مدلوله اسم من الاسماء بملاحظة الرمز على حروفه، ولغزا من حيث إن مدلوله ذات من الذوات بملاحظة أوصافها.\nفعلى هذا يكون قول القائل: يا أيها العطار أعرب لنا * عن اسم شئ قل في سومك تنظره بالعين في يقظة * كما ترى بالقلب في نومك! يصلح أن يكون لغزا بملاحظة دلالته على صفات الكمون.\nويصلح أن يكون معمى باعتبار دلالته على اسم بطريق الرمز (اللغات)"},{"id":"furuq-lughawiyya:631","bookId":"furuq-lughawiyya","type":"section","seq":631,"chapter":"* (أ) *","title":"1873 - الفرق بين اللقاء والاجتماع (1) : قال الطبرسي، رضي الله عنه: اللقاء: هو الاجتماع على وجه المقارنة، والاتصال.","page":"ج1 ص466","text":"والاجتماع قد يكون على غير المقارنة والاتصال، فلا يكون لقاء (2) ، كاجتماع القوم في الدار، وإن لم يكن هناك اتصال.\nانتهى.\nويدل عليه قوله تعالى: \" وإذا لقوا الذين آمنوا قالوا آمنا \" (3) فإن المراد حين المواجهة والتحدث.\nوقوله \" لئن اجتمعت الانس والجن على أن يأتوا بمثل هذا القران ... \" (4) .\nالآية، فإن المراد اتفاقهم وتعاضدهم سواء كان ذلك\nمع مشافهة أم لا، كما هو ظاهر.\n(اللغات) ."},{"id":"furuq-lughawiyya:632","bookId":"furuq-lughawiyya","type":"section","seq":632,"chapter":"* (أ) *","title":"الفرق بين اللمس والمس","page":"ج1 ص467","text":"أن اللمس يكون باليد خاصة ليعرف اللين من الخشونة والحرارة من البرودة، والمس يكون باليد وبالحجر وغير ذلك ولا يقتضي أن يكون باليد ولهذا قال تعالى \" مستهم البأساء \" (2)\nوقال \" وإن يمسسك الله بضر \" (3) ولم يقل يلمسك."},{"id":"furuq-lughawiyya:633","bookId":"furuq-lughawiyya","type":"section","seq":633,"chapter":"* (أ) *","title":"1880- الفرق بين اللمس والمس","page":"ج1 ص467","text":"الفرق بين اللمس والمس (4) .\nقيل: الفرق بينهما أن اللمس لصوق بإحساس، والمس: لصوق فقط.\nوقد يكون اللمس بمعنى المس.\nوقال البيضاوي: المس: إيصال الشئ بالبشرة بحيث تتأثر الحاسة.\nواللمس كالطلب له، ولذلك يقال: ألمسه فلا أجده.\nانتهى.\nوالمراد أن اللمس ينبئ عن اعتبار الطلب له سواء كان داخلا في مفهومه، أو لازما له.\nوقد يستعار اللمس للاصابة، ومنه قوله\nتعالى: \" إن تمسسكم حسنة \" (1) .\nقال في الاساس (2) : ومن المجاز: مسه الكبر، ومسه العذاب، انتهى.\nوقال علي بن عيسى (3) : إن المس يكون بين جمادين، واللمس لا يكون إلا بين حيين، لما فيه من [25 / أ] .\n(اللغات) ."},{"id":"furuq-lughawiyya:634","bookId":"furuq-lughawiyya","type":"section","seq":634,"chapter":"* (أ) *","title":"الفرق بين اللهو واللعب","page":"ج1 ص468","text":"أنه لا لهو إلا لعب وقد يكون لعب ليس بلهو لان اللعب يكون للتأديب كاللعب بالشطرنج وغيره ولا يقال لذلك\nلهو وإنما اللهو لعب لا يعقب نفعا وسمي لهوا لانه يشغل عما يعني من قولهم ألهاني الشئ أي شغلني ومنه قوله تعالى \" ألهاكم التكاثر \" (1) ."},{"id":"furuq-lughawiyya:635","bookId":"furuq-lughawiyya","type":"section","seq":635,"chapter":"* (أ) *","title":"1886 - الفرق بين اللهو واللعب (2) : اللهو: ما يشغل الانسان عما يعنيه.","page":"ج1 ص469","text":"ويهمه.\nواللعب: طلب المزح بما لا يحسن أن يطلب به (3) .\nقيل واشتقاقه اللعاب، وهو المرور على غير استواء.\nكلعاب الطفل.\n(اللغات) ."},{"id":"furuq-lughawiyya:636","bookId":"furuq-lughawiyya","type":"section","seq":636,"chapter":"* (أ) *","title":"م","page":"ج1 ص470","text":"وقع الضرر في فعلة وتهجين طريقته فيه، وقد يكون اللوم على الفعل الحسن كاللوم على السخاء والذم لا يكون إلا على القبيح واللوم أيضا يواجه به الملوم، والذم قد يواجه به المذموم ويكون دونه، وتقول حمدت هذا الطعام أو ذممته وهو إستعارة ولا يستعار اللوم في ذلك."},{"id":"furuq-lughawiyya:637","bookId":"furuq-lughawiyya","type":"section","seq":637,"chapter":"* (أ) *","title":"1900 - الفرق بين المالك والملك (2) : الملك: القادر الواسع المقدور الذي","page":"ج1 ص472","text":"له السياسة والتدبير.\nوالمالك: القادر على التصرف في ماله، وله أن يتصرف فيه على وجه ليس لاحد منعه منه.\nقال شيخنا الطبرسي في المجمع في تفسير الفاتحة: (3) \" اختلفوا في أن أي القراءتين أمدح، فمن قرأ (مالك) ،\nقال: إن هذه الصفة أمدح.\nلانه لا يكون مالكا للشئ، إلا وهو يملكه، وقد يكون ملكا للشئ ولا يملكه، كما يقال: ملك العرب.\nوملك الروم، وإن كان لا يملكهم.\nوقد يدخل في المالك ما لا يصح دخوله في الملك.\nيقال: فلان مالك الدراهم، ولا يقال: ملك الدراهم.\nفالوصف بالمالك أعم من الوصف بالملك.\nوالله تعالى مالك كل شئ وقد وصف نفسه بأنه: مالك الملك.\nيؤتي الملك من يشاء.\nفوصفه بالمالك، أبلغ في الثناء والمدح من وصفه بالملك.\nومن قرأ (ملك) قال: إن هذه الصفة أمدح.\nلانه لا يكون إلا مع التعظيم والاحتواء [26 / أ] عل الجمع الكثير، واختاره السراج (1) ، وقال: إن الملك الذي يملك الكثير من الاشياء، ويشارك غيره من الناس في ملكه بالحكم عليه.\nفكل ملك مالك، وكل مالك ليس ملكا، وإنما قال تعالى \" مالك الملك \" (2) ، لانه تعالى يملك ملوك الدنيا وما ملكوا فمعناه أنه يملك ملوك الدنيا، فيؤتي الملك فيها من يشاء.\nفأما يوم الدين، فليس إلا ملكه، وهو ملك الملوك يملكهم\nكلهم: \" وقد يستعمل هذا في الناس، يقال: فلان ملك الملوك، وأمير الامراء، يريد بذلك، أن من دونه ملوكا وامراء، ولا يقال: ملك الملك، ولا أمير الإمارة، لأن (أميرا) و (ملكا) صفة غير جارية على فعل، فلا معنى لاضافتهما إلى المصدر \" انتهى ملخصا.\n(اللغات) ."},{"id":"furuq-lughawiyya:638","bookId":"furuq-lughawiyya","type":"section","seq":638,"chapter":"* (أ) *","title":"1901 - الفرق بين مالك وملك: أن مالك يفيد مملوكا، وملكا لا يفيد ذلك ولكنه (3) يفيد الامر وسعة المقدرة على أن المالك أوسع من الملك","page":"ج1 ص474","text":"لانك تقول الله مالك الملائكة والانس والجن ومالك الارض والسماء ومالك السحاب والرياح ونحو ذلك، ومالك لا يحسن إلا في الملائكة والانس والجن قال الفرزدق: سبحان من عنت الوجوه لوجهه * ملك الملوك ومالك الغفر ولو قال ملك (1) الغفر لم يحسن."},{"id":"furuq-lughawiyya:639","bookId":"furuq-lughawiyya","type":"section","seq":639,"chapter":"* (أ) *","title":"1907 - الفرق بين المباح والحسن: أن كل مباح حسن وليس كل حسن","page":"ج1 ص474","text":"مباحا وذلك أن أفعال الطفل والملجأ قد تكون حسنة وليست بمباحة."},{"id":"furuq-lughawiyya:640","bookId":"furuq-lughawiyya","type":"section","seq":640,"chapter":"* (أ) *","title":"1908 - الفرق بين المبدئ والمبتدئ: أن المبدئ للفعل هو المحدث له وهو مضمن بالاعادة وهي فعل الشئ كرة ثانية ولا يقدر عليها إلا الله تعالى، فأما","page":"ج1 ص475","text":"إلا لفعل يتطاول كمبتدئ بالصلاة وبالاكل وهو عبارة عن أول أخذه فيه."},{"id":"furuq-lughawiyya:641","bookId":"furuq-lughawiyya","type":"section","seq":641,"chapter":"* (أ) *","title":"1913 - الفرق بين المتانة والقوة: أن المتانة صلابة في إرتفاع، والمتن من الارض الصلب المرتفع والجمع متان، ومنه سمي عقب الظهر متنا، والصلابة قر","page":"ج1 ص475","text":"أعلم."},{"id":"furuq-lughawiyya:642","bookId":"furuq-lughawiyya","type":"section","seq":642,"chapter":"* (أ) *","title":"1914 - الفرق بين المتحقق والعالم: أن المتحقق هو المتطلب حق المعنى حتى يدركه كقولك تعلم أي اطلب العلم، ولهذا لا يقال ان الله متحقق","page":"ج1 ص476","text":"وقيل التحقق لا يكون إلا بعد شك تقول تحققت ما قلته فيفيد ذلك أنك عرفته بعد شك فيه."},{"id":"furuq-lughawiyya:643","bookId":"furuq-lughawiyya","type":"section","seq":643,"chapter":"* (أ) *","title":"1924 - الفرق بين المتكير والكبير (1) : قال بعض المحققين: الكبير هو الذي كل شئ، دونه، لكمال وجوده، وكمال الوجود يرجع إلى شيئين: أحدهما دوامه","page":"ج1 ص476","text":"فالكبر يستعمل فيما\nلا يستعمل فيه العظيم.\nفإن كان ما طال وجوده - مع كونه محدود مدة البقاء كبيرا - كان الدائم الازلي الابدي الذي يستحيل عليه العدم أولى بأن يكون كبيرا.\nوالثاني: أن وجوده هو الوجود الذي يصدر عنه وجود كل موجود، فإن كان الذي تم وجوده في نفسه كاملا وكبيرا، فالذي حصل منه الوجود لجميع الموجودات أحق أن يكون كاملا وكبيرا.\nوالمتكبر: ذو الكبرياء والعظمة والجبروت، فهو الذي يرى الكل حقيرا بالاضافة إلى ذاته، ولا يرى الكمال والشرف والعز إلا لنفسه.\nفإن كانت هذه الرؤية صادقة، كان التكبر حقا محمودا، وكان صاحبها جديرا بأن يتكبر حقا.\nولا يتصور ذلك على الاطلاق إلا الله - سبحانه - وإن كان ذلك الرأي باطلا، ولم يكن ما يراه من التفرد بالعظمة كما يراه، كان التكبر باطلا مذموما.\nوكل من رأى العظمة والكبرياء لنفسه على الخصوص دون غيره كانت رؤيته كاذبة ونظره باطلا إلا الله سبحانه وتعالى.\n(اللغات) ."},{"id":"furuq-lughawiyya:644","bookId":"furuq-lughawiyya","type":"section","seq":644,"chapter":"* (أ) *","title":"1925 - الفرق بين المتكلم والكلماتي: أن المتكلم هو فاعل الكلام ثم استعمل في القاص ومن يجري مجراه من أهل الجدل على وجه الصناعة.","page":"ج1 ص477","text":"والكلماتي الحقت به الزوائد للمبالغة ومثله الشعراني.\nوالصفة به تلحق الذرب اللسان المقتدر على الكلام القوي على الاحتجاج ولا يوصف الله تعالى به لان الصفة بالذرابة لا تلحقه."},{"id":"furuq-lughawiyya:645","bookId":"furuq-lughawiyya","type":"section","seq":645,"chapter":"* (أ) *","title":"1926 - الفرق بين المتمكن والقادر: أن المتمكن مضمن بالآلة والمكان الذي يتمكن فيه، ولهذا لا تجوز الصفة به على الله تعالى، وصفة القادر مطلقة","page":"ج1 ص477","text":"لانه لا يجوز أن يستغني بنفسه عن القدرة كما يستغني بها عن الآلة في الكتابة ونحوها ويقال مكنه ومكن له قال بعضهم معناهما واحد، قال ومنه قوله تعالى \" مكناهم في الارض ما لم نمكن لكم \" (1) قال فجاء باللغتين للتوسع في الكلام، والصحيح أن مكنت له جعلت له ما يتمكن به ومكنته أقدرته على ملك الشئ في المكان."},{"id":"furuq-lughawiyya:646","bookId":"furuq-lughawiyya","type":"section","seq":646,"chapter":"* (أ) *","title":"1927 - الفرق بين المتناقض والمحال: أن من المتناقض ما ليس بمحال وذلك ان القائل ربما قال صدقا ثم نقضه فصار كلامه متناقضا قد نقض آخره أوله ولم","page":"ج1 ص478","text":"والمناقضة تنقسم أقساما: فمنها مناقضة جملة بتفصيل كقول المخبر الله عادل ولا يظلم مع قولهم إنه خلق الكفار للنار من غير جرم، ومنها نقض جملة بجملة وهو قولهم إن جميع جهات الفعل بالله ثم يقولون إنه ليثاب العبد، ومنها نقض تفصيل بتفصيل كقول النصارى واحد ثلاثة وثلاثة واحد لان إثباته واحدا نفي لثاني وثالث وفي إثباته ثلاثة إثبات لما نفي في الاول بعينه."},{"id":"furuq-lughawiyya:647","bookId":"furuq-lughawiyya","type":"section","seq":647,"chapter":"* (أ) *","title":"1933 - الفرق بين المثل والمثال (1) : المثل: هو المشارك في تمام الحقيقة ولذا نفي عن الله - سبحانه - كما قال: \" ليس كمثله شئ \" (2) .","page":"ج1 ص479","text":"والمثال: المشارك في بعض الاغراض.\nفإن الانسان المنقش (3) في الجدار.\nمثال للانسان الطبيعي لمشاركته في المقدار، والجهة، ونحوه، وليس مثلا له.\n(اللغات) ."},{"id":"furuq-lughawiyya:648","bookId":"furuq-lughawiyya","type":"section","seq":648,"chapter":"* (أ) *","title":"1936 - الفرق بين المثل والنظير: أن المثلين ما تكافئا في الذات (6) على ما ذكرنا، والنظير ما قابل نظيره في جنس أفعاله وهو متمكن منها","page":"ج1 ص480","text":"كالنحوي نظير النحوي وإن لم يكن له مثل كلامه في النحو أو كتبه فيه، ولا يقال النحوي مثل النحوي لان التماثل يكون حقيقة في أخص الاوصاف وهو الذات."},{"id":"furuq-lughawiyya:649","bookId":"furuq-lughawiyya","type":"section","seq":649,"chapter":"* (أ) *","title":"1947 - الفرق بين المجون والمزاح: أن المجون هو صلابة الوجه وقلة الحياء من","page":"ج1 ص482","text":"قولك مجن الشئ يمجن مجونا إذا صلب وغلظ ومنه سميت الخشبة التي يدق عليها القصار الثوب مجنة وأصل المجنة البقعة الغليظة تكون في الوادي وأصلها موجنة فقلبت الواو ياء لكسرة ما قبلها، ومنه الوجين وهو الغليظ من الارض ومنه ناقة وجناء صلبة شديدة وقيل\nهي الغليظة الوجنات والوجنة ما صلب من الوجه، والمجون كلمة مولدة لم تعرفه العرب وإنما تعرف أصله وهو الذي ذكرناه، وقيل المزاح الابهام للشئ في الظاهر وهو على خلافه في الباطن من غير إغترار للايقاع في مكروه، والاستهزاء الايهام لما يجب في الظاهر والامر على خلافه في الباطن على جهة الاغترار."},{"id":"furuq-lughawiyya:650","bookId":"furuq-lughawiyya","type":"section","seq":650,"chapter":"* (أ) *","title":"1949 - الفرق بين المحال والكذب: أن المحال ما احيل من الخبر عن حقه حتى لا يصح إعتقاده ويعلم بطلانه إضطرارا مثل قولك سأقوم أمس وشربت غدا والجس","page":"ج1 ص482","text":"والمحال ليس بصدق ولا كذب، ولا يقع الكذب إلا في الخبر، وقد يكون المحال في صورة الخبر مثل قولك هو حسن قبيح من وجه واحد، وفي صورة الاستخبار مثل قولك أقدم زيد غدا، وفي صورة التمني كقولك ليتني في هذه الحال بالبصرة ومكة، وفي صورة الامر إتق زيدا أمس، وفي صورة النهي كقولك لا تلق زيدا في السنة الماضية، ويقع في النداء كقولك يا زيد بكر على أن تجعل زيدا بكرا.\nوخلاف المحال المستقيم وخلاف الكذب الصدق.\nوالمحال على ضربين تجويز الممتنع وإيجابه فتجويزه قولك المقيد يجوز أن يعدو\nوإيجابه كقولك المقيد يعدو، والآخر مالا يفيد ممتنعا ولا غير ممتنع بوجه من الوجوه كقول القائل يكون الشئ أسود أبيض وقائما قاعدا."},{"id":"furuq-lughawiyya:651","bookId":"furuq-lughawiyya","type":"section","seq":651,"chapter":"* (أ) *","title":"1953 - الفرق بين المحبة والارادة: أن المحبة تجري على الشئ ويكون المراد به غيره، وليس كذلك الارادة تقول أحببت زيدا والمراد أنك تحب إكرامه ونف","page":"ج1 ص484","text":"أيضا تجري مجرى الشهوة فيقال فلان يحب اللحم أي يشتهيه وتقول أكلت طعاما لا أحبه أي لا أشتهيه ومع هذا فإن المحبة هي الارادة،\nوالشاهد أنه لا يجوز أن يحب الانسان الشئ مع كراهته له."},{"id":"furuq-lughawiyya:652","bookId":"furuq-lughawiyya","type":"section","seq":652,"chapter":"* (أ) *","title":"1961 - الفرق بين المحض والخالص: أن المحض هو الذي يكون على وجهه لم يخالطه شئ.","page":"ج1 ص484","text":"والخالص هو المختار من الجملة ومنه سمي الذهب\nالنقي عن الغش خالصا، ومن الاول قولهم لبن محض أي لم يخالطه ماء."},{"id":"furuq-lughawiyya:653","bookId":"furuq-lughawiyya","type":"section","seq":653,"chapter":"* (أ) *","title":"1962 - الفرق بين المحظور والحرام: أن الشئ يكون محظورا إذا نهى عنه ناه وإن كان حسنا كفرض السلطان التعامل ببعض النقود أو الرعي ببعض الارضين وإ","page":"ج1 ص485","text":"حرام محظور وليس كل محظور حراما، والمحظور يكون قبيحا إذا دلت الدلالة على أن من حظره لا يحظر إلا القبيح كالمحظور في الشريعة وهو ما أعلم المكلف أو دل على قبحه، ولهذا لا يقال أن أفعال البهائم محظورة وإن وصفت بالقبح وقال أبو عبد الله الزبيري: الحرام يكون مؤبدا والمحظور قد يكون إلى غاية.\nوفرق أصحابنا بين قولنا والله لا آكله فقالوا إذا حرمه على نفسه حنث بأكل الخبز وإذا قال والله لا آكله لم يحنث حتى يأكله كله وجعلوا تحريمه على نفسه بمنزلة قوله والله لا آكل منه شيئا."},{"id":"furuq-lughawiyya:654","bookId":"furuq-lughawiyya","type":"section","seq":654,"chapter":"* (أ) *","title":"1964 - الفرق بين المحق والاذهاب: أن المحق يكون للاشياء ولا يكون في الشئ الواحد يقال محق الدنانير ولا يقال محق الدينار إذا أذهبه بعينه ولكن ت","page":"ج1 ص486","text":"المال يزيد بالربا في العاجل."},{"id":"furuq-lughawiyya:655","bookId":"furuq-lughawiyya","type":"section","seq":655,"chapter":"* (أ) *","title":"1965 - الفرق بين المحيط بالشئ والعالم به: أن أصل المحيط المطيف بالشئ من حوله بما هو كالسور الدائر عليه يمنع أن يخرج عنه ما هو منه ويدخل فيه","page":"ج1 ص486","text":"\" وكان الله بكل شئ محيطا \" (1) يصلح أن يكون معناه أن كل شئ في مقدوره فهو بمنزلة ما قبض القابض عليه في إمكان تصريفه، ويصلح أن يكون معناه أنه يعلم بالاشياء من جميع وجوهها وقال \" قد أحاط بكل شئ علما \" (2) أي علمه من جميع وجوهه وقوله \" وأحاط بما لديهم \" (3) يجوز في العلم والقدرة وقال \" قد أحاط الله بها \" (4) أي قد أحاط بها لكم بتمليككم إياه وقال \" والله محيط بالكافرين \" (5) أي لا يفوتونه، وهو تخويف شديد بالغلبة فالمعلوم الذي علم من كل وجه بمنزلة ما قد احيط به بضرب سور حوله وكذلك المقدور عليه من كل وجه فإذا اطلق اللفظ فالاولى أن يكون من جهة المقدور كقوله تعالى \" والله محيط بالكافرين \" وقوله \" وكان الله بكل شئ محيطا \" ويجوز أن يكون من الجهتين فإذا قيد بالعلم فهو من جهة المعلوم لا غير، ويقال للعالم بالشئ عالم وإن عرف من جهة واحدة فالفرق بينهما بين، وقد أحتطت في الامر إذا أحكمته كأنك منعت الخلل أن يدخله، وإذا احيط بالشئ علما فقد علم من كل وجه يصح أن يعلم منه، وإذا لم يعلم الشئ مشاهدة لم يكن\nعلمه إحاطة."},{"id":"furuq-lughawiyya:656","bookId":"furuq-lughawiyya","type":"section","seq":656,"chapter":"* (أ) *","title":"1966 - الفرق بين المخاصمة والمجادلة والمناظرة (1) : هي نظائر.","page":"ج1 ص487","text":"وإن كان بينها فرق.\nفإن المجادلة: هي المخاصمة فيما وقع فيه خلاف بين اثنين.\nوالمخاصمة: منازعة (2) المخالفة بين اثنين على وجه الغلظة.\nوالمناظرة: ما يقع بين النظيرين (3) .\n(اللغات) ."},{"id":"furuq-lughawiyya:657","bookId":"furuq-lughawiyya","type":"section","seq":657,"chapter":"* (أ) *","title":"1969 - الفرق بين المداراة واللطف: أن المداراة ضرب من الاحتيال والختل","page":"ج1 ص488","text":"من قولك دريت الصيد إذا ختلته وإنما يقال داريت الرجل إذا توصلت إلى المطلوب من جهته بالحيلة والختل."},{"id":"furuq-lughawiyya:658","bookId":"furuq-lughawiyya","type":"section","seq":658,"chapter":"* (أ) *","title":"1971 - الفرق بين المداهنة والتقية (1) *: قال الشهيد الثاني - طاب ثراه - في قواعد المداهنة في قوله تعالى: \" ودوا لو تدهن فيدهنون \" (2) .","page":"ج1 ص488","text":"[المداهنة] (3) معصية، والتقية غير معصية، والفرق بينهما أن الاول تعظيم غير المستحق، لاتلاب نفعه، أو لتحصيل صداقته، كمن يثني على ظالم بسبب ظلمه، يصوره بصورة العدل.\nأو مبتدع على بدعته ويصورها بصورة الحق.\nوالتقية مخالطة الناس فيما يعرفون، وترك ما ينكرون حذرا من غوائلهم، كما أشار أمير المؤمنين عليه السلام: وموردها غالبا الطاعة والمعصية فمجاملة الظالم فيما يعتقده ظلما، والفاسق التظاهر بفسقه اتقاء شرهما [من] (4) باب المداهنة الجائزة، ولا تكاد تسمى تقية (5) الكتاب والسنة، قال تعالى: \" لا يتخذ المؤمنون الكافرين أولياء من دون المؤمنين ومن يفعل ذلك فليس من الله في شئ إلا أن تتقوا منهم تقاة \" (6) .\nوقال تعالى: \" إلا من اكره وقلبه مطمئن بالايمان \" (7) .\nوقال الائمة عليهم السلام: \" تسعة أعشار الدين التقية \".\nوقالوا عليهم السلام: \" من لا تقية له لا دين له \".\nانتهى مخلصا.\nأقول: ويدل على التقية من الكتاب العزيز قوله تعالى: \" ولا تلقوا بأيديكم إلى التهلكة \" (1) .\nفإن إظهار الحق إذا قضي إلى التهلكة يكون منهيا عنه، فتجب التقية.\nوكذا قوله تعالى: \" وقال رجل مؤمن من آل فرعون يكتم إيمانه \" (2) .\nفأن كتمانه إيمانه إنما كان لاجل الخوف من الاعداء، وهو معنى التقية وقد سماه - سبحانه - مؤمنا.\n(اللغات) ."},{"id":"furuq-lughawiyya:659","bookId":"furuq-lughawiyya","type":"section","seq":659,"chapter":"* (أ) *","title":"1978 - الفرق بين المدح والتقريظ: أن المدح يكون للحي والميت، والتقريظ لا يكون إلا للحي، وخلافه التأبين ولا يكون إلا للميت يقال أبنه يؤبنه تأب","page":"ج1 ص490","text":"دبغ به حسن وصلح وزادت قيمته فشبه مدحك للانسان الحي بذلك كأنك تزيد في قيمته بمدحك إياه ولا يصح هذا المعنى في الميت ولهذا يقال مدح الله ولا يقال قرظه."},{"id":"furuq-lughawiyya:660","bookId":"furuq-lughawiyya","type":"section","seq":660,"chapter":"* (أ) *","title":"1985 - الفرق بين المذي والوذي والودي (1) : المذي: بالتسكين والذال المعجمة: ماء لزج يخرج عقيب الملاعبة والتقبيل بعد انكسار الشهوة.","page":"ج1 ص490","text":"والوذي: بالمعجمة أيضا: ماء يخرج عقيب الانزال.\nوالودي: بالدال المهملة: ماء أبيض غليظ يخرج عقيب البول.\nكلها طاهرة غير ناقضة للوضوء على المشهور بين الفقهاء رضوان الله عنهم.\n(اللغات) ."},{"id":"furuq-lughawiyya:661","bookId":"furuq-lughawiyya","type":"section","seq":661,"chapter":"* (أ) *","title":"1988 - الفرق بين المرجع والمصير (1) : قال الطبرسي قد يفرق بينهما بأن المرجع: انقلاب الشئ إلى حال قد كان عليها.","page":"ج1 ص491","text":"والمصير: انقلاب الشئ إلى خلاف الحال التي هو عليها نحو: مصير الطين خزفا، ولا يقال رجع الطين خزفا، لانه لم يكن قبل خزفا.\nانتهى.\nفإن قلت: ينافي هذا الفرق قوله تعالى: \" ثم إن لهم عليها لشوبا من حميم، ثم إن مرجعهم لالى الجحيم \" (2) .\nمع أنهم لم يكونوا قبل في الجحيم.\nقلت: قد روي أن أهل النار يوردون الحميم لشربه، وهو خارج\nمن الجحيم، كما تورد الابل الماء، ثم يردون إلى الجحيم.\nيدل على ذلك قوله تعالى: \" يطوفون بينها وبين حميم آن \" (3) .\n(اللغات) ."},{"id":"furuq-lughawiyya:662","bookId":"furuq-lughawiyya","type":"section","seq":662,"chapter":"* (أ) *","title":"1989 - الفرق بين المرح والفرح (4) : الفرق بينهما أن الفرح قد يكون بحقه فيحمد عليه.","page":"ج1 ص491","text":"وقد يكون بالباطل فيندم عليه.\nوالمرح لا يكون إلا بالباطل.\nويؤيده قوله تعالى: \" ذلكم بما كنتم تفرحون في الارض بغير الحق وبما كنتم تمرحون \" (5) حيث قيد\nالاول، وأطلق الثاني.\n(اللغات) ."},{"id":"furuq-lughawiyya:663","bookId":"furuq-lughawiyya","type":"section","seq":663,"chapter":"* (أ) *","title":"1991 - الفرق بين المرسل والرسول: أن المرسل يقتضي إطلاق غيره له","page":"ج1 ص492","text":"والرسول يقتضي إطلاق لسانه بالرسالة."},{"id":"furuq-lughawiyya:664","bookId":"furuq-lughawiyya","type":"section","seq":664,"chapter":"* (أ) *","title":"1998 - الفرق بين المسألة والدعاء: أن المسألة يقارنها الخضوع والاستكالة ولهذا قالوا المسألة ممن دونك والامر ممن فوقك والطلب ممن يساويك، فأما","page":"ج1 ص493","text":"فهو على وجه الازدراء بالمخاطب والتخطئة له ليقبل لرأيه الا دلال عليه أو غير ذلك مما يجري مجراه، والامر في هذا الموضع هو المشورة وسميت المشورة أمرا لانها على صيغة الامر ومعلوم أن التابع لا يأمر المتبوع ثم يعنفه على مخالفته أمره، لا يجوز ذلك في باب الدين والدنيا ألا ترى انه لا يجوز أن يقال إن المسكين أمر الامير بإطعامه وإن كان المسكين أفضل من الامير في الدين، والدعاء إذا كان لله تعالى فهو مثل المسألة معه إستكانة وخضوع وإذا كان لغير الله جاز أن يكون معه خضوع وجاز أن لا يكون معه ذلك كدعاء النبي صلى الله عليه [وآله] وسلم أبا جهل إلى الاسلام لم يكن فيه إستكانة، ويعدى هذا الضرب من الدعاء بإلى فيقال دعاه إليه، وفي الضرب الاول بالباء\nفيقال دعاه به تقول دعوت الله بكذا ولا تقول دعوته إليه لان فيه معنى مطالبته به وقوده إليه."},{"id":"furuq-lughawiyya:665","bookId":"furuq-lughawiyya","type":"section","seq":665,"chapter":"* (أ) *","title":"2001 - الفرق بين المستحب والمندوب (1) : المستحب: هو الذي حث الشارع على فعله، ووعد عليه الثوب، والاثم في تركه.","page":"ج1 ص494","text":"والمندوب: هو\nالمرغوب فيه، المدعو إليه، لانه من الندب سواء كان الداعي إليه، هو الشرع، أو العقل، كبعض مكارم العادات، ووظائف المروءات، ولذلك يقال: هذا الامر مندوب شرعا، ولا يقال مستحب شرعا.\nإذ الاستحباب لا يكون إلا من قبل الشارع، فبينهما عموم وخصوص مطلق، إذ كل مستحب مندوب، وليس كل مندوب مستحبا.\nوأما السنة فهو ما سنة النبي صلى الله عليه وآله من الاحكام، وهو يعم الواجب والمستحب ومنه الحديث.\n\" الختان سنة \" (2) ، أي علم وجوبه من سنة النبي صلى الله عليه وآله.\n(اللغات) ."},{"id":"furuq-lughawiyya:666","bookId":"furuq-lughawiyya","type":"section","seq":666,"chapter":"* (أ) *","title":"2026 - الفرق بين المعارضة والالزام: أن كل معارضة إلزام وليس كل إلزام معارضة ألا ترى أن قولك لمن أنكر حدوث الاجسام ما أنكرت أنها سابقة للحواد","page":"ج1 ص497","text":"المسألة وبما في رأيه ثم تأتي بالمسألة فتجمع بينهما وبين ذلك إما بعلة\nأو بغير علة.\nفالمعارضة بالعلة كقولك إن كان الله تعالى يفعل الجور فلا يكون الجور لانه القادر المالك، والمعارضة على غير علة نحو قولنا لمن يقول إن السواد والحركة جسم ما أنكرت إن البياض والسكون أيضا جسم."},{"id":"furuq-lughawiyya:667","bookId":"furuq-lughawiyya","type":"section","seq":667,"chapter":"* (أ) *","title":"2031 - الفرق بين المعذر والمعذر والمعتذر (1) : المعذر، بالتخفيف: الذي له عذر صحيح.","page":"ج1 ص498","text":"والمعذر.\nبالتشديد: الذي لا عذر له، وهو يريك بلسانه أنه معذور.\nوقال تعالى: \" وجاء المعذرون من الاعراب \" (2) .\nوالمعتذر: يقال لمن له عذر.\nولمن لا عذر له.\nوقولهم: من يعذرني؟، معناه: من يقوم بعذري؟.\n(اللغات) ."},{"id":"furuq-lughawiyya:668","bookId":"furuq-lughawiyya","type":"section","seq":668,"chapter":"* (أ) *","title":"الفرق بين المعرفة والعلم","page":"ج1 ص499","text":"أن المعرفة أخص من العلم لانها علم بعين الشئ مفصلا عما سواه، والعلم يكون مجملا ومفصلا قال الزهري: لا أصف الله بأنه عارف ولا أعنف من يصفه بذلك لان المعرفة مأخوذة من عرفان الدار يعني آثارها التي تعرف بها، قال ولا يجوز أن يكون علم الله تعالى بالاشياء من جهة الاثر والدليل، قال والمعرفة تمييز المعلومات فأومأ إلى أنه لا يصفه بذلك كما لا يصفه بأنه مميز، وليس ما قاله بشئ لان آثار الدار إن كانت سميت عرفانا فسميت بذلك لانها طريق إلى المعرفة بها وليس في ذلك دليل على أن كل معرفة تكون من جهة الاثر والدليل، وأما وصف العارف بأنه يفيد تمييز المعلومات في علمه فلو جعله دليلا على أن الله عارف كان أولى من المعلومات متميزة في علمه بمعنى أنها متخيلة له وإنما لم يسم علمه تمييزا لان التمييز فينا هو إستعمال العقل بالنظر والفكر اللذين يؤديان إلى تمييز المعلومات فلم يمتنع أن توصف معلوماته بأنها متميزة وإن كان لا يوصف بأنه مميز لان تميزها صفة لها لا له والمعرفة بها تفيد ذلك فيها لا فيه فكل معرفة علم وليس كل علم معرفة وذلك أن لفظ المعرفة يفيد تمييز المعلوم من غيره ولفظ العلم لا يفيد ذلك إلا بضرب آخر من التخصيص في ذكر المعلوم، والشاهد قول أهل اللغة إن العلم يتعدى إلى مفعولين ليس لك الاقتصار على أحدهما إلا أن يكون بمعنى المعرفة تعالى \" لا تعلمونهم الله يعلمهم \" (1) أي لا تعرفونهم الله يعرفهم، وإنما كان ذلك كذلك لان لفظ العلم مبهم\nفإذا قلت علمت زيدا فذكرته بإسمه الذي يعرفه به المخاطب لم يفد فإذا قلت قائما أفدت لانك دللت بذلك على أنك علمت زيدا على صفة جاز أن لا تعلمه عليها مع علمك به في الجملة، وإذا قلت عرفت زيدا أفدت لانه بمنزلة قولك علمته متميزا من غيره فاستغنى عن قولك متميزا من غيره لما في لفظ المعرفة من الدلالة على ذلك.\nوالفرق بين العلم والمعرفة إنما يتبين في الموضع الذي يكون فيه جملة غير مبهمة ألا ترى أن قولك علمت أن لزيد ولدا وقولك عرفت أن لزيد ولدا يجريان مجرى واحدا."},{"id":"furuq-lughawiyya:669","bookId":"furuq-lughawiyya","type":"section","seq":669,"chapter":"* (أ) *","title":"2034 - الفرق بين المعرفة والعلم (1) : قيل: المعرفة إدراك البسائط والجزئيات.","page":"ج1 ص500","text":"والعلم: إدراك المركبات والكليات.\nومن ثم يقال: عرفت الله، ولا يقال علمته.\nوقيل: هي عبارة عن الادراك التصوري.\nوالعلم هو الادراك التصديقي.\nومن ذهب إلى هذا القول جعل العرفان أعظم رتبة من العلم، قال: لان استناد هذه المحسوسات إلى موجود واجب الوجود أمر معلوم بالضرورة.\nوأما تصور حقيقة واجب الوجود فأمر فوق الطاقة البشرية، لان الشئ ما لم يعرف لم تطلب ماهيته.\nفعلى هذا كل عارف عالم من دون عكس (2) ولذلك كان الرجل لا يسمى عارفا إلا إذا توغل في بحار العلوم ومباديها (3) ، وترقى من مطالعها إلى مقاطعها.\nومن مباديها\nإلى غاياتها بحسب الطاقة البشرية.\nوقيل: المعرفة: إدراك الشئ ثانيا بعد توسط نسيانه.\nلذلك يسمى الحق - تعالى - بالعالم دون العارف.\nوهو أشهر الاقوال في تعريف المعرفة.\nوقيل: المعرفة: قد تقال فيما تدرك آثاره، وإن لم يدرك ذاته (1) ، والعلم لا يكاد يقال إلا فيما أدرك ذاته.\nولذا يقال: فلان يعرف الله، ولا يقال: يعلم الله، لما كانت معرفته - سبحانه - ليست إلا بمعرفة آثاره دون معرفة ذاته.\nوأيضا (2) فالمعرفة تقال فيما لم يعرف إلا كونه موجودا فقط.\nوالعلم أصله فيما يعرف وجوده، وجنسه، وعلته، وكيفيته.\nولهذا يقال: الله عالم بكذا ولا يقال: عارف لما كان العرفان يستعمل في العلم القاصر.\nوأيضا [21 / ب] فالمعرفة تقال فيما يتوصل إليه بتفكر وتدبر.\nوالعلم قد يقال في ذلك وفي غيره.\nهذا وقد يستفاد من كلام الشيخ الرئيس (3) في بعض مصنفاته أنهما مترادفان.\nوإليه ذهب جماعة من أهل اللغة وأرباب الاصول.\nويشهد لذلك قول سيد الساجدين في الصحيفة الكاملة: (4) \" وقد أحصيتهم بمعرفتك \".\nفإنه أطلق المعرفة عليه - سبحانه - ويمكن أن يراد بها العلم هنا تجوزا.\n(اللغات) ."},{"id":"furuq-lughawiyya:670","bookId":"furuq-lughawiyya","type":"section","seq":670,"chapter":"* (أ) *","title":"2039 - الفرق بين المعنى والحقيقة: أن المعنى هو القصد الذي يقع به القول على وجه دون وجه وقد يكون معنى الكلام في اللغة ما تعلق به القصد.","page":"ج1 ص502","text":"والحقيقة ما وضع من القول موضعه منها على ما ذكرنا (2) يقال عنيته أعنيه معنى.\nوالمفعل يكون مصدرا ومكانا وهو هاهنا مصدر ومثله قولك دخلت مدخلا حسنا أي دخولا حسنا.\nولهذا قال أبو علي رحمة الله عليه: إن المعنى هو القصد إلى ما يقصد إليه من القول فجعل المعنى القصد لانه مصدر.\nقال: ولا يوصف الله تعالى بأنه معنى لان المعنى هو قصد قلوبنا إلى ما نقصد إليه من القول والمقصود هو المعنى والله تعالى\nهو المعنى وليس بمعنى وحقيقة هذا الكلام أن يكون ذكر الله هو المعنى\nوالقصد إليه هو المعنى إذا كان المقصود في الحقيقة حادث.\nوقولهم عنيت بكلامي زيدا كقولك أردته بكلامي ولا يجوز أن يكون زيد في الحقيقة مرادا مع وجوده فدل ذلك على أنه عنى ذكره واريد الخبر عنه دون نفسه.\nوالمعنى مقصور على القول دون ما يقصد.\nألا ترى انك تقول معنى قولك كذا ولا تقول معنى حركتك كذا ثم توسع فيه فقيل ليس لدخولك إلى فلان معنى والمراد أنه ليس له فائدة تقصد ذكرها بالقول.\nوتوسع في الحقيقة ما لم يتوسع في المعنى فقيل لا شئ إلا وله حقيقة ولا يقال لا شئ إلا وله معنى.\nويقولون حقيقة الحركة كذا ولا يقولون معنى الحركة كذا هذا على أنهم سمو الاجسام والاعراض معاني إلا أن ذلك توسع والتوسع يلزم موضعه المستعمل فيه ولا يتعداه."},{"id":"furuq-lughawiyya:671","bookId":"furuq-lughawiyya","type":"section","seq":671,"chapter":"* (أ) *","title":"2040 - الفرق بين المعنى والغرض: أن المعنى القصد الذي يقع به القول على وجه دون وجه على ما ذكرنا (1) والكلام لا يترتب في الاخبار والاستخبار وغ","page":"ج1 ص503","text":"والغرض هو المقصود بالقول أو الفعل بإضمار مقدمة ولهذا لا يستعمل في الله تعالى غرضي بهذا الكلام كذا اي هو مقصودي به وسمي غرضا تشبيها بالغرض الذي يقصده الرامي بسهمه وهو الهدف وتقول معنى قول الله كذا لان الغرض هو المقصود وليس\nللقول مقصود فإن قلت ليس للقول قصد أيضا قلنا هو مجاز والمجاز يلزم موضعه ولا يجوز القياس عليه فتقول غرض قول الله كما تقول معنى قول\nالله قياسا.\nوالغرض ايضا يقتضي أن يكون بإضمار مقدمة والصفة بالاضمار لا يجوز على الله تعالى ويجوز أن يقال الغرض المعتمد الذي يظهر وجه الحاجة إليه ولهذ لا يوصف الله تعالى به لان الوصف بالحاجة لا يلحقه."},{"id":"furuq-lughawiyya:672","bookId":"furuq-lughawiyya","type":"section","seq":672,"chapter":"* (أ) *","title":"2046 - الفرق بين المفهوم والمعنى والمدلول (1) : قال الفاضل اليزدي *: اعلم أن ما يستفاد من اللفظ باعتبار أنه [فهم منه: يسمى مفهوما، وباعتبار","page":"ج1 ص504","text":"ولا يخفى أنها فروق اعتبارية.\n(اللغات) ."},{"id":"furuq-lughawiyya:673","bookId":"furuq-lughawiyya","type":"section","seq":673,"chapter":"* (أ) *","title":"2048 - الفرق بين المقابلة والجزاء: أن المقابلة هي المساواة بين شيئين كمقابلة","page":"ج1 ص505","text":"الكتاب بالكتاب وهي في المجازاة إستعارة قال بعضهم قد يكون جزاء الشئ أنقص منه والمقابلة عليه لا تكون إلا مثله واستشهدوا بقوله \" وجزاء سيئة سيئة مثلها \" (1) قال ولو كان جزاء الشئ مثله لم يكن الذكر المثل هاهنا وجه والجواب عن هذا أن الجزاء يكون على بعض الشئ فإذا قال مثلها فكأنه قال على كلها."},{"id":"furuq-lughawiyya:674","bookId":"furuq-lughawiyya","type":"section","seq":674,"chapter":"* (أ) *","title":"2050 - الفرق بين المقاصة والمجازاة (3) قيل: الفرق بينهما أن المقاصة تكون بمقابلة الفعل بفعل من جنسه.","page":"ج1 ص505","text":"كمقابلة الضرب والجرح بالضرب والجرح، والمجازاة: تكون بمقابلته من غير الآخر (4) .\n(اللغات) ."},{"id":"furuq-lughawiyya:675","bookId":"furuq-lughawiyya","type":"section","seq":675,"chapter":"* (أ) *","title":"2051 - الفرق بين المقالة والمذهب: أن المقالة قول يعتمد عليه قائله ويناظر فيه يقال هذه مقالة فلان إذا كان سبيله فيها هذا السبيل والمذهب ما يم","page":"ج1 ص506","text":"أنك تقول هذا مذهبي في السماع والاكل والشرب لشئ (1) تختاره من ذلك وتميل إليه تناظر فيه أولا.\nوفرق آخر وهو أن المذهب يفيد أن يكون الذاهب إليه معتقدا له أو بحكم المعتقد والمقالة لا تفيد ذلك لانه يجوز أن يقول ويناظر فيه ويعتقد خلافه فعلى هذا يجوز أن يكون مذهب ليس بمقالة ومقالة ليس بمذهب."},{"id":"furuq-lughawiyya:676","bookId":"furuq-lughawiyya","type":"section","seq":676,"chapter":"* (أ) *","title":"2058 - الفرق بين المكر والغدر (3) : الفرق بينهما أن الغدر نقض العهد","page":"ج1 ص508","text":"الذي يجب الوفاء به.\nوالمكر: قد يكون ابتداء من غير عقد.\n(اللغات) ."},{"id":"furuq-lughawiyya:677","bookId":"furuq-lughawiyya","type":"section","seq":677,"chapter":"* (أ) *","title":"الفرق بين الملة والدين","page":"ج1 ص508","text":"أن الملة إسم لجملة الشريعة، والدين إسم لما عليه كل واحد من أهلها ألا ترى انه يقال فلان حسن الدين ولا يقال حسن الملة وإنما يقال هو من أهل الملة ويقال لخلاف الذمي الملي نسب إلى جملة الشريعة فلا يقال له ديني وتقول ديني دين الملائكة ولا تقول ملتي ملة الملائكة لان الملة إسم للشرائع مع الاقرار بالله.\nوالدين ما يذهب إليه الانسان ويعتقد أنه يقربه إلى الله وإن لم يكن فيه شرائع مثل دين أهل الشرك وكل ملة دين وليس كل دين ملة واليهودية ملة لان فيها شرائع وليس الشرك ملة وإذا أطلق الدين فهو الطاعة العامة التي يجازى عليها بالثواب مثل قوله تعالى \" إن الدين عند الله الاسلام \" (1) وإذا قيد إختلف دلالته وقد يسمى كل واحد من الدين والملة بإسم الآخر في بعض المواضع لتقارب معنييهما\nوالاصل ما قلناه، والفرس تزعم أن الدين لفظ فارسي وتحتج بأنهم يجدونه في كتبهم المؤلفة قبل دخول العربية أرضهم بألف سنة ويذكرون أن لهم خطا يكتبون به كتابهم المنزل بزعمهم يسمى دين دوري أي كتابه الذي سماه بذلك صاحبهم زرادشت، ونحن نجد للدين أصلا واشتقاقا صحيحا في العربية وما كان كذلك لا نحكم عليه بأنه أعجمي وإن صح ما قالوه فإن الدين قد حصل في العربية والفارسية إسما لشئ واحد على جهة الاتفاق وقد يكون على جهة الاتفاق ما هو أعجب من هذا، وأصل الملة في العربية المل وهو أن يعدو الذئب على سن ضربا من العدو فسميت الملة ملة لاستمرار أهلها عليها وقيل أصلها التكرار من قولك طريق مليل إذا تكرر سلوكه حتى توطأ، ومنه الملل وهو تكرار الشئ على النفس حتى تضجر، وقيل الملة مذهب جماعة يحمي بعضهم لبعض عند الامور الحادثة وأصلها من المليلة وهي ضرب من الحمى، ومنه الملة موضع النار وذلك أنه إذا دفن فيه اللحم وغيره تكرر عليه الحمى حتى ينضج.\nوأصل الدين الطاعة ودان الناس مالكهم أي أطاعوه.\nويجوز أن يكون أصله العادة ثم قيل للطاعة دين لانها تعتاد وتوطن النفس عليها."},{"id":"furuq-lughawiyya:678","bookId":"furuq-lughawiyya","type":"section","seq":678,"chapter":"* (أ) *","title":"2062 - الفرق بين الملة والدين (1) : الدين: هو الطريقة المخصوصة الثابتة من النبي صلى الله عليه وآله، يسمى من حيث الانقياد له دينا، ومن حيث إن","page":"ج1 ص509","text":"ومن حيث إنه يردها الواردون\nالمتعطشون إلى زلال نيل الكمال: شرعا وشريعة.\nوالدين يضاف إلى الله، وإلى النبي، وإلى آحاد الائمة.\nوالملة إلى النبي وإلى الائمة: كذا حققه التفتازاني.\nقال الراغب (1) : الملة هي: الدين، غير أن الملة لا تستعمل إلا في جملة الشرائع دون آحادها، ولا تضاف إلا إلى النبي، تسند إليه نحو: \" فاتبعوا ملة إبراهيم حنيفا \" (2) .\nولا تكاد توجد مضافة ألى الله ولا إلى آحاد امة النبي، فلا يقال: ملة الله، ولا ملتي، ولا ملة زيد كما يقال: دين الله، وديني، ودين زيد.\nانتهى.\nأقول: ويرده قول سيد الساجدين عليه السلام في دعاء مكارم الاخلاق: \" واجعلني على ملتك أموت وأحيا \" (3) .\nوقوله عليه السلام في دعاء وداع شهر رمضان: \" اللهم إنا نتوب إليك في يوم فطرنا الذي جعلته للمؤمنين عيدا وسرورا، ولاهل ملتك مجمعا [16 ب] ومحتشدا \" (4) .\nحيث أضاف الملة إلى الله سبحانه، فإذا وقع ذلك في كلام المعصوم، وهو منبع البلاغ ومعدن الفصاحة (5) والبراعة، فتحقيق التفتازاني لا حقيقة له، وكلام الراغب لا يرغب فيه."},{"id":"furuq-lughawiyya:679","bookId":"furuq-lughawiyya","type":"section","seq":679,"chapter":"* (أ) *","title":"2063 - الفرق بين الملك والملكوت (6) : الملك، بالضم: ما يدرك بالحس، ويقال له: عالم الشهادة.","page":"ج1 ص510","text":"والملكوت: ما لم يدرك به، وهو عالم الغيب، وعالم الامر.\nولكون عالم الشهادة بالنسبة إلى عام الغيب كالقطرة من البحر، يسمى\nالاول: ملكا والثاني ملكوتا، لما تقرر أن زيادة المباني تدل على زيادة المعاني.\n(اللغات) ."},{"id":"furuq-lughawiyya:680","bookId":"furuq-lughawiyya","type":"section","seq":680,"chapter":"* (أ) *","title":"2068 - الفرق بين الملك والدولة: أن الملك يفيد إتساع المقدور على ما ذكرنا (1) : والدولة إنتقال حال سارة من قوم إلى قوم، والدولة ما ينال من ال","page":"ج1 ص512","text":"غرفة لما في يدك والغرفة فعلة من غرفت ومثل ذلك خطوة للموضع وخطوة فعلة من خطوت، وجمع الدولة دول مثل غرف ومن قال دول فهي لغة والاول الاصل."},{"id":"furuq-lughawiyya:681","bookId":"furuq-lughawiyya","type":"section","seq":681,"chapter":"* (أ) *","title":"2075 - الفرق بين المملق والفقير: أن المملق مشتق من الملق وهو الخضوع والتضرع ومنه قيل للاجمة المفترشة ملقة والجمع ملقات فلما كان الفقير في أك","page":"ج1 ص512","text":"غنى كأنه صار ذا ملق كما تقول أطفلت المرأة إذا صار لها طفل، ويجوز أن يقال إن الاملاق نقل إلى عدم التمكن من النفقة على العيال ولهذا قال الله تعالى \" ولا تقتلوا أولادكم خشية إملاق \" (1) أي خشية العجز عن النفقة عليهم."},{"id":"furuq-lughawiyya:682","bookId":"furuq-lughawiyya","type":"section","seq":682,"chapter":"* (أ) *","title":"2081 - الفرق بين من يأتيني فله درهم والذي يأتيني فله درهم: أن جواب الجزاء يدل على أنه يستحق من الفعل الاول والفاء في خبر الذي مشبهة بالجزاء","page":"ج1 ص514","text":"الاتيان."},{"id":"furuq-lughawiyya:683","bookId":"furuq-lughawiyya","type":"section","seq":683,"chapter":"* (أ) *","title":"2085 - الفرق بين المنحة والهبة: أن أصل المنحة الشاة أو البعير يمنحها الرجل أخاه فيحتلبها زمانا ثم يردها، قال بعضهم لا تكون المنحة إلا الناقة","page":"ج1 ص515","text":"* قد علمت إذ منحتني فاها * والهبة عطية منفعة تفضل بها على صاحبك ولذلك لم تكن عطية\nالدين ولا عطية الثمن هبة، وهي مفارقة للصدقة لما في الصدقة من معنى تضمن فقر صاحبها لتصديق حاله فيما ينبئ حاله من فقره."},{"id":"furuq-lughawiyya:684","bookId":"furuq-lughawiyya","type":"section","seq":684,"chapter":"* (أ) *","title":"2091 - الفرق بين المنع والكف: أن المنع ما ذكرنا (3) والكف على ما ذكر بعضهم يستعمل في الامتناع عما تدعو إليه الشهوة قال والامساك","page":"ج1 ص516","text":"مثله يقال كف عن زيارة فلان وأمسك عن الافطار، وليس الامر كما قال بل يستعمل الامساك والكف فيما تدعو إليه الشهوة وفيما لا تدعو إليه، يقال كف عن القتال كما يقال كف عن شرب الماء\nوأمسك عن ذلك أيضا، وأصل الامساك حبس النفس عن الفعل ومنه المساك وهو مكان يمسك الماء أي يحبسه والجمع مسك، والمسكة السوار سمي بذلك لانه يلزم المعصم فهو كالمحبوس فيه، والماسكة جلدة تكون على وجه الولد في بطن امه لانها محيطة به كإحاطه الحبس بالمحبوس، واستمسك الشئ وتماسك كأن بعضه إحتبس على بعض، ونقيض الاستمساك الاسترسال ونقيض الامساك الارسال، وأصل الكف الانقباض والتجمع ومنه سميت الكف كفا لانها تقبض على الاشياء وتجتمع، ويقال جاءني الناس كافة أي جميعا فالكف عن الفعل هو الامتناع عن موالاة الفعل وإيجاده حالا بعد حال خلاف الانبساط فيه وإنما قلنا ذلك لان أصله الانقباض وخلاف الانقباض الانبساط، والامساك حبس النفس عن الفعل على ما ذكرنا فالفرق بينهما بين."},{"id":"furuq-lughawiyya:685","bookId":"furuq-lughawiyya","type":"section","seq":685,"chapter":"* (أ) *","title":"2093 - الفرق بين المنفعة والخير: أن من المعصية ما يكون منفعة وقد شهد الله تعالى بذلك في قوله \" قل فيهما إثم كبير ومنافع للناس \" (1) وما كانت","page":"ج1 ص517","text":"فيه منفعة فهو منفعة ولا تكون المعصية خيرا وقد اجريت الصفة بنافع على الموجب للنفع فقيل طعام نافع ودواء نافع."},{"id":"furuq-lughawiyya:686","bookId":"furuq-lughawiyya","type":"section","seq":686,"chapter":"* (أ) *","title":"2095 - الفرق بين المنفعة والمتعة (1) قد فرق بينهما: بأن المتعة: منفعة توجب الالتذاذ في الحال.","page":"ج1 ص517","text":"والمنفعة: قد تكون بألم تؤدي عاقبته إلى نفع.\nفكل متعة منفعة، ولا ينعكس.\nويرشد إليه قوله تعالى: \" أفمن وعدناه وعدا حسنا فهو لاقيه، كمن متعناه متاع الحياة الدنيا \" (2) (اللغات) ."},{"id":"furuq-lughawiyya:687","bookId":"furuq-lughawiyya","type":"section","seq":687,"chapter":"* (أ) *","title":"2101 - الفرق بين المهجة والذات والروح والنفس: أن المهجة خالص دم الانسان الذي إذا خرج خرجت روحه وهو دم القلب في قول الخليل، والعرب تقول: سالت","page":"ج1 ص518","text":"مشترك يقع على الروح وعلى الذات ويكون توكيدا يقال خرجت نفسه أي روحه وجاءني زيد نفسه بمعنى التوكيد والسواد سواد لنفسه كما تقول لذاته، والنفس أيضا الماء وجمعه أنفاس قال جرير: تعلل وهي شاغبة بفيها * بأنفاس من الشبم القراح والنفس ملء الكف من الدباغ والنفس التي تستعد بمعنى الذات ما يصح أن تدل على الشئ من وجه يختص به دون غيره، وإذا قلت هو لنفسه على صفة كذا فقد دللت عليه من وجه يختص به دون ما يخالفه، وقال علي بن عيسى: الشئ والمعنى والذات نظائر وبينها فروق فالمعنى المقصود ثم كثر حتى سمي المقصود معنى، وكل شئ ذات وكل ذات شئ إلا أنهم ألزموا الذات الاضافة فقالوا ذات الانسان وذات الجوهر ليحققوا الاشارة إليه دون غيره، قلنا ويعبر بالنفس عن المعلوم في قولهم قد صح ذلك في نفسى أي قد صار في جملة ما أعلمه ولا يقال صح في ذاتي."},{"id":"furuq-lughawiyya:688","bookId":"furuq-lughawiyya","type":"section","seq":688,"chapter":"* (أ) *","title":"2102 - الفرق بين العقل والنفس والروح (1) : قال بعض المحققين: العقل جوهر مجرد عن المادة، وهو الذي يدرك المعاني الكلية والحقائق المعنوية.","page":"ج1 ص518","text":"مشتق من عقل البعير عقلا، إذا شده، سمي به، لانه يمنع صاحبه عن ارتكاب مالا ينبغي، مثل العقال.\nوهذا الجوهر سمي نفسا باعتبار تعلقه بالبدن، وهي النفس الناطقة، ويسمى عقلا باعتبار نسبته إلى عالم القدس لما فيه من\nمعنى الاشتقاق.\nقال بعض الافاضل: العقل يطلق في كلام العلماء على عشرة معان.\nوفي الاحاديث على ثلاثة معان: أحدها: الطبيعة التي خص بها الانسان يميز بها بين الخير والشر.\nويقابلها الجنون، وأدنى مراتبه مناط التكليف، وهو موجود في المؤمن والكافر.\nوثانيها: الطبيعة التي بها مناط السعادة الاخروية، وهي القوة الداعية إلى الخيرات الصارفة عن اكتساب السيئات.\nوإليه أشار الصادق عليه السلام بقوله: \" من كان عاقلا كان له دين، ومن كان له دين دخل الجنة.\n\" وقوله عليه السلام: \" العقل: ما عبد به الرحمان واكتسب به الجنان \".\nوثالثها: ما كان بمعنى العلم أخذا من التعقل وهو المعنى المقابل للجهل.\nكما في قول الرضا عليه السلام: \" صديق كل امرئ عقله، وعدوه جهله \".\nومثله حديث العقل، وجنوده، والجهل وجنوده.\nوأما النفس: فتطلق على النفس الناطقة كما عرفت، وهي المعبر عنها بقولك: (أنا) .\nوهي التي عنى الله سبحانه [21 / أ] بقوله تعالى: \" أن النفس بالنفس \" (1) .\nوعلى العقل كما عرفت باعتبار تعلقه بالبدن، وهي النفس الناطقة.\nوعلى القوة الداعية إلى الشرور، والموقعة صاحبها في المحذور.\nوهي التي\nعنى الله سبحانه بقوله: \" إن النفس لامارة بالسوء \" (1) .\nوعلى الروح أيضا، كما ورد في الاخبار، وكما ورد في حسنة إدريس القمي (2) قال: سمعت أبا عبد الله يقول: إن الله عزوجل يأمر ملك الموت برد نفس المؤمن ليهون عليه ويخرجها من أحسن وجهها فيحصل من ذلك أن للعقل ثلاثة إطلاقات، وللنفس أربعة.\nوإن كلا منهما يطلق على الآخر في مادة وتنفرد النفس في ثلاث، فيكون بينهما عموم وخصوص من وجه.\nوأما الروح: فهي ما به الحياة.\nوقد تطلق على النفس أيضا.\nقلت: ويؤيد هذا الفرق ما رواه العياشي (3) عن الباقر عليه السلام في تفسير قوله تعالى: \" الله يتوفى الانفس حين موتها والتي لم تمت في منامها \" (4) قال: \" ما من أحد ينام إلا عرجت نفسه إلى السماء وبقيت روحه في بدنه وصار بينهما سبب كشعاع الشمس، فإن أذن الله في قبض روح أجابت الروح النفس.\nوإن أذن الله في رد الروح أجابت النفس الروح ... \" الحديث.\nوالظاهر أن المراد برد (5) الروح إبقاؤها في البدن.\nوقال بعض المفسرين في تفسير الآية: إن التوفي مستعمل في الاول حقيقة، وفي الثاني مجازا (6) .\nوالتي تتوفى عند الموت هي نفس الحياة التي إذا\nزالت زالت معها النفس، والتي تتوفى عند النوم هي النفس التي بها العقل، والتمييز، وهي التي تفارق النائم فلا يعقل (1) .\nوالفرق بين قبض النوم وقبض الموت أن قبض النوم يضاد اليقظة وقبض الموت يضاد الحياة.\n(اللغات) ."},{"id":"furuq-lughawiyya:689","bookId":"furuq-lughawiyya","type":"section","seq":689,"chapter":"* (أ) *","title":"2103 - الفرق بين المهلة والمدارة (2) : الفرق بينهما: أن المهلة: عدم سرعة المؤاخذة، وترك الانتقام مع القدرة، لمصلحة تقتضي ذلك عاجلا أو آجلا،","page":"ج1 ص521","text":"والمداراة: عبارة عن الملاطفة، وحسن المعاشرة مع الناس اتقاء من شرهم.\nولذا لا تنسب إلى الله عزوجل، ويدل على ذلك قول سيد الساجدين في دعاء الصحيفة الشريفة (3) : (لم يكن إمهالك عجزا، ولا إمساكك غفلة، ولا انتظارك مداراة) .\n(اللغات) ."},{"id":"furuq-lughawiyya:690","bookId":"furuq-lughawiyya","type":"section","seq":690,"chapter":"* (أ) *","title":"2105 - الفرق بين المهمل والهذيان والهذر: أن المهمل خلاف المستعمل وهو لا معنى له في اللغة التي هو مهمل فيها والمستعمل ما وضع لفائدة مفردا كان","page":"ج1 ص522","text":"والصحيح هو الذي تقدم."},{"id":"furuq-lughawiyya:691","bookId":"furuq-lughawiyya","type":"section","seq":691,"chapter":"* (أ) *","title":"2109 - الفرق بين الموجود والكائن: أن الموجود من صح له تأثير فتأثير القديم صحة الفعل منه وتأثير الجسم شغله للحيز (3) وتأثير العرض تغييره للجس","page":"ج1 ص523","text":"بأصل رجع إليه إما محقق وإما مقدر وقد يكون الكلام المقدر أبلغ منه بالمحقق ألا ترى أن قول إمرء القيس: * بمنجرد قيد الاوابد هيكل * أبلغ من مانع الاوابد وهو مقدر تقدير المانع، والكائن على أربعة أوجه أحدها بمعنى الوجود يصح ذلك في القديم كما يصح في المحدث والناس يقولون إن الله لم يزل كائنا، والثاني بمعنى وجود الصنع والتدبير وهو قول الناس إن الله تعالى كائن بكل مكان والمراد أنه صانع مدبر بكل مكان وإنه عالم بذلك غير غائب عن شئ من أحواله فيكون من هذا الوجه في حكم من هو كائن منه، والثالث قولنا للجوهر إنه كائن بالمكان ومعناه أنه شاغل للمكان، والرابع قولنا للعرض إنه كائن في الجسم فالمراد حلوله."},{"id":"furuq-lughawiyya:692","bookId":"furuq-lughawiyya","type":"section","seq":692,"chapter":"* (أ) *","title":"2111 - الفرق بين الموصوف والمعنى: أن قولنا موصوف يجئ مطلقا وقولنا معنى لا يجئ إلا مقيدا تقول هذا الشئ موصوف ولا تقول معنى حتى تقول معنى بهذا","page":"ج1 ص523","text":"وعنيت يتعدى إلى مفعولين أحدهما بنفسه والآخر بالحرف تقول عنيت زيدا بكذا فالفائدة في قولك بكذا فهو كالشئ الذي لابد منه.\nفلهذا يقيد المعنى ويطلق الموصوف."},{"id":"furuq-lughawiyya:693","bookId":"furuq-lughawiyya","type":"section","seq":693,"chapter":"* (أ) *","title":"2113 - الفرق بين الميت والميت (1) : قال أكثر اللغويين: (2) إن الثاني لغة في الاول.","page":"ج1 ص524","text":"وقد جمعهما الشاعر في بيت واحد (3) .\nليس من مات فاستراح بميت * إنما الميت ميت الأحياء وفرق بعضهم بينهما فقال: الميت، بالتشديد: يطلق \" على من مات \"، وعلى الحي الذي سيموت.\nقال تعالى: \" إنك ميت وإنهم ميتون \" (4) (5) * وبالتخفيف لا يطلق إلا على من مات * (6) .\n(اللغات) ."},{"id":"furuq-lughawiyya:694","bookId":"furuq-lughawiyya","type":"section","seq":694,"chapter":"* (أ) *","title":"الفرق بين الميقات والوقت","page":"ج1 ص524","text":"أن الميقات أقدر ليعمل فيه عمل من الاعمال، والوقت وقت الشئ قدره مقدر أو لم يقدره ولهذا قيل مواقيت الحج للمواضع التي قدرت للاحرام وليس الوقت في الحقيقة ساعة غير حركة الفلك وفي ذلك كلام كثير ليس هذا موضع ذكره."},{"id":"furuq-lughawiyya:695","bookId":"furuq-lughawiyya","type":"section","seq":695,"chapter":"* (أ) *","title":"ن","page":"ج1 ص525","text":"الميقات والوقت (1) : قد يفرق بينهما: بأن الميقات ما قدر ليعمل فيه عمل من الاعمال.\nوالوقت: وقت الشئ.\nقدره مقدر، أو لم يقدره، ولذلك قيل: مواقيت الحج، وهي المواضع التي قدرت للاحرام فيها.\nومنه قوله تعالى: \" فتم ميقات ربه أربعين ليلة \" (2) .\n(اللغات) ."},{"id":"furuq-lughawiyya:696","bookId":"furuq-lughawiyya","type":"section","seq":696,"chapter":"* (أ) *","title":"2128 - الفرق بين الناس والخلق: أن الناس هم الانس خاصة وهم جماعة لا واحد لها من لفظها، وأصله عندهم اناس فلما سكنت الهمزة أدغمت اللام، كما قيل","page":"ج1 ص526","text":"بعضهم يأنس ببعض، والخلق مصدر سمي به المخلوقات والشاهد قوله عزوجل \" خلق السموات بغير عمد ترونها \" (1) ثم عدد الاشياء من الجماد والنبات والحيوان ثم قال \" هذا خلق الله \" (2) وقد يختص به الناس فيقال ليس في الخلق مثله كما تقول ليس في الناس مثله، وقد يجري على الجماعات الكثيرة فيقال جاءني خلق من الناس أي جماعة كثيرة."},{"id":"furuq-lughawiyya:697","bookId":"furuq-lughawiyya","type":"section","seq":697,"chapter":"* (أ) *","title":"2130 - الفرق بين الناس والورى: أن قولنا الناس يقعل على الاحياء","page":"ج1 ص527","text":"والاموات، والورى الاحياء منهم دون الاموات، وأصله من وري الزند يري إذا أظهر النار، فسمي الورى ورى لظهوره على وجه الارض، ويقال الناس الماضون ولا يقال الورى الماضون."},{"id":"furuq-lughawiyya:698","bookId":"furuq-lughawiyya","type":"section","seq":698,"chapter":"* (أ) *","title":"الفرق بين النبأ والخبر","page":"ج1 ص527","text":"أن النبأ لا يكون إلا للاخبار بما لا يعلمه المخبر ويجوز أن يكون المخبر بما يعلمه وبما لا يعلمه ولهذا يقال تخبرني عن نفسي ولا يقال تنبئني عن نفسي، وكذلك تقول تخبرني عما عندي ولا تقول تنبئني عما عندي، وفي القرآن \" فسيأتيهم أنباء ما كانوا به يستهزءون \" (3) وإنما استهزءوا به لانهم لم يعلموا حقيقته ولو علموا ذلك لتوقوه يعني العذاب وقال تعالى \" ذلك من أنباء القرى نقصه\nعليك \" (1) وكان النبي صلى الله عليه [وآله] وسلم لم يكن يعرف شيئا منها، وقال علي بن عيسى: في النبأ معنى عظيم الشأن وكذلك أخذ منه صفة النبي صلى الله عليه [وآله] وسلم، قال أبو هلال أيده الله ولهذا يقال سيكون لفلان نبأ ولا يقال خبر بهذا المعنى، وقال الزجاج في قوله تعالى \" فسيأتيهم أنباء ما كانوا به يستهزءون \" (2) أنباؤه تأويله والمعنى سيعلمون ما يؤول إليه إستهزاؤهم.\nقلنا وإنما يطلق عليه هذا لما فيه من عظم الشأن.\nقال أبو هلال والانباء عن الشئ أيضا قد يكون بغير حمل النبأ عنه تقول هذا الامر ينبئ بكذا ولا تقول يخبر بكذا لان الاخبار لا يكون إلا بحمل الخبر."},{"id":"furuq-lughawiyya:699","bookId":"furuq-lughawiyya","type":"section","seq":699,"chapter":"* (أ) *","title":"2134 - الفرق بين النبأ والخبر (3) : النبأ: الخبر الذي له شأن عظيم (4) ، ومنه اشتقاق النبوة، لان النبي مخبر عن الله تعالى ويدل عليه قوله تعال","page":"ج1 ص528","text":"وقوله \" وهل أتاك نبأ الخصم \" (6) .\nوقوله تعالى: \" عم يتساءلون عن النبإ العظيم \" (7) فوصفه بالعظمة.\nوصف كاشف عن حقيقته.\nوقال الراغب: النبأ خبر ذو فائدة عظيمة يحصل به علم أو غلبة ظن.\nولا يقال للخبر (8) نبأ حتى يتضمن هذه الاشياء (9) .\nوحق الخبر الذي قال فيه نبأ أن يتعرى عن الكذب كالمتواتر (10) .\nوخبر الله\nعزوجل وخبر النبي صلى الله عليه وآله.\n(اللغات) ."},{"id":"furuq-lughawiyya:700","bookId":"furuq-lughawiyya","type":"section","seq":700,"chapter":"* (أ) *","title":"2136 - الفرق بين النبل والجمال: أن النبل هو ما يرتفع به الانسان من الرواء","page":"ج1 ص529","text":"ومن المنظر ومن الاخلاق والافعال ومما يختص به من ذلك في نفسه دون ما يضاف يقال رجل نبيل في فعله ومنظره وفرس نبيل في حسنه وتمامه، والجمال يكون في ذلك وفي المال وفي العشيرة والاحوال الظاهرة فهو أعم من النبل ألا ترى انه يقال لك في المال والعشيرة جمال ولا يقال لك في المال نبل ولا هو نبيل في ماله، والجمال أيضا يستعمل في موضع الحسن فيقال وجه جميل كما يقال وجه حسن ولا يقال نبيل بهذا المعنى، ويجوز أن يكون معنى قولهم وجه جميل أنه يجري فيه السمن ويكون إشتقاقه من الجميل وهو الشحم المذاب."},{"id":"furuq-lughawiyya:701","bookId":"furuq-lughawiyya","type":"section","seq":701,"chapter":"* (أ) *","title":"الفرق بين النبي والرسول","page":"ج1 ص529","text":"أن النبي لا يكون إلا صاحب معجزة وقد يكون الرسول رسولا لغير الله تعالى فلا يكون صاحب معجزة.\nوالانباء عن الشئ قد يكون من غير تحميل النبأ، والارسال لا يكون بتحميل، والنبوة يغلب عليها الاضافة إلى النبي فيقال نبوة النبي لانه يستحق منها الصفة التي هي على طريقة الفاعل، والرسالة تضاف إلى\nالله لأنه المرسل بها ولهذا قال برسالتي ولم يقل بنبوتي والرسالة جملة من البيان يحملها القائم بها ليؤديها إلى غيره، والنبوة تكليف القيام بالرسالة فيجوز إبلاغ الرسالات ولا يجوز إبلاغ النبوات."},{"id":"furuq-lughawiyya:702","bookId":"furuq-lughawiyya","type":"section","seq":702,"chapter":"* (أ) *","title":"2138 - الفرق بين النبي والرسول (1) : قيل: لا فرق بينهما، وقيل: الرسول أخص من النبي لان كل رسول نبي من غير عكس.","page":"ج1 ص530","text":"وقيل: الرسول الذي معه كتاب الانبياء، والنبي الذي ينبئ عن الله وإن لم يكن معه كتاب.\nكذا قال جماعة من [17 / أ] المفسرين،\nوأورد عليه أن لوطا وإسماعيل وأيوب ويونس وهارون كانوا مرسلين، كما ورد في التنزيل، ولم يكونوا أصحاب كتب مستقلة.\nوقيل: الرسول من بعثه الله بشريعة جديدة يدعو الناس إليها، والنبي: من بعثه لتقرير (2) شريعة سابقة كأنبياء بني إسرائيل الذين كانوا بين موسى وعيسى عليهما السلام.\nويدل عليه أنه عليه السلام سئل عن الانبياء فقال: \" مئة ألف وأربعة وعشرون ألفا فقيل: فكم الرسل منهم؟ فقال: ثلاث مئة وثلاثة عشر.\nوقيل: الرسول من يأتيه الملك بالوحي عيانا ومشافهة \".\nوالنبي يقال له ولمن يوحى إليه في المنام.\nوهذا القول مروي عن أبي جعفر، وأبي عبد الله عليهما السلام.\nقالا: إن الرسول الذي يظهر له الملك فيكلمه، والنبي: هو الذي يرى في منامه.\nوربما اجتمعت\nالنبوة والرسالة لواحد.\nوعن زرارة قال: سألت أبا عبد الله عليه السلام عن قوله الله تعالى: \" وكان رسولا نبيا \" (1) ما الرسول؟ وما النبي؟.\nقال: النبي: \" الذي يرى في منامه ويسمع الصوت ولا يعاين الملك، والرسول: الذي يسمع الصوت ويرى في المنام ويعاين الملك \".\n(اللغات) ."},{"id":"furuq-lughawiyya:703","bookId":"furuq-lughawiyya","type":"section","seq":703,"chapter":"* (أ) *","title":"2143 - الفرق بين النجدة والشجاعة: أن النجدة حسن البدن وتمام لحمه","page":"ج1 ص532","text":"وأصلها الارتفاع ومنه سميت بلادهم المرتفعة نجدا، وقيل للنجاد نجاد لانه يحشو الثياب فترتفع ثم قيل للشجاعة نجدة لانها تكون مع تمام الجسم في أكثر الحال."},{"id":"furuq-lughawiyya:704","bookId":"furuq-lughawiyya","type":"section","seq":704,"chapter":"* (أ) *","title":"2145 - الفرق بين النجوى والسر: أن النجوى إسم للكلام الخفي الذي تناجي به صاحبك كأنك ترفعه عن غيره وذلك أن أصل الكلمة الرفعة، ومنه النجوة من ا","page":"ج1 ص532","text":"السلام مناجاة لانه كان كلاما أخفاه عن غيره، والسر إخفاء الشئ في النفس، ولو إختفى بستر أو وراء جدار لم يكن سرا، ويقال في هذا الكلام سر تشبيها بما يخفي في النفس، ويقال سري عند فلان تريد ما يخفيه في نفسه من ذلك ولا يقال نجواي عنده، وتقول لصاحبك هذا القيه إليك تريد المعنى الذي تخفيه في نفسك، والنجوي تتناول جملة ما يتناجى به من الكلام، والسر يتناول معنى ذلك وقد يكون السر في غير المعاني مجازا تقول فعل هذا سرا وقد أسر الامر، والنجوى لا تكون إلا كلاما."},{"id":"furuq-lughawiyya:705","bookId":"furuq-lughawiyya","type":"section","seq":705,"chapter":"* (أ) *","title":"2146 - الفرق بين النحلة والعطية: أن النحلة ما يعطيه الانسان بطيب نفس، ومنه قوله تعالى \" وآتوا النساء صدقاتهن نحلة \" (1) أي عن طيب أنفس، وقيل","page":"ج1 ص533","text":"ولده أفضل من أدب حسن \" وقال علي بن عيسى: الهبة لا تكون واجبة والنحلة تكون (1) واجبة وغير واجبة، وأصلها العطية من غير معاوضة، ومنه النحلة الديانة لانها كالنحلة التي هي العطية."},{"id":"furuq-lughawiyya:706","bookId":"furuq-lughawiyya","type":"section","seq":706,"chapter":"* (أ) *","title":"2147 - الفرق بين النحو والقصد: أن النحو قصد الشئ من وجه واحد يقال نحوته إذا قصدته من وجه واحد، والناس يقولون الكلام في هذا على أنحاء أي على","page":"ج1 ص533","text":"فسمي الاعراب نحوا، وناحية الشئ الوجه الذي يقصد منه وهي فاعلة بمعنى مفعولة أي هي منحوة."},{"id":"furuq-lughawiyya:707","bookId":"furuq-lughawiyya","type":"section","seq":707,"chapter":"* (أ) *","title":"الفرق بين النداء والدعاء","page":"ج1 ص533","text":"أن النداء هو رفع الصوت بماله معنى والعربي يقول لصاحبه ناد معي ليكون ذلك أندى لصوتنا أي أبعد له، والدعاء يكون برفع الصوت وخفضه يقال دعوته من بعيد ودعوت الله في نفسي ولا يقال ناديته في نفسي، وأصل الدعاء طلب الفعل دعا يدعو وادعى ادعاء لانه يدعو إلى مذهب من غير دليل، وتداعى البناء يدعو بعضه بعضا إلى السقوط، والدعوى مطالبة الرجل بمال\nيدعو إلى أن يعطاه، وفي القرآن \" تدعو من أدبر وتولى \" (1) أي يأخذه بالعذاب كأنه يدعوه إليه."},{"id":"furuq-lughawiyya:708","bookId":"furuq-lughawiyya","type":"section","seq":708,"chapter":"* (أ) *","title":"2151 - الفرق بين النداء والدعاء (2) : الاول قد يكون بعلامة من غير صوت ولا كلام، ولكن بإشارة تنئ عن معنى: تعال، ولا يكون النداء إلا برفع الصو","page":"ج1 ص534","text":"قاله الطبرسي (3) .\nقلت: ولذا لا يسند النداء إلى الله - سبحانه - بخلاف الدعاء قال تعالى: \" والله يدعوا إلى دار السلام \" (4) ، \" والله يدعوا إلى الجنة والمغفرة \" (5) .\n(اللغات) ."},{"id":"furuq-lughawiyya:709","bookId":"furuq-lughawiyya","type":"section","seq":709,"chapter":"* (أ) *","title":"الفرق بين الند والمثل","page":"ج1 ص534","text":"أن الند هو المثل المناد من قولك ناد فلان فلانا إذا عاداه وباعده ولهذا سمي الضد ندا، وقال صاحب العين: الند ما كان مثل الشئ يضاده في اموره والنديد مثله والندود الشرود والتناد التنافر وأنددت البعير ونددت بالرجل سمعت بعيوبه، وأصل الباب التشريد فالند لمناداته لصاحبه كأنه يريد تشريده."},{"id":"furuq-lughawiyya:710","bookId":"furuq-lughawiyya","type":"section","seq":710,"chapter":"* (أ) *","title":"2155 - الفرق بين الند والمثل (1) : هما بمعنى في اللغة، وقال بعضهم: لا يقال الند إلا للمثل.","page":"ج1 ص535","text":"الناد أي المخالف، من ناددته.\nأي خالفته ونافرته.\nومعنى قول الموحدين: \" ليس لله ضد ولا ند \" نفى ما يسد مسده، ونفي ما ينافيه، قلت: ويدل عليه عبارة الدعاء في الصحيفة الشريفة (2) : \" ولا ند لك فيعارضك \".\nوقال الراغب: ند الشئ: مشاركة في جوهره.\nوذلك ضرب من المماثلة، فإن المثل يقال في أي مشاركة كانت.\nفكل ند مثل، وليس كل مثل ندا.\n(اللغات) ."},{"id":"furuq-lughawiyya:711","bookId":"furuq-lughawiyya","type":"section","seq":711,"chapter":"* (أ) *","title":"2158 - الفرق بين الندى والجواد: أن الندى إسم للجواد الذي ينال القريب والبعيد فيبعد مذهبه مشبه بندى المطر لبعد مذهبه، وفلان أندى صوتا من فلان","page":"ج1 ص535","text":"وقال الخليل: الندى له وجوه ندى الماء وندى الخير وندى الشم وندى الصوت قال الشاعر: بعيد ندى التغريد أزمع صوته * سجيل وأدناه شحيح محشرج وندى الحضر وندى الوجنة كل ذلك من بعد المذهب."},{"id":"furuq-lughawiyya:712","bookId":"furuq-lughawiyya","type":"section","seq":712,"chapter":"* (أ) *","title":"2159 - الفرق بين الندى والمجلس والمقامة: أن الندى هو المجلس للاهل ومن","page":"ج1 ص536","text":"ثم قيل هو أنطقهم في الندى، ولا يقال في المجلس إذا خلا من أهله ندى، وقد تنادى القوم إذا تجالسوا في الندى، والمقامة بالضم المجلس يؤكل فيه ويشرب والمقامة بالفتح المجلس الذي يتحدث فيه، والمقامة بالفتح أيضا الجماعة وأما المقام فالاقامة والمقام بالفتح مصدر قام يقوم مقاما، والمقام أيضا موضع القيام."},{"id":"furuq-lughawiyya:713","bookId":"furuq-lughawiyya","type":"section","seq":713,"chapter":"* (أ) *","title":"2160 - الفرق بين النزغ والوسوسة: أن النزغ هو الاغواء بالوسوسة وأكثر ما يكون عند الغضب، وقيل أصله للازعاج بالحركة إلى الشر ويقال هذه نزعة من","page":"ج1 ص536","text":"تفصيله لخفائه وسوسة ووسواس وكذلك ما وقع في النفس خفيا، وسمى الله تعالى الموسوس وسواسا بالمصدر في قوله تعالى: \" من شر الواس الخناس \" (1) ."},{"id":"furuq-lughawiyya:714","bookId":"furuq-lughawiyya","type":"section","seq":714,"chapter":"* (أ) *","title":"2164 - الفرق بين النساجة والحياكة (1) : قد تخص النساجة ببعض الاجناس كالرقيق، والحياكة بغيره.","page":"ج1 ص537","text":"وقيل: النساجة أعم من الحياكة مطلقا.\nولم يفرق الجوهري بينهما، قال في الصحاح: نسج الثوب وحاكه واحد.\n(اللغات) ."},{"id":"furuq-lughawiyya:715","bookId":"furuq-lughawiyya","type":"section","seq":715,"chapter":"* (أ) *","title":"2165 - الفرق بين النسخ والبداء: أن النسخ رفع حكم تقدم بحكم ثان أوجبه كتاب أو سنة ولهذا يقال إن تحريم الخمر وغيرها مما كان مطلقا في العقل نسخ","page":"ج1 ص537","text":"بدا لي في الشئ إذا ظهر لك فيه رأي لم يكن ظاهرا لك فتركته لاجل ذلك، ولا يجوز على الله البداء لكونه عالما لنفسه، وما ينسخه من الاحكام ويثبته إنما هو على قدر المصالح لا أنه يبدو له من الاحوال ما لم يكن باديا، والبداء هو أن تأمر المكلف الواحد بنفس ما تنهاه عنه على الوجه الذي تنهاه عنه والوقت الذي تنهاه فيه عنه وهذا لا يجوز على الله لانه يدل على التردد في الرأي، والنسخ في الشريعة لفظة منقولة عما وضعت له في أصل اللغة كسائر الاسماء الشرعية مثل الفسق والنفاق ونحو ذلك، وأصله في العربية الازالة ألا تراهم قالوا نسخت الريح الآثار فان قلت إن الريح ليست بمزيلة لها على الحقيقة قلنا\nإعتقد أهل اللغة أنها مزيلة لها كإعتقادهم أن الصنم إله."},{"id":"furuq-lughawiyya:716","bookId":"furuq-lughawiyya","type":"section","seq":716,"chapter":"* (أ) *","title":"2168 - الفرق بين النسيان والسهو: أن النسيان إنما يكون عما كان، والسهو يكون عما لم يكن تقول نسيت ما عرفته ولا يقال سهوت عما عرفته وإنما تقول","page":"ج1 ص538","text":"ذكر لانه خفاء المعنى بما يمتنع به إدراكه، وفرق آخر وهو أن الشئ الواحد محال أن يسهى عنه في وقت ولا يسهى عنه في وقت آخر وإنما يسهى في وقت آخر عن مثله ويجوز أن ينسى الشئ الواحد في وقت ويذكره في وقت آخر."},{"id":"furuq-lughawiyya:717","bookId":"furuq-lughawiyya","type":"section","seq":717,"chapter":"* (أ) *","title":"2174 - الفرق بين النصر والمعونة (2) : النصر: يختص بالمعونة على الاعداء.","page":"ج1 ص539","text":"والمعونة: عامة في كل شئ.\nفكل نصر معونة ولا ينعكس.\nويدل عليه قوله تعالى: \" إنا لننصر رسلنا \" (3) و \" وينصرك الله نصرا عزيزا \" (4) و \" ونصرناهم فكانوا هم الغالبين \" (5) .\nفإن مساق الآيات الاخبار عن ظفر الانبياء عليهم السلام، ونصرتهم على أعدائهم، إما بالغلبة، أو بالحجة (*) (6) .\n(اللغات) ."},{"id":"furuq-lughawiyya:718","bookId":"furuq-lughawiyya","type":"section","seq":718,"chapter":"* (أ) *","title":"2177 - الفرق بين النصيب والحظ: أن النصيب يكون في المحبوب والمكروه يقال وفاه الله نصيبه من النعيم أو من العذاب، ولا يقال حظه من","page":"ج1 ص540","text":"العذاب إلا على إستعارة بعيدة لان أصل الحظ هو ما يحظه الله تعالى للعبد من الخير، والنصيب ما نصب له ليناله سواء كان محبوبا أو مكروها، ويجوز أن يقال الحظ إسم لما يرتفع به المحظوظ، ولهذا يذكر على جهة المدح فيقال لفلان حظ وهو محظوظ، والنصيب ما يصيب الانسان من مقاسمة سواء ارتفع به شأنه أم لا ولهذا يقال لفلان حظ في التجارة ولا يقال له نصيب فيها لان الربح الذي يناله فيها ليس عن مقاسمة."},{"id":"furuq-lughawiyya:719","bookId":"furuq-lughawiyya","type":"section","seq":719,"chapter":"* (أ) *","title":"2179 - الفرق بين النصيب والقسط: أن النصيب يجوز أن يكون عادلا وجائرا وناقصا عن الاستحقاق وزائدا يقال نصيب مبخوس وموفور، والقسط الحصة العادلة","page":"ج1 ص540","text":"لابد له من ذلك."},{"id":"furuq-lughawiyya:720","bookId":"furuq-lughawiyya","type":"section","seq":720,"chapter":"* (أ) *","title":"2181 - الفرق بين النطق والكلام (1) : قيل: الفرق بينهما أن الكلام هو","page":"ج1 ص541","text":"ما يتكلم به قليلا كان (1) أو كثيرا.\nوأما كلام الله - سبحانه - فهو عبارة عن إيجاده الاصوات والحروف في محل، وإسماعها الانبياء والملائكة.\nوالنطق.\nإرادة اللسان في الفم بالكلام.\n[24 / ب] ولذا لا يوصف - سبحانه - بالنطق، ويوصف بأنه متكلم.\nقال تعالى: \" وكلم الله موسى تكليما \" (2) .\nوأهل اللغة لم يفرقوا بينهما.\nقال الجوهري (3) : النطق: الكلام.\n(اللغات) ."},{"id":"furuq-lughawiyya:721","bookId":"furuq-lughawiyya","type":"section","seq":721,"chapter":"* (أ) *","title":"2187 - الفرق بين النظر والتأمل: أن النظر هو ما ذكرناه (4) ، والتأمل هو","page":"ج1 ص542","text":"النظر المؤمل به معرفة ما يطلب ولا يكون إلا في طول مدة فكل تأمل نظر وليس كل نظر تأملا."},{"id":"furuq-lughawiyya:722","bookId":"furuq-lughawiyya","type":"section","seq":722,"chapter":"* (أ) *","title":"الفرق بين النظر والرؤية","page":"ج1 ص542","text":"أن النظر طلب الهدى، والشاهد قولهم نظرت فلم أر شيئا، وقال علي بن عيسى: النظر طلب ظهور الشئ، والناظر الطالب لظهور الشئ والله ناظر لعباده بظهور رحمته إياهم، ويكون الناظر الطالب لظهور الشئ بإدراكه من جهة حاسة بصره أو غيرها من حواسه ويكون الناظر إلى لين هذا الثوب من لين غيره، والنظر بالقلب من جهة التفكر، والانظار توقف لطلب وقت الشئ الذي يصلح فيه قال والنظر أيضا هو الفكر والتأمل لاحوال الاشياء ألا ترى أن الناظر على هذا الوجه لابد أن يكون مفكرا والمفكر على هذا الوجه يسمى ناظرا وهو معنى غير الناظر وغير المنظور فيه ألا ترى أن الانسان يفصل بين كونه ناظرا وكونه غير ناظر، ولا يوصف القديم بالنظر لان النظر لا يكون إلا مع فقد العلم ومعلوم أنه لا يصلح النظر في الشئ ليعلم ألا وهو مجهول، والنظر يشاهد بالعين فيفرق بين نظر الغضبان ونظر الراضي، واخرى فإنه لو طلب جماعة الهلال ليعلم من رآه منهم ممن لم يره مع أنهم جميعا ناظرون فصح بهذا أن\nالنظر تقليب العين حيال مكان المرئي طلبا لرؤيته، والرؤية هي إدراك المرئي، ولما كان الله تعالى يرى الاشياء من حيث لا يطلب رؤيتها صح أنه لا يوصف بالنظر.\n* * *"},{"id":"furuq-lughawiyya:723","bookId":"furuq-lughawiyya","type":"section","seq":723,"chapter":"* (أ) *","title":"2190 - الفرق بين النظر والرؤية (1) : قيل: الفرق بينهما أن الرؤية هي (2) : إدراك المرئي.","page":"ج1 ص543","text":"والنظر: الاقبال بالبصر نحو المرئي.\nولذلك قد ينظر ولا يراه، ولذلك يجوز أن يقال لله تعالى: إنه راء، ولا يقال: إنه ناظر.\nوفيه نظر.\nفإنه قد ورد في أسمائه سبحانه: (يا ناظر) .\nرواه الشيخ الكفعمي (3) في المصباح.\n(اللغات) ."},{"id":"furuq-lughawiyya:724","bookId":"furuq-lughawiyya","type":"section","seq":724,"chapter":"* (أ) *","title":"2193 - الفرق بين النعت والصفة: أن النعت فيما حكى ابو العلاء رحمه الله: لما يتغير - من الصفات.","page":"ج1 ص543","text":"والصفة لما يتغير ولما لا يتغير فالصفة أعم من النعت.\nقال فعلى هذا يصح أن ينعت الله تعالى بأوصافه لفعله لانه يفعل ولا يفعل.\nولا ينعت بأوصافه لذاته إذ لا يجوز أن يتغير.\nولم يستدل على صحة ما قاله من ذلك بشئ والذي عندي أن النعت هو ما يظهر من الصفات ويشتهر ولهذا قالوا هذا نعت الخليفة كمثل قولهم الامين والمأمون والرشيد.\nوقالوا أول\nمن ذكر نعته على المنبر الامين ولم يقولوا صفته وإن كان قولهم الامين صفة له عندهم لان النعت يفيد من المعاني التي ذكرناها مالا تفيده الصفة ثم قد تتداخل الصفة والنعت فيقع كل واحد منهما موضع الآخر لتقارب معناهما، ويجوز أن يقال الصفة لغة والنعت لغة أخرى ولا فرق بينهما في المعنى والدليل على ذلك أن أهل البصرة من النحاة يقولون الصفة وأهل الكوفة يقولون النعت ولا يفرقون بينهما فأما قولهم نعت الخليفة فقد غلب على ذلك كما يغلب بعض الصفات على بعض الموصوفين بغير معنى يخصه فيجري مجرى اللقب في الرفعة ثم كثرا حتى استعمل كل واحد منهما في موضع الآخر."},{"id":"furuq-lughawiyya:725","bookId":"furuq-lughawiyya","type":"section","seq":725,"chapter":"* (أ) *","title":"2194 - الفرق بين النعت والوصف (1) : قيل: هما مترادفان، وفرق بعضهم بينهما، بأن الوصف: ما كان بالحال المتنفلة كالقيام والقعود.","page":"ج1 ص544","text":"والنعت: ما كان في خلق وخلق.\nكالبياض والكرم.\nقيل: ولهذا لا يجوز إطلاق النعت عليه - سبحانه -، لان صفاته - سبحانه - لا تزول.\nقلت: ويرده ما في الادعية المأثورة.\nومن ذلك (2) : \" يا من عجزت عن نعته أوصاف الواصفين \".\nوغير ذلك من الادعية.\nقال ابن الاثير: \" النعت وصف الشئ بما فيه من حسن، ولا يقال في القبيح، إلا أن يتكلف، فيقال: نعت سوء.\nوالوصف،\nيقال في الحسن وفي القبيح \".\n(3) انتهى (اللغات) ."},{"id":"furuq-lughawiyya:726","bookId":"furuq-lughawiyya","type":"section","seq":726,"chapter":"* (أ) *","title":"2207 - الفرق بين النفاذ والفطنة: أن النفاذ أصله في الذهاب يقال نفذ","page":"ج1 ص545","text":"السهم إذا ذهب في الرمية، ويسمى الانسان نافذا إذا كان فكره يبلغ حيث لا يبلغ فكر البليد ففي النفاذ معنى زائد على الفطنة، ولا يكاد الرجل يسمى نافذا إلا إذا كثرت فطنته للاشياء ويكون خراجا ولاجا في الامور، وليس هو من الكيس أيضا في شئ لان الكيس هو سرعة الحركة فيما يعني دون ما لا يعني، ويوصف به الناقص الآلة مثل الصبي ولا يوصف بالنفاذ إلا الكامل الراجح وهذا معروف."},{"id":"furuq-lughawiyya:727","bookId":"furuq-lughawiyya","type":"section","seq":727,"chapter":"* (أ) *","title":"2210 - الفرق بين النفر والرهط: أن النفر الجماعة نحو العشرة من الرجال","page":"ج1 ص546","text":"خاصة ينفرون لقتال وما أشبهه، ومنه قوله عزوجل \" مالكم إذا قيل لكم إنفروا في سبيل الله اثاقلتم إلى الارض \" (1) ثم كثر ذلك حتى سموا نفرا وإن لم ينفروا.\nوالرهط الجماعة نحو العشرة يرجعون إلى أب واحد وسموا رهطا بقطعة أو لم يقطع أطرافها مثل الشرك فتكون فروعها شتى وأصلها واحد تلبسها الجارية يقال لها رهط والجمع رهاط قال الهذلي: * وطعن مثل تعطيط الرهاط * وتقول ثلاثة رهط وثلاثة نفر لانه إسم لجماعة، ولو كان إسما واحدا لم تجز إضافة الثلاثة إليه كما لا يجوز أن تقول ثلاثة رجل وثلاثة فليس وقال عز وجل \" وكان في المدينة تسعة رهط \" (2) على التذكير لانه وإن كان جماعة فإن لفظه مذكر مفرد فيقال تسعة على اللفظ وجاء في التفسير أنهم كانوا تسعة رجال والمعنى على هذا وكان في المدينة تسعة من رهط."},{"id":"furuq-lughawiyya:728","bookId":"furuq-lughawiyya","type":"section","seq":728,"chapter":"* (أ) *","title":"2213 - الفرق بين النفل والغنيمة: أن أصل النفل في اللغة الزيادة على المستحق ومنه النافلة وهي التطوع ثم قيل لما ينفله صاحب السرية بعض أصحابه ن","page":"ج1 ص548","text":"سلبه، أو يقول لجماعة لكم الربع بعد الخمس وما أشبه ذلك، ولا خلاف في جواز النفل قبل إحراز الغنيمة، وقال الكوفيون لا نفل بعد إحراز الغنيمة على جهة الاجتهاد، وقال الشافعي: يجوز النفل بعد إحراز الغنيمة على جهة الاجتهاد، وقال إبن عباس: في رواية الانفال ما شذ عن المشركين إلى المسلمين من غير قتال نحو العبد والدابة ولذلك جعلها الله تعالى للنبي صلى الله عليه [وآله] وسلم في قوله \" قل الانفال لله والرسول \" (1) وروي عن مجاهد: أن الانفال الخمس جعله الله لاهل الخمس، وقال الحسن: الانفال من السرايا التي تتقدم أمام الجيش الاعظم، وأصلها ما ذكرنا ثم اجريت على الغنائم كلها مجازا."},{"id":"furuq-lughawiyya:729","bookId":"furuq-lughawiyya","type":"section","seq":729,"chapter":"* (أ) *","title":"2216 - الفرق بين النقص والنقصان (2) : الفرق بينهما: أن النقص يستعمل في ذهاب الاعيان، كالمال والمنافع والنفوس.","page":"ج1 ص548","text":"وفي المعاني: كالعيب والنقيصة.\nقال تعالى: \" ولنبلونكم بشئ من الخوف والجوع ونقص من الاموال والانفس والثمرات \" (3) .\nوتقول: فلان دخل عليه نقص في عقله، أو في دينه.\nوأما النقصان: فلا يستعمل إلا في ذهاب الاعيان، لا يقال: فلان في عقله\nنقصان، أو في دينه، بل نقول: نقص، ونقول: ليس في هذا الامر نقص، أي بأس وعيب، ولا تقول فيه نقصان، إلا إذا استلزم ذهاب مال أو انتفاع.\nفالنقص أعم استعمالا من النقصان.\nوأهل اللغة لم يذكروا بينهما فرقا.\n(اللغات) ."},{"id":"furuq-lughawiyya:730","bookId":"furuq-lughawiyya","type":"section","seq":730,"chapter":"* (أ) *","title":"2229 - الفرق بين النهاية والحد والعاقبة: أن النهاية ما ذكرناه (1) ، والحد يفيد معنى تمييز المحدود من غيره، ولهذا قال المتكلمون حد القدرة كذا","page":"ج1 ص551","text":"وحد السواد كذا وسمي حدا لانه يمنع غيره من المحدود فيما هو حد له وفي هذا تمييز له من غيره، ولهذ قال الشروطيون إشترى الدار بحدودها ولم يقولوا بنهاياتها لان الحد أجمع للمعنى، ولهذا يقال للعالم\nنهاية ولا يقال للعالم حد فان قيل فعلى الاستعارة وهو بعيد، وعندهم أن حد الشئ منه فقال أبو يوسف والحسن بن زياد: إذا كتب حدها الاول دار زيد دخلت دار زيد في الشراء، وقال أبو حنيفة: لا تدخل فيه وإن كتب حدها الاول المسجد وأدخله فسد البيع في قولهما وقال أبو حنيفة: لا يفسد لان هذا على مقتضى العرف وقصد الناس في ذلك معروف، وأما العاقبة فهي ما تؤدي إليه التأدية والعاقبة هي الكائنة بالنسب الذي من شأنه التأدية وذلك أن السبب على وجهين مولد ومؤد وإنما العاقبة في المؤدي فالعاقبة يؤدي إليها السبب المقدم وليس كذلك الآخرة لانه قد كان يمكن أن تجعل هي الاولى في العدة."},{"id":"furuq-lughawiyya:731","bookId":"furuq-lughawiyya","type":"section","seq":731,"chapter":"* (أ) *","title":"ة","page":"ج1 ص552","text":"والعزم: أن النية إرادة متقدمة للفعل بأوقات من قولك إنتوى إذا بعد، والنوى والنية البعد فسميت بها الارادة التي بعد ما بينها وبين مرادها، ولا يفيد قطع الروية في الاقدام على الفعل،\nوالعزم قد يكون متقدما للمعزوم عليه بأوقات وبوقت، ولا يوصف الله بالنية لان إرادته لا تتقدم فعله ولا يوصف بالعزم كما لا يوصف بالروية وقطعها في الاقدام والاحجام."},{"id":"furuq-lughawiyya:732","bookId":"furuq-lughawiyya","type":"section","seq":732,"chapter":"* (أ) *","title":"2235 - الفرق بين النيف والبضع (1) : النيف: من واحد إلى ثلاثة.","page":"ج1 ص552","text":"والبضع: من أربعة (2) إلى تسعة.\nولا يقال (نيف) إلا بعد عقد، نحو عشرة ونيف، ومائة ونيف، بخلاف البضع فإنه يستعمل مستقلا.\nومنه قوله تعالى: \" فلبث في السجن بضع سنين \" (3) .\n(اللغات) ."},{"id":"furuq-lughawiyya:733","bookId":"furuq-lughawiyya","type":"section","seq":733,"chapter":"* (أ) *","title":"2237 - الفرق بين الهبة والبذل (1) : هما بمعنى النحلة والعطية.","page":"ج1 ص553","text":"ويستفاد من كلام الفقهاء في كتاب الحج الفرق بينهما، بأن الهبة إذا تعلقت بالزاد والراحلة أعيانهما، فهي بذل سواء كان بصيغة الهبة أم غيرها على خلاف، وإذا لم تتعلق بأعيانها فهي بذل (2) سواء تعلقت بأثمانها\nأم مال غيره.\nوتظهر الفائدة في أن البذل يجب قبوله والرضا به في الاستطاعة للحج.\nولا يشترط فيه القبول، لانه إباحة يكفي فيها الايقاع.\nبخلاف الثاني فإن المعتبر فيه القبول.\nوهو نوع اكتساب والاكتساب (3) غير واجب للحج، لان وجوبه مشروط بوجود الاستطاعة، فلا يجب تحصيل شرطه.\nوأورد عليه بأن مقتضى الروايات تحقق الاستطاعة ببذل ما يحج به، وهو كما يتحقق يتناول عين الزاد والراحلة، كذلك يتناول أثمانها.\nوثانيا: إن الظاهر تحقق الاستطاعة، وهي التمكن من الحج بمجرد البذل، ومتى تحققت الاستطاعة يصير الوجوب مطلقا.\nوحينئذ، فيجب كل ما يتوقف عليه من المقدمات.\n(اللغات) ."},{"id":"furuq-lughawiyya:734","bookId":"furuq-lughawiyya","type":"section","seq":734,"chapter":"* (أ) *","title":"الفرق بين الهدية والهبة","page":"ج1 ص554","text":"أن الهدية ما يتقرب به المهدي إلى المهدى إليه، وليس كذلك الهبة ولهذ لا يجوز أن يقال إن الله يهدي إلى العبد كما يقال إنه يهب له وقال تعالى \" فهب لي من لدنك وليا \" (3) وتقول أهدى المرؤوس إلى الرئيس ووهب الرئيس للمرؤوس، وأصل الهدية من قولك هدى\nالشئ إذا تقدم وسميت الهدية هدية لانها تقدم أمام الحاجة."},{"id":"furuq-lughawiyya:735","bookId":"furuq-lughawiyya","type":"section","seq":735,"chapter":"* (أ) *","title":"2246 - الفرق بين الهدية والهبة (1) : الهدية: وإن كانت ضربا من الهبة، إلا أنها مقرونة بما يشعر إعظام المهدي إليه وتوقيره، بخلاف الهبة.","page":"ج1 ص555","text":"وأيضا الهبة: يشترط فيها الايجاب، والقبول، والقبض إجماعا.\nواختلف الاصحاب في الهدية: فذهب العلامة الجرجاني في القواعد على الاشتراط، لانها نوع من الهبة، فيشترط فيها ما يشترط في الهبة.\nوذهب بعض المتأخرين: إلى عدم اشتراط ذلك فيها، لان الهدايا كانت تحمل إلى النبي صلى الله عليه وآله من كسرى، وقيصر.\nوسائر الملوك، فيقبلها، ولا لفظ هناك.\nواستمر الحال على هذا من عهده صلى الله عليه وآله إلى هذا الوقت في سائر الاصقاع، ولهذا كانوا يبعثونها على أيدي الصبيان الذين لا يعتد بعبارتهم.\nلا يقال كان ذلك إباحة لا تمليكا، لانا نقول: لو كان كذلك لما تصرفوا فيه\nتصرف المال.\nومعلوم أن النبي صلى الله عليه وآله كان يتصرف فيه، ويملكه غيره من زوجاته، وغيرهن، قيل: ويؤيده: أن الهدية مبنية على الحشمة والاعظام.\nوذلك يفوت مع اعتبار الايجاب والقبول، وينقص موضعها من النفس.\nيقول جامع الكتاب - وفقه الله للصواب -: هذا ما تيسر لي في هذا الوقت (2) إيراده من الفروق، وإن وقفت على غير ذلك فما بعد (3) ، ألحقته - إن شاء تعالى - بالكتاب، والله\nالهادي في كل باب.\n(اللغات) ."},{"id":"furuq-lughawiyya:736","bookId":"furuq-lughawiyya","type":"section","seq":736,"chapter":"* (أ) *","title":"2252 - الفرق بين الهضم والظلم: أن الهضم نقصان بعض الحق ولا يقال لمن","page":"ج1 ص556","text":"أخذ جميع حقه قد هضم.\nوالظلم يكون في البعض والكل وفي القرآن \" فلا يخاف ظلما ولا هضما \" (1) أي لا يمنع حقه ولا بعض حقه وأصل الهضم في العربية النقصان ومنه قيل للمنخفض من الارض هضم والجمع أهضام."},{"id":"furuq-lughawiyya:737","bookId":"furuq-lughawiyya","type":"section","seq":737,"chapter":"* (أ) *","title":"2257 - الفرق بين الهمة والهم: أن الهمة إتساع الهم وبعد موقعه ولهذ يمدح بها الانسان فيقال فلان ذو همة وذو عزيمة، وأما قولهم فلان بعيد الهمة و","page":"ج1 ص557","text":"فالشهادة من الله تعالى إخبار وبيان ومنهم إقرار، والهم أيضا عند الحزن الذي يذيب البدن من قولك هم الشحم إذا أذابه.\nوسنذكر الفروق بين الهم والغم والحزن في بابه إن شاء الله."},{"id":"furuq-lughawiyya:738","bookId":"furuq-lughawiyya","type":"section","seq":738,"chapter":"* (أ) *","title":"2259 - الفرق بين الهمزة واللمزة (3) : قيل هما بمعنى.","page":"ج1 ص558","text":"وقيل بينهما فرق.\nفإن الهمزة: الذي يعكس بظهر الغيب.\nواللمزة: الذي يعكس في وجهك.\nوقيل: الهمزة: الذي يؤذي حليسه بسوء.\nلفظه.\nواللمزة: الذي يكثر عيبه على جليسه، ويشير برأسه، ويومئ بعينه.\n(اللغات) ."},{"id":"furuq-lughawiyya:739","bookId":"furuq-lughawiyya","type":"section","seq":739,"chapter":"* (أ) *","title":"2260 - الفرق بين الهم والارادة: أن الهم آخر العزيمة عند مواقعة الفعل قال الشاعر: هممت ولم أفعل وكدت وليتني * تركت على عثمان تبكي حلائله ويقا","page":"ج1 ص558","text":"وقيل الهم تعلق الخاطر بشئ له قدرة في الشدة، والمهمات الشدائد، وأصل الكلمة الاستقصاء ومنه هم الشحم إذا أذابه حتى أحرقه وهم المرض إذا هبط."},{"id":"furuq-lughawiyya:740","bookId":"furuq-lughawiyya","type":"section","seq":740,"chapter":"* (أ) *","title":"الفرق بين الهم والغم","page":"ج1 ص559","text":"أن الهم هو الفكر في إزالة المكروه واجتلاب المحبوب، وليس هو من الغم في الشئ ألا ترى أنك تقول لصاحبك اهتم في حاجتي ولا يصح أن تقول اغتم بها.\nوالغم معنى ينقبض القلب معه ويكون لوقوع ضرر قد كان أو توقع ضرر يكون أو يتوهمه وقد سمي الحزن الذي تطول مدته حتى يذيب البدن هما، وإشتقاقه من قولك إنهم (1) الشحم إذا ذاب، وهمه إذا أذابه."},{"id":"furuq-lughawiyya:741","bookId":"furuq-lughawiyya","type":"section","seq":741,"chapter":"* (أ) *","title":"2263- الفرق بين الهم والغم","page":"ج1 ص559","text":"الفرق بين الهم والغم (2) * (3) : قيل: الغم: ما لا يقدر الانسان على إزالته كموت المحبوب.\n* (4) والهم: ما يقدر على إزالته، كالافلاس مثلا.\nقلت: ويؤيده قوله تعالى في وصف أهل النار: \" كلما أرادوا أن يخرجوا منها من غم اعيدوا \" (5) .\nفإنهم لم يكونوا قادرين على إزالة ما بهم من العذاب.\nوقيل: الهم: قبل نزول الامر، ويطرد النوم، والغم.\nبعد نزول الامر، ويجلب النوم.\nكذا في مجمع البحرين.\nوأما الحزن فهو الأسف على ما فات.\n(اللغات) ."},{"id":"furuq-lughawiyya:742","bookId":"furuq-lughawiyya","type":"section","seq":742,"chapter":"* (أ) *","title":"الفرق بين الهنئ والمرئ","page":"ج1 ص560","text":"أن الهنئ هو الخالص الذي لا تكدير فيه ويقال ذلك في الطعام وفي كل فائدة لم يعترض عليها ما يفسدها، والمرئ المحمود العاقبة يقال مرئ ما فعلت أي أشرفت على سلامة عاقبته، وقال الكسائي: تقول هناني الطعام ومراني الطعام بغير ألف فإذا أفردت قلت أمراني بغير همز، وقال المبرد: هذا الكلام لو كان له وجه لكان قمنا أن يأتي فيه بعلة وهل يكون فعل على شئ إذا كان وحده فإذا كان مع غيره إنتقل لفظه والمراد واحد وإنما الصحيح ما أعلمتك، وأمراني بغير همز معناه هضمته معدتي."},{"id":"furuq-lughawiyya:743","bookId":"furuq-lughawiyya","type":"section","seq":743,"chapter":"* (أ) *","title":"2268- الفرق بين الهنئ والمرئ","page":"ج1 ص560","text":"الفرق بين الهنئ والمرئ (1) : قال الهروي (2) : والهنئ: ما لا تعب فيه، ولا إثم.\nوالمرئ: ما لا داء فيه.\n(اللغات) ."},{"id":"furuq-lughawiyya:744","bookId":"furuq-lughawiyya","type":"section","seq":744,"chapter":"* (أ) *","title":"2269 - الفرق بين ما هو وما حده: أن قولنا ما هو يكون سؤالا عن الحد كقولك ما الجسم، وسؤالا عن الرسم كقولك ما الشئ وذلك أن الشئ لا يحد على ما ذ","page":"ج1 ص560","text":"يعلم ويذكر ويخبر عنه.\nوسؤالا عن الجنس كقولك ما الدنيا، وسؤالا عن التفسير اللغوي كقولك ما القطر فتقول النحاس وما القطر فتقول العود.\nوليس كذلك قولنا ما حده لان ذلك يبين الاختصاص من\nوجه من هذه الوجوه."},{"id":"furuq-lughawiyya:745","bookId":"furuq-lughawiyya","type":"section","seq":745,"chapter":"* (أ) *","title":"الفرق بين الهوى والشهوة","page":"ج1 ص561","text":"أن الهوى لطف محل الشئ من النفس مع الميل إليه بما لا ينبغي ولذلك غلب على الهوى صفة الدم، وقد يشتهي الانسان الطعام ولا يهوى الطعام."},{"id":"furuq-lughawiyya:746","bookId":"furuq-lughawiyya","type":"section","seq":746,"chapter":"* (أ) *","title":"2271- الفرق بين الهوى والشهوة","page":"ج1 ص561","text":"الفرق بين الهوى والشهوة (1) : الفرق بينهما بأن الهوى يختص بالاداء والاعتقادات، والشهوة تختص بنيل المستلذات.\nويدل عليه قوله تعالى: \" ولا تتبع الهوى فيضلك \" (2) أي لا تتبع ما يميل إليه طبعك ويقتضيه رأيك من غير أن يسند (3) إلى دليل شرعى.\nويدل على الثاني قوله تعالى: \" زين للناس حب الشهوات من النساء والبنين \" (4) الآية.\nحيث بين مراتب المشتهيات بعدها، وفصل أصول المستلذات عقيب ذلك، وعدها.\n(اللغات) ."},{"id":"furuq-lughawiyya:747","bookId":"furuq-lughawiyya","type":"section","seq":747,"chapter":"* (أ) *","title":"2272 - الفرق بين الهول والخوف: أن الهول مخافة الشئ لا يدري على ما يقحم عليه منه، كهول الليل وهول البحر وقد هالني الشئ وهو هائل ولا يقال أمر","page":"ج1 ص561","text":"فاعل كقولهم دارع وإذا كان الشئ انشئ فيه أخرجوه على مفعول\nمثل يحبون فيه ذلك"},{"id":"furuq-lughawiyya:748","bookId":"furuq-lughawiyya","type":"section","seq":748,"chapter":"* (أ) *","title":"و","page":"ج1 ص562","text":"مديون عليه ذلك وهذا قول الخليل."},{"id":"furuq-lughawiyya:749","bookId":"furuq-lughawiyya","type":"section","seq":749,"chapter":"* (أ) *","title":"2278 - الفرق بين واحد وأحد: أن معنى الواحد أنه لا ثاني له فلذلك لا يقال في التثنية واحدان كما يقال رجل ورجلان، ولكن قالوا إثنان حين أرادوا أ","page":"ج1 ص563","text":"العين: الواحد أول العدد، وحد الاثنين ما يبين أحدهما عن صاحبه بذكر أو عقد فيكون ثانيا له بعطفه عليه ويكون الاحد أولا له ولا يقال إن الله ثاني إثنين ولا ثالث ثلاثة لان ذلك يوجب المشاركة في أمر تفرد به فقوله تعالى \" ثاني إثنين إذ هما في الغار \" (2) معناه أنه ثاني إثنين في التناصر وقال تعالى \" لقد كفر الذين قالوا إن الله ثالث ثلاثة \" (3) لانهم أوجبوا مشاركته فيما ينفرد به من القدم والالهية فأما\nقوله تعالى \" إلا هو رابعهم \" (1) فمعناه أنه يشاهدهم كما تقول للغلام اذهب حيث شئت فأنا معك تريد أن خبره لا يخفى عليك."},{"id":"furuq-lughawiyya:750","bookId":"furuq-lughawiyya","type":"section","seq":750,"chapter":"* (أ) *","title":"2279 - الفرق بين الواحد والاحد (2) والمتوحد: قال بعض المحققين: الواحد: الفرد الذي لم يزل وحده ولم يكن معه آخر.","page":"ج1 ص564","text":"والاحد: الفرد الذي لا يتجزأ، ولا يقبل الانقسام.\nفالواحد: هو المتفرد بالذات في عدم المثل.\nلاحد: المتفرد بالمعنى.\nوقيل: المراد بالواحد: نفي التركيب والاجزاء الخارجية والذهنية عنه تعالى، وبالاحد: نفي الشريك عنه في ذاته وصفاته.\nوقيل: الواحدية: لنفي المشاركة في الصفات، والاحدية لتفرد الذات.\nولما لم ينفك عن شأنه تعالى أحدهما عن الآخر قيل: الواحد والاحد (3) في حكم اسم واحد.\nوقد يفرق بينهما في الاستعمال من وجوه: أحدها: أن الواحد يستعمل وصفا مطلقا، والاحد يختص بوصف\nالله تعالى نحو: \" قل هو الله أحد \" (4) .\nالثاني: أن الواحد أعم موردا، لانه يطلق على من يعقل وغيره، والاحد لا يطلق إلا على من يعقل.\nالثالث: أن الواحد يجوز أن يجعل له ثان، لانه لا يستوعب جنسه بخلاف الاحد [7 / ب] ألا ترى انك * لو قلت: فلان لا يقاومه\nواحد، جاز أن يقاومه اثنان، ولا أكثر * (1) .\nالرابع: أن الواحد يدخل في الحساب، والضرب، والعدد والقسمة، والاحد يمتنع دخوله في ذلك.\nالخامس: أن الواحد يؤنث بالتاء، والاحد يستوي فيه المذكر والمؤنث، قال تعالى: \" كأحد من النساء \" (2) ، ولا يجوز: كأحد من النساء، بل: كواحدة.\nالسادس: أن الواحد لا يصلح للاقرار والجمع، بخلاف الاحد [7 / ب] فإنه يصلح لهما، ولهذا وصف بالجمع قوله تعالى: \" من أحد عنه حاجزين \" (3) .\nالسابع: أن الواحد لا جمع له من لفظه، وهو أحدون، وآحاد.\nوأما المتوحد: فهو البليغ في الوحدانية، كالمتكبر: البليغ في الكبرياء.\nوفي القاموس (4) : الله الاحد، والمتوحد: ذو الوحدانية.\nوقيل: المتوحد: المستنكف عن النظير، كما قيل: المتكبر: هو\nالذي تكبر عن كل ما يوجب حاجة أو نقصانا.\n(اللغات) ."},{"id":"furuq-lughawiyya:751","bookId":"furuq-lughawiyya","type":"section","seq":751,"chapter":"* (أ) *","title":"2280 - الفرق بين الوالد والاب (5) : الفرق بينهما: أن الوالد لا يطلق إلا على من أولدك من غير واسطة.","page":"ج1 ص565","text":"والاب: قد يطلق على الجد البعيد، قال تعالى: \" ملة أبيكم إبراهيم \" (6) .\nوفي الحديث النبوي: \" هذا أبي آدم، وهذا أبي نوح \" ومنه يظهر الفرق بين الولد والمولود، فإن الولد يطلق على ولد الولد أيضا، بخلاف المولود، فإنه لمن ولد منك من غير واسطة ويدل عليه قوله تعالى: \" واخشوا يوما لا يجزي والد عن ولده ولا مولود هو جاز عن والده شيئا \" (1) .\nفإنه تضمن نفي النفع والشفاعة بأبلغ وجه، فكأنه قيل: إن الواحد منهم لو شفع للاب الادنى الذي ولد منه لم تقبل شفاعته، فضلا أن يشفع لمن فوقه.\n(اللغات) ."},{"id":"furuq-lughawiyya:752","bookId":"furuq-lughawiyya","type":"section","seq":752,"chapter":"* (أ) *","title":"2285 - الفرق بين الواسع والجواد: أن الواسع مبالغة في الوصف بالجود","page":"ج1 ص566","text":"والشاهد أنه نقيض قولهم للبخيل ضيق مبالغة في الوصف بالجو وهذا في أوصاف الخلق مجاز لان المراد أن عطاءه كثير، وقال بعضهم هو في صفات الله تعالى بمعنى أنه المحيط بالاشياء علما من قوله تعالى \" وسع كل شئ علما \" (2) وله وجه آخر في اللغة وهو أن يكون مأخوذا من الوسع وهو قدر ما تسع له القوة وهو بمنزلة الطاقة وهو نهاية مقدور القادر فلا يصح ذلك في الله تعالى."},{"id":"furuq-lughawiyya:753","bookId":"furuq-lughawiyya","type":"section","seq":753,"chapter":"* (أ) *","title":"2291 - الفرق بين الوجدان والادراك: أن الوجدان في أصل اللغة لما ضاع أو لما يجري مجرى الضائع في أن لا يعرف موضعه، وهو على خلاف النشدان فأخرج ع","page":"ج1 ص567","text":"قوله تعالى \" قال أصحاب موسى إنا لمدركون \" (1) والدرك الحبل يقرن بحبل آخر ليبلغ ما يحتاج إلى بلوغه، والدرك المنزلة لانها مبلغ من تجعل له، ثم توسع في الادراك والوجدان فاجريا مجرى واحدا فقيل أدركته ببصري ووجدته ببصري ووجدت حجمه (2) بيدي وأدركت حجمه بيدي ووجدته بسمعي وأدركته بسمعي وأدركت\nطعمه بفمي ووجدت طعمه بفمي وأدركت ريحه بأنفي ووجدت ريحه بأنفي، وحد المتكلمون الادراك فقالوا هو ما يتجلى به المدرك تجلي الظهور ثم قيل يجد بمعنى يعلم ومصدره الوجود وذلك معروف في العربية ومنه قول الشاعر: وجدت الله أكبر كل شئ * محاولة (1) وأكثرهم جنودا أي علمته كذلك إلا أنه لا يقال للمعدوم موجود بمعنى أنه معلوم وذلك أنك لا تسمى واجدا لما غاب عنك فإن علمته في الجملة فذلك في المعدوم أبعد وقال الله تعالى \" يجد الله غفورا رحيما \" (2) أي يعلمه كذلك وقيل يجدونه حاضرا فالوجود هو العلم بالموجود، وسمي العالم بوجود الشئ واجدا له لا غير وهذا مما جرى على الشئ ثم ما قاربه وكان من سببه، ومن هاهنا يفرق بين الوجود والعلم."},{"id":"furuq-lughawiyya:754","bookId":"furuq-lughawiyya","type":"section","seq":754,"chapter":"* (أ) *","title":"2309 - الفرق بين الوسط والوسط: أن الوسط لا يكون إلا ظرفا تقول قعدت","page":"ج1 ص571","text":"وسط القوم وثوبي وسط الثياب وإنما تخبر عن شئ فيه الثوب وليس به، فإذا حركت السين كان إسما وكان بمعنى بعض الشئ تقول وسط رأسه صلب فترفع لانك إنما تخبر عن بعض الراس لا عن شئ فيه، والوسط إسم الشئ الذي لا ينفك من الشئ المحيط به جوانبه كوسط الدار، وإذا حركت السين دخلت عليه في فتقول إحتجم في وسط رأسه ووسط رأسه بموضع هذا في وسط القوم، ولا يقال قعدت في وسط القوم كما لا يقال قعدت في بين القوم كما أن بين لا يدخل عليه في فكذلك لا تدخل على ما أدى عنه بين."},{"id":"furuq-lughawiyya:755","bookId":"furuq-lughawiyya","type":"section","seq":755,"chapter":"* (أ) *","title":"2311 - الفرق بين الوسيلة والذريعة: أن \" الوسيلة \" عند أهل اللغة هي القربة وأصلها من قولك سألت أسأل أي طلبت وهما يتساولان أي يطلبان القربة ال","page":"ج1 ص571","text":"بكذا فتجعل كذا طريقا إلى بغيتك عنده، والذريعة إلى الشئ: هي الطريقة إليه ولهذا يقال جعلت كذا ذريعة إلى\nكذا فتجعل الذريعة هي الطريقة نفسها وليست الوسيلة هي الطريقة فالفرق بينهما بين."},{"id":"furuq-lughawiyya:756","bookId":"furuq-lughawiyya","type":"section","seq":756,"chapter":"* (أ) *","title":"2314 - الفرق بين الوصف والصفة: أن الوصف مصدر والصفة فعلة.","page":"ج1 ص572","text":"وفعلة نقصت فقيل صفة وأصلها وصفة فهي أخص من الوصف لان الوصف إسم جنس يقع على كثيره وقليله والصفة ضرب من الوصف مثل الجلسة والمشية وهي هيئة الجالس والماشي.\nولهذا اجريت الصفات على المعاني فقيل العفاف والحياء من صفات المؤمن ولا يقال أوصافه بهذا المعنى لان الوصف لا يكون إلا قولا والصفة اجريت مجرى الهيئة وإن لم تكن بها فقيل للمعاني نحو العلم والقدرة صفات لان الموصوف بها يعقل عليها كما ترى صاحب الهيئة على هيئته وتقول هو على صفة كذا وهذه صفتك كما تقول هذه حليتك ولا تقول هذا وصفك إلا أن يعني به وصفه للشئ."},{"id":"furuq-lughawiyya:757","bookId":"furuq-lughawiyya","type":"section","seq":757,"chapter":"* (أ) *","title":"2317 - الفرق بين الوضاءة والحسن: أن الوضاءة تكون في الصورة فقط لانها","page":"ج1 ص573","text":"تتضمن معنى النظافة يقال غلام وضئ إذا كان حسنا نظيفا ومنه قيل الوضوء لانه نظافة ووضوء الانسان وهو وضئ ووضاء كما تقول رجل قراء وقد يكون حسنا ليس بنظيف، والحسن أيضا يستعمل في الافعال والاخلاق ولا تستعمل الوضاءة إلا في الوضوء، والحسن على وجهين حسن في التدبير وهو من صفة الافعال والحسن في المنظر على السماء يقال صورة حسنة وصوت حسن."},{"id":"furuq-lughawiyya:758","bookId":"furuq-lughawiyya","type":"section","seq":758,"chapter":"* (أ) *","title":"2318 - الفرق بين الوضيعة والخسران: أن الوضيعة ذهاب رأس المال ولا يقال لمن ذهب رأس ماله كله قد وضع، والشاهد أنه من الوضع خلاف الرفع، والشئ إذ","page":"ج1 ص573","text":"وأصل الخسران في العربية الهلاك."},{"id":"furuq-lughawiyya:759","bookId":"furuq-lughawiyya","type":"section","seq":759,"chapter":"* (أ) *","title":"2321 - الفرق بين الوعد والوعيد (3) : الفرق بينهما: أن الوعيد: في الشر","page":"ج1 ص574","text":"خاصة.\nوالوعد: يصلح بالتقييد للخير والشر، غير أنه إذا اطلق اختص بالخير، وكذلك إذا ابهم التقييد كقولك: وعدته بأشياء، لانه بمنزلة المطلق.\n(اللغات) ."},{"id":"furuq-lughawiyya:760","bookId":"furuq-lughawiyya","type":"section","seq":760,"chapter":"* (أ) *","title":"2323 - الفرق بين الوفاء والصدق (2) : قيل: هما أعم وأخص.","page":"ج1 ص574","text":"فكل وفاء صدق.\nوليس كل صدق وفاء.\nفإن الوفاء قد يكون بالفعل دون القول، ولا يكون الصدق إلا في القول، لانه نوع من أنواع الخبر، والخبر قول.\n(اللغات) ."},{"id":"furuq-lughawiyya:761","bookId":"furuq-lughawiyya","type":"section","seq":761,"chapter":"* (أ) *","title":"2330 - الفرق بين الوقت والاوان (1) : الفرق بينهما أن الوقت: مقدار من الزمان مفروض لامر ما.","page":"ج1 ص575","text":"والاوان: الحين، وهو الزمان قل أو كثر، وسواء كان مفروضا أم لا، فكل وقت أوان دون العكس.\nوفي دعاء الصحيفة الكاملة: \" اللهم صل على محمد وآل محمد في كل وقت، وفي كل أوان \" (2) .\nفهو من [8 / أ] عطف العام على الخاص.\n(اللغات) ."},{"id":"furuq-lughawiyya:762","bookId":"furuq-lughawiyya","type":"section","seq":762,"chapter":"* (أ) *","title":"2334 - الفرق بين وكالة الله ووكالة العباد بين الوكيل في صفات الله تعالى وبينه في صفات العباد: أن الوكيل في صفات الله بمعنى المتولي القائم بت","page":"ج1 ص576","text":"بالتوكيل."},{"id":"furuq-lughawiyya:763","bookId":"furuq-lughawiyya","type":"section","seq":763,"chapter":"* (أ) *","title":"2340 - الفرق بين الولي والمولى: أن الولي يجري في الصفة على المعان والمعين تقول الله ولي المؤمنين أي معينهم، والمؤمن ولي الله أي المعان بنصر","page":"ج1 ص576","text":"وكلاءتهم كولي الطفل المتولي شأنه، ويكون الولي على وجوه منها ولي المسلم الذي يلزمه القيام بحقه إذا احتاج إليه، ومنها الولي الحليف المعاقد، ومنها ولي المرأة القائم بأمرها، ومنها ولي المقتول الذي هو أحق بالمطالبة بدمه.\nوأصل الولي جعل الثاني بعد الاول من غير فصل من قولهم هذا يلي ذاك وليا وولاه الله كأنه يلي أمره ولم يكله\nإلى غيره، وولاه أمره وكله إليه كأنه جعله بيده وتولى أمر نفسه قام به من غير وسيطة وولي عنه خلاف والى إليه ووالى بين رميتين جعل إحداهما تلي الاخرى والاولى هو الذي الحكمة إليه أدعى، ويجوز أن يقال معنى الولي أنه يحب الخير لوليه كما أن معنى العدو أنه يريد الضرر لعدوه.\nوالمولى على وجوه هو السيد والمملوك والحليف وإبن العم والاولى بالشئ والصاحب ومنه قول الشاعر: ولست بمولى سوأة أدعى لها * فإن لسوآت الامور مواليا أي صاحب سوأة، وتقول الله مولى المؤمنين بمعنى أنه معينهم ولا يقال إنهم مواليه بمعنى أنهم معينوا أوليائه كما تقول إنهم أولياؤه بهذا المعنى."},{"id":"furuq-lughawiyya:764","bookId":"furuq-lughawiyya","type":"section","seq":764,"chapter":"* (أ) *","title":"2345 - الفرق بين ويح وويل (1) : ويح: كلمة عذاب.","page":"ج1 ص578","text":"قال تعالى: \" ويل لكل همزة لمزة \" (2) ، وقيل: ويل \" واد في جهنم \".\nوقال سيبوية (3) : [ (ويح) زجر لمن أشرف على الهلكة.\nو (ويل) لمن وقع فيها] وفي المجمع: (ويح) كلمة ترحم، وتوجع لمن وقع في هلكة، وقد"},{"id":"furuq-lughawiyya:765","bookId":"furuq-lughawiyya","type":"section","seq":765,"chapter":"* (أ) *","title":"ي","page":"ج1 ص578","text":"قال للمدح، والتعجب، ومنه: \" ويح ابن عباس \" كأنه\nأعجب بقوله."},{"id":"furuq-lughawiyya:766","bookId":"furuq-lughawiyya","type":"section","seq":766,"chapter":"* (أ) *","title":"2350 - الفرق بين قولنا يجوز كذا وقولك يجزئ كذا: أن قولك يجوز كذا بمعنى يسوغ ويحل كما تقول يجوز للمسافر أن يفطر ونحوه ويجوز قراءة \" مالك يوم","page":"ج1 ص579","text":"وقال أبو بكر: الاخشاد أكره هذا القول لأن المسلمين لا يستجيزون أن يقولوا يجوز الكفر من الملائكة حتى يصيروا كإبليس لقدرتهم على ذلك، ولا أن يقولوا يجوز من الله تعالى وقوع الظلم لقدرته عليه إلا أن يقيد.\nوأصل هذا كله من\nقولك جاز أي وجد مسلكا مضى فيه ومنه الجواز في الطريق والمجاز في اللغة، فقولك قراءة جائزة معناه أن قارئها وجد لها مذهبا يأمن معه أن يرد عليه، وإذا قلت يجوز أن يكون فلان خيرا من فلان فمعناه أن وهمك قد توجه إلى هذا المعنى منه فإذا علمته لم يحسن فيه ذكر الجواز، والجائز لابد أن يكون منيبا عما سواه ألا ترى أن قائلا لو قال: يجوز أن يعبد العبد ربه لم يكن ذلك كلاما مستقيما إذا لم يكن منبئا عما سواه.\nوقولنا هذا الشئ يجزئ يفيد أنه وقع موقع الصحيح فلا يجب فيه القضاء ويقع به التمليك إن كان عقدا وقد يكون المنهي عنه مجزئا نحو التوضوء بالماء المغصوب والذبح بالسكين المغصوب وطلاق البدعة والوطئ في الحيض والصلاة في الدار المغصوبة محرمة عند الفقهاء لانه نهي عنها لا بشرائط الفعل الشرعية ولكن لحق صاحب الدار لانه لو أذن في ذلك لجاز ولا يكون المنهي عنه جائزا فالفرق بينهما بين، وذهب أبو علي وأبو هاشم رحمهما الله تعالى: إلى أن الصلاة في الدار المغصوبة غير مجزئة لانه قد أخذ على المصلي ينوي أداء الواجب ولا يجوز أن ينوي ذلك والفعل معصية."}]};